window.__D("text/zohar/c036",{"p":[[9520012506,"<p>וַיְהִי בַבֹּקֶר וַיִּקַּח בָּלָק אֶת בִּלְעָם וְגוֹ'. רִבִּי יִצְחָק אָמַר, בָּלָק חַכִּים הֲוָה בְּחַרְשִׁין, יַתִיר מִבִּלְעָם, בַּר דְּלָא הֲוָה מְכַוִּון שַׁעֲתָא לְלַטְיָיא. מָשָׁל וְכוּ'. בְּגִין כָּךְ וַיִּקַּח בָּלָק אֶת בִּלְעָם וְגוֹ'. הוּא הֲוָה אַתְקִין לֵיהּ וְאָחִיד לֵיהּ לְכֹלָּא.</p>\n<p>וַיַּעֲלֵהוּ בָּמוֹת בָּעַל. מַאי וַיַּעֲלֵהוּ בָּמוֹת בָּעַל. אֶלָּא אַשְׁגַח בְּחַרְשׁוֹי, בְּמַאי סִטְרָא יִתְאֲחִיד בְּהוּ, וְאַשְׁכַּח דִּזְמִינִין יִשְׂרָאֵל לְמֶעְבַּד בָּמוֹת, וּלְמִפְלַח לַבַּעַל. כְּמָה דִּכְתִּיב, וַיֵּלְכוּ אַחֲרֵי הַבַּעַל. וַיַּרְא מִשָּׁם קְצֵה הָעָם, חָמָא רַבְרְבֵי דְּעַמָּא, וּמַלְכָּא דִּלְהוֹן, דְּפָלְחִין לֵיהּ, כְּמָה דִּכְתִּיב (מלכים א י״ח:כ״ו) וְיִקְרְאוּ בְשֵׁם הַבַּעַל, וּכְתִיב (מלכים א י״ח:כ״א) אִם יְיָ הָאֱלֹהִים וְגוֹ'. כֵּיוָן דְּחָמָא בִּלְעָם, דִּזְמִינִין יִשְׂרָאֵל לְהַאי, מִיַּד וַיֹּאמֶר בִּלְעָם אֶל בָּלָק בְּנֵה לִי בָזֶה שִׁבְעָה מִזְבְּחֹת. (חסר כתיב)</p>\n<p>רִבִּי יוֹסֵי וְרִבִּי יְהוּדָה, חַד אָמַר לָקֳבְלֵי מַדְבְּחָן דְּקַדְמָאֵי, אַקְרִיב אִינּוּן שִׁבְעָה מַדְבְּחָן. וְחַד אָמַר, בְּחָכְמְתָא עָבֵד כֹּלָּא, וְאַשְׁכַּח דְּחוּלָקֵיהוֹן דְּיִשְׂרָאֵל בְּשִׁבְעָה דַּרְגִּין אִתְקְשָּׁרוּ. בְּגִין כַּךְ אַסְדַּר שִׁבְעָה מַדְבְּחָן.</p>\n<p>לְבַּר נָשׁ דְּהֲוָה לֵיהּ רְחִימָא חַד, דְּשָׁבַק לֵיהּ אֲבוֹי. וּבְנֵי נָשָׁא מִסְתָּפוּ לְקַטְּטָה בַּהֲדֵיהּ, בְּגִין הַהוּא רְחִימָא. לְיוֹמִין, אָתָא בַּר נָשׁ חַד, וּבָעָא לְאַתְעָרָא קְטָטוּ בַּהֲדֵיהּ. אָמַר, מַה אַעְבֵּיד, אִי אַתְעַר בֵּיהּ קְטָטָא, הָא הַהוּא רְחִימָא דְּאִתְקְשַׁר בַּהֲדֵיהּ, וְלָא יָכִילְנָא, אָמַר מָה עֲבַד, שָׁדַר לֵיהּ דּוֹרוֹן לְהַהוּא רְחִימָא. אָמַר הַהוּא רְחִימָא, וְכִי מָה אִית לֵיהּ לְהַאי בַּר נָשׁ גַּבָּאי, יְדַעְנָא דִּבְגִין הַהוּא בַּר רְחִימָאי הוּא. אָמַר, הַאי דּוֹרוֹן לָא יֵיעוּל קַמָּאי, זְמִינוּ לֵיהּ לְכַלְבֵּי וְיֵכְלוּנֵיהּ.</p>\n<p>כַּךְ בִּלְעָם, אָתָא לְאַתְעָרָא קְטָטוּ בְּהוּ בְּיִשְׂרָאֵל, וְחָמָא דְּלָא יָכִיל בְּגִין הַהוּא רְחִימָא עִלָּאָה דִּלְהוֹן, (כמה דאת אמר (משלי כ״ז:י׳) רעך ורע אביך אל תעזוב.) שָׁארֵי לְתַקְּנָא קַמֵּיהּ דּוֹרוֹן. אָמַר קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע וּמַה אִית לָךְ גַּבָּאי, אַתְּ בָּעֵי לְאִזְדַּוְּוגָא בְּבְנַי, הֲרֵי דּוֹרוֹנָךְ זַמִּין לְכַלְבֵּי. תָּא חֲזֵי, מַה כְּתִיב, וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וְאָמַר רַבִּי שִׁמְעוֹן, לָשׁוֹן קֶרִי וְטוּמְאָה. דּוֹרוֹנָךְ לְאִלֵּין אִתְמְסַר וְלָא יֵיעוּל קַמָּאי.</p>\n<p>רִבִּי אַבָּא אָמַר, וַיִּקָּר: כְּמָה דְאַתְּ אָמֵר, (תהילים קמ״ז:י״ז) לִפְנֵי קָרָתוֹ מִי יַעֲמוֹד. הוּא הֲוָה זַמִּין, דִּבְהַהוּא דּוֹרוֹן, יָכִיל בְּהוּ בְּיִשְׂרָאֵל. מַה כְּתִיב. וַיִּקָּר אֱלֹהִים. קָרִיר גַּרְמֵיהּ מִן דָּא דְּהֲוָה חָשִׁיב. וַיִּקָּר אֱלֹהִים, כְּמָה דְּאִתְּמַר, דְּאִתְעַר עָלֵיהּ מִסִּטְרָא דִּמְסָאֲבוּתָא.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, וַיִּקָּר, בִּלְעָם חָשִׁיב דִּבְהַהוּא דּוֹרוֹן יֵיעוּל לְאַבְאָשָׁא לְהוּ לְיִשְׂרָאֵל, וְקוּדְשָׁא בְּרִיךְ הוּא אַעְקָר לֵיהּ מִקַּמֵּיהּ לְהַהוּא דּוֹרוֹן. וְאַעְקַר לֵיהּ לְבִלְעָם, מִמַּה דְּהֲוָה חָשִׁיב. וְאַעְקַר (ס\"א ליה מההוא דרגא), לְהַהוּא דַּרְגָּא הֲדָא הוּא דִכְתִיב וַיִּקָּר. כְּמָה דְאַתְּ אָמֵר (משלי לו) יִקְּרוּהָ עוֹרְבֵי נַחַל. אָמַר לֵיהּ, רָשָׁע, לֵית אַנְּתְּ כְּדַאי לְאִתְקַשְּׁרָא בַּהֲדָאי <Nonei></i>וּלְמֵיעַל קַמָּאי. דּוֹרוֹנָךְ לְכַלְבֵּי אִתְמְסַר.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, תָּא חֲזֵי, הַאי רָשָׁע, גַּעֲלָא דְּכֹלָּא הֲוָה. דְּלָא תִּשְׁכַּח בְּכָל פָּרַשְׁתָא דָּא, וַיֹּאמֶר יְיָ אֶל בִּלְעָם, אוֹ וַיְדַבֵּר יְיָ, חַס וְשָׁלוֹם. מַה כְּתִיב. וַיָּשֶׂם יְיָ דָּבָר בְּפִי בִּלְעָם וְגוֹ', כְּמַאן דְּשַׁוִּי חִסְמָא בְּפוּם חֲמָרַא, דְּלָא יִסְטֵי הָכָא אוֹ הָכָא, כַּךְ וַיָּשֶׂם יְיָ דָּבָר בְּפִי וְגוֹ'.</p>\n<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, אַתְּ חָשִׁיב דְּעַל יְדָךְ יְהֵא וְיִתְקַיֵּים בְּרָכָה בְּבָנַי, אוֹ אִפְּכָא. לָא צְרִיכִין אִינּוּן לָךְ, כְּמָה דְּאַמְרִין לַצִּרְעָה וְכוּ'. אֶלָּא אַתְּ שׁוּב אֶל בָּלָק, וְכַד תִּפְתַּח פּוּמָךְ, לָא יְהֵא בִּרְשׁוּתָךְ. וְלָא בְּפוּמָךְ תַּלְיָיא מִלּוּלָא, אֶלָּא וְכֹה תְּדַבֵּר. הֲרֵי כֹּ\"ה, דִּזְמִינָא לְבָרְכָא לוֹן. כֹּה, תְּמַלֵּל בְּרָכָה דִּבְנַי, דְּכַד תִּפְתַּח פּוּמָךְ, הִיא תְּמַלֵּל מִלִּין, לְאִתְקַיְּימָא עַל בְּנַי, דְּלָא אֶשְׁבּוֹק מִלִּין לָךְ.</p>\n<p>תָּא חֲזֵי, דְּכַךְ הוּא, כֵּיוָן דְּאָתָא לְבָלָק, וּבָלָק שָׁמַע כָּל אִינּוּן מִלִּין, הֲוָה חָשִׁיב דְּהָא מִפּוּמֵיהּ דְּבִלְעָם נָפְקִין, אָמַר, לָקוֹב אוֹיְבַי לְקַחְתִּיךָ. אָמַר בִּלְעָם. סַב אִלֵּין חַרְשִׁין בִּידָךְ, בְּגִין לְאַעְכָּבָא הָכָא לְהַאי כֹּה, וְאִי אַתְּ תֵּיכוּל לְאַעְכְּבָא (ס\"א לאעקרא) לָהּ בְּהַאי חַרְשִׁין, אֲנָא אַעְקָר לָהּ מֵאִינּוּן מִלִּין דְּהִיא אָמְרָה.</p>\n<p>מַה כְּתִיב, הִתְיַצֵּב כֹּה עַל עוֹלָתֶךָ, בְּהַאי, וּבְאִלֵּין חַרְשִׁין, תְּעַכֵּב לָהּ, וְאָנֹכִי אִקָּרֶה כֹּ\"ה, כְּלוֹמַר, אַעְקָר לָהּ מֵאִלֵּין מִלִּין. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, אֲנָא אַעְקָר לָךְ. מַה כְּתִיב בַּתְרֵיהּ. וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם. וְהַהוּא דָּבָר אָרִים קָלָא, בְּמִלוּלֵי דְּכֹ\"ה. וַיֹּאמֶר שׁוּב אֶל בָּלָק וְכֹה תְּדַבֵּר, כֹּ\"ה תְּדַבֵּר וַדַּאי.</p>\n<p>תָּא חֲזֵי, בְּקַדְמִיתָא לָא כְּתִיב הִתְיַצֵּב כֹּה עַל עוֹלָתֶךָ, אֶלָּא הִתְיַצֵּב עַל עוֹלָתֶךָ וְאֵלְכָה אוּלַי יִקָּרֶה יְיָ לִקְרָאתִי. כֵּיוָן דְּחָמָא דְּכֹ\"ה אָמַר אִינּוּן בִּרְכָאן, כְּדֵין אָמַר הִתְיַצֵּב כֹּ\"ה עַל עוֹלָתֶךָ, וְאָנֹכִי אִקָּרֶה כֹּ\"ה.</p>\n<p>לְכָה אָרָה לִּי יַעֲקֹב, כְּלוֹמַר, לְקוֹט. רִבִּי יוֹסֵי אָמַר, אַשְׁדֵּי לוֹן מֵהַהוּא דַּרְגָּא דְּאִינּוּן קַיְימֵי, כְּמָה דְאַתְּ אָמֵר (שמואל א כ׳:כ׳) צִדָּהּ אוֹרֶה. אָמַר, אִי תֵּיכוּל לְמִשְׁדֵּי (ס\"א לון מההוא דרגא) לְהַהוּא דַּרְגָּא דִּלְהוֹן, הָא כֻּלְּהוּ אִתְעֲקָרוּ מֵעָלְמָא. וּלְכָה זוֹעֲמָה יִשְׂרָאֵל, יִשְׂרָאֵל דִּלְעֵילָּא, דְּיִשְׁתְּכַח רוּגְזָא קַמֵּיהּ, כְּמָה דְאַתְּ אָמֵר (תהלים ז) וְאֵל זוֹעֵם בְּכָל יוֹם.</p>\n<p>(במדבר כ״ג:ט׳) כִּי מֵרֹאשׁ צוּרִים וְגוֹ'. אָמַר רִבִּי יִצְחָק, מֵרֹאשׁ צוּרִים, אִלֵּין אִינּוּן אֲבָהָתָא. דִּכְתִיב (ישעיהו נ״א:א׳) הַבִּיטוּ אֶל צוּר חוּצַּבְתֶּם. וּמִגְּבָעוֹת אֲשׁוּרֶנוּ, אִלֵּין אִמָּהָן, בֵּין מֵהַאי סִטְרָא וּבֵין מֵהַאי סִטְרָא, לָא יַכְלִין לְאִתְלַטְּיָיא.</p>\n<p>רִבִּי אַבָּא אָמַר, כִּי מֵרֹאשׁ צוּרִים, מַאן יָכִיל לְהוּ לְיִשְׂרָאֵל, דְּהָא הוּא אָחִיד מֵרֵישָׁא דְּכָל צוּרִים נָפְקִין (שמות ס\"ד), וּמַאן אִינּוּן צוּרִים. גְּבוּרָן. דְּהָא כָּל דִּינִין דְּעָלְמָא מֵאִינּוּן גְּבוּרָן נָפְקֵי, וְאִינּוּן אִתְאַחֲדָן בְּהוּ. וּמִגְּבָעוֹת אֲשׁוּרֶנוּ, אִלֵּין שְׁאַר מַשִׁרְיָין (ס\"א כתרין) דְּאִתְאַחֲדָן בְּהוּ. הֶן עָם לְבָדָד וְגוֹ'. כְּמָה דְאַתְּ אָמֵר (דברים ל״ב:י״ב) ה' בָּדָד יַנְחֶנּוּ.</p>\n<p>מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ', הָא אוּקְמוּהָ. אֶלָּא אָמַר רִבִּי יוֹסֵי, תְּרֵין דַּרְגִּין אִינּוּן, יַעֲקֹב וְיִשְׂרָאֵל. בְּקַדְמִיתָא יַעֲקֹב, וּלְבָתַר יִשְׂרָאֵל. וְאַף עַל גַּב דְּכֹלָּא חַד, תְּרֵין דַּרְגִּין אִינּוּן, דְּהָא דַּרְגָא עִלָּאָה יִשְׂרָאֵל הוּא.</p>\n<p>מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ'. לְתַתָּא, מַאן הוּא עָפָר. רִבִּי שִׁמְעוֹן אָמַר, הַאי דִּכְתִּיב בֵּיהּ (ישעיהו מ״א:ב׳) יִתֵּן כֶּעָפָר חַרְבּוֹ וְגוֹ'. מַאן חַרְבּוֹ. הָא יְדִיעָא, דִּכְתִיב (ישעיהו ל״ד:ו׳) חֶרֶב לַיְיָ מָלְאָה דָם. עָפָר, הַהוּא אֲתָר דְּאִתְבְּרֵי מִנֵּיהּ אָדָם הָרִאשׁוֹן, דִּכְתִיב (בראשית ב׳:ז׳) וַיִּיצֶר יְיָ אֱלֹהִים אֶת הָאָדָם עָפָר וְגוֹ'. וּמֵהַהוּא עָפָר, כַּמָּה חַיָּילִין, וְכַּמָּה מַשִׁרְיָין נָפְקוּ, כַּמָּה טַפְסִין, כַּמָה גַּרְדִּינֵי נִמוּסִין, כַּמָּה גִּירִין, כַּמָּה בַּלִיסְטְרָאוֹת, כַּמָה רוּמְחִין, וְסַיְיפִין, וְזַיְינִין, אִשְׁתְּכָחוּ מֵהַהוּא עָפָר. (מי מנה) כְּמָה דְאַתְּ אָמֵר, (איוב כ״ה:ג׳) הֲיֵשׁ מִסְפָּר לִגְדוּדָיו.</p>\n<p>וּמִסְפָּר אֶת רוֹבַע יִשְׂרָאֵל. רֹבַע יִשְׂרָאֵל הִיא הֵ\"א, וְחַד מִלָּה הִיא. רוֹבַע יִשְׂרָאֵל, כְּמָה דְאַתְּ אָמֵר (שמות כ״ג:ה׳) רוֹבֵץ תַּחַת מַשָּׂאוֹ, רְבִיעַ הֲדָא הוּא דִּכְתִּיב, (שיר השירים ג׳:ז׳) מִטָּתוֹ שֶׁלִּשְׁלֹמֹה. דָּבָר אַחֵר רֹבַע, כְּמוֹ רְבִיעִית מִיִשְׂרָאֵל לְתַתָּא, רֹבַע אִתְקְרֵי לְפוּם כִּתְרִין מַשְׁמַע דָּוִד, דְּאִיהוּ רַגְלָא רְבִיעָאָה דְּכוּרְסְיָיא.</p>\n<p>דָּבָר אַחֵר מִי מָנָה עֲפַר יַעֲקֹב וְגוֹ', כָּל אִינּוּן דַּחֲשִׁיבִין עַפְרָא, כְּמָה דְּאוֹקִימְנָא. וּמִסְפָּר אֶת רֹבַע יִשְׂרָאֵל, דִּכְתִּיב הֲיֵשׁ מִסְפָּר לִגְדוּדָיו. רֹבַע יִשְׂרָאֵל כְּמָה <Nonei></i>דְּאוֹקִימְנָא. דָּבָר אַחֵר מִי מָנָה עֲפַר, אִינּוּן פִּקוּדִין דְּאִינּוּן בְּעַפְרָא, בִּזְרִיעָה, בִּנְטִיעָה, בְּחַצְדָּא, וְהָא אוּקְמוּהָ חַבְרַיָּיא. וּמִסְפָּר אֶת רֹבַע, כְּמָה דְאַתְּ אָמֵר (ויקרא י״ט:י״ט) בְּהֶמְתְּךָ לֹא תַרְבִּיעַ. (אמר רבי אבא, בלק חכים הוה בחרשוי כבלעם. בר דלא ידע לכוון שעתא ללטיא).</p>\n<p>(במדבר כ״ג:ז׳) וְיִשָּׂא מְשָׁלוֹ וַיֹּאמַר. וַיְדַבֵּר לָא כְּתִיב, מַאי וְיִשָּׂא מְשָׁלוֹ. רִבִּי חִיָּיא אָמַר, הוּא הֲוָה זָקִיף קָלָא לְגַבֵּי הַהוּא מְמַלֵּל, וְיִּשָּׂא מְשָׁלוֹ בִּלְעָם. וַיֹּאמַר הַאי כֹּה כְּמָה דִּכְתִּיב וְכֹה תְּדַבֵּר, וַאֲמִירָה מִנָּהּ הֲוָה.</p>\n<p>תָּא חֲזֵי, כֵּיוָן דְּחָמָא בִּלְעָם דִּבְכָל חֲרָשׁוֹי וּבְכָל הַהוּא דּוֹרוֹן, לָא יָכִיל לְאַעְקְרָא הַהוּא כֹּה, כְּמָה דְאַתְּ אָמֵר וְאָנֹכִי אִקָּרֶה כֹּה, אַעְקָר לְהַאי כֹּה. אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, אַנְּתְּ סָבוּר לְאַעְקְרָא לָהּ, אֲנָא אַעְקָר לָךְ מִשֶּׁלְשׁוּלָךְ, מַה כְּתִיב. וַיִּקָּר אֱלֹהִים אֶל בִּלְעָם, כְּמָה דְּאִתְּמַר. לְבָתַר, כֵּיוָן דְּחָמָא דְּלָא יָכִיל, הָדָר וְאָמַר, וּבֵרֵךְ וְלֹא אֲשִׁיבֶנָּה, וְלֹא אֲשִׁיבֶנּוּ מִבָּעֵי לֵיהּ. אֶלָּא וְלֹא אֲשִׁיבֶנָּה ודַּאי, לְהַהִיא דִּכְתִּיב כֹּה, וְכֹּה תְּדַבֵּר. לֵית אֲנָא יָכִיל לְאָהַדְּרָא לָהּ.</p>\n<p>אָמַר בִּלְעָם, בִּתְרֵין דַּרְגִּין בָּעֵינָא לְאַעֲלָא בְּהוּ. בָּעֵינָא לְאַעֲלָא בְּהוּ מִדַּרְגָּא דְּיַעֲקֹב, וְלָא יָכִילְנָא. בָּעֵינָא לְאַעֲלָא בְּהוּ מִסִּטְרָא אַחֲרָא דְּיִשְׂרָאֵל, וְלָא יָכִילְנָא. מַאי טַעֲמָא. בְּגִין דִּשְׁמָא דָּא אוֹ דָּא, לָא אִתְקְשַׁר בְּזִינִין בִּישִׁין, הֲדָא הוּא דִכְתִיב לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְגוֹ'.</p>\n<p>תָּאנָא, תְּרֵין דַּרְגִּין אִינּוּן: נַחַשׁ, וְקֶסֶם. לָקֳבְלֵיהוֹן: עָמָל, וָאָוְן. אָמַר בִּלְעָם, הָא וַדַּאי אַשְׁכַּחְנָא לָקֳבְלֵי דְּהָנֵי יַעֲקֹב וְיִשְׂרָאֵל. אָוְן, לָקֳבְלֵיהּ דְּיַעֲקֹב, דְּאִיהוּ קָטִיר בְּנַחַשׁ. עָמָל, לְקָבְלֵיהּ דְּיִשְׂרָאֵל, דְּאִיהוּ קָטִיר בְּקֶסֶם. כֵּיוָן דְּחָמָא דְּלָא יָכִיל, אָמַר, וַדַּאי לֹא הִבִּיט אָוְן בְּיַעֲקֹב וְגוֹ'. מַאי טַעְמָא. בְּגִין דַּיְיָ אֱלֹהָיו עִמּוֹ וְגוֹ'.</p>\n<p>וְאִי תֵּימָא, בְּהָנֵי לָא יָכִילְנָא. בְּקֶסֶם וְנַחַשׁ יָכִילְנָא. כְּתִיב כִּי לֹא נַחַשׁ בְּיַעֲקֹב וְגוֹ'. וְלֹא עוֹד, אֶלָּא דְּכָל חֵילִין דִּלְעֵילָּא, וְכָל מַשִׁרְיָין כֻּלְּהוּ, לָא יַדְעֵי וְלָא מִסְתַּכְּלֵי בְּנִמוּסָא דְּמַלְכָּא עִלָּאָה, עַד דְּשָׁאֲלֵי לְהָנֵי תְּרֵי יַעֲקֹב וְיִשְׂרָאֵל. וּמַאי אַמְרֵי. מַה פָּעַל אֵל. אָמַר רִבִּי אֶלְעָזָר, כָּל הָנֵי מִלִּין, כֹּה אָמַר, וְהוּא אָרִים קָלָא לָקֳבְלָהּ, וְלָא יָדַע מַאי הוּא, וְלָא אִשְׁתְּמַע בַּר קַלֵיהּ.</p>\n<p>הֶן עָם כְּלָבִיא יָקוּם וְגוֹ', מַאן עַמָּא תַּקִּיפָא כְּיִשְׂרָאֵל. בְּשַׁעֲתָא דְּאִתְנְהִיר צַפְרָא, קָם וּמִתְגַבָּר כְּאַרְיָא, לְפוּלְחָנָא דְּמָארֵיהוֹן, בְּכַמָּה שִׁירִין, בְּכַמָּה תּוּשְׁבְּחָן. מִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא כָּל יוֹמָא, וּבַלַּיְלָה לֹא יִשְׁכַּב וְגוֹ'. כַּד בָּעֵי בַּר נָשׁ לְמִשְׁכַּב עַל עַרְסֵיהּ, מְקַדֵּשׁ שְׁמָא עִלָּאָה, אַמְלִיךְ לֵיהּ לְעֵילָּא וְתַתָּא. כַּמָה גַּרְדִּינֵי נִמוּסִין מִתְקַשְּׁרָן קַמַּיְיהוּ, בְּשַׁעֲתָא דְּפַתְחִין פּוּמְהוֹן עַל עַרְסַיְיהוּ, בִּשְׁמַע יִשְׂרָאֵל. וּבָעָאן רַחֲמֵי קַמֵּי מַלְכָּא קַדִּישָׁא, בְּכַמָּה קְרָאֵי דְּרַחֲמֵי.</p>\n<p>רִבִּי אַבָּא אָמַר, הֶן עָם כְּלָבִיא יָקוּם. זְמִינִין הַאי עַמָּא, לְמֵיקָם עַל כָּל עַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, כְּאַרְיֵה גִּיבָּר וְתַקִּיף, וְיִתְרְמֵי עָלַיְיהוּ. אָרְחַיְיהוּ דְּכָל אַרְיָיוָותָא לְמִשְׁכַּב עַל טַרְפַּיְיהוּ, אֲבָל עַמָּא דָּא לָא יִשְׁכַּב, עַד יֹאכַל טֶרֶף.</p>\n<p>דָּבָר אַחֵר הֶן עָם כְּלָבִיא יָקוּם, לְקָרְבָא קָרְבְּנִין וְעִלָּוָון קַמֵּי מַלְכְּהוֹן, עַל גַּבֵּי מַדְבְּחָא. וְתָאנָא, בְּשַׁעֲתָא דְּקוּרְבְּנָא אִתּוֹקַד עַל גַּבֵּי מַדְבְּחָא, הֲווֹ חָמָן דִּיּוּקְנָא דְּחַד אַרְיֵה רְבִיעַ עַל הַהוּא קָרְבְּנָא, וְאָכִיל לֵיהּ.</p>\n<p>וְאָמַר רִבִּי אַבָּא, אוּרִיאֵ\"ל מַלְאָכָא עִלָּאָה הֲוָה, וְחָמָאן לֵיהּ בְּדִיּוּקְנָא דְּאֲרְיָא תַּקִיפָא, רְבִיעַ עַל מַדְבְּחָא, וְאָכִיל לוֹן לְקָרְבְּנִין. וְכַד יִשְׂרָאֵל לָא הֲווֹ זַכָּאִין כָּל כַּךְ, הֲווֹ חָמָאן דִּיּוּקְנָא דְּחָד כַּלְבָּא חֲצִיפָא רְבִיעַ עָלֵיהּ, כְּדֵין הֲווֹ יַדְעֵי יִשְׂרָאֵל דְּבַעְיָין תְּשׁוּבָה, וּכְדֵין תַּיְיבַן. לֹא יִשְׁכַּב וְגוֹ', אִלֵּין קָרְבְּנִין דְּלֵילְיָא כְּגוֹן עַלָּוָון. וְדַם חֲלָלִים יִשְׁתֶּה, דְקוּדְשָׁא בְּרִיךְ הוּא אֲגַח קְרָבָא דִּלְהוֹן עַל שַׂנְאֵיהוֹן.</p>\n<p>רִבִּי אֶלְעָזָר אָמַר, לֹא יִשְׁכַּב, מַהוּ לֹא יִשְׁכַּב. אֶלָּא בְּכָל לֵילְיָא וְלֵילְיָא, כַּד בַּר נָשׁ אִיהוּ אָזִיל בְּפִקּוּדֵי דְּמָארֵיהּ, לָא <Nonei></i>שָׁכִיב עַל עַרְסֵיהּ, עַד דְּקָטִיל אֶלֶף וּמְאָה וְעֶשְׂרִים וַחֲמֵשׁ, מֵאִינּוּן זַיְינִין בִּישִׁין, דְּשַׁרְיָין עִמֵּיהּ. רִבִּי אַבָּא אָמַר, אֶלֶף אִינּוּן דִּסְטָר שְׂמָאלָא, דִּכְתִּיב, (תהילים צ״א:ז׳) יִפּוֹל מִצִּדְּךָ אֶלֶף. כְּמָה דִּכְתִּיב, (תהילים קמ״ט:ה׳) יַעְלְזוּ חֲסִידִים בְכָבוֹד וְגוֹ', (תהילים קמ״ט:ה׳) רוֹמְמוֹת אֵל בִּגְרוֹנָם וְגוֹ', לַעֲשׂוֹת נְקָמָה וְגוֹ', הֲדָא הוּא דִכְתִיב לֹא יִשְׁכַּב וְגוֹ' וְדָא הוּא לַעֲשׂוֹת בָּהֶם מִשְׁפָּט וְגוֹ'.</p>\n<p>אָמַר רִבִּי חִזְקִיָּה, לָקֳבְלֵי תְּלַת זִמְנִין דְּהוּא מָחָא לְאַתְנֵיהּ, וְאַטְעִין לָהּ בְּחַרְשׁוֹי, אִתְבָּרְכוּן יִשְׂרָאֵל תְּלַת זִמְנִין. רִבִּי חִיָּיא אָמַר, לָקֳבְלֵיה אִתְבָּרְכוּן יִשְׂרָאֵל תְּלַת זִמְנִין, דְּסַלְּקִין יִשְׂרָאֵל לְאִתְחֲזָאָה קַמֵּי מַלְכָּא קַדִּישָׁא.</p>\n<p>(במדבר כ\"ג) וַיַּרְא בִּלְעָם כִּי טוֹב בְּעֵינֵי יְיָ וְגוֹ', וְלֹא הָלַךְ כְּפַעַם בְּפַעַם לִקְרַאת נְחָשִׁים וְגוֹ'. מַאי לִקְרַאת נְחָשִׁים. אָמַר רִבִּי יוֹסֵי, דְּהָנֵי תְּרֵין זִמְנִין קַדְמָאֵי, הֲוָה אָזִיל בְּכָל חֲרָשׁוֹי, וּבָעָא לְמֵילָט לְיִשְׂרָאֵל. כֵּיוָן דְּחָמָא רְעוּתֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאָמַר שׁוּב אֶל בָּלָק, דְּהָא מִלּוּלָךְ לָא בַּעְיָין בָּנַי. מִלּוּלָא אוֹחֲרָא זַמִּין מֵהַאי כֹּה, כְּמָה דִּכְתִּיב וְכֹה תְּדַבֵּר. כֹּה תְּדַבֵּר, וְלָא אַנְּתְּ. כֹּה תְּדַבֵּר, דְּשַׁלְטָא עַל כָּל שַׁלִיטִין חַרְשִׁין וְקִסְמִין וְּזִינִין בִּישִׁין, דְּלָא יַכְלִין לְאַבְאָשָׁא לִבְנַי. כְּדֵין בָּעָא לְאִסְתַּכְּלָא בְּהוּ, בְּעֵינָא בִּישָׁא.</p>\n<p>תָּא חֲזֵי, הַאי רָשָׁע כַּד אִסְתָּכַּל בְּהוּ בְּיִשְׂרָאֵל, הֲוָה מִסְתָּכַּל בְּאִלֵּין תְּרֵין דַּרְגִּין יַעֲקֹב וְיִשְׂרָאֵל, לְאַבְאָשָׁא לוֹן, אוֹ בְּהַאי אוֹ בְּהַאי בְּחֲרָשׁוֹי, בְּגִין כַּךְ כָּל בִּרְכָּן וּבִרְכָּן יַעֲקֹב וְיִשְׂרָאֵל אִתְבְּרִיכוּ. וַיַּרְא בִּלְעָם כִּי טוֹב וְגוֹ'. בַּמֶה חָמָא חָמָא דִּי בְּשַׁעֲתָא דְּאַנְפֵי מַלְכָּא נְהִירִין, זִינִין בִּישִׁין לָא קַיְימֵי בְּקִיּוּמַיְיהוּ, וְכָל חַרְשִׁין וְכָל קִסְמִין לָא סַלְּקָאן בְּחַרְשַׁיְיהוּ.</p>\n<p>תָּא חֲזֵי, בְּהָנֵי תְּרֵי זְמַנֵי כְּתִיב וַיִּקָּר. וַיֵּקָּר אֱלֹהִים. וַיִּקָּר יְיָ אֶל בִּלְעָם וְגוֹ'. וּכְתִיב וְכֹה תְּדַבֵּר. וְהַשְׁתָּא כֵּיוָן דְּחָמָא דְּהָא לָא אִשְׁתְּכַח רוּגְזָא, וְחַרְשׁוֹי לָא סַלְּקִין, כְּדֵין וְלֹא הָלַךְ כְּפַעַם בְּפַעַם וְגוֹ'. כֵּיוָן דְּאַפְרִישׁ וְאִסְתַּלָּק גַּרְמֵיהּ מֵחַרְשׁוֹי, שָׁארֵי (ברוחא אחרא) בְּאִתְעָרוּתָא אַחֲרָא לְשַׁבְּחָא לְיִשְׂרָאֵל. אָמַר רִבִּי יְהוּדָה, מַאי אִתְּעָרוּתָא הָכָא. אָמַר לֵיהּ, (רוח אלהים ולא רוח יי אלא) אִתְּעָרוּתָא דְּרוּחָא חֲדָא מִסִּטְרָא דִּשְׂמָאלָא, הַהוּא דְּאִתְקְשָׁרוּ תְּחוֹתוֹי אִינּוּן זִינִין וְחָרָשִׁין דִּילֵיהּ.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, הָכִי אוֹלִיפְנָא, דְּאֲפִילּוּ הַאי זִמְנָא לָא שַׁרְיָא בֵּיהּ רוּחָא דְּקוּדְשָׁא. אָמַר לֵיהּ רִבִּי יוֹסֵי, אִי הָכִי, הָא כְּתִיב וַתְּהִי עָלָיו רוּחַ אֱלֹהִים, וּבְכָל אִינּוּן זִמְנִין אָחֲרָנִין לָא כְּתִיב בְּהוּ הָכִי. אָמַר לֵיהּ הָכִי הוּא. תָּא חֲזֵי, כְּתִיב (משלי כ״ב:ט׳) טוֹב עַיִן הוּא יְבוֹרָךְ, וְהָא אוּקְמוּהָ אַל תִּקְרֵי יְבוֹרָךְ. אֶלָּא יְבָרֵךְ. וּבִלְעָם הֲוָה רַע עַיִן, דְּלָא אִשְׁתְּכַח רַע עַיִן בְּעָלְמָא כְּוָותֵיהּ, דִּבְכָל אֲתָר דְּהֲוָה מִסְתָּכַּל בְּעֵינוֹי, הֲוָה מִתְלַטְּיָיא. וְעַל דָּא אָמְרוּ, הַאי מַאן דְּאַעְבַּר בְּרֵיהּ בְּשׁוּקָא, וּמִסְתַּפֵי מֵעֵינָא בִּישָׁא, יֶחֱפֵּי סוּדְרָא עַל רֵישֵׁיהּ, בְּגִין דְּלָא יָכִיל עֵינָא בִּישָׁא לְשַׁלְּטָאָה עָלֵיהּ. אוּף הָכָא, כֵּיוָן דְּחָמָא בִּלְעָם, דְּלָא יָכִיל בְּחַרְשׁוֹי וְקִסְמוֹי לְאַבְאָשָׁא לְיִשְׂרָאֵל, בָּעָא לְאִסְתַּכָּל בְּהוּ בְּעֵינָא בִּישָׁא, בְּגִין דִּבְכָל אֲתָר דְּהֲוָה מִסְתָּכַּל בְּעֵינוֹי בִּישִׁין, הֲוָה מִתְלַטְּיָיא.</p>\n<p>תָּא חֲזֵי מַה רְעוּתֵיהּ דִּילֵיהּ לַקֳבְלֵהוֹן דְּיִשְׂרָאֵל, כְּתִיב וַיָּשֶׁתּ אֶל הַמִּדְבָּר פָּנָיו, כְּתַרְגּוּמוֹ, (ושוי (ס\"א לקבל עגלא) לעגלא די עבדו ישראל במדברא אפוהי), בְּגִין דִּיְהֵא לֵיהּ סְטַר סִיּוּעָא, לְאַבְאָשָׁא לְהוּ.</p>\n<p>הַשְׁתָּא חָמֵי מַה כְּתִיב, וַיִּשָּׂא בִּלְעָם אֶת עֵינָיו וַיַּרְא אֶת יִשְׂרָאֵל. בָּעָא לְאִסְתַּכְּלָא בְּהוּ בְּעֵינָא בִּישָׁא. בֵּיהּ שַׁעֲתָא, אִלְמָלֵא דְּאַקְדִּים לוֹן קוּדְשָׁא בְּרִיךְ הוּא אַסְוָותָא, הֲוָה מְאַבֵּד לוֹן בְּאִסְתַּכְּלוּתָא דְּעֵינוֹי. וּמַאי אַסְוָותָא יָהַב קוּדְשָׁא בְּרִיךְ הוּא לְיִשְׂרָאֵל בְּהַהִיא שַׁעֲתָא. דָּא הוּא דִּכְתִּיב וַתְּהִי עָלָיו רוּחַ אֱלֹהִים. וַתְּהִי עָלָיו, עַל יִשְׂרָאֵל קָאָמַר. כְּמַאן דְּפָרִישׁ סוּדְרָא עַל רֵישֵׁיהּ דְּיַּנּוּקָא, בְּגִין דְּלָא יִשְׁלוֹט בְּהוּ עֵינוֹי.</p>\n<p>כְּדֵין שָׁארֵי וְאָמַר, מַה טֹּבוּ אֹהָלֶיךָ יַעֲקֹב. תָּא חֲזֵי, כָּל מַאן דְּבָעֵי לְאִסְתַּכְּלָא בְּעֵינָא בִּישָׁא, לָא יָכִיל, אֶלָּא כַּד מְשַׁבַּח וְאוֹקִיר לְהַהוּא מִלָּה, דְּבָעֵי לְאַלְטְיָיא בְּעֵינָא בִּישָׁא. וּמַה אָרְחֵיהּ. אָמַר, חָמוּ כַּמָה טָבָא דָּא. כַּמָה יָאָה דָּא. בְּגִין דְּיִשְׁלוֹט בֵּיהּ עֵינָא בִּישָׁא. אוּף הָכָא אָמַר, מַה טֹבוּ אֹהֳלֶיךָ יַעֲקֹב, כַּמָה אִינּוּן יָאָן, כַּמָה <Nonei></i>אִינּוּן שַׁפִּירָן, כַּמָה נְטִיעָן שַׁפִּירָן דְּאִתְנְטָעָן מִנַיְיהוּ, דַּמְיָין לְאִינּוּן נְטִיעִין דְּנָטַע קוּדְשָׁא בְּרִיךְ הוּא בְּגִנְתָּא דְּעֵדֶן יָאָיָין. מַאן יִתֵּן, וְאִלֵּין (נ\"א דאלין) נְטִיעָן אִשְׁתְּכָחוּ מֵאִינּוּן מִשְׁכְּנֵי, דִּבְהוּ.</p>\n<p>(במדבר כ״ד:ז׳) יִזַּל מַיִם מִדָּלְּיָו וְגוֹ'. לְבַּר נָשׁ דַּהֲווֹ לֵיהּ יְדָן שַׁפִּירָן, יָאָן לְמֵחֱזֵי. אַעְבָּר חַד בַּר נָשׁ דְּעֵינָא בִּישָׁא, אִסְתָּכַּל בְּאִינּוּן יְדִין, נָקִיט בְּהוּ, שָׁארֵי לְשַׁבְּחָא, אָמַר, כַּמָה אִינּוּן שַׁפִּירָן, כַּמָה אִינּוּן יָאָן, חָמוּ אֶצְבְּעָן מִגְּזֵרָה דְּשַׁפִּירוּ עִלָּאָה. לְבָתַר אָמַר, מַאן יִתֵּן יְדִין אִלֵּין דְּשַׁרְיָין בֵּין אֲבָנִין יַקִירִין, וּבִלְבוּשֵׁי יְקָר דְּאַרְגְּוָונָא (ס\"א בביתאי וכו' בתיבותא דיליה) בְּבֵיתֵיהּ לְאִשְׁתַּמְּשָׁא בְּהוּ, וְיֵהוֹן גְּנִיזִין בְּתֵיבוּתָא דִּילֵיהּ.</p>\n<p>כַּךְ בִּלְעָם, שָׁרֵי לְשַׁבְּחָא, מַה טֹּבוּ אֹהָלֶיךָ, חָמוּ כַּמָּה שְׁפִּירָן, כַּמָּה יָאָן וְכוּ', לְבָתַר אָמַר יִזַּל מַיִם מִדָּלְּיָו, לָא יִשְׁתְּכַּח נְטִיעָא שַׁפִּירָא דָּא, נְטִיעָא דְּאוֹרַיְיתָא, לְבַר מֵאִינּוּן מַסְכְּנִין (דליו, כלומר מסכנין) (נ\"א משכנין), וְזַרְעוֹ בְּמַיִם רַבִּים, דְּלָא יִסְגֵּי וְלָא יַרְבֵּי רוּחָא דְּקוּדְשָׁא.</p>\n<p>אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, רָשָׁע, לָא יַכְלִין עֵינַיִךְ לְאַבְאָשָׁא, הָא פְּרִיסוּ דְּקוּדְשָׁא עָלַיְיהוּ, כְּדֵין אָמַר, אֵל מוֹצִיאוֹ מִמִּצְרַיִם וְגוֹ', הָא לָא יַכְלִין כָּל בְּנֵי עָלְמָא לְאַבְאָשָׁא לוֹן, דְּהָא חֵילָא תַּקִּיפָא עִלָּאָה אָחִיד בְּהוּ, וּמַאי אִיהוּ. אֵל מוֹצִיאוֹ מִמִּצְרַיִם. וְלֹא עוֹד, אֶלָּא כְּתוֹעֲפוֹת רְאֵם לוֹ, דְּלָא יָכִיל בַּר נָשׁ לְאוֹשִׁיט יְדֵיהּ עָלֵיהּ, מִגּוֹ רוּמֵיהּ. וּמִדְּאִשְׁתְּכַח בִּזְקִיפוּ עִלָּאָה הָכִי, יֹאכַל גּוֹיִם צָרָיו וְגוֹ'. וְלֵית מַאן דְּיָכִיל לְאַבְאָשָׁא לוֹן.</p>\n<p>וַאֲפִילּוּ בְּזִמְנָא דְּלָא זָקִיף, לָא יַכְלִין, הֲדָא הוּא דִכְתִיב כָּרַע שָׁכַב. לָא דָּחִיל, בְּגִין דְּאִשְׁתְּכַח גִּיבָּר כַּאֲרִי וּכְלָבִיא, אֲפִילּוּ כַּד אִינּוּן בֵּינֵי עֲמְמַיָא, וְכָרַע וְשָׁכַב בֵּינַיְיהוּ, כַּאֲרִי הוּא יִשְׁתְּכַּח בְּנִמוּסֵי אוֹרַיְיתָא, בְּאוֹרְחֵי אוֹרַיְיתָא. (ואף על פי כן) שׁוּלְטָנוּתָא אִית לְהוּ בְּמָארֵיהוֹן, דְּאֲפִילּוּ כָּל מַלְכַיָּא דְּעָלְמָא, לָא יַעְקְרוּן לְהוּ. כְּאַרְיָא דָּא כַּד שָׁכִיב עַל טַרְפֵיהּ, לָא יַכְלִין לְאַקָּמָא לֵיהּ מִנֵּיהּ, הֲדָא הוּא דִכְתִיב כָּרַע שָׁכַב כַּאֲרִי וְגוֹ'.</p>\n<p>אָמַר רִבִּי אֶלְעָזָר, לָא אִשְׁתְּכַח בְּעָלְמָא חַכִּים לְאַבְאָשָׁא, כְּבִלְעָם רְשִׁיעָא, דְּהָא בְּקַדְמִיתָא הֲוָה אִשְׁתְּכַח בְּמִצְרַיִם, וְעַל יְדוֹי, קְשִׁירוּ מִצְרָאֵי עָלַיְיהוּ דְּיִשְׂרָאֵל קִשּׁוּרָא, דְּלָא יִפְּקוּן מֵעַבְדוּתְהוֹן לְעָלְמִין. וְדָא הוּא דְּאָמַר, מָה אֵיכוּל לְאַבְאָשָׁא לְהוּ, דְּהָא אֲנָא עֲבִידְנָא דְּלָא יִפְּקוּן מֵעֲבִידָתָא דְּמִצְרָאֵי לְעָלְמִין, אֲבָל אֵל מוֹצִיאוֹ, מִמִּצְרַיִם וּלָקֳבְלֵיהוֹן (נ\"א ולקבליה) לָא יַכְלִין חַכִּמִין וַחֲרָשִׁין דְּעָלְמָא.</p>"],[9520012507,"<p>(במדבר כ״ד:י״ד) וְעַתָּה הִנְנִי הוֹלֵךְ לְעַמִּי וְגוֹ' רִבִּי יְהוּדָה פָּתַח, (דברים כ״ג:י״ז) לֹא תַסְגִּיר עֶבֶד אֶל אֲדוֹנָיו וְגוֹ' עִמְּךָ יֵשֵׁב בְּקִרְבְּךָ. כַּמָה חֲבִיבִין מִלֵּי דְּאוֹרַיְיתָא. כַּמָה חֲבִיבָה אוֹרַיְיתָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. כַּמָה חֲבִיבָה אוֹרַיְיתָא, דְּאוֹרִית לָהּ קוּדְשָׁא בְּרִיךְ הוּא לִכְּנֶסֶת יִשְׂרָאֵל. תָּא חֲזֵי, בְּשַׁעֲתָא דִּי נַפְקוּ מִמִּצְרָיִם. שְׁמַע בִּלְעָם דְּהָא חֲרָשׁוֹי וְקִסְמוֹי, וְכָל אִינּוּן קִשְׁרִין, לָא סְלִיקוּ בְּהוּ בְּיִשְׂרָאֵל, שָׁארֵי לְגַרְרָא גַּרְמֵיהּ, וּלְמֵירַט רֵישֵׁיהּ. אָזַל לְאִינּוּן טוּרֵי חֲשׁוֹכָא, וּמָטָא לְגַבֵּי אִינּוּן שַׁלְשְׁלָאֵי דְּפַרְזְלָא.</p>\n<p>וְכַךְ הוּא אָרְחָא דְּמַאן דְּמָטֵי גַּבַּיְיהוּ, כֵּיוָן דְּעָאל בַּר נָשׁ בְּרֵישֵׁי טוּרַיָּא, חָמֵי לֵיהּ עֲזָאֵ\"ל, הַהוּא דְּאִקְרֵי גְּלוּי עֵינַיִם. מִיַּד אָמַר לַעֲזָ\"א, כְּדֵין יָהֲבִין קָלָא, וּמִתְכַּנְּשִׁין גַּבַּיְיהוּ חִוְיָין רַבְרְבֵי דִּמְתוֹקְדָן, וְסַחֲרִין לוֹן. מְשַׁדְּרֵי אוֹנִימְתָא זְעֵירְתָּא לָקֳבְלֵיהּ דְּבַּר נָשׁ, וְתָנָא, כְּמִין שׁוּנְרָא, הִיא, וְרֵישֵׁהּ כְּרֵישָׁא דְּחִוְיָיא, וּתְרֵין זַנְבִין בָּהּ, וִידָהָא וְרַגְלָהָא זְעִירִין. בַּר נָשׁ דְּחָמֵי לָהּ, חָפֵּי אַנְפּוֹי, וְהוּא מַיְיתֵי חַד קַטוּרְתָּא, מֵאוֹקִידוּ דְּתַרְנְגוֹלָא חִוָּורָא, שָׁדֵי בְּאַנְפָּהָא וְהִיא אָתְיָת עִמֵּיהּ.</p>\n<p>עַד דְּמָטֵי לְגַבֵּי רֵישָׁא דְּשַׁלְשְׁלָאֵי, וְהַהִיא רֵישָׁא דְּשַׁלְשְׁלָאֵי, נָעִיץ בְּאַרְעָא, וּמָטֵי עַד תְּהוֹמָא. וְתַמָּן בִּתְהוֹמָא. חַד סָמִיךְ, וְהוּא נָעִיץ בִּתְהוֹמָא תַּתָּאָה, וּבְהַהוּא סָמִיךְ אִתְקְשַׁר רֵישָׁא דְּשַׁלְשְׁלָאֵי. כַּד מָטֵי בַּר נָשׁ לְרֵישָׁא דְּשַׁלְשְׁלָאָה, בָּטַשׁ בָּהּ ג' זִמְנִין, וְאִינּוּן קָרָאן לֵיהּ, כְּדֵין כָּרַע וְסָגִיד עַל בִּרְכּוֹי, וְאָזִיל וְאָטִים עֵינוֹי, עַד דְּמָטֵי גַּבַּיְיהוּ. כְּדֵין יָתִיב קַמַּיְיהוּ, וְכָל אִינּוּן חִוְיָין סָחֲרִין לֵיהּ מֵהַאי סִטְרָא וּמֵהַאי סִטְרָא. פָּתַח עֵינוֹי, וְחָמֵי לוֹן, אִזְדַּעְזָע, וְנָפַל עַל אַנְפּוֹי, וְסָגִיד לָקֳבְלַיְיהוּ.</p>\n<p>לְבָתַר אוֹלְפִין לֵיהּ חֲרָשִׁין וְקִסְמִין, וְיָתִיב גַּבַּיְיהוּ <Nonei></i>נ' יוֹמִין. כַּד מָטָא זִמְנָא לְמֵיהַךְ לְאָרְחֵיהּ, הַהִיא אוֹנִימְתָא, וְכָל אִינּוּן חִוְיָין, אַזְלִין קַמֵּיהּ, עַד דְּנָפִיק מִן טוּרַיָּיא, בֵּין הַהוּא חֲשׁוֹכָא תַּקִּיפָא.</p>\n<p>וּבִלְעָם כַּד מָטָא גַּבַּיְיהוּ, אוֹדַע לוֹן מִלָּה, וְאַסְגַּר גַּרְמֵיהּ בְּטוּרַיָיא עִמְּהוֹן. וּבָעָא לְקַטְרְגָא לוֹן, לְאָתָבָא לוֹן לְמִצְרַיִם. וְקוּדְשָׁא בְּרִיךְ הוּא בִּלְבֵּל וְקִלְקֵל כָּל חָכְמְתָא דְּעָלְמָא, וְכָל חֲרָשִׁין דְּעָלְמָא, דְּלָא יָכִילוּ לְקָרְבָא בַּהֲדַיְיהוּ.</p>\n<p>תָּא חֲזֵי, הַשְׁתָּא כֵּיוָן דְּחָמָא בִּלְעָם דְּלָא יָכִיל לְאַבְאָשָׁא לְיִשְׂרָאֵל, אַהְדָּר גַּרְמֵיהּ, וְאַמְלִיךְ לֵיהּ לְבָלָק, מַה דְּלָא בָּעָא מִנֵיהּ, בְּגִין לְאַבְאָשָׁא לוֹן. וְעֵיטָא דִּילֵיהּ הֲוָה בְּאִינּוּן נוּקְבֵי דְּמִדְיָן דְּאִינּוּן שָׁפִּירָן, וְאִלְמָלֵא דְאֲמַר לֵיהּ מֹשֶׁה, לָא הֲוִינָא יָדַע, דִּכְתִּיב, (במדבר ל״א:ט״ז) הֵן הֵנָּה הָיוּ לִבְנֵי יִשְׂרָאֵל בִּדְבַר בִּלְעָם.</p>\n<p>כֵּיוָן דְּחָמָא קוּדְשָׁא בְּרִיךְ הוּא עֵיטָא דִּילֵיהּ, אָמַר, הָא וַדַּאי גַּרְמָךְ בְּעִיטֵךְ יִפּוֹל. מַה עָבֵד, הַהוּא חֵילָא דְּשָלַט עַל כָּל חֲרָשִׁין, אַחְמֵי לֵיהּ סוֹפָא דְּכֹלָּא. וְכִי אִית לְהוּ רְשׁוּתָא לִזְמַן רָחִיק. אָמַר רִבִּי יִצְחָק, עֵינָא חָמָא, וּמִלִּין אִתְמָרוּ מֵהַהוּא דְּקָאִים עָלֵיהּ, וְהָא אוּקְמוּהָ. וַיִּשָּׂא מְשָׁלוֹ וַיֹּאמַר. מַאן דְּאִית לֵיהּ לְמֵימַר. מַאי טַעְמָא. בְּגִין דְּלָא יִתְקַיְּימוּן מִלִּין דְּגָעְלָא, בִּרְעוּתָא עִלָּאָה, (ס\"א ובגין דיתקיימון מלין דלעילא) בְּדַעְתָּא עִלָּאָה בְּאוֹרַיְיתָא.</p>"],[9520012508,"<p>(במדבר כ״ד:י״ז) אֶרְאֶנּוּ וְלֹא עַתָּה, דְּהָא מִלִּין אִלֵּין מִנַּיְיהוּ אִתְקָיָּימוּ בְּהַהוּא זִמְנָא, וּמִנַּיְיהוּ לְבָתַר, וּמִנַּיְיהוּ בְּזִמְנָא דְּמַלְכָּא מְשִׁיחָא. (מה שחסר כאן תמצא בזוהר חדש דף ס\"ח ע\"א עי\"ש) תְּנָן, זַמִּין קוּדְשָׁא בְּרִיךְ הוּא לְמִבְנֵי יְרוּשָׁלַם, וּלְאַחְזָאָה חַד כֹּכָבָא קְבִיעָא, מְנַצְּצָא בְּע' רָהֲטִין, וּבְע' זִיקִין נַהֲרִין מִנֵּיהּ בְּאֶמְצָעוּת רְקִיעַ, וְיִשְׁתָּאֲלוּן בֵּיהּ ע' כֹּכָבִין אַחֲרָנִין, וִיהֵא נָהִיר וְלָהִיט ע' יוֹמִין.</p>\n<p>וּבְיוֹמָא שְׁתִיתָאָה, יִתְחֲזֵי בְּכ\"ה יוֹמִין לְיַרְחָא שְׁתִּיתָאָה, וְיִתְכְּנִישׁ בְּיוֹמָא שְׁבִיעָאָה, לְסוֹף ע' יוֹמִין, יוֹמָא קַדְמָאָה יִתְחֲזֵי בְּקַרְתָּא (חדא) דְּרוֹמָא. וְהַהוּא יוֹמָא יִנְפְּלוּן ג' שׁוּרִין עִלָּאִין מֵהַהִיא קַרְתָּא דְּרוֹמִי, וְהֵיכָלָא רַבְרְבָא יִנְפּוֹל, וְשַׁלִּיטָא דְּהַהִיא קַרְתָּא יְמוּת. כְּדֵין יִתְפָּשַּׁט הַהוּא כֹּכָבָא לְאִתְחֲזָאָה בְּעָלְמָא. וּבְהַהוּא זִמְנָא יִתְּעֲרוּן קְרָבִין תַּקִּיפִין בְּעָלְמָא, לְכָל ד' סִטְרִין, וּמְהֵימְנוּתָא לָא יִשְׁתְּכַּח בֵּינַיְיהוּ.</p>\n<p>וּבְאֶמְצָעוּת עָלְמָא, כַּד יִתְּנְהִיר הַהוּא כֹּכָבָא, בְּאֶמְצָעוּת רְקִיעָא. יְקוּם מַלְכָּא חַד רַב וְשָׁלִיט בְּעַלְמָא, וְיִתְגָּאֶה רוּחֵיהּ עַל כָּל מַלְכִין, וְיִתְּעַר קְרָבִין בִּתְרֵין סִטְרִין, וְיִתְגַּבָּר עָלַיְיהוּ.</p>\n<p>וּבְיוֹמָא דְּיִתְבְּרֵי (ס\"א דיתכסי) כֹּכָבָא, יִזְדַּעְזַע אַרְעָא קַדִּישָׁא מ\"ה מִילִּין, סַחֲרָנֵיהּ אֲתָר דְּהֲוָה בֵּי מַקְדְּשָׁא. וּמְעַרְתָּא חֲדָא מִן תְּחוֹת אַרְעָא יִתְגְּלֵי. וּמֵהַהִיא מְעַרְתָּא יִפּוּק אֶשָּׁא תַּקִּיפָא לְאוֹקְדָא עָלְמָא. וּמֵהַהִיא מְעַרְתָּא יִסְגֵּי חַד עוֹפָא (ס\"א ענפא), רַבְרְבָא עִלָּאָה, דְּיִשְׁלוֹט בְּכָל עָלְמָא, וְלֵיהּ אִתְיְהִב מַלְכוּתָא. וְקַדִּישֵׁי עֶלְיוֹנִין יִתְכַּנְּשׁוּן גַּבֵּיהּ. וּכְדֵין יִתְגְּלֵי מַלְכָּא מְשִׁיחָא בְּכָל עָלְמָא, וְלֵיהּ אִתְיְהִיב מַלְכוּתָא.</p>\n<p>וּבְנֵי עָלְמָא בְּשַׁעֲתָא דְּיִתְגְּלֵי, יֵהוֹן מִשְׁתַּכְּחִין בְּעַקְתָּא בָּתַר עַקְתָּא. וְשַׂנְאֵיהוֹן דְּיִשְׂרָאֵל יִתְגַבְּרוּן, כְּדֵין יִתְּעַר רוּחָא דִּמְשִׁיחָא עָלַיְיהוּ, וִישֵׁיצֵי לֶאֱדוֹם חַיָּיבָא, וְכָל אַרְעָא דְּשעִיר יוֹקִיד בְּנוּרָא. כְּדֵין כְּתִיב, וְיִשְׂרָאֵל עוֹשֶׂה חָיִל. הֲדָא הוּא דִכְתִיב, וְהָיָה אֱדוֹם יְרֵשָׁה וְהָיָה יְרֵשָׁה שֵׂעִיר אוֹיְבָיו. אוֹיְבָיו דְּיִשְׂרָאֵל. וּכְדֵין וְיִשְׂרָאֵל עוֹשֶׂה חָיִל. וּבְהַהוּא זִמְנָא, יָקִים קוּדְשָׁא בְּרִיךְ הוּא לְמֵתַיָּיא דְּעַמֵּיהּ, וְיִתְנָשֵׁי מִנְּהוֹן מִיתָה, הֲדָא הוּא דִכְתִיב, (תהילים קי״ח:ט״ז-י״ז) יְמִין יְיָ עֹשָׂה חָיִל. לֹא אָמוּת כִּי אֶחְיֶה. וּכְתִיב (עובדיה א׳:כ״א) וְעָלוּ מוֹשִׁיעִים וְגוֹ'. וּכְדֵין (זכריה י״ד:ט׳) וְהָיָה יְיָ לְמֶלֶךְ.</p>\n<p>אָמַר רִבִּי אַבָּא, מַאי דִּכְתִּיב, (ישעיה נה) כִּי בְּשִׂמְחָה תֵצֵאוּ וְגוֹ'. אֶלָּא כַּד יִפְּקוּן יִשְׂרָאֵל מִן גָּלוּתָא, שְׁכִינְתָּא נָפְקָא עִמְּהוֹן, וְעִמָהּ יִפְּקוּן. הֲדָא הוּא דִּכְתִּיב, (ישעיה נה) כִּי בְשִׂמְחָה תֵצֵאוּ. שָׂשׂוֹן דָּא קוּדְשָׁא בְּרִיךְ הוּא. רִבִּי יִצְחָק אָמַר דָּא צַדִּיק. הֲדָא הוּא דִּכְתִּיב, (ישעיה נה) שָׂשׂוֹן וְשִׂמְחָה יִמָּצֵא בָהּ.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, צַדִּיק שָׂשׂוֹן אִקְרֵי. וּמִן יוֹמָא דִכְּנֶסֶת יִשְׂרָאֵל נַפְלַת בְּגָלוּתָא. אִתְמְנָעוּ בִּרְכָּן מִלְּנַחְתָּא לְעָלְמָא מֵהַאי צַדִּיק. בְּהַהוּא זִמְנָא מַה כְּתִיב, (ישעיהו י״ב:ג׳) וּשְׁאַבְתֶּם מַיִם בְּשָׂשׂוֹן, דָּא צַדִּיק. מִמַּעַיְינֵי הַיְשׁוּעָה, אִלֵּין אַבָּא וְאִמָא. דָּבָר אַחֵר, אִלֵּין נֶצַ\"ח וְהוֹ\"ד. וְכֹלָּא מִמַּבּוּעֵי נְבִיעִין עֲמִיקִן. כְּדֵין (ישעיהו י״ב:א׳) וְאָמַרְתָּ בַּיוֹם הַהוּא אוֹדְךָ יְיָ וְגוֹ', (ישעיהו י״ב:א׳) צַהֲלִי וָרֹנִּי יֹשֶׁבֶת צִיּוֹן וְגוֹ'. בָּרוּךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן. יִמְלוֹךְ יְיָ לְעוֹלָם אָמֵן וְאָמֵן.</p>"],[9520012509,"<p><Nonei></i>(במדבר כ״ה:י׳) וַיְדַבֵּר יְיָ אֶל מֹשֶׁה לֵאמֹר, פִּנְחָס בֶּן אֶלְעָזָר וְגוֹ', רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (משלי א׳:ח׳) שְׁמַע בְּנִי מוּסַר אָבִיךָ וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ. (יתרו פ\"ה ע\"א) שְׁמַע בְּנִי מוּסַר אָבִיךָ, דָּא קוּדְשָׁא בְּרִיךְ הוּא. וְאַל תִּטּוֹשׁ תּוֹרַת אִמֶּךָ, דָּא כְּנֶסֶת יִשְׂרָאֵל. מַאי מוּסַר אָבִיךָ, מוּסַר, דָּא אוֹרַיְיתָא, דְּאִית בָּהּ כַּמָּה תּוֹכָחִין, כַּמָּה עוֹנָשִׁין. כְּמָה דְאַתְּ אָמֵר, (משלי ג׳:י״א) מוּסַר יְיָ בְּנִי אַל תִּמְאָס וְאַל תָּקוֹץ בְּתוֹכַחְתּוֹ.</p>\n<p>וּבְגִין דְּכָל מַאן דְּאִשְׁתְּדַּל בְּאוֹרַיְיתָא בְּהַאי עָלְמָא, זָכֵי דְּיִפְתְּחוּן לֵיהּ כַּמָּה תַּרְעִין לְהַהוּא עָלְמָא, כַּמָּה נְהוֹרִין. בְּשַׁעֲתָא דְּיִנְפּוֹק מֵהַאי עָלְמָא, הִיא אַקְדִימַת קַמֵּיהּ, וְאַזְלָא לְכָל נְטוּרֵי תַּרְעִין, מַכְרֶזֶת וְאוֹמֶרֶת, (ישעיהו כ״ו:ב׳) פִּתְחוּ שְׁעָרִים וְיָבֹא גּוֹי צַדִּיק. אַתְקִינוּ כֻּרְסְיָין לִפְלָנַיָּא עַבְדָּא דְּמַלְכָּא. דְּלֵית חֲדוּ לְּקוּדְשָׁא בְּרִיךְ הוּא אֶלָּא מַאן דְּאִשְׁתְּדַל בְּאוֹרַיְיתָא, כָּל שֶׁכֵּן בַּר נָשׁ דְּמִתְעַר בְּלֵילְיָא לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, דְּהָא כָּל צַדִיקַיָּיא דִּבְגִּנְתָּא דְּעֵדֶן, צַיְיתִין לְקַלֵּיהּ, וְקוּדְשָׁא בְּרִיךְ הוּא מִשְׁתְּכַח בֵּינַיְיהוּ, כְּמָה דְּאוּקְמוּהָ (שיר השירים ח׳:י״ג) הַיּוֹשֶׁבֶת בַּגַנִּים חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ הַשְׁמִיעִינִי.</p>"],[9520012510,"<p>רַבִּי שִׁמְעוֹן אָמַר הַאי קְרָא רָזָא דְּחָכְמְתָא אִית בֵּיהּ. הַיּוֹשֶׁבֶת בַּגַנִּים, דָּא כְּנֶסֶת יִשְׂרָאֵל, דְּאִיהִי בְּגָלוּתָא עִם יִשְׂרָאֵל, וְאַזְלָא עִמְּהוֹן בְּעַקְתַּיְיהוּ. חֲבֵרִים מַקְשִׁיבִים לְקוֹלֵךְ, מַשִׁרְיָין עִלָּאִין. כֻּלְּהוּ צַיְיתִין לְקוֹלֵךְ, לְקוֹל תּוּשְׁבַּחְתֵּךְ בְּגָלוּתָא. הַשְׁמִיעִינִי, כְּמָה דְאַתְּ אָמֵר (שיר השירים ב׳:י״ד) הַרְאִינִי אֶת מַרְאַיִךְ הַשְׁמִעִינִי אֶת קוֹלֵךְ. הַשְׁמִעִינִי, קָלָא דְּאִינּוּן חַבְרַיָּיא דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא דְּהָא לֵית תּוּשְׁבַּחְתָּא קַמָּאי, כְּאִינּוּן דְּמִשְׁתַּדְּלֵי בְּאוֹרַיְיתָא.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, כִּבְיָכוֹל, כָּל אִינּוּן דְּזַכָּאן לְאִשְׁתַּדְּלָא בְּאוֹרַיְיתָא, וּמִכַּד פָּלִיג לֵילְיָא, וְאַתְיָין בְּמַטְרוֹנִיתָא כַּד נָהִיר יְמָמָא, לְקַבְּלָא אַנְפֵּי מַלְכָּא, אַתְקִיף וְאַחֲסִין בִּשְׁכִינְתָּא. וְלֹא עוֹד, אֶלָּא דְּשַׁרְיָא בֵּיהּ חוּט שֶׁל חֶסֶד, כְּמָה דְּאוֹקִימְנָא.</p>\n<p>תָּא חֲזֵי, כָּל מַאן דְּזָכֵי לְאִתְתָּקַף בִּשְׁכִינְתָּא, יִסְתְּמַר גַּרְמוֹהִי מֵאִנּוּן מִלִּין דַּאֲחִידָן לָקֳבְלָהּ. כְּגוֹן מַאן. אִינּוּן דְּלָא מְשַׁקְּרֵי בְּאָת קַדִישָׁא, כְּגוֹן בַּת אֵל נֵכָר. וְכָל מַאן דְּנָטִיר גַּרְמֵיהּ, כִּבְיָכוֹל כְּנֶסֶת יִשְׂרָאֵל אֲחִידָא בֵּיהּ, וְנַטְרָא לֵיהּ, וְהִיא אַקְדִּימַת לֵיהּ שְׁלָם. וְכָּל שֶׁכֵּן אִי זָכֵי וְקָּנֵי לְהַאי.</p>\n<p>וְאָמַר רַבִּי שִׁמְעוֹן, אִתְחַזְיָין יִשְׂרָאֵל לְאִשְׁתֵּצָאָה בְּהַהוּא שַׁעֲתָא, בַּר דְּאַקְדִים פִּנְחָס לְהַאי עוֹבָדָא, וְשָׁכִיךְ רוּגְזָא. הֲדָא הוּא דִכְתִיב, פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הֵשִׁיב וְגוֹ'. דָּבָר אַחֵר, פִּנְחָס בֶּן אֶלְעָזָר וְגוֹ'. אָמַר רַבִּי שִׁמְעוֹן, בֶּן בֶּן תְּרֵי זִמְנֵי, לְאַשְׁלְמָא אוֹבָדָא (נ\"א עובדא) קָא אָתֵי.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, הַאי בַּר נָשׁ דְּנָטִיל גִּלְגוּלָא דְּנִשְׁמְתָא, וְלָא זָכֵי דְּיִתְתָּקַּן בֵּיהּ, כְּאִילּוּ מְשַׁקֵּר בְּקוּשְׁטָא דְּמַלְכָּא. וַאֲנָא קָרֵינָּא עָלֵיהּ הַאי קְרָא (ויקרא ה׳:כ״ב) אוֹ מָצָא אֲבֵידָה וְכִחֶשׁ בָּהּ וְנִשְׁבַּע עַל שָׁקֶר. וְכִחֶשׁ בָּהּ, טַב לֵיהּ דְּלָא אִבְרֵי.</p>"],[9520012511,"<p>תָּנֵינָן צַדִּיק גָּמוּר, אֵינוֹ נִדְחֶה. וְצַדִּיק שֶׁאֵינוֹ גָּמוּר, נִדְחֶה. מַאן הוּא צַדִּיק גָּמוּר, וּמַאן הוּא צַדִּיק שֶׁאֵינוֹ גָּמוּר, וְכִי מַאן דְּלָא שְׁלִים בְּמִלּוֹי, צַדִּיק אִקְרֵי. אֶלָּא, צַדִּיק גָּמוּר, יְדִיעַ, דְּהָא לָא נָטִיל גִּלְגוּלִין עַקִימִּין, וּבְאַחֲסַנְתֵּיה בָּנֵי בִּנְיָין, וְאַתְקִין שׁוּרִין, וְחָצַב בֵּירִין, וְנָטַע אִילָנִין.</p>\n<p>צַדִיק שֶׁאֵינוֹ גָּמוּר, דְּבָנֵי בִּנְיָין בְּאַחֲסַנְתָּא אָחֳרָא, חָפַר בָּהּ בֵּירִין, וְאַעְדָּר, הָא אַתְקִין אַבְנֵי יְסוֹדָא כְּמִלְּקַדְּמִין, וְאַעְמַל בָּהּ, וְלָא יָדַע אִי אִשְׁתְּאַר דִּילֵיהּ. מִסִּטְרָא דִּילֵיהּ, טַב וְצַדִיק אִקְרֵי. וּמִסִּטְרָא דְּהַהוּא אַחֲסַנְתָּא, לָאו הָכִי.</p>\n<p>לְבַּר נָשׁ דְּבָנֵי בִּנְיָין שְׁפִּירָן, יָאָן לְמֵחֱזֵי, אִסְתָּכַּל בִּיסוֹדָא, וְחָמֵי לֵיהּ שְׁקִיעַ עֲקִימָא מִכָל סִטְרִין. הָא בִּנְיָינָא לָא שְׁלִים, עַד דְּסָתַר לֵיהּ, וְאַתְקִין לֵיהּ כְּמִלְּקַדְּמִין. מִסִּטְרָא דְּהַהוּא בִּנְיָינָא דִּילֵיהּ, אִשְׁתְּכַח טַב וְשַׁפִּיר. <Nonei></i>מִסִּטְרָא דִּיְסוֹדָא, בִּישׁ וְעָקִים. וּבְגִין כַּךְ, לָא אִקְרֵי עוֹבָדָא שְׁלִים, לָא אִקְרֵי בִּנְיָינָא שְׁלִים. בְּגִין כָּךְ צַדִיק שֶׁאֵינוֹ גָּמוּר אִקְרֵי, וְנִדְחֶה. וְעַל דָּא (חבקוק א׳:י״ג) כְּבַלַּע רָשָׁע צַדִּיק מִמֶּנּוּ.</p>\n<p>תָּא חֲזֵי, מַאן דִּמְקַנֵּא לִשְׁמָא קַדִישָׁא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאֲפִילּוּ לָא יִזְכֵי לַגְּדּוּלָה, וְלָא אִתְחֲזֵי לָהּ, (ס\"א דירית לה) רָוַוח לָהּ וְנָטִיל לָהּ. וְדָא יָרִית לָהּ וְעָיִיל לָהּ. פִּנְחָס לָא אִתְחֲזֵי לֵיהּ בְּהַהוּא זִמְנָא, וּבְגִין דְּקִנֵּא לִשְׁמָא דְּמָארֵיהּ, רָוַוח לְכֹלָּא, וְסָלִיק לְכֹלָּא, וְאִתְתָּקַּן בֵּיהּ כֹּלָּא וְזָכָה לְאִשְׁתַּמְּשָׁא בִּכְהוּנָה עִלָּאָה. מֵהַהִיא שַׁעֲתָא, פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, דְּאַשְׁלִים לִתְרֵין דַּרְגִּין, בְּגִין דְּקַנֵּא לִשְׁמָא דְּמָארֵיהּ, דְּאִתְתְּקַן מַה דְּאִתְעַקָּם.</p>"],[9520012512,"<p>רִבִּי יְהוּדָה פָּתַח וְאָמַר, (תהילים פ״ו:ב׳) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי הוֹשַׁע עַבְדְךָ וְגוֹ'. סוֹפֵיהּ דִּקְרָא אִית לְאִסְתַּכְּלָא, וּלְבָתַר קְרָא כֹּלָּא, סוֹפֵיהּ דִּקְרָא כְּתִיב, הַבּוֹטֵחַ אֵלֶיךָ, הַבּוֹטֵחַ בָּךְ מִבָּעֵי לֵיהּ, מַאי הַבּוֹטֵחַ אֵלֶיךָ. אֶלָּא כִּבְיָכוֹל דָּוִד מַבְטַח לֵיהּ, דְּלָא יַעְבַּר לֵיהּ פַּלְגוּת לֵילְיָא בְּשִׁנְתָּא, כְּמָה דִּכְתִּיב, (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. קַמְתִּי מִבָּעֵי לֵיהּ. אֶלָּא, אָקוּם, וְאֶתְקְשַׁר בָּךְ לְעָלְמִין.</p>\n<p>שָׁמְרָה נַפְשִׁי, שְׁמוֹר מִבָּעֵי לֵיהּ. וְהָא תָּנֵינָן דְּלֵית אָת בְּאוֹרַיְיתָא דְּלָא אִית בָּהּ רָזִין עִלָּאִין וְיַקִּירִין. שָׁמְרָה. לְּקוּדְשָׁא בְּרִיךְ הוּא קָאָמַר, שָׁמְרָה לְהַהוּא חוּלָקָא, דְּאִתְאֲחָד בֵּיהּ נֶפֶשׁ. דְּכַד נַפְשָׁא נָפְקָאת מֵהַאי עָלְמָא, אַתְיָא לְמֵירַת עָלְמָא (דאתי). אִי זָכֵי, כַּמָה חֵילִין עִלָּאִין נָפְקִין לָקֳבְלָא, וּלְנַטְרָא לָהּ, וּלְאַעֲלָא לָהּ בְּמָדוֹרָא דְּדוּכְתָהָא, וְהַאי ה' נָטִיל לָהּ, לְאִתְאַחֲדָא עִמָּהּ בְּרֵישׁ יַרְחֵי וְשַׁבַּתֵּי.</p>\n<p>וְאִי לָא זָכֵי, כַּמָה גַּרְדִּינֵי טְהִירִין אִזְדַמְּנָן לָקֳבְלָהּ, וְדָחוּ לָהּ לְבַר. וַוי לְהַהִיא נַפְשָׁא, דְּמִתְגַּלְגְּלָא בְּרֵיקָנַיָּא, כְּאַבְנָא בְּקוּסְפִיתָא. הֲדָא הוּא דִכְתִיב, (שמואל א כ״ה:כ״ט) וְאֵת נֶפֶשׁ אוֹיְבֶיךָ יְקַלְעֶנָּה בְּתוֹךְ כַּף הַקָּלַע. וְדָוִד בָּעֵי בָּעוּתֵיהּ קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא וְאָמַר, שָׁמְרָה נַפְשִׁי, דְּלָא יִדְחוּן לָהּ לְבַר. וְכַד מָטֵי (ס\"א לקבלך, יפתחון לך) לָקֳבְלָהּ, יִפְתְּחוּן לָהּ פִּתְחִין, וּתְקַבֵּל לָהּ קַמָּךְ. כִּי חָסִיד אָנִי, וְכִי חָסִיד אִקְרֵי. אָמַר רִבִּי יְהוּדָה, אִין. דִּכְתִיב, (ישעיהו נ״ה:ג׳) חַסְדֵי דָּוִד הַנֶּאֱמָנִים. בְּגִין כַּךְ שָׁמְרָה נַפְשִׁי, דְּלָא תִּשְׁבּוֹק לָהּ לְמֵהַךְ לְבַר.</p>\n<p>רִבִּי יִצְחָק אָמַר, כָּל בַּר נָשׁ דְּאִית לֵיהּ חוּלָקָא בְּצַדִּיק, יָרִית לְהַאי אֶרֶץ, כְּמָה דִּכְתִּיב, (ישעיהו ס׳:כ״א) וְעַמֵּךְ כֻּלָּם צַדִּיקִים וְגוֹ'. וְהַאי צַדִיק חָסִיד אִקְרֵי. אָמַר דָּוִד בָּתַר דִּבְהַאי אֲתָר אֲחִידְנָא, חָסִיד אָנִי, וּבְגִין כָּךְ שָׁמְרָה נַפְשִׁי, לְאִתְקַשְּׁרָא בָּךְ.</p>"],[9520012513,"<p>רִבִּי חִיָּיא פָּתַח, (תהילים פ״א:ו׳) עֵדוּת בִּיהוֹסֵף שָׂמוֹ וְגוֹ'. הָא אוֹקְמוּהָ, דְּאוֹלִיף שִׁבְעִין פִּתְקִין, וְלָשׁוֹן הַקֹּדֶשׁ יַתִיר. הֲדָא הוּא דִכְתִיב, (תהילים פ״א:ו׳) שְׂפַת לֹא יָדַעְתִּי אֶשְׁמָע. אֲבָל מַאי עֵדוּת. תָּא חֲזֵי, בְּשַׁעֲתָא דְּאִתְּתֵיהּ דְּפוֹטִיפַר הֲוַת אֲחִידָא בֵּיהּ לְהַהִיא מִלָּה, הֲוָה יוֹסֵף עָבִיד גַּרְמֵיהּ כְּמַאן דְּלָא יָדַע לִישָׁנָא דִּילָהּ, וְכֵן בְּכָל יוֹמָא עַד הַהִיא שַׁעֲתָא בַּתְרַיְיתָא, דִּכְתִיב (בראשית ל״ט:י״ב) וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ. מַאי וַתִּתְפְּשֵׂהוּ. אֶלָּא בְּגִין דְּעָבִיד גַּרְמֵיהּ כְּמַאן דְּלָא יָדַע לִישָׁנָא. וְרוּחַ הַקֹּדֶשׁ צָוַוח לָקֳבְלֵיהּ, (משלי ז׳:ה׳) לִשְׁמָרְךָ מֵאִשָׁה זָרָה מִנָּכְרִיָּה אֲמָרֶיהָ הֶחלִיקָה. מַאי קָא מַשְׁמַע לָן. אֶלָּא כָּל מַאן דְּנָטִיר גַּרְמֵיהּ מֵהַאי, אִתְקְשַׁר בָּהּ בִּשְׁכִינְתָּא, וְאָחִיד בְּהַהוּא עֵדוּת. וּמַאי הוּא. ה' דְּאִתּוֹסַף בֵּיהּ. דִּכְתִיב, עֵדוּת בִּיהוֹסֵף שָׂמוֹ. אוּף הָכָא י' אִתּוֹסַף בְּפִנְחָס, עַל דְּקַנֵּי בְּהַאי.</p>"],[9520012514,"<p>רִבִּי יֵיסָא פָּתַח, (תהילים קל״ז:א׳) עַל נַהֲרוֹת בָּבֶל שָׁם יָשַׁבְנוּ גַּם בָּכִינוּ בְּזָכְרֵנוּ אֶת צִיּוֹן. אֶת יְרוּשָׁלַם מִבָּעֵי לֵיהּ, כְּמָה דִּכְתִּיב, (תהילים קל״ז:א׳) אִם אֶשְׁכָּחֵךְ יְרוּשָׁלַ ם תִּשְׁכַּח יְמִינִי, מַאי בְּזָכְרֵנוּ אֶת צִיּוֹן. לְבַּר נָשׁ דְּהֲוָה לֵיהּ הֵיכָלָא יַקִירָא, יָאָה וְשַׁפִּירָא, אָתוּ לִסְטִין וְאוֹקִידוּ לֵיהּ. צַעֲרָא דְּמַאן הוּא, לָאו דְּמָארֵיהּ דְּהֵיכָלָא. אוּף הָכָא שְׁכִינְתָּא בְּגָלוּתָא שַׁרְיָא, צַעֲרָא דְּמַאן הוּא, לָאו דְּצַדִּיק. וְאַזְלָא הָא כְּמָה דְּאוּקְמוּהָ, דִּכְתִיב (ישעיהו נ״ז:א׳) הַצַּדִּיק אָבָד, אָבָד מַמָּשׁ. אוּף הָכָא בְּזָכְרֵנוּ אֶת צִיּוֹן, בְּזָכְרֵנוּ הַהוּא צַעֲרָא דִּילֵיהּ עַל זִוּוּגָהָא, צַעֲרָא דִּילֵיהּ הוּא.</p>\n<p>אָמַר רִבִּי יֵיסָא, מַאן דְּאוֹקִיר שְׁמָא דְּמָארֵיהּ בְּהַאי, וְנָטִיר הַאי, זָכָה דְּיוֹקִיר לֵיהּ מָארֵיהּ עַל כֹּלָּא. מְנָלָן. מִיּוֹסֵף. דִּכְתִּיב, (בראשית מ״א:מ״ג) וַיַּרְכֵּב אוֹתוֹ בְּמִרְכֶּבֶת הַמִּשְׁנֶה אֲשֶׁר לוֹ, וּכְתִיב וְנָתֹן אוֹתוֹ עַל כָּל אֶרֶץ מִצְרָיִם <Nonei></i>וְלֹא עוֹד, אֶלָּא כַּד עָבְרוּ יִשְׂרָאֵל יַת יַמָּא, אֲרוֹנָא דְּיוֹסֵף עָאל בְּגוֹ בְּקַדְמִיתָא, וְלָא הֲווֹ מַיָּא קַיְימִין עַל קִיוּמַיְיהוּ קַמֵּיהּ, הֲדָא הוּא דִּכְתִיב, (תהילים קי״ד:ג׳) הַיָּם רָאָה וַיָּנוֹס. מַאי וַיָּנוֹס. אֶלָּא רָאָה הַהוּא דִּכְתִיב בֵּיהּ (בראשית ל״ט:י״ב) וַיָּנָס וַיֵּצֵא הַחוּצָה.</p>\n<p>תָּא חֲזֵי, זָכֵי לִיקָרָא בְּחַיּיוֹי וְזָכֵי לִיקָרָא בְּמִיתָתֵיהּ. בְּחַיָיו אֲמַאי. בְּגִין הַהוּא זְמַן דְּלָא בָּעָא לְאִתְדַּבְּקָא בָּהּ, דִּכְתִּיב, (בראשית ל״ט:י׳) וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדֹנָיו. וּכְתִיב וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ. בְּגִין כַּךְ זָכָה בְּהַאי עָלְמָא. כֵּיוָן דִּכְתִּיב וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ, וּכְתִיב וַיָנָס וַיֵּצֵא הַחוּצָה, זָכֵי לְבָתַר דְּעָאל לְגוֹ פָּרוֹכְתָּא עִלָּאָה, וְהָכִי אִתְחֲזֵי לֵיהּ, דִּידֵיהּ נָטַל בְּהַאי עָלְמָא, וְדִידֵיהּ נָטַל בְּעָלְמָא אַחֲרָא.</p>\n<p>פִּנְחָס זָכֵי בְּהַאי עָלְמָא, וְזָכָה בְּעָלְמָא דְּאָתֵי, וְזָכָה לְקַיְּימָא יַתִיר מִכָּל אִינּוּן דְּנַפְקוּ מִמִּצְרַיִם, וְזָכָה לְכַהֲנָא עִלָּאָה, הוּא וְכָל בְּנוֹי אֲבַּתְרֵיהּ. וְאִי תֵּימָא דְּלָא (נ\"א דהא) זָכָה לְכַהֲנָא עַד לָא עָבֵד עוֹבָדָא דָּא. אִין (ס\"א לא). דְּהָא אִינּוּן דְּאַמְרֵי (דלא) דְּזָכָה קוֹדֶם. לָאו הָכִי אֶלָּא בְּמַאי אוֹקִימְנָא תַּחַת אֲשֶׁר קִנֵּא לֵאלֹהָיו, דְּמַשְׁמַע דִּבְגִין עוֹבָדָא דָּא רָוַוח כְּהוּנָתָא, מַה דְּלָא הֲוָה קוֹדֶם.</p>\n<p>תָּא חֲזֵי, כָּל כֹּהֵן דְּקָטִיל נֶפֶשׁ, פָּסִיל לֵיהּ כְּהוּנָתֵיהּ לְעָלְמִין. דְּהָא וַדַּאי פָּסִיל הַהוּא דַּרְגָּא דִּילֵיהּ לְגַבֵּיהּ. וּפִנְחָס מִן דִּינָא פָּסִיל לְכַהֲנָא הֲוָה, וּבְגִין דְּקַנֵּא לֵיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, אִצְטְרִיךְ לְיַחֲסָא לֵיהּ כְּהוּנַת עָלְמִין, לֵיהּ, וְלִבְנוֹי אֲבַּתְרֵיהּ, לְדָרֵי דָּרִין. אָמַר רִבִּי יִצְחָק, תָּא חֲזֵי, רָשִׁים הוּא פִּנְחָס לְעֵילָּא, וְרָשִׁים הוּא לְתַתָּא, עַד לָא יִפּוּק לְעָלְמָא דְּהָא עִם אִינּוּן דְּנַפְקוּ מִמִּצְרַיִם אִתְמְנֵי.</p>\n<p>רִבִּי אֶלְעָזָר וְרִבִּי יוֹסֵי וְרִבִּי חִיָּיא, הֲווֹ אָזְלֵי בְּמַדְבְּרָא, אָמַר רִבִּי יוֹסֵי, הָא דִּכְתִּיב בְּפִנְחָס הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. שָׁלוֹם מִמַּלְאַךְ הַמָּוְת, דְּלָא שַׁלִּיט בֵּיהּ לְעָלְמִין, וְלָא אִתְדָּן בְּדִינוֹי. וְאִי תֵּימָא דְּלָא מִית. וַדַּאי לָא מִית כִּשְׁאַר בְּנֵי עָלְמָא, וְאוֹרִיךְ יוֹמִין עַל כָּל בְּנֵי דָּרָא, בְּגִין דִּבְהַאי בְּרִית עִלָּאָה אָחִיד, וְכַד אִסְתְּלַּק מֵעָלְמָא, בְּתִיאוּבְתָא עִלָּאָה וּבִדְבִיקוּתֵיהּ שַׁפִּירָא אִסְתַּלָּק מִשְּׁאַר בְּנֵי עָלְמָא.</p>"],[9520012515,"<p>רִבִּי אֶלְעָזָר פָּתַח וְאָמַר, (זכריה ג׳:א׳) וַיַּרְאֵנִי אֶת יְהוֹשֻׁעַ הַכֹּהֵן הַגָּדוֹל עוֹמֵד לִפְנֵי מַלְאַךְ יְיָ וְגוֹ'. תָּא חֲזֵי, וַוי לְאִינּוּן בְּנֵי נָשָׁא, דְּלָא מִסְתַּכְּלָאן בִּיקָרָא דְּמָארֵיהוֹן, וְכָל יוֹמָא וְיוֹמָא כָּרוֹזָא קָארֵי עָלַיְיהוּ, וְלָא מַשְׁגִּיחִין. אָתָא בַּר נָשׁ לְאִסְתַּכְּלָא בְּפִקּוּדֵי אוֹרַיְיתָא, כַּמָה סַנֵּיגוֹרִין קַיְימִין לְאַדְכְּרָא עָלֵיהּ לְטָב. אָתָא בַּר נָשׁ וְאַעְבַּר עַל פִּקּוּדֵי אוֹרַיְיתָא, אִינּוּן עוֹבָדִין קַטֵיגוֹרִין עָלֵיהּ לְבִישׁ, קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. יְהוֹשֻׁעַ כֹּהֵן גָּדוֹל הֲוָה, וְאוֹקְמוּהָ, מַה כְּתִיב בֵּיהּ. וְהַשָּׂטָן עוֹמֵד עַל יְמִינוֹ לְשִׂטְנוֹ. וּמַה בְּהַאי כַּךְ, בִּשְׁאַר בְּנֵי עָלְמָא דְּלָא מִסְתַּכְּלֵי בִּיקָרָא דְּמָארֵיהוֹן, עַל אַחַת כַּמָּה וְכַמָּה.</p>\n<p>חָמֵי מַה כְּתִיב, וִיהוֹשֻׁעַ הָיָה לָבוּשׁ בְּגָדִים צוֹאִים, וְאוֹקְמוּהָ. אֲבָל בְּגָדִים צוֹאִים, וַדַּאי אִינּוּן לְבוּשִׁין דְּאִתְלַבְּשָׁא בֵּיהּ רוּחָא בְּהַהוּא עָלְמָא. זַכָּאָה חוּלָקֵיהּ דְּמַאן דִּלְבוּשׁוֹי מִתְתַקְּנִין וּשְׁלֵמִין בְּהַהוּא עָלְמָא. וְהָא אִתְּמַר, כָּל מַאן דְּבַעְיָין לְאַעֲלָא לַגֵיהִנָם, אִינּוּן לְבוּשִׁין דִּמְלַבְּשִׁין לֵיהּ, הֵיךְ אִינּוּן. מַה כְּתִיב הָכָא, וִיהוֹשֻׁעַ הָיָה לָבוּשׁ בְּגָדִים צוֹאִים וְעוֹמֵד לִפְנֵי הַמַּלְאָךְ. מַאן מַלְאָךְ. דָּא מַלְאָךְ דִּמְמָנָא עַל גֵּיהִנָּם, וּמְמָנָא עַל מַאן דְּחָמֵי בְּאִינּוּן לְבוּשִׁין. עַד דְּאָתִיב קָלָא וְאָמַר, הָסִירוּ הַבְּגָדִים הַצּוֹאִים מֵעָלָיו.</p>\n<p>מֵהָכָא אִית לְאִסְתַּכְּלָא, דְּעוֹבָדִין בִּישִׁין דְּבַּר נָשׁ, עַבְדִין לֵיהּ אִינּוּן לְבוּשִׁים צוֹאִים. וַיֹּאמֶר אֵלָיו רְאֵה הֶעֱבַרְתִּי מֵעָלֶיךָ עֲוֹנֶךָ וְהַלְבֵּשׁ אוֹתְךָ מַחֲלָצוֹת. אַלְבִּישִׁינֵיהּ לְבוּשִׁין אַחֲרָנִין מְתֻתְקְנָן, דִּבְהוּ אִסְתָּכַּל בַּר נָשׁ בְּזִיו יְקָרָא דְּמָארֵיהּ.</p>\n<p>תָּא חֲזֵי, כְּגַוְונָא דָּא פִּנְחָס, דְּלָא אִסְתַּלָּק מֵעָלְמָא, עַד דְּאִתְתְּקָנוּ קַמֵּיהּ לְבוּשִׁין אַחֲרָנִין, דְּרוּחָא אִתְהֲנֵי בְּהוּ, לְעָלְמָא <Nonei></i>דְּאָתֵי. בְּשַׁעֲתָא חֲדָא אִתְפְּשָּׁט מֵאִלֵּין. וְאִתְלְבָּשׁ בְּאִלֵּין, לְקַיְּימָא דִּכְתִּיב הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. עַד דַּהֲווֹ אָזְלֵי, שִׁמְשָׁא הֲוָה תַּקִּיפָא, וְיָתְבוּ תְּחוֹת צִלָּא דְּחַד טִנָרָא דְּמַדְבְּרָא. אָמַר רִבִּי אֶלְעָזָר, וַדַּאי צִלָּא חֶדְוָותָא דְּנַפְשָׁא הוּא.</p>"],[9520012516,"<p>אָמַר רִבִּי חִיָּיא לְרִבִּי אֶלְעָזָר, אִלֵּין יוֹמִין, מֵרֹאשׁ הַשָּׁנָה עַד יוֹמָא בַּתְרָאָה דְּחַג, בָּעֵינָא לְמֵיקָם עָלַיְיהוּ. אָמַר רִבִּי אֶלְעָזָר, הָא אִתְּמַר וְחַבְרַיָּיא אִתְעָרוּ בְּהוּ. אָמַר רִבִּי חִיָּיא, וַדַּאי הָכִי הוּא, אֲבָל אֲנָא שְׁמַעְנָא לְבוּצִינָא קַדִישָׁא עִלָּאָה מִלָּה בְּהוּ. אָמַר לֵיהּ, אֵימָא הַהוּא מִלָּה. אָמַר לֵיהּ עַד לָא קָאִימְנָא בֵּיהּ. אָמַר רִבִּי אֶלְעָזָר, אַף עַל גַּב דְּחַבְרַיָּיא אוֹקְמוּ מִלָּה, וְשַׁפִּיר הוּא, אֲבָל סִדּוּרָא דְּהָנֵי יוֹמֵי, רָזָא דְּחָכְמְתָא הוּא, בֵּין מְחַצְּדֵי חַקְלָא.</p>\n<p>תָּא חֲזֵי, הָא אִתְּמַר סִדּוּרָא דְּיִחוּדָא כֹּלָּא בְּחַד הֵיךְ הֲוִי. וְהָא אִתְּמַר. פָּתַח וְאָמַר, (ישעיהו נ״ב:י׳) חָשַׂף יְיָ אֶת זְרוֹעַ קָדְשׁוֹ, דָּא דְּרוֹעָא חֲדָא, דְּבֵיהּ תַּלְיָא יְשׁוּעָה, דְּבֵיהּ תַּלְיָא נוּקְמָא, דְּבֵיהּ תַּלְיָא פּוּרְקָנָא. וְלָמָּה, לְמֵיקָם לָהּ לְכְנֶסֶת יִשְׂרָאֵל מֵעַפְרָא, וּלְקַבְּלָא לָהּ לְגַבֵּיהּ, לְאִזְדַוְּוגָא כַּחֲדָא. וְכַד הַאי אִתְעַר לְקַבְּלָהּ, כַּמָה דְּחִילוּ שַׁרְיָא בְּעָלְמָא, עַד דְּיָנַח הַהוּא דְּרוֹעָא תְּחוֹת רֵישָׁהָא לְאִתְחַבְּרָא. כְּמָה דְּאַתְּ אָמַר, (שיר השירים ב׳:ו׳) שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי וְגוֹ', וּכְדֵין נַיְיחָא דִּינָא, וּמְכַפֵּר חוֹבִין.</p>\n<p>לְבָתַר אָתֵי יְמִינָא לְחַבְּקָא, כְּדֵין חֶדְוָותָא שַׁרְיָיא בְּעָלְמָא, וְכָל אַנְפִּין נְהִירִין. לְבָתַר אִזְדַוְּוגַת בְּגוּפָא, וּכְדֵין כֹּלָּא אִקְרֵי אֶחָד, בְּלָא פִּרוּדָא, כְּדֵין הוּא שְׁלִימוּ דְּכֹלָּא, וְחֶדְוָותָא דְּכֹלָּא, וְאָחִידוּ ודַּאי, מַה דְּלָא אִשְׁתְּכַח הָכִי בִּשְׁאַר זִמְנֵי.</p>\n<p>כְּגַוְונָא דְּהַאי, סִדּוּרָא דְּהָנֵי יוֹמִין, מֵרֹאשׁ הַשָּׁנָה עַד יוֹמָא בַּתְרָאָה דְּחַג. בְּרֹאשׁ הַשָּׁנָה, אִתְעַר דְּרוֹעָא דִּשְׂמָאלָא, לְקַבְּלָא לָהּ לְמַטְרוֹנִיתָא, וּכְדֵין כָּל עָלְמָא בִּדְחִילוּ בְּדִינָא, וּבָעֵי הַהוּא זִמְנָא בְּתִיּוּבְתָא שְׁלִים, לְאִשְׁתַּכְחָא עָלְמָא קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא. לְבָתַר אֲתִיאַת מַטְרוֹנִיתָא, וּבַעְיָין בְּנֵי הֵיכָלָא בְּתִשְׁעָה לְיַרְחָא, לְמֶעְבַּד חֶדְוָותָא, וּלְמִטְבַּל בְּנַהֲרָא, לְדַכְאָה גַּרְמַיְיהוּ בְּזִווּגָא דְּמַטְרוֹנִיתָא, בְּיוֹמָא אַחֲרָא, הוּא זִוּוּגָא דִּילָהּ לְשַׁוָּואָה שְׂמָאלָא תְּחוֹת רֵישָׁהָא, (נ\"א רישא דמלכא) כְּמָה דְּאַתְּ אָמַר שְׂמֹאלוֹ תַּחַת לְרֹאשִׁי.</p>\n<p>וּכְדֵין יִשְׂרָאֵל בְּתַעֲנִיתָא עַל חוֹבַיְיהוּ, וּמְכַפְּרָא לְהוּ. דְּהָא אִימָּא עִלָּאָה אַנְהִירַת אַנְפָּהָא לְמַטְרוֹנִיתָא בְּזִוּוּגָהָא, וּמִתְכַּפְּרִין כָּל בְּנֵי הֵיכָלָא. כֵּיוָן דִּשְׂמָאלָא מְקַבְּלָהּ לָהּ בְּהַאי יוֹמָא, דְּרֵישָׁא דְּמַטְרוֹנִיתָא שַׁרְיָיא עַל שְׂמָאלָא.</p>\n<p>בְּיוֹמָא קַדְמָאָה דְּחַג, יִתְעַר יְמִינָא לְקַבְּלָהּ, בְּגִין לְחַבְּקָה וּכְדֵין כָּל חֶדְוָוא וְכָל אַנְפִּין נְהִירִין, וְחֶדְוָותָא דְּמַיִם צְלִילָן, לְנַסְּכָא עַל מַדְבְּחָא. וּבַעְיָין בְּנֵי נָשָׁא לְמֶחֱדֵי בְּכָל זִינִין דְּחֶדְוָה, דְּהָא יְמִינָא גָּרִים. בְּכָל אֲתָר דְּשָׁארִי יְמִינָא, חֶדְוָותָא אִצְטְרִיךְ בְּכֹלָּא, כְּדֵין חֶדְוָותָא הִיא לְאִשְׁתַּעְשְׁעָא.</p>\n<p>לְבָתַר בְּיוֹמָא תְּמִינָאָה, חֶדְוָותָא דְּאוֹרַיְיתָא הוּא, דְּהָא כְּדֵין זִוּוּגָא דְּגוּפָא, הוּא זִוּוּגָא דְּכֹלָּא, לְמֶהֱוִי כֹּלָּא חַד, וְדָא הוּא שְׁלִימוּ דְּכֹלָּא, וְדָא יוֹמָא דְּיִשְׂרָאֵל אִיהוּ וַדַּאי, וְעַדְבָא דִּידְהוּ בִּלְחוֹדַיְיהוּ, דְּלֵית בֵּיהּ חוּלָקָא לְאַחֲרָא. זַכָּאִין אִינּוּן יִשְׂרָאֵל בְּעָלְמָא דֵּין, וּבְעָלְמָא דְּאָתֵי, עָלַיְיהוּ כְּתִיב (דברים י״ד:ב׳) כִּי עַם קָדוֹשׁ אַתָּה לַיְיָ אֱלֹהֶיךָ וְגוֹ'.</p>"],[9520012517,"<p>(במדבר כ״ה:י״א) פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל וְגוֹ'. רִבִּי יְהוּדָה פָּתַח, (איוב ד׳:ז׳) זְכָר נָא מִי הוּא נָקִי אָבָד וְאֵיפֹה יְשָׁרִים נִכְחָדוּ, תַּמָּן תָּנֵינָן, מַאן דְּחָמֵי קֶשֶׁת בִּגְוָונוֹי (ס\"א נהרין), אִצְטְרִיךְ לְבָרְכָא בָּרוּךְ זוֹכֵר הַבְּרִית. בְּגִין דְּדָא אִיהוּ בְּרִית קַיְּימָא קַדִישָׁא, דְּשַׁוִּי קוּדְשָׁא בְּרִיךְ הוּא <Nonei></i>בְּאַרְעָא דְּלָא יֵיתֵי עָלָהּ מֵי טוֹפָנָא. בְּגִין דְּכַד סְגִיאוּ חַיָּיבִין בְּעָלְמָא, בָּעֵי קוּדְשָׁא בְּרִיךְ הוּא לְאוֹבָדָא לוֹן, וּכְדֵין דָּכִיר לוֹן הַאי אוֹמָאָה דְּאוֹמֵי לְאַרְעָא, דִּכְתִּיב תְּרֵי זִמְנֵי לֹא לֹא. (בראשית ח׳:כ״א) לֹא אוֹסִיף לְקַלֵּל, וְלֹא אוֹסִיף עוֹד לְהַכּוֹת, דָּא אִיהוּ אוֹמָאָה. כְּמָה דִּכְתִּיב, (ישעיהו נ״ד:ט׳) אֲשֶׁר נִשְׁבַּעְתִּי מֵעֲבוֹר מֵי נֹחַ. (קשור עם הרעיא מהימנא)</p>\n<p>רִבִּי יוֹסֵי אָמַר, קֶשֶׁת אָתָא לְאַגָּנָא עַל עָלְמָא. לְמַלְכָּא, דְּכָל זִמְנִין דִּבְרֵיהּ חָב לָקֳבְלֵיהּ, אָתָא מַלְכָּא לְאַלְקָאָה לֵיהּ, אִתְגַּלְיָא עָלֵיהּ מַטְרוֹנִיתָא בִּלְבוּשֵׁי יְקָר דְּמַלְכוּ, מַלְכָּא חָמֵי לָהּ סָלִיק רוּגְזָא דִּבְרֵיהּ, וְחַדֵי בָּהּ, דִּכְתִּיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. וְעַל דָּא, לָא אִתְחֲזֵי קֶשֶׁת בְּעָלְמָא, אֶלָּא בִּלְבוּשֵׁי יְקָר דְּמַלְכוּ. וּבְשַׁעֲתָא דְּאִית צַדִּיק בְּעָלְמָא, אִיהוּ בְּרִית, לְמֵיקָם בְּרִית, וְאָגִין עַל עָלְמָא. לָא הֲוִי צַדִּיק, הָא קֶשֶׁת, לְאִתְחֲזָאָה דְּהָא עָלְמָא אִיהוּ קַיְּימָא לְאוֹבָדָא, אֶלָּא בְּגִין קֶשֶׁת דָּא. רִבִּי אֶלְעָזָר אָמַר, לְעוֹלָם לָא אִתְלְבַּשׁ קֶשֶׁת דָּא, אֶלָּא בִּלְבוּשָׁא דַּאֲבָהָן קַדְמָאֵי. יָרוֹק וְסוּמָק וְחִיוָּור. יְרוֹקָא, דָּא לְבוּשָׁא דְּאַבְרָהָם, אִצְטְבַּע לְבוּשָׁא (ס\"א גוון) דָּא, כַּד נָפַק מִנֵּיהּ יִשְׁמָעֵאל. סוּמָקָא, דָּא גּוָֹון יִצְחָק. דְּאַתְיָא סוּמָקָא וְאִצְטְבַּע, כַּד נָפִיק מִנֵּיהּ עֵשָׂו. וְאִתְמְשַׁךְ הַהוּא סוּמָקָא לְתַתָּא, עַד כֹּכָבָא דְּמַאְדִּים, דְּאִתְאֲחִיד בֵּיהּ עֵשָׂו. חִוָּורָא, דָּא אִיהוּ לְבוּשָׁא טָבָא דְּיַעֲקֹב, דְּהָא לָא אִשְׁתָּנּוּ אַנְפּוֹהִי לְעָלְמִין. רִבִּי אַבָּא אָמַר יָאוּת הוּא, אֲבָל הָכִי אָמַר בּוּצִינָא קַדִישָׁא, חִוָּור, דָּא אַבְרָהָם. דְּאִתְלָבַּן בְּחִוָּורָא דְּנוּרָא. סוּמָקָא, דָּא יִצְחָק וַדָאי. יָרוֹק, דָּא הוּא יַעֲקֹב, דְּקַיְּימָא בֵּין תְּרֵין גַּוְונִין, וּכְתִיב בֵּיהּ בְּיַעֲקֹב, (ישעיהו כ״ט:כ״ב) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יֶחוָרוּ דְּהָא כָּל עַרְסֵיהּ שְׁלִים הֲוָה. וְהָכִי הוּא לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב, לְאִתְחֲזָאָה בְּגָוְון סוּמָק, כְּיִצְחָק דְּנָפַק מִנֵּיהּ עֵשָׂו. וְלָא עַתָּה פָּנָיו יֶחוָרוּ, כְּאַבְרָהָם לְאִתְחֲזָאָה בְּגָוְון חִוָּור, דְּנָפַק מִנֵּיהּ יִשְׁמָעֵאל. אֶלָּא נָטַל גַּוְונִין, לְאִתְעַטְּרָא בְּהוּ, עַל אֲבָהָן דִּילֵיהּ, <Nonei></i>וּבְאִלֵּין לְבוּשִׁין מִתְלַבְּשַׁת קֶשֶׁת, בְּשַׁעֲתָא דְּאִתְחֲזֵי קַמֵּי מַלְכָּא. תָּא חֲזֵי, רָזָא דִּבְרִית קַדִּישָׁא, הִיא אָת יוֹ\"ד, דְּמִתְעַטְּרָא בִּרְשִׁימוּ עִלָּאָה, וְהָא (ס\"א ודא) אִיהוּ דְּאִתְרְשִׁים בִּבְרִית תָּדִיר לְעָלְמִין, וּבְגִין דְּקַנֵּי פִּנְחָס עַל בְּרִית, אִתְרְשִׁים בִּשְׁמֵיהּ הָכָא אָת דָּא, פִּנְחָס יוֹ\"ד זְעֵירָא, אִיהוּ יוֹ\"ד דְּאִיהוּ בְּרִית וַדַּאי, דְּנָפִיק מִגוֹ יוֹ\"ד עִלָּאָה קַדִישָׁא. וְעַל דָּא, אִיהוּ קָאִים בְּקִיּוּמָא שְׁלִים קַמֵּי מַלְכָּא קַדִישָׁא, דְּלָא אִתְאֲבִיד מִגּוֹ עָלְמָא. וְהָכִי הוּא נָקִי מֵהַהוּא חוֹבָא דִּפְעוֹר, וְלָא אִתְאֲבִיד תָּדִיר מִגּוֹ קַדִישָׁא דְּעָלְמָא. (ס\"א ולא אתאביד מגו עלמא) (איוב ד׳:ז׳) וְאֵיפֹה יְשָׁרִים נִכְחָדוּ, אִלֵּין נָדָב וַאֲבִיהוּא, דְּלָא אִשְׁתְּצִיאוּ מִן הַהוּא עָלְמָא בְּגִינֵיהּ.</p>\n<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, שַׁפִּיר קָאַמְרַת, אֲבָל בְּגִין דְּאֵלִיָּהוּ דְּאִיהוּ פִּנְחָס, קַנֵּי עַל בְּרִית, צָּרִיךְ לְחַדְתָּא מִלִּין סַגִיאִין בֵּיהּ, דְּהַאי פַּרְשְׁתָא כְּתִיבָא בְּאוֹרַיְיתָא עַל שְׁמֵיהּ, דְּעָלֵיהּ אִתְּמַר (מלכים א י״ט:י׳) קַנֹּא קִנֵּאתִי, תְּרֵי קְנָאוֹת, חַד בְּשַׁדַּ\"י דִּלְעֵילָּא, וְתִנְיָינָא בְּשַׁדַּ\"י דִּלְתַתָּא, וּבְגִין דָּא עָבִיד תְּרֵין שְׁבוּעוֹת (נ\"א בתרין לא לא) (ס\"א בתרין זמנין) בְּתַרְוַויְיהוּ, וּתְרֵין זִמְנִין לֹא לֹא.</p>\n<p>אֲבָל רִבִּי יְהוּדָה אָמַר, מַאן דְּחָמֵי קֶשֶׁת בִּגְוָונוֹי נְהִירִין, צָּרִיךְ לְבָרְכָא בָּרוּךְ זוֹכֵר הַבְּרִית. וּבְגָלוּתָא דְּלָאו אִיהוּ נָהִיר בִּגְוָונוֹי כְּדְקָא יֵאוֹת, וְלֹא עוֹד אֶלָּא דִּלְזִמְנִין נָהִיר זְעֵיר, וְזִמְנִין לָא נָהִיר כְּלַל, זִמְנִין אִתְחֲזִי בִּשְׁלִימוּ, וְזִמְנִין לָאו. דְּקֶשֶׁת קָא רָמִיז גְּוָונוֹי, לְזַכְוָון דְּכֹהֲנִים לְוִיִּם וְיִשְׂרְאֵלִים, כַּד אִינּוּן שַׁפִּירִין, דְּנָהִיר קֶשֶׁת בְּגְוָונוֹי דְּאִינּוּן תְּלַת.</p>\n<p>קוּם אַנְתְּ רִבִּי יוֹסֵי הַגָלִילִי, וְאֵימָא, דְּהָא מִלִּין שְׁפִּירִין קָאַמְרַת בְּחִבּוּרָה קַדְמָאָה, דְּקֶשֶׁת לָא אַתְיָא אֶלָּא לְאַגָּנָא עַל עָלְמָא. לְמַלְכָּא, דִּבְכָל זִמְנָא דִּבְרֵיהּ חָב, וּמַלְכָּא חֲזֵי לְמַטְרוֹנִיתָא, סָלִיק רוּגְזָא דִּבְרֵיהּ, דִּכְתִּיב, (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. וְעַל דָּא לָא אִתְחֲזִי קֶשֶׁת, אֶלָּא לְאַגָּנָא עַל עָלְמָא. וְלָא אִתְגַלְיָא, אֶלָּא בִּלְבוּשׁ יְקָר דְּמַלְכוּ, וּבְשַׁעֲתָא דְּאִית צַּדִיק בְּאַרְעָא, אִיהוּ בְּרִית. לְמֵיקָם בְּרִית.</p>\n<p>וְכִי בְּגָלוּתָא, קוּדְשָׁא בְּרִיךְ הוּא אִתְרְחַק מִמַּטְרוֹנִיתָא, וְאֵיךְ מַטְרוֹנִיתָא אִתְלַבְּשַׁת לְבוּשֵׁי מַלְכוּתָא בְּגָלוּתָא (ס\"א ל\"ג לא) לֹא. אֲבָל בְּגָלוּתָא, לְבוּשָׁהּ דְּקַדְרוּת, וְאִיהוּ אַמְרַת (שיר השירים א׳:ו׳) אַל תִּרְאוּנִי שֶׁאֲנִי שֶׁחַרְחֹרֶת. אֶלָּא וַדַּאי הַהוּא קֶשֶׁת דְּאִתְגַּלְיָיא בְּגָלוּתָא, לָאו אִיהוּ אֶלָּא מְטַטְרוֹ\"ן, דְּאִתְקְרֵי שַׁדַּ\"י וְאִיהוּ (בראשית כ״ד:ב׳) עַבְדּוֹ זְקַן בֵּיתוֹ, דְּשַׁלִּיט בְּכָל דִּילֵיהּ (בגלותא), וּבְנוֹי, אִתְקְרִיאוּ עֲבָדִים דְקוּדְשָׁא בְּרִיךְ הוּא. וּבְנֵי מַטְרוֹנִיתָא בָּנִים, וּבְגִין דָּא, אִם כְּבָנִים אִם כַּעֲבָדִים.</p>\n<p>וּבְזִמְנָא דְּאִתְחָרַב בֵּי מַקְדְשָׁא, אוּקְמוּהָ דַּעֲבָדִים חָפוּ רֹאשָׁם, וְנִתְדַלְדְלוּ אַנְשֵׁי מַעֲשֵׂה. וַדַּאי אַנְשֵׁי מַעֲשֵׂה אִתְקְרִיאוּ, עַל שֵׁם מַטְרוֹנִיתָא, דְּאִתְּמַר עָלָהּ (משלי ל״א:כ״ט) רַבּוֹת בָּנוֹת עָשׂוּ חָיִל וְאַתְּ עָלִית עַל כֻּלָּנָה. אֲבָל אִי אִית לֵיהּ צַּדִיק, דְּזַכְווֹי <Nonei></i>וְעוֹבָדוֹי לְאַנְהָרָא, בְּהוֹן מַטְרוֹנִיתָא, וּלְמִפְשַׁט מִנָּהּ לְבוּשֵׁי קַדְרוּתָא דִּפְשָׁטִין וּלְקַשְׁטָא לָהּ בִּלְבוּשִׁין דִּגְוָונִין נְהִירִין דְּרָזִין דְּאוֹרַיְיתָא, מַה כְּתִיב בֵּיהּ, וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם. וּרְאִיתִיהָ, בְּרָזִין נְהִירִין דְּאוֹרַיְיתָא, דְּאוֹר רָ\"ז אִתְקְרֵי, הֲדָא הוּא דִכְתִיב, (משלי ו׳:כ״ג) כִּי נֵר מִצְּוָה תוֹרָה אוֹר. וּבְאִלֵּין רָזִין אִתְּמַר וּרְאִיתִיהָ.</p>\n<p>וּבְהַהוּא זִמְנָא סָלִיק מִנֵּיהּ רוּגְזָא דִּבְרֵיהּ, (אסתר ז׳:י׳) וַחֲמַת הַמֶּלֶךְ שָׁכָכָה, וְיֵימָּא לָהּ מַלְכָּא בִּצְּלוֹתָא דַּעֲמִידָה קַמֵּיהּ, (אסתר ה׳:ו׳) מַה שְּׁאֵלָתֵךְ וְיִּנָתֶן לָךְ וּמַה בַּקָּשָׁתֵךְ. בְּהַהוּא זִמְנָא, שְׁאֵלְתָּא עַל פּוּרְקָנָא דִּילָהּ, וּבְנָהָא עִמֵּיהּ, הֲדָא הוּא דִכְתִיב, (אסתר ז׳:ג׳) תִּנָּתֶן לִי נַפְשִׁי בִּשְׁאֵלָתִי וְעַמִּי בְּבַקָּשָׁתִי. אֲבָל קֶשֶׁת דְּאִתְחַזְיָא בְּעָלְמָא בְּגָלוּתָא, דְּעַבְדָּא אִיהוּ, זִמְנִין דְּנָפִיק בִּשְׁלִימוּ, כַּד בְּנוֹי מַכְשִׁירִין עוֹבָדוֹי, וּלְזִמְנִין לָא אִשְׁתְּכַח בִּשְׁלִימוּ, כַּד בְּנוֹי לָא מַכְשְׁרִין עוֹבָדוֹי (כאן חסר). וְאִי לָאו בְּגִין אוֹת יוֹ\"ד דְּשַׁדַּ\"י דְּקַנִּי עֲלָהּ פִּנְחָס דְּאַגִין לֵיהּ מִשִׁבְטָא דְּשִׁמְעוֹן הֲווּ קַטְלִין לֵיהּ וְאוֹבְדִין לֵיהּ מֵעָלְמָא.</p>\n<p>וּבְגִין דָּא (איוב ד׳:ז׳) זְכוֹר נָא מִי הוּא נָקִי אֲבַד דָּא פִּנְחָס וְאֵיפֹה יְשָׁרִים נִכְחַדוּ, אִלֵּין דִּמְכַשְׁרִין עוֹבָדֵיהוֹן קַמֵּי מַלְכָּא, וּמְקַנִּין עַל שְׁמֵיהּ, וּמַקְדִּישִׁין לֵיהּ בָּרַבִּים. הָכִי מְקַדְשִׁין לֵיהּ לְעֵילָּא, בֵּין מְמָנָן דִּשְׁאַר עַמִּין, וְאִשְׁתְּמוֹדְעִין לֵיהּ כָּל מְמָנָא בְּכִנוּיֵיהּ. אֲבָל יִשְׂרָאֵל אִשְׁתְּמוֹדְעִין לְעֵילָּא כֹּלָּא בְּשֵׁם יְדוָֹ\"ד, דְּאִיהוּ חַיֵּי כָּל כִּנּוּיִין.</p>\n<p>וְכָל שֵׁם וְכִנּוּי סָהִיד עָלֵיהּ, אֵ\"ל סָהִיד עָלֵיהּ, דְּאִית לֵיהּ יְכוֹלֶת עַל כָּל אֵל, הֲדָא הוּא דִכְתִיב, (איוב ה׳:ח׳) אֲנִי אֶדְרוֹשׁ אֶל אֵל. אֵל, מָארֵי דְּאֵל. אֱלֹהִים סָהִיד עָלֵיהּ, דְּאִיהוּ אֱלֹהֵי הָאֱלֹהִים. אֲדֹנָ\"י סָהִיד עָלֵיהּ, דְּאִיהוּ אֲדוֹנֵי הַאֲדוֹנִים. אוּף הָכִי כָּל שֵׁם. דְּכָל (ספירה ומלאך) מַלְאָךְ אִית לְכָל חַד שֵׁם יְדִיעַ, לְאִשְׁתְּמוֹדְעָא לְכָל כַּת בְּהַהוּא שֵׁם דְּמַלְכָּא דִּילֵיהּ. אֲבָל יִשְׂרָאֵל, אִשְׁתְּמוֹדְעָן לֵיהּ ביהו\"ה.</p>\n<p>וְרָזָא דְּמִלָּה, בַּר נָשׁ חַד יָכִיל לְמֶהֱוִי לֵיהּ כַּמָה סוּסְוָון, אוּף הָכִי כָּל יִשְׂרָאֵל אִינּוּן בְּנוֹי דְּאָדָם, וְכָל בְּרָא צָּרִיךְ לְמֶהֱוִי לֵיהּ לַאֲבוּי כַּסּוּס וְכַחֲמוֹר לְמָשׂוּי, וּלְמֶהֱוִי כָּפִיף תְּחוֹתוֹי, וְהַאי אִיהוּ רָזָא (תהילים ל״ו:ז׳) אָדָם וּבְהֵמָה תּוֹשִׁיעַ יְיָ. דְּאִיהוּ בְּרָא דְּאָדָם, וְעָבִיד גַּרְמֵיהּ כַּבְהֵמָה תְּחוֹתוֹי.</p>"],[9520012518,"<p>וּבְגִין דָּא אִיהוּ פִּקּוּדָא דְקוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְיתָא, לְמֶהֱוִי אָח מְיַבֵּם לְאִתְּתֵיהּ דְּאָח, לְמֶעְבַּד בְּרָא לַאֲחוּי, בְּגִין דְּלָא יִתְאֲבִיד מֵהַהוּא עָלְמָא. וְהַאי אִיהוּ כְּגוֹן רָזָא דְּכִלְאַיִם בְּצִּיצִּית. דְּאָמְרוּ, מַה שֶׁאָסַרְתִּי לָךְ כָּאן, הֵתַּרְתִּי לָךְ כָּאן. אָסַרְתִּי לָךְ כִּלְאַיִם דְּעָלְמָא, הֵתַּרְתִּי לָךְ כִּלְאַיִם דְּצִּיצִּית. אָסַרְתִּי לָךְ אֵשֶׁת אָח, הֵתַּרְתִּי לָךְ יְבָמָה. כְּגוֹן מַרְכִיבִים תַּפּוּחִים אוֹ דְּקָלִּים מִן בְּמִינוֹ. וְאָסוּר לְאַרְכָּבָא מִין בְּשֶׁאֵינוֹ מִינוֹ. וְאִתְּמַר בֵּיהּ (דברים כ׳:י״ט) כִּי הָאָדָם עֵץ הַשָּׂדֶה. וּבַיְּבָמָה מַרְכִּיבִין מִין בְּשֶׁאֵינוֹ מִינוֹ, (תיקונים י\"ט ע\"א ע\"ש) בְּגִין דְּלָא לִתְאֲבִיד (להאביד) נֶפֶשׁ הַמֵּת. (דברים כ״ה:ו׳) וְלֹא יִמָּחֶה שְׁמוֹ מִיִּשְׂרָאֵל.</p>\n<p>וְהַאי אִיהוּ רָזָא דְּגִלְגּוּל. גַּלְגַּל לֵית לֵיהּ תְּנוּעָה בְּלָא אֲמַת הַמַּיִם, אוּף הָכִי, אֲמַת הַמַּיִם רָזָא דְּאָת ו', בֵּיהּ אִתְעָבִיד גַּלְגַּל גִּלְגּוּל. וְרָזָא דְּמִלָּה, מַה גַּלְגַּל אֵין לוֹ תְּנוּעָה בְּלָא אֲמַת הַמַּיִם, אוּף הָכִי, גַּלְגַל אִיהוּ י', וְלֵית לֵיהּ תְּנוּעָה בְּלָא אֲמַת הַמַּיִם דְּאִיהוּ ו'. יְבָמָה ה'. לְהַאי אִיהוּ בִּינָ\"ה בֵּ\"ן יָ\"הּ. בְּאוֹת י' בָּרָא עָלְמָא דְּאָתֵי, עוֹלָם אָרוֹךְ, דְּאִיהוּ ו'.</p>\n<p>בְּגִין דָּא, מַאן דְּלֵית לֵיה בֵּן, לָאו אִיהוּ מִבְּנֵי עָלְמָא דְּאָתֵי, דְּיַמָּא לָקֳבְלֵיהּ, וּמִנֵּיהּ נָפִיק, מִבֵּינַיְיהוּ (תיקונים ע\"ב ע\"א) ו', וּמִנֵּיהּ מִתְפַּלְּגִין כַּמָה נַחֲלֵי, דְּאִינּוּן מְסַבְּבִין עָלְמָא, עַד דְּחַזְרוּ לְיַמָּא דְּנַפְקוּ מִתַּמָּן, וּבְגִין דָּא אָמַר קְרָא, (קהלת א׳:ז׳) כָּל הַנְּחָלִים הוֹלְכִים אֶל הַיָּם וְהַיָּם אֵינֶנּוּ מָלֵא אֶל מְקוֹם שֶׁהַנְּחָלִים וְגוֹ'. עַד דְּאָהַדְרוּ כְּגַוְונָא דְּנַפְקוּ.</p>\n<p>אוּף הָכִי, (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. כְּגַוְונָא דְּיָהִיב לָהּ <Nonei></i>שְׁלֵימָתָא. אִם תָּשׁוּב בְּתִיּוּבְתָא, דְּאִיהוּ בִּינָ\"ה בֵּ\"ן יָ\"הּ, עִלָּאָה. אָת ה' סְלִיקַת בְּאָת י' לְחַמְשִׁין, עֶשֶׂר זִמְנִין חֲמֵשׁ. הָא אִיהוּ יָ\"ם, יָ\"הּ. בֵּ\"ן, נַחַל דְּנָפַק מִן יַמָּא, וְאִתְפְּלִיג לְכַמָּה נַחֲלִין, כְּגַוְונָא דְּאִילָנָא דְּאִתְפְשַׁט לְכַמָּה עַנְפִּין.</p>\n<p>וְאִי לָא חָזַר נִשְׁמְתָא שְׁלֵימָתָא, כְּגַוְונָא דְּאִשְׁתְּלָמַת. אִתְּמַר בָּהּ, שָׁם הֵם שָׁבִים לָלָכֶת, אִיהִי וְכָל נִשְׁמָתִין אַחֲרָנִין. אוּף הָכִי לָאו אִיהוּ שְׁלִים בְּבֶן, אִי לֵית לֵיהּ בַּת, דְּאִיהוּ עָלְמָא דֵּין, לְמֶהֱוִי שְׁלִים בְּהַאי עָלְמָא דְּאִתְבְּרֵי בְּה', הֲדָא הוּא דִכְתִיב, (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם. (אלא)</p>\n<p>יְה\"וּ, (איוב ל״ג:כ״ט) הֵן כָּל אֵלֶּה יִפְעַל אֵל פַּעֲמַיִם שָׁלֹשׁ עִם גָּבֶר. וְרַשִּׁיעַיָּיא דְּאִתְּמַר בְּהוֹן, (קהלת ח׳:י׳) וּבְכֵן רָאִיתִי רְשָׁעִים קְבוּרִים וָבָאוּ, גַּרְמוּ אֵלֶּה אֱלֹהֶיךָ יִשְׂרָאֵל, דְּאִתְּמַר עָלַיְיהוּ, (עמוס ב׳:ו׳) עַל שְׁלֹשָׁה פִּשְׁעֵי יִשְׂרָאֵל. בָּתַר דְּקִלְקְלוּ גַּרְמַיְיהוּ תְּלַת זִמְנִין, וְלָא זָכֵי בְּיה\"ו, דְּאִתְּמַר בֵּיהּ (קהלת י״א:ג׳) מְקוֹם שֶׁיִּפּוֹל הָעֵץ שָׁם יְהוּ. עַל אַרְבָּעָה לֹא אֲשִׁיבֶנּוּ, דְּהַיְינוּ ה'. וְאִתְדָּנוּ בַּגֵיהִנָּם, בְּמַשְׁחִית אַף וְחֵימָה.</p>\n<p>וּלְבוּשִׁין דִּתְלַת אַתְוָון אִלֵּין, אִשְׁתְּמוֹדְעִין בַּקֶּשֶׁת, דְּאִינּוּן חִיוָּור סוּמָק וְיָרוֹק. מַאן דְּיִיתֵי בְּזִמְנָא חֲדָא, אִיהוּ חִיוָּור. בְּתִנְיָינָא, סוּמָק. בִּתְלִיתָאָה, יָרוֹק. וּבְגִין דִּבְיַעֲקֹב אִתְכְּלִילוּ אַתְוָון, וְאִשְׁתְּרָשׁ אִילָנָא וְאִתְנְטָע וְאִתְרַבָּא, וְאִתְעָבִיד אִיבָּא טָבָא, (ישעיהו כ״ט:כ״ב) לֹא עַתָּה יֵבוֹשׁ יַעֲקֹב וְלֹא עַתָּה פָּנָיו יְחֱוָרוּ, לְמֶהֱוִי מֶרְכַּבְתֵּיהּ בְּיִצֶּר הָרָע, דְּאִיהוּ נָחָשׁ, וְכָל מִינֵי חַיָּה בִּישָׁא. וּבְגִין דָּא, (הושע י״ב:ה׳) וַיָּשַׂר אֶל מַלְאָךְ וַיוּכָל. וּבְגִין דְּאִתְקְרֵי אָדָם אִילָנָא, אִיהוּ רָזָא דָּא, לְאִילָנָא דְּאִתְנָטַע בַּאֲתָר דְּלָא עָבִיד אִיבָּא. מֶה עָבֵד. עָקַר לֵיהּ וּנְטָעֵיהּ בַּאֲתָר אַחֲרָא. וּבְגִין דָּא אוּקְמוּהָ מִכָּל מָקוֹם דְּלָא הֲוִי מוּחְזָק לְמֶהֱוִי עָקָר, עַד דְּאָזִיל לְאֶרֶץ יִשְׂרָאֵל, וְאִתְנְטָע תַּמָּן בְּאִתְּתָא.</p>\n<p>אוּף הָכִי צַּדִיק, דְּאִיהוּ מִטַלְטֵל מֵאֲתָר לְאֲתָר, מִבַּיִת לְבַיִת, כְּאִילּוּ יֵיתֵי בְּגִלְגּוּלָא זִמְנִין סַגִּיאִין. וְהַיְינוּ (שמות כ׳:ו׳) וְעוֹשֶׂה חֶסֶד לַאֲלָפִים לְאוֹהֲבָיו, עַד דְּיִזְכֶּה לְעָלְמָא (דאתי) שְׁלִים. אֲבָל לְחַיָּיבַיָּא, לָא אַיְיתֵי לֵיהּ יַתִיר מִתְּלַת זִמְנִין. וְאִי חָזַר בְּתִיּוּבְתָא, אִתְּמַר בֵּיהּ גָּלוּת מְכַפֶּרֶת עֲוֹן. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, צַּדִיקִים שׁוּב אֵינָן חוֹזְרִים לַעֲפָרָם.</p>\n<p>אֶלָּא קָא רָמִיז, (ויקרא י״ד:מ״ב) וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת. (איוב ל״ד:ט״ו) וְאָדָם עַל עָפָר יָשׁוּב. (קהלת י״ב:ז׳) וְיָשׁוֹב הֶעָפָר עַל הָאָרֶץ כְּשֶׁהָיָה. בְּגִין דְּהוּא מְנוּגַע, וְלֵית בֵּיהּ אֶלָּא אִשָׁה רָעָה, יֵצֶּר הָרָע, דְּאִתְּמַר בָּהּ אִשָׁה רָעָה צָּרַעַת לְבַעְלָהּ. מַאי תָּקַנְתֵיהּ. יְגָרְשֶׁנָּה וְיִתְרַפֵּא. דְּאִיהִי גַּרְמַת (בראשית ג׳:כ״ד) וַיְגָרֶשׁ אֶת הָאָדָם הָאָדָם, דָּא נִשְׁמְתָא. אֶ\"ת, בַּת זוּגוֹ דְּאָדָם. (משלי כ״ז:ח׳) כְּצִּפּוֹר נוֹדֶדֶת מִן קִנָּהּ כֵּן אִישׁ נוֹדֵד מִמְּקוֹמוֹ.</p>\n<p>וּבְגִין דָּא, (תהילים פ״ד:ד׳) גַּם צִּפּוֹר מָצְּאָה בַיִת, הַיְינוּ יְבָמָה. וּדְרוֹר קֵן לָהּ, הַיְינוּ גּוֹאֵל, אֲשֶׁר שָׁתָה אֶפְרוֹחֶיהָ, בֵּן וּבַת. זַכָּאָה אִיהוּ מַאן דְּעָבַד (לון) קִינָּא, (ויקרא כ״ה:כ״ה) וְגָאַל אֵת מִמְכַּר אָחִיו. דְּאִיהוּ מָכוּר בַּעֲבוּר דְּלָאו דִּילֵיהּ.</p>\n<p>וּבְגִין דָּא אָמַר מֹשֶׁה, (דברים ג׳:כ״ו) וַיִתְעֲבֵּר יְיָ בִּי לְמַעַנְכֶם. הָכָא הוּא סוֹד הָעִבּוּר. רַעְיָא מְהֵימָנָא, שֵׁזִיב שִׁתִּין רִבּוֹא, כַּמָּה זִמְנִין דְּאָתֵי בְּגִלְגּוּלָא, וּבְגִין דָּא זְכוּת כֻּלְּהוּ תַּלְיָיא קוּדְשָׁא בְּרִיךְ הוּא בֵּיהּ. וּבְגִין דָּא אוֹקְמוּהָ רַבָּנָן, אִשָּׁה אַחַת יָלְדָה בְּמִצְּרַיִם שִׁשִּׁים רִבּוֹא בְּכֶרֶס אֶחָד. וְאַף עַל גַּב דְּאוֹקְמוּהָ רַבָּנָן בְּמִלִּין אַחֲרָנִין, שִׁבְעִים פָּנִים לַתּוֹרָה.</p>\n<p>דְּהָכִי אֹרַח דְּמָארֵי רָזִין, אַמְרִין מַרְגָלִית לְתַלְמִידֵיהוֹן, וְלָא אִשְׁתְּמוֹדְעוּן בֵּיהּ בִּרְמִיזָא, אַהְדָּר לוֹן הַהוּא מִלָּה בְּמִלֵּי שְׂחוֹק, כְּגַוְונָא דְּהַהוּא דְּאָמַר, דְּבֵיצָּה אַחַת, אַפִּילַת שִׁתִּין כְּרָכִין. וְאָתָא בֵּיצָּה וְנַפְלַת מִן עוֹפָא דְּהֲוָה פָּרַח בַּאֲוִירָא, וּמָחָאָת אִלֵּין שִׁתִּין כְּרָכִין, וּמָארֵי דְּלֵיצָּנוּתָא אָמְרוּ, דְּלָא אָמַר הוּא אֶלָּא דְּבַּר נָשׁ כָּתַב שִׁשִּׁים כְּרָכִין, וְאָתָא בֵּיצָּה דְּנַפְקַת מִן עוֹפָא וּמְחָקַת שִׁתִין כְּרָכִין דִּכְתִיבָה. וְחָס וְשָׁלוֹם דְּמָארֵי אוֹרַיְיתָא אַמְרִין מִלִּין דִּשְׂחוֹק, וּדְבָרִים בְּטֵלִים בְּאוֹרַיְיתָא.</p>\n<p>אֶלָּא הָא אוֹקְמוּהָ, (דברים כב) אֶפְרוֹחִים, אִלֵּין מָארֵי מִשְׁנָה. אוֹ בֵּיצִּים, אִלֵּין מָארֵי מִקְרָא. וּכְגַוְונָא דְּנָפַל מֵהַהוּא נִפּוֹל, דְּאִיהוּ בַּר נַפְלֵי, נְפִילַת בֵּיצָּה דְּאִיהוּ אֶתְרוֹג שִׁיעוּרָא בְּכַבֵּיצָּה. וּבְגִינָהּ אִתְּמַר (עמוס ט׳:י״א) בַּיוֹם הַהוּא אָקִים אֶת סֻכַּת דָּוִד הַנּוֹפֶלֶת. וְנָפְלוּ עִמָּהּ (שיר השירים ו׳:ח׳) שִׁשִּׁים הֵמָּה מְלָכוֹת, דְּאִינּוּן כְּרִיכִין בָּהּ, כְּגוֹן כֵּיצַּד כּוֹרְכִין אֶת שְׁמַע. וְאִינּוּן לָקֳבֵל שִׁשִּׁים מַסֶּכְתּוֹת. וַעֲלָמוֹת אֵין מִסְפָּר, אִלֵּין (תהילים מ״ה:ט״ו) בְּתוּלוֹת אַחֲרֶיהָ רֵעוֹתֶיהָ, דְּאִינּוּן הֲלָכוֹת, דְּלֵית לוֹן חוּשְׁבַּן.</p>\n<p>וְהַהוּא נִיפּוֹל אִיהוּ בֶּן יָ\"הּ אִיהוּ בְּתוֹךְ נ' תַּרְעִין דְּבִינָ\"ה, דְּהַיְינוּ יָ\"הּ חֲמֵשׁ זִמְנִין עֶשֶׂר ו' אִיהוּ נִיפּוֹל, דְּנָפַל בָּתַר הַהִיא דְּאִתְּמַר, (ישעיהו י״ד:י״ב) אֵיךְ נָפַלְתָּ מִשָּׁמַיִם הֵילֵּל בֶּן שָׁחַר וְאִקְרֵי נִיפּוֹל, וְלֹא נָפַל, וְלֹא נוֹפֵל. בְּגִין דְּבֵיהּ נִיפּוֹל י\"ו וְנָחִית בְּהוֹן לְגַבֵּי ה' ה', דְּאִתְּמַר בְּהוֹן (רות א׳:י״ט) וַתֵּלַכְנָה שְׁתֵּיהֶן. הֲדָא הוּא דִכְתִיב, (דברים כ״ב:ז׳) שַׁלֵּח תְּשַׁלַּח חַד מִבַּיִת רִאשׁוֹן וְתִנְיָינָא מִבַּיִת שֵׁנִי, לְאַקָמָא לוֹן. הֲדָא הוּא דִכְתִיב, <Nonei></i>(תהלים צו) יִ\"שְׂמְחוּ הַ\"שָּׁמַיִם וְ\"תָגֵל הָ\"אָרֶ ץ.</p>\n<p>תָּא חֲזִי, הַאי שִׁמְשָׁא אִתְגַלְיָא בִּימָמָא, וְאִתְכַּסְיָא בְּלֵילְיָא. וְנָהִיר בְּשִׁתִּין רִבּוֹא כֹּכָבַיָּא. אוּף הָכִי רַעְיָא מְהֵימָנָא, בָּתַר דְּאִתְכְּנִישׁ מֵעָלְמָא, נָהִיר בְּשִׁתִּין רִבּוֹא נִשְׁמָתִין דְּיִשְׂרָאֵל, אִי דָּרָא כַּדְּקָא יָאוּת. וְהַאי אִיהוּ רָזָא דְּגִלְגּוּלָא, דְּאָמַר עָלֵיהּ קֹהֶלֶת, (קהלת א׳:ד׳) דּוֹר הוֹלֵךְ וְדוֹר בָּא. וְאוֹקְמוּהָ דְּלֵית דּוֹר פָּחוּת מִשִּׁשִׁים רִבּוֹא. וְהָאָרֶץ לְעוֹלָם עוֹמֶדֶת, דָּא כְּנֶסֶת יִשְׂרָאֵל. הַהִיא דְּאִתְּמַר בָּהּ, (ישעיהו ס״ו:א׳) וְהָאָרֶץ הֲדוֹם רַגְלָי, (בראשית כ״ח:י״ד) וְהָיָה זַרְעֲךָ כַּעֲפַר הָאָרֶץ.</p>\n<p>וְעוֹד רָזָא אַחֲרָא אוֹקְמוּהָ רַבָּנָן, הַדוֹר שֶׁהוֹלֵךְ הוּא הַדוֹר שֶׁבָּא, הָלַךְ חִגֵר בָּא חִגֵר, הֹלֵךְ סוּמָא בָּא סוּמָא. וְעוֹד אוֹקְמוּהָ רַבָּנָן, דְּעָתִיד הֲוָה מֹשֶׁה לְקַבְּלָא אוֹרַיְיתָא בְּדָרָא דְּטוֹפָנָא, אֶלָּא בְּגִין דַּהֲווֹ רַשִׁיעַיָּיא, הֲדָא הוּא דִכְתִיב, (בראשית ו׳:ג׳) בְּשַׁגַּ\"ם הוּא בָּשָׂר. בְּשַׁגַּ\"ם זֶה מֹשֶׁ\"ה. וַאֲמַאי קָרֵי לֵיהּ בְּשַׁגַּם. אֶלָּא קֹהֶלֶת חִסֵּר ב' מִן בְּשַׁגַּ\"ם לְכַסָּאָה מִלָּה. אָמַר (קהלת ח׳:י״ד) אָמַרְתִּי שֶׁגַּם זֶה הָבֶל.</p>\n<p>וְאוֹקְמוּהָ עַל יִתְרוֹ, לָמָּה נִקְרָא שְׁמוֹ קֵינִי, שֶׁנִּפְרָד מִקַּיִן. קָם בּוּצִּינָא קַדִישָׁא וְאָמַר, עַל דָּא כְּתִיב, (בראשית ד׳:א׳) קָנִיתִי אִישׁ אֶת יְדוָֹ\"ד. דְּחָזָאָת לֵיהּ בְּרוּחַ הַקֹּדֶשׁ, דַּעֲתִידִין בְּנוֹי לְמֵיתַב בְּלִשְׁכַּת הַגָּזִית.</p>\n<p>וְאוֹף הָכִי רִבִּי אֶלְעָזָר בֶּן פְּדָת, דְּהֲוָה דְּחִיקָא לֵיהּ שַׁעֲתָא, דְּלָא הֲוָה לֵיהּ אֶלָּא קַב חֲרוּבִין מְעֶרֶב שַׁבָּת לְעֶרֶב שַׁבָּת, כְּמוֹ לְרִבִּי חֲנִינָא. אֲמַאי הַאי, בָּתַר דַּהֲוַת בַּת קוֹל נַפְקַת וְאוֹמֶרֶת, כָּל הָעוֹלָם כֻּלּוֹ אֵינוֹ נִיזוֹן אֶלָּא בִּשְׁבִיל חֲנִינָא בְּנִי.</p>\n<p>אֶלָּא אִיהוּ גָּרִים קוֹדֶם, דְּחָרַב ק\"ב מִן י', דְּאִיהוּ יַבֹּ\"ק. אוּף הָכִי לָא הֲוָה לֵיהּ אֶלָּא קַב חֲרוּבִין. דְּאָת י' אִיהוּ יִחוּד, וּמִנֵּיהּ אַתְיָא נְבִיעוּ לְאָת ב', דְּאִיהִי בְּרָכָה, וְאִיהִי קֹדֶשׁ, וּמִנֵּיהּ אִתְקַדָּשׁ ק', דְּאִיהִי קִדוּשֵׁיה. וְרִבִּי פְּדָת גָּרִים לְמֶהֱוִי חֲרוּבִין דִּילֵיהּ ק\"ב, דְּאִינּוּן קְ\"דוּשָׁה בְּ\"רָכָה, אוּף הָכִי לָא הֲוָה לֵיהּ אֶלָּא קַב חֲרוּבִין, אוּף הָכִי אִיּוֹב בֶּן יְבָמָה הֲוָה, וּבְגִין דָּא אִתְעַנָּשׁ, עַל מַה דְּאִירַע לוֹ כְּבָר.</p>"],[9520012519,"<p>וְאִינּוּן דְּלָא יַדְעֵי רָזָא דָּא, אַמְרֵי בְּנֵי חַיֵּי וּמְזוֹנֵי לָאו בִּזְכוּתָא תַּלְיָא מִלְּתָא, אֶלָּא בְּמַזָּלָא תַּלְיָא מִלְּתָא. וְהָא חֲזֵינָא לְאַבְרָהָם דְּחָזָא בְּמַזָּלֵיהּ, דְּלָא הֲוָה עָתִיד לְמֶהֱוִי לֵיהּ בְּרָא, וְקוּדְשָׁא בְּרִיךְ הוּא אַפִּיק לֵיהּ לְבָרָא, כְּדִכְתִּיב (בראשית ט״ו:ה׳) וַיּוֹצֵּא אוֹתוֹ הַחוּצָּה וַיּאמֶר הַבֶּט וְגוֹ'. וְאַקְמוּהָ, דְאָמַר לֵיהּ צֵּא מֵאִצְּטַגְנִינוּת שֶׁלָּךְ, וְהֶעֱלָהוּ לְמַעְלָה מֵהַכֹּכָבִים, וְאָמַר לוֹ הַבֶּט נָא הַשָּׁמַיְמָה וּסְפוֹר הַכֹּכָבִים. עַד הָכָא מִלִּין דְּרַבָּנָן, וְצָּרִיךְ לְפָרְשָׁא לוֹן בְּדֶרֶךְ נִסְתָּר.</p>\n<p>תָּא חֲזֵי, כָּל בִּרְיָין דְּעָלְמָא, קוֹדֶם דְּאִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל, הֲווֹ תַּלְיָין בְּמַזָּלָא, וַאֲפִילּוּ בְּנֵי חַיִּי וּמְזוֹנֵי. אֲבָל בָּתַר דְּאִתְיְיהִיבַת אוֹרַיְיתָא לְיִשְׂרָאֵל, אַפִּיק לוֹן מֵחִיּוּבָא דְּכֹכָבַיָּא וּמַזָּלֵי. וְדָא אוֹלִיפְנָא מֵאַבְרָהָם. בְּגִין דַּהֲווֹ עֲתִידִין בְּנוֹי לְקַבְּלָא ה' מֵאַבְרָהָם, דְּאִיהִי חֲמִשָּׁה חוּמָשֵׁי תּוֹרָה. דְּאִתְּמַר בָּהּ (בראשית ב׳:ד׳) אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם, בְּה' בְּרָאָם. אָמַר לְאַבְרָהָם, בְּגִין הַאי ה' דְּאִתוֹסָף בִּשְׁמָךְ, הַשָּׁמַיִם תַּחְתָּךְ, וְכָל כֹּכָבַיָא וּמַזָּלֵי דִּנְהִירִין בְּה'. וְלֹא עוֹד, אֶלָּא דְּאִתְּמַר בָּהּ (בראשית מ״ז:כ״ג) הֵ\"א לָכֶם זְרַע, וּזְרַעְתֶּם בְּהֵ\"א. (בראשית כ״א:י״ב) כִּי בְּיִצְּחָק יִקָּרֵא לְךָ זָרַע.</p>\n<p>וּבְגִין דָּא, כָּל הַמִשְׁתַּדֵּל בְּאוֹרַיְיתָא, בָּטִיל מִנֵּיהּ חִיוּבָא דְּכֹכָבַיָּא וּמַזָּלֵי. אִי אוֹלִיף לָהּ כְּדֵי לְקַיְּימָא פִּקּוּדָהָא. וְאִם לָאו, כְּאִלּוּ לָא אִשְׁתְּדַּל בָּהּ, וְלָא בָּטִיל מִנֵּיהּ חִיוּבָא דְּכֹכָבַיָּא וּמַזָּלֵי. כָּל שֶׁכֵּן עַמֵּי הָאָרֶץ דְּאִינּוּן אִתְמַתְלָן לִבְעִירָן. דְּאוֹקְמוּהָ עָלַיְיהוּ (דברים כ״ז:כ״א) אָרוּר שׁוֹכֵב עִם כָּל בְּהֵמָה, דְּלָא אִתְבָּטְלוּן מִנְּהוֹן חִיוּבָא דְּכֹכָבַיָּא וּמַזָּלֵי.</p>\n<p>(תהילים ק״ג:ט״ו) אֱנוֹשׁ כֶּחָצִּיר יָמָיו כְּצִּיץ הַשָּׂדֶה כֵּן יָצִּיץ, וְאִתְּמַר בֵּיהּ, (תהילים ל״ז:כ״ה) נַעַר הָיִיתִי גַּם זָקַנְתִּי. לְבָתַר (איוב ל״ג:כ״ה) יָשׁוּב לִימֵי עֲלוּמָיו. דְּאִילָנָא דְּאִתְקְצִּיצּוּ עַנְפִין עַתִּיקִין דִּילֵיהּ, וְצָּמְחוּ כְּמִלְּקַדְּמִין בְּשָׁרְשׁוֹי, אָהַדְרוּ בְּעָלְמָא כְּמִלְּקַדְּמִין. מִיתוּ סָבִין, וְאִתְהַדְרוּ לְהַאי עָלְמָא עוּלְימִין. וְהַיְינוּ רָזָא דִּמְחַדֵּשׁ קוּדְשָׁא בְּרִיךְ הוּא בְּכָל יוֹם תָּמִיד מַעֲשֵׂה בְרֵאשִׁית. דְּמֵתִין אֶלֶף בְּכָל יוֹמָא וּמִתְחַדְּשִׁין אֶלֶף בְּכָל יוֹמָא.</p>"],[9520012520,"<p>(תהילים ק״ד:ט״ו) וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ, דָּא יִינָא דְּאוֹרַיְיתָא. דְּהָכִי סָלִיק יַיִן, כְּחוּשְׁבַּן סוֹ\"ד. וּמַה יַיִ\"ן צָּרִיךְ לְמֶהֱוִי סָתִים וְחָתִים, דְּלָא יִתְנְסַּךְ לְעֲבוֹדָה זָרָה. אוּף הָכִי צָּרִיךְ לְמֶהֱוִי סָתִים וְחָתִים סוֹד דְּאוֹרַיְיתָא, וְכָל רָזִין דִּילָהּ, וְלָא אִשְׁתַּקְיָין אֶלָּא לִירֵאָיו. וְלָאו לְמַגָנָא עַבְדִין כַּמָּה פִּקוּדִין בַּיַיִן, וּמְבָרְכִין בֵּיהּ לְּקוּדְשָׁא בְּרִיךְ הוּא, וְיַיִן אִית לֵיהּ תְּרֵי גַּוְונִין, חִיוָּר וְסוּמָק, דִּינָא וְרַחֲמֵי, וְהַיְינוּ ב' תּוֹסֶפֶת בַּיַיִן. כְּגַוְונָא דְּשׁוֹשַׁנָּה חִיוָּרָא וְסוּמָקָא. חִוָּור מִסִּטְרָא דִּימִינָא, סוּמָק מִסִּטְרָא דִּשְׂמָאלָא.</p>\n<p>וּמַאי לְבַב אֱנוֹשׁ, לֵב הֲוָה לֵיהּ לְמֵימַר. אֶלָּא אִית לֵב מָסוּר לַלֵּב. וְאִינּוּן ל\"ב אֱלֹהִים דְּעוֹבָדָא דִּבְרֵאשִׁית, ב' מִן בְּרֵאשִׁית, ל' מִן לְעֵינֵי כָּל יִשְׂרָאֵל, אִיהוּ ל\"ב תִּנְיָינָא. דָּא לֵ\"ב לֵ\"ב (ס\"א אינון) שְׁנַיִם סַלְּקָא דַּעְתָּךְ, חֲסַר תְּמַנְיָא לְע\"ב, דְּאִיהוּ וַיְכֻלּוּ. אִינּוּן שִׁבְעָה יְמֵי בְּרֵאשִׁית. תְּמִינָאָה מַאי הִיא. ז' יְמֵי בְּרֵאשִׁית, עִם (בראשית ה׳:א׳) זֶה סֵפֶר תּוֹלְדוֹת אָדָם. זֶה ע\"ב, בְּחוּשְׁבָן בְּיַיִן.</p>\n<p>מַאי לְהַצְּהִיל פָּנִים מִשָּׁמֶן. אִינּוּן י\"ב פָּנִים, ד' דְּאַרְיִה, ד' דְּשׁוֹר, ד' דְּנֶשֶׁר, <Nonei></i>דְּאִינּוּן מִיכָאֵל אַרְיִה, אַרְבַּע אַנְפִּין דִּילֵיהּ יֶהוְֹ\"ה. אַרְבַּע אַנְפִּין דְּשׁוֹר, וְאִיהוּ גַּבְרִיאֵל, וְאִינּוּן יַהוַֹ\"ה. ד' אַנְפִּין דְּנֶשֶׁר, וְאִיהוּ נוּרִיאֵל, וְאִינּוּן יִהוְֹ\"ה. וְאִינּוּן מְמָנָן, תְּחוֹת חֶסֶ\"ד פַּחַ\"ד אֶמֶ\"ת, דַּרְגִּין דִּתְלַת אֲבָהָן. וְאוֹקְמוּהָ רַבָּנָן, הָאָבוֹת הֵן הֵן הַמֶרְכָּבָה. וְסַלְּקִין (ס\"א נקודין) נְהוֹרִין לְחֻשְׁבָּן יַבֹּ\"ק. וְאִינּוּן מֶלֶךְ מַלַךְ יִמְלוֹךְ, יְהוָֹ\"ה אֶהְיְ\"ה אֲדֹנָ\"י. סַךְ הַכֹּל יַבֹּ\"ק (רבי אבא ורבי יוסי שבע\"ב שייך כאן).</p>\n<p>רִבִּי שִׁמְעוֹן הֲוָה יָתִיב וְלָעֵי בְּפָרְשְׁתָא דָּא, אָתָא לְקַמֵּיהּ רִבִּי אֶלְעָזָר בְּרֵיהּ, אָמַר לֵיהּ, נָדָב וַאֲבִיהוּא מַאי עֲבִידְתַיְיהוּ בְּפִנְחָס. אִי לָא הֲוָה פִּנְחָס בְּעָלְמָא כַּד מִיתוּ, וּבָתַר אָתָא לְעָלְמָא וְאַשְׁלִים דּוּכְתַיְיהוּ שַׁפִּיר. אֲבָל פִּנְחָס בְּעָלְמָא הֲוָה, (ס\"א וסגן קאי) וְנִשְׁמָתֵיהּ בֵּיהּ בְּקִיּוּמָא קָאֵי.</p>\n<p>אָמַר לֵיהּ בְּרִי, רָזָא עִלָּאָה הָכָא, וְהָכִי הוּא. דִּבְשַׁעֲתָא דְּאִסְתָּלָקוּ מִן עָלְמָא, לָא הֲווֹ מִתְטַמְּרָן תְּחוֹת גַּדְפֵּי טִנָרָא קַדִישָׁא. מַאי טַעְמָא. בְּגִין דִּכְתִּיב, (במדבר ג) וּבָנִים לֹא הָיוּ לָהֶם, דְּאַזְעִירוּ דִּיּוּקְנָא דְּמַלְכָּא, דְּהָא אִינּוּן לָא אִתְחָזוּן לְשַׁמְּשָׁא בִּכְהוּנָה רַבָּה.</p>\n<p>בְּשַׁעֲתָא דְּקַנֵּי פִּנְחָס עַל בְּרִית קַדִישָׁא, וְעָאל בְּגוֹ כַּמָה אוּכְלוֹסִין, וְסָלִיק לוֹן, לְגַיִיפִין עַל רוּמְחָא, לְעֵינֵיהוֹן דְּכָל יִשְׂרָאֵל. כַּד חָמָא שִׁבְטָא דְּשִׁמְעוֹן בְּכַמָּה אֻכְלוּסִין דְּאָתוּ לְגַבֵיהּ, פַּרְחָא נִשְׁמָתֵיהּ מִנֵּיהּ, וּתְרֵין נִשְׁמָתִין דַּהֲווֹ עַרְטִירָאִין בְּלָא דּוּכְתָא, אִתְקְרִיבוּ בָּהּ, וְאִתְכְּלִילוּ כַּחֲדָא, וְאִתְהַדְּרַת נִשְׁמָתֵיהּ, כְּלִילָא רוּחָא, דְּאִתְכְלִיל בִּתְרֵין רוּחִין, וְאִתְתָּקָפוּ בֵּיהּ, כְּדֵין רָוַוח דּוּכְתַיְיהוּ, לְמֵיהֱוִי כַּהֲנָא (רבא) מַה דְּלָא (אתחזי) מִן קַדְמַת דְּנָא.</p>\n<p>וְעַל דָּא כְּתִיב, (איוב ד׳:ז׳) זְכָר נָא מִי הוּא נָקִי אָבָד, דְּלָא אִתְאֲבִיד בְּהַהִיא שַׁעֲתָא, וְלָא אָבִיד רוּחֵיהּ כַּד פַּרְחָה מִנֵּיהּ. וְאֵיפֹה יְשָׁרִים נִכְחָדוּ. אִלֵּין בְּנֵי אַהֲרֹן, דְּאִתְהַדְרוּ לְעָלְמָא, מַה דְּאָבַד בְּחַיִּיהוֹן. וְעַל דָּא כְּתִיב בֵּיהּ בְּפִנְחָס בֶּן בֶּן, תְּרֵי זִמְנֵי. פִּנְחָס בֶּן אֶלְעָזָר בֶּן.</p>\n<p>מַה כְּתִיב לְעֵילָּא מִפָּרַשְׁתָא דָּא. (במדבר כ״ה:ד׳) וַיּאמֶר יְיָ אֶל מֹשֶׁה קַח אֶת כָּל רָאשֵׁי הָעָם וְהוֹקַע אוֹתָם לַיְיָ נֶגֶד הַשָּׁמֶשׁ. וְכִי עַל דְּקַטְלִין בְּלֵילְיָא, אוֹ עַל דְּקַטְלִין בִּימָמָא בְּיוֹמָא דְּעִיבָא, כְּתִיב נֶגֶד הַשָּׁמֶשׁ. אָמַר רִבִּי יְהוּדָה, דְּתְהֵא מִיתָתְהוֹן בְּאִתְגַּלְיָיא, כְּמָה דְּחָבוּ בְּאִתְגַּלְיָיא.</p>\n<p>אָמַר רִבִּי שִׁמְעוֹן, לָאו בְּגִין כַּךְ אִתְּמַר. אֶלָּא מֵהָכָא אוֹלִיפְנָא, בְּדַרְגָא דְּחָב בַּר נָשׁ לְּקוּדְשָׁא בְּרִיךְ הוּא, לְהַהוּא אֲתָר אִצְּטְרִיךְ לְמֶעְבַּד תְּקַנְתָּא לְנַפְשֵׁיהּ. אִינּוּן חָבוּ בִּבְרִית קַדִישָׁא דְּאִקְרֵי שֶׁמֶשׁ. בְּגִין כַּךְ דִּינָא וְתִקּוּנָא דִּילְהוֹן אִיהוּ כְּנֶגֶד הַשֶּׁמֶשׁ, וְלָאו בַּאֲתָר אַחֲרָא. מִכָּאן דְּלָא אִצְּטְרִיךְ בַּר נָשׁ לְתַקְּנָא נַפְשֵׁיהּ, אֶלָּא בְּהַהוּא אֲתָר דְּחָב לְגַבֵיהּ וּמַאן דְּלָא יַעְבִּיד הָכִי, לֵית לֵיהּ תִּקּוּנָא לְעָלְמִין כַּדְּקָא יָאוּת.</p>\n<p>רִבִּי חִיָּיא פָּתַח, (תהילים ק״ד:ט״ז) יִשְׂבְּעוּ עֲצֵּי יְיָ אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, מַה כְּתִיב לְעֵילָּא, וְיַיִן יְשַׂמַּח לְבַב אֱנוֹשׁ וְגוֹ'. וְכִי מַאי הַאי לְהַאי. אֶלָּא הָכִי אוֹלִיפְנָא, דִּכְתִּיב, (תהילים ק״ד:ט״ו) (בראשית י\"ח ע\"ב) מַצְּמִיחַ חָצִּיר לַבְּהֵמָה וְגוֹ'. וְכִי שְׁבָחָא דִּבְהֵמָה דְּאִית לָהּ חָצִּיר אָתָא דָּוִד לְמֵימַר בְּרוּחַ קוּדְשָׁא. אֶלָּא מַצְּמִיחַ חָצִּיר, אִלֵּין אִינּוּן שִׁתִּין אֶלֶף רִבּוֹא דְּמַלְאָכִין, שְׁלִיחָן, דְּאִתְבְּרִיאוּ בְּיוֹמָא תִּנְיָינָא דִּבְרֵאשִׁית, וְכֻלְּהוּ אֶשָּׁא מְלָהֲטָא. אִלֵּין אִינּוּן חָצִּיר. אֲמַאי חָצִּיר. בְּגִין דְּצַּמְחִין כֶּחָצִּיר דָּא בְּעָלְמָא, דְּכָל יוֹמָא וְיוֹמָא אִתְקְצִּירוּ הַשְׁתָּא, וּלְבָתַר צַּמְחִין וּמְהַדְּרִין כְּמִלְּקַדְּמִין.</p>\n<p>וְעַל דָּא כְּתִיב מַצְּמִיחַ חָצִּיר לַבְּהֵמָה, הֲדָא הוּא דִכְתִיב (משלי י״ב:י׳) יוֹדֵעַ צַּדִּיק נֶפֶשׁ בְּהֶמְתּוֹ, וְתָנֵינָן, אֶלֶף טוּרִין סַלְּקִין לָהּ בְּכָל יוֹמָא וְיוֹמָא. וְכָל טוּרָא וְטוּרָא שִׁתִּין רִבּוֹא הֲוִי, וְהִיא אָכְלָה.</p>\n<p>וְעֵשֶׂב לַעֲבוֹדַת הָאָדָם, אִלֵּין אִינּוּן נִשְׁמָתְהוֹן דְּצַּדִּיקַיָּיא, דְּהַהוּא אָדָם דְּרָכִיב וְשָׁלִיט עַל בְּהֵמָה דָּא אָכִיל, וְאָעִיל לוֹן בְּגַוִּויהּ, וּבִזְכוּתֵהוֹן אִתְּזָן כָּל עָלְמָא מֵהַהוּא אָדָם, דִּכְתִּיב בֵּיהּ, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם וְגוֹ'. וְעַל דָּא כְּתִיב הָאָדָם, הַהוּא דְּאִשְׁתְּמוֹדַע, בְּגִין לְהוֹצִּיא לֶחֶם מִן הָאָרֶץ, לְאַפָּקָא מְזוֹנָא לְעָלְמָא מִן הָאָרֶץ קַדִּישָׁא.</p>\n<p>וְיַיִן, דָּא חַמְרָא עַתִּיקָא דְּנָגִיד מִלְעֵילָּא. יְשַׂמַּח לְבַב אֱנוֹשׁ, אֱנוֹשׁ: דָּא רָזָא דְּהַהוּא נַעַר, <Nonei></i>דְּסָלִיק לְסִיבוּ, וְאִתְהַדָּר כְּמִלְּקַדְּמִין. וְעַל דָּא כְּתִיב, (תהילים ק״ג:ט״ו) אֱנוֹשׁ כֶּחָצִּיר יָמָיו.</p>\n<p>לְהַצְּהִיל פָּנִים: אִלֵּין אִינּוּן פָּנִים, דְּאִקְרוּן אַנְפֵּי רַבְרְבֵי, וְאַנְפֵּי זוּטְרֵי. מִשָּׁמֶן: מִנְּגִידוּ דְּעָלְמָא דְּאָתֵי, מְשַׁח וּרְבוּ קַדִּישָׁא עִלָּאָה. וְלֶחֶם לְבַב אֱנוֹשׁ יִסְעָד, הַהוּא לֶחֶם דְּאֲזִילוּ שְׁחָקִים, וְטַחֲנָן מַנָא לְמֵיכְלָא דְּצַּדִּיקַיָּיא סְתָמָא, וּמִתַּמָּן אִתְנְגִיד לְכַמָּה חַיָּילִין, דְּאִקְרוּן לְבַב אֱנוֹשׁ. וְכֹלָּא אָתָא מִנְּגִידוּ עִלָּאָה.</p>\n<p>יִשְׂבְּעוּ עֲצֵּי יְיָ, אִלֵּין אִינּוּן אִילָנִין עִלָּאִין פְּנִימָאִין. אַרְזֵי לְבָנוֹן אֲשֶׁר נָטָע, דְּהָא אִתְעֲקָרוּ וְנָטַע לוֹן קוּדְשָׁא בְּרִיךְ הוּא. מַאי בֵּין עֲצֵּי יְיָ, לְאַרְזֵי לְבָנוֹן. עֲצֵּי יְיָ, אִלֵּין עֵץ הַחַיִּים, וְעֵץ הַדַּעַת וְטוֹב וָרָע. אַרְזֵי לְבָנוֹן, אִלֵּין חַמְשִׁין תַּרְעִין, דְּאִקְרוּן חָמֵשׁ מֵאוֹת שָׁנָה.</p>\n<p>אֲשֶׁר נָטָע. אֲשֶׁר שָׁם צִּפֳּרִים יְקַנֵּנוּ, בְּטוּלְיהוֹן, (רצ\"ו) מְקַנְּנָן נִשְׁמָתֵהוֹן דְּצַּדִּיקַיָּיא, וְכָל חַיָּילִין קַדִּישִׁין אִתְּזָנוּ מִתַּמָּן. חֲסִידָה, בְּרָתֵיהּ דְּאַבְרָהָם אָבִינוּ, דְּאִקְרֵי חָסִיד, וְעָבִיד חֶסֶד עִם כָּל בְּנֵי עָלְמָא, בְּגִין כָּךְ אִקְרֵי (שמות צ\"ה ע\"ב) חֲסִידָה. בְּרוֹשִׁים בֵּיתָה. בֵּין דְּרוֹעֵי עָלְמָא יָתְבָא. (ע\"כ רעיא מהימנא)</p>"],[9520012521,"<p>רִבִּי אַבָּא וְרִבִּי יוֹסֵי, קָמוּ לְמִלְעֵי בְּאוֹרַיְיתָא בְּפַלְגוּת לֵילְיָא, עַד דַּהֲווֹ יַתְבֵי וְלָעָאן בְּאוֹרַיְיתָא. אָמַר רִבִּי יוֹסֵי, הָא דְּאָמַר רִבִּי חִיָּיא אֱנוֹשׁ כֶּחָצִיר יָמָיו שַׁפִּיר קָאָמַר. אֲבָל בְּמַאי אוֹקִימְנָא סוֹפֵיהּ דִּקְרָא, כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ. אָמַר לֵיהּ הָכִי הוּא וַדַּאי, אֱנוֹשׁ כֶּחָצִיר יָמָיו כְּמָה דְּאָמַר, כְּצִיץ הַשָּׂדֶה הַהוּא שָׂדֶה דְּאִשְׁתְּמוֹדַע. כֵּן יָצִיץ דְּאִתְחַדָּשׁ וְאִתְהַדָּר כְּמִלְּקַדְּמִין. (הכי יציץ וסליק, מאי טעמא בגין)</p>\n<p>כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ, דָּא הוּא רוּחָא עִלָּאָה טְמִירָא קַדִּישָׁא גְּנִיזָא מִכֹּלָּא, דְּכָלִיל לֵיהּ בְּגַוִּיהּ. וּכְדֵין וְאֵינֶנּוּ. וְדָא הוּא רָזָא דַּחֲנוֹךְ, דִּכְתִּיב בֵּיהּ (בראשית ה׳:כ״ד) וְאֵינֶנּוּ כִּי לָקַח אוֹתוֹ אֱלֹהִים, דָּא אֱלֹהִים עִלָּאָה. רוּחַ עִלָּאָה, רוּחַ גְּנִיזָא טְמִירָא. וְלָא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ. דְּהָא אִתְכְּלִיל רוּחָא זְעֵירָא, בְּרוּחָא עִלָּאָה. מַה כְּתִיב בַּתְרֵיהּ, וְחֶסֶד יְיָ מֵעוֹלָם וְעַד עוֹלָם וְעָאל לֵיהּ כַּהֲנָא רַבָּא לְגוֹ קֹדֶשׁ קֳדָשִׁים. וְנָטִיל לֵיהּ, וְאוֹלִיד לֵיהּ כְּמִלְּקַדְּמִין, וְאִתְחַדָּשׁ כְּנֶשֶׁר עוּלְמִין. וְאִתְהַדָּר אִיהוּ נַעַר.</p>\n<p><Noneb>רעיא מהימנא</b> וּבְחִבּוּרָא קַדְמָאָה אָמַר רַעְיָא מְהֵימָנָא בּוּצִּינָא קַדִּישָׁא, שַׁפִּיר אָמְרוּ רִבִּי אַבָּא וְרִבִּי חִיָּיא וְרִבִּי יוֹסֵי, אֲבָל (תהילים ק״ג:ט״ז) כִּי רוּחַ עָבְרָה בּוֹ וְאֵינֶנּוּ, הָכָא צָּרִיךְ לְמִפְתַּח מִלִּין, מַאי עָבְרָה בּוֹ. דָּא עֶבְרָה וְזַעַם וְצָּרָה. חַד מֵאִינּוּן מַלְאֲכִין רָעִים.</p>\n<p>דִּבְגִין דְּלָא יִשְׁתְּמוֹדְעוּ בֵּיהּ אִינּוּן מָארֵי חוֹבִין, צָּרִיךְ לְמֶעְבַּד לֵיהּ שִׁנּוּי מָקוֹם, וְשִׁנּוּי הַשֵּׁם, וְשִׁנּוּי מַעֲשֵׂה. כְּגַוְונָא דְּאַבְרָהָם, דְּאִתְּמַר בֵּיהּ (בראשית י״ב:א׳) לֶךְ לְךָ מֵאַרְצְּךָ וּמִמּוֹלַדְתְּךָ, הֲרֵי שִׁנּוּי מָקוֹם. (בראשית י״ז:ה׳) וְלֹא יִקָּרֵא עוֹד שִׁמְךָ אַבְרָם, וְהָיָה שִׁמְךָ אַבְרָהָם, הֲרֵי שִׁנּוּי הַשֵּׁם. שִׁנּוּי מַעֲשֵׂה דְּאִשְׁתָּנֵי מֵעוֹבָדִין בִּישִׁין דְּעָבַד בְּקַדְמִיתָא, לְעוֹבָדִין טָבִין. אִיהוּ מְתָלָא. לְרוּחַ דְּהַהוּא דְּמִית בְּלָא בְּנִין. כְּגַוְונָא דָּא עָבֵד קוּדְשָׁא בְּרִיךְ הוּא לְאָדָם, כַּךְ תָּרִיךְ לֵיהּ מֵהַהוּא עָלְמָא, וְאַיְיתֵי לֵיהּ לְהַאי עָלְמָא. וְהָא אִתְּמַר לְעֵיל.</p>\n<p>(איוב י״ד:כ׳) מְשַׁנֶּה פָּנָיו וַתְּשַׁלְּחֵהוּ, וּבְגִין דָּא כִּי רוּחַ עָבְרָה בּוֹ, חַד מֵאִינּוּן מַלְאֲכִין רָעִים, כַּד חֲזֵי לֵיהּ מְשׁוּנֶּה, בְּזִמְנָא דְּאִעְרַע (ס\"א ביה) עִמֵּיהּ, שָׁאַלִין לֵיהּ שְׁאַר מַשְׁחִיתִין עָלֵיהּ, דָּא הוּא מָארֵי חוֹבָךְ. אִיהוּ עָנֵי לוֹן וְאָמַר, וְאֵינֶנּוּ.</p>\n<p>כַּד אִתְתָּרַךְ מֵאַתְרֵיהּ, וְאִתְנְטָע בְּאֲתָר אַחֲרָא, אִתְּמַר בֵּיהּ וְלֹא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ. בְּגִין (ויקרא י״ד:מ״ב) דְּעָפָר אַחֵר יִקַּח וְטָח אֶת הַבַּיִת. וְדָא אִיהוּ רָזָא, וְנָתַץ אֶת הַבַּיִת אֶת אֲבָנָיו וְאֶת עֵצָּיו, אִינּוּן גַּרְמִין וְגִידִין וּבִשְׂרָא דְּהֲוָה חָזַר עֲפָרָא. מַה כְּתִיב בֵּיהּ (ישעיהו ס״ה:כ״ה) וְנָחָשׁ עָפָר לַחְמוֹ. בְּגִין דְּהֲוָה מְנוּגָע. וּלְבָתַר וְעָפָר אַחֵר יִקַּח וְטָח אֶת הַבָּיִת, וּבָנֵי לֵיהּ גַּרְמִין וְגִידִין. וְאִתְחַדָּשׁ, כְּבַיִת יְשָׁנָה דְּעַבְדִין לֵיהּ חֲדָשָׁה. וַדַּאי אִיהוּ דְּאִתְחַדֵּשׁ.</p>\n<p>וּמַאי דְּאָמַר וְלֹא <Nonei></i>יַכִּירֶנּוּ עוֹד מְקוֹמוֹ. עַל רוּחַ, דְּאִתְכְּלִיל רוּחָא זְעֵירָא, בְּרוּחָא עִלָּאָה. הַאי אִיהוּ מְתָלָא, לְאִילָן דְּלָא עָבִיד אֵיבִין, נַטְלִין עַנְפִין דִּילֵיהּ, וּמַרְכִּיבִין לֵיהּ בְּעַנְפָּא דְּאִילָנָא אַחֲרָא עִלָּאָה, (דא בדא) דְּעָבִיד פֵּירִין, וְאִתְכְּלִיל דָּא בְּדָא, וְעָבִיד פֵּירִין. בְּהַהוּא זִמְנָא אִתְּמַר בֵּיהּ, וְלָא יַכִּירֶנּוּ עוֹד מְקוֹמוֹ.</p>\n<p>אוּף הָכִי בַּר נָשׁ דְּיָתִיב בְּקַרְתָּא דְּיַתְבִין בָּהּ אֲנָשִׁין בִּישִׁין, וְלָא יָכִיל לְקַיְּימָא פִּקוּדִין דְּאוֹרַיְיתָא, וְלָא אַצְּלַח בְּאוֹרַיְיתָא, עָבִיד שִׁנּוּי מָקוֹם, וְאִתְעַקָּר מִתַּמָּן, וְאִשְׁתְּרָשׁ בַּאֲתָר דְּדַיְירִין בֵּיהּ גּוּבְרִין טָבִין, מָארֵי תּוֹרָה, מָארֵי פִּקוּדִין, דְּאוֹרַיְיתָא אִקְרֵי עֵץ. הֲדָא הוּא דִכְתִיב, (משלי ג׳:י״ח) עֵץ חַיִּים הִיא לַמַּחֲזִיקִים בָּה. וּבַר נָשׁ הוּא עֵץ, דִּכְתִּיב, (דברים כ׳:י״ט) כִּי הָאָדָם עֵץ הַשָּׂדֶה. וּפִקּוּדִין דְּבָהּ, דַּמְיָין לְאִיבָא, וּמַה כְּתִיב בֵּיהּ, (דברים כ׳:כ׳) רַק עֵץ אֲשֶׁר תֵּדַע כִּי לֹא עֵץ מַאֲכָל הוּא אוֹתוֹ תַּשְׁחִית וְכָרַתָּ. אוֹתוֹ תַּשְׁחִית מֵעָלְמָא דֵּין, וְכָרַתָּ מֵעָלְמָא דְּאָתֵי. וּבְגִין דָּא צָּרִיךְ לְאַעְקְרָא (ליה מההוא) מֵהַהוּא אֲתָר, וְיִתְנְטַע בַּאֲתָר אַחֲרָא בֵּין צַּדִּיקַיָּיא.</p>\n<p>מַה בַּר נָשׁ בְּלָא בְּנִין, אִתְקְרֵי עָקָר, וְאִתְּתֵיהּ עֲקָרָה. אוּף הָכִי אוֹרַיְיתָא בְּלָא פִּקוּדִין, אִתְקְרִיאַת עֲקָרָה, וּבְגִין דָּא אוּקְמוּהָ, לֹא הַמִּדְרָשׁ הוּא הָעִיקָּר אֶלָּא הַמַּעֲשֶׂה. אָתוּ חַבְרַיָּיא וְאִשְׁתְּטָחוּ קַמֵּיהּ, וְאָמְרוּ וַדַּאי כְּעַן אוֹלִיפְנָא חִדּוּשָׁא, אֵיךְ אִתְכְּלִיל רוּחַ בְּרוּחַ, כְּמַאן דְּחָזֵי מִלָּה בְּעֵינָא וְאִתְבְּרִיר לֵיהּ. בְּקַדְמִיתָא הֲוָה לָן קַבָּלָה, וּכְעַן בְּרִירוּ דְּמִלָּה.</p>"],[9520012522,"<p>וְתוּ אִתְּמַר בְּחִבּוּרָא קַדְמָאָה, דְּהָא נִיחָא לֵיהּ לְסִטְרָא אַחֲרָא לְשַׁלְּטָאָה עַל זַכָּאָה, יַתִּיר מִכֹּלָּא, וְלָא חָיִישׁ כְּדֵין לְכָל עָלְמָא. אַדְּהָכִי, הָא טוּלָא אִזְדְּמַן לְגַבַּיְיהוּ, וְאָמַר לֵיהּ מְנָלָן. מֵאִיּוֹב. דְּחָזָא קוּדְשָׁא בְּרִיךְ הוּא דְּדָרָא הֲווֹ מְחוּיָבִין כְּלָיָיה, וְאָתָא שָׂטָן לְקַטְרְגָא, אָמַר לֵיהּ קוּדְשָׁא בְּרִיךְ הוּא, (איוב א׳:ח׳) הֲשַׂמְתָּ לִבְּךָ אֶל עַבְדִּי אִיּוֹב כִּי אֵין כָּמוֹהוּ בְּכָל הָאָרֶץ, לְאִשְׁתְּזָבָא בֵּיהּ דָּרָא. וְאִיהוּ מְתָלָא לְרַעְיָא דְּאָתָא זְאֵב לְמִטְרַף עָאנֵיהּ, וּלְמֵיבַד לֵיהּ. מַה עָבֵד הַהוּא רַעְיָא דְּהֲוָה חַכִּימָא, יָהִיב לֵיהּ אִמְרָא תַּקִּיפָא וּשְׁמֵנָה וְרַבְרְבָא מִכֻּלְּהוּ, הַהוּא דַּהֲווֹ מִתְנַהֲגִין אֲבַּתְרֵיהּ כֻּלְּהוּ. וּבִרְעוּ לְשַׁלְּטָאָה עַל הַהוּא אִמְרָא טָבָא, שָׁכַח (נ\"א שבק) לְכֻלְּהוּ. מַה עָבֵד הַהוּא רַעְיָא, בְּשַׁעֲתָא דְּהֲוָה זְאֵב אִשְׁתָּדַּל בְּהַהוּא אִמְרָא, בָּרַח רַעְיָא עִם עָאנָא וְשַׁוִּי לוֹן <Nonei></i>בְּאַתְרֵיהוֹן. וּלְבָתַר תָּב לְאִמְרָא, וְשֵׁזִיב לֵיהּ מִזְּאֵב.</p>\n<p>הָכִי עָבִיד קוּדְשָׁא בְּרִיךְ הוּא עִם דָּרָא, יָהִיב קוּדְשָׁא בְּרִיךְ הוּא לַצַּדִּיק, בִּרְשׁוּ מְקַטְרְגָא, לְשֵׁזָבָא לְדָרָא בְּגִינֵיהּ. וְאִם הוּא תַּקִּיף כְּיַעֲקֹב, אִתְּמַר בֵּיהּ (בראשית ל״ב:כ״ה) וַיִאָבֵק אִישׁ עִמּוֹ, כָּל שֶׁכֵּן וְכָּל שֶׁכֵּן דְּנָצַּח לֵיהּ, עַד דְּאָמַר שַׁלְּחֵנִי. אָמַר טוּלָא טוּלָא, הָכִי הוּא, זַכָּאָה חוּלָקֵיהּ דְּהַהוּא צַּדִּיק, דְּאִיהוּ תַּקִּיף לְמִסְבַּל יִיסוּרִין, כָּל שֶׁכֵּן מַאן דְּנָצַּח בְּהוֹן לִמְקַטְרְגָא דִּילֵיהּ. דְּאִיהוּ שׁוּלְטָנוּתֵיהּ עַל כָּל דָּרָא, וְאִתְחֲשִׁיב לֵיהּ כְּאִילּוּ הוּא שֵׁזִיב לוֹן, וְקוּדְשָׁא בְּרִיךְ הוּא עָבִיד לֵיהּ רַעְיָא עָלַיְיהוּ בְּאַתְרֵיהּ, וּבְגִין דָּא זָכָה רַעְיָא מְהֵימָנָא. לְמֶהֱוִי רוֹעֶה עַל יִשְׂרָאֵל, וְלֹא עוֹד אֶלָּא דְּהָכִי אַשְׁלִיט לֵיהּ עָלַיְיהוּ בְּעָלְמָא דְּאָתֵי. בְּגִין דְּשֵׁזִיב לוֹן דְּלָא אִתְאֲבִידוּ מִתַּמָּן, דְּאַנְהִיג לוֹן בְּאוֹרַיְיתָא וּבְעוֹבָדִין טָבִין.</p>\n<p>אַדְּהָכִי הָא רַעְיָא מְהֵימָנָא, אָמַר לוֹן, וַאֲמַאי לָקֵי דְּרוֹעָא יְמִינָא. דְּאוֹרַח כָּל מָארֵי אַסְוָותָא דַּאֲקִיזִין בְּקַדְמִיתָא דְּרוֹעָא יְמִינָא, וְהָא דְּרוֹעָא שְׂמָאלָא אִיהוּ קָרִיב לְלִבָּא, אֲמַאי לָא אֲקִיזִין לֵיהּ. אָמַר לֵיהּ בְּגִין דְקוּדְשָׁא בְּרִיךְ הוּא לָא בָּעֵי לְאַלְקָאָה יַתִּיר, דְּהָא בְּהַאי סַגֵּי, וְאִי אִתְיְקַר מַרְעָא עַל שַׁיְיפִין דְּגוּפָא, אָקִיז דְּרוֹעָא שְׂמָאלָא.</p>\n<p>אָמַר לֵיהּ, אִי לָא הֲווֹ תַּרְוַויְיהוּ בְּחַד זִמְנָא, יָאוּת אֲבָל אִית צַּדִּיק הָכָא, וְאִית צַּדִּיק הָכָא, לְדָא אִית מַרְעִין וּמַכְתְּשִׁין, וּלְדָא אִית טִיבוּ. אֲמַאי. אִי אִתְיְיקַר בֵּיהּ מַרְעָא יַקִּיז לְתַרְוַויְיהוּ, דְּאִינּוּן תְּרֵין דְּרוֹעִין, לְמֵיהַב אַסְוָותָא לְכָל שַׁיְיפִין, וְאִי לָא אִתְיְיקַר בֵּיהּ מַרְעָא עַל כָּל שַׁיְיפִין, אֲמַאי אָקִיז לִדְרוֹעָא יְמִינָא, יַתִּיר מִשְּׂמָאלָא. אֶלָּא (נ\"א אמר ליה) אֵימָא אַנְתְּ.</p>\n<p>אָמַר לֵיהּ, וַדַּאי גּוּפָא וּתְרֵין דְּרוֹעִין, אִינּוּן לָקֳבֵל אֲבָהָן. רֵישָׁא, לָקֳבֵל אָדָם קַדְמָאָה. דְּרוֹעָא יְמִינָא, לָקֳבֵל אַבְרָהָם. דְּרוֹעָא שְׂמָאלָא, לָקֳבֵל יִצְּחָק. גּוּפָא, לָקֳבֵל יַעֲקֹב. וּמִלְּגוֹ לְגוּפָא, כָּבֵד לִימִינָא. טְחוֹל לִשְׂמָאלָא. עֵשָׂו וְיִשְׁמָעֵאל. לִבָּא יַעֲקֹב, בְּאֶמְצָּעִיתָא. כַּנְפֵי רֵיאָה וְכוּלְיָין, לָקֳבֵל אַבְרָהָם וְיִצְּחָק. רֵיאָה מַיִם. דְּאִינּוּן (ס\"א כנפי ריאה שואבין) שׁוֹאֲבִין כָּל מִינֵי מַשְׁקִין. כּוּלְיָין אֶשָּׁא, דְּבָשִׁיל זְרַע דְּנָחִית מִמּוֹחָא.</p>\n<p>וּבְגִין דְּאַבְרָהָם אִיהוּ מַיִם, שַׁוִּי זַרְעֵיהּ בְּגָלוּתָא דֶּאֱדוֹם וּבְגִין דָּא כָּבֵד לִימִינָא דְּאַבְרָהָם, וּמָרָה, דְּכָבֵד חֶרֶב דִּילֵיהּ, אִיהִי מָרָה, אִתְּמַר <Nonei></i>בָּהּ (משלי ה׳:ד׳) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה. וְאִי חוֹבִין מִתְרַבִּין בִּבְנוֹי דְּאַבְרָהָם דְּאִינּוּן בְּגָלוּתָא דֶּאֱדוֹם, אִתְיְקַר בֵּיהּ מְרָע עָלַיְיהוּ מִסִּטְרָא דְּכָבֵד, דְּרוֹעָא יְמִינָא צָּרִיךְ לְאַלְקָאָה לְאָקָזָא דָּמֵיהּ מִנֵּיהּ, דְּמַאן דְּנַטְלִין מִנֵּיהּ מָמוֹנֵיהּ, כְּאִילּוּ שְׁפִיכוּ דָּמֵיהּ, וְאִשְׁתְּאַר עָנִי, דְּעָנִי חָשׁוּב כַּמֵּת.</p>\n<p>וְאִי חוֹבִין מִתְרַבִּין מִסִּטְרָא דִּבְנֵי יִצְּחָק, דְּאִינּוּן (ס\"א בגלותא) בֵּין יִשְׁמָעֵאל, בֵּי מַרְעֵיהּ יִתְיְקַר מִסִּטְרָא דִּטְחוֹל לִשְׂמָאלָא, וְצָּרִיךְ לְאָקָזָא דְּרוֹעָא שְׂמָאלָא, וְלָא יַתִּיר.</p>\n<p>וְאִי חוֹבִין מִתְרַבִּין בִּבְנֵי יַעֲקֹב, דְּאִינּוּן אֲחִידָן לִתְרֵין סִטְרִין, דְּאִינּוּן מְפוּזָרִים בִּבְנֵי עֵשָׂו וְיִשְׁמָעֵאל, הָא מַרְעָא אִתְיְקַר עַל גּוּפָא, וּבָעֵי לְאָקָזָא ב' דְּרוֹעִין. וְאִי כֻּלְּהוּ תְּלַת בְּמַרְעִין כַּחֲדָא. הָא מַרְעָא סָלִיק לְרֵישָׁא, וּבָעֵי לְאָקָזָא וְרִידִין דְּרֵישָׁא, וְאִלֵּין תְּלַת אִתְעָבִידוּ מֶרְכָּבָה לְאָדָם קַדְמָאָה וְלַאֲבָהָן, וּבְהוֹן אִתְתְּקָפוּ לְמִסְבַּל יִיסוּרִין, לְאַגָּנָא עַל דָּרָא לְאַרְבַּע סִטְרֵי דְּעָלְמָא.</p>\n<p>וַוי לֵיהּ לְדָרָא, דְּגַרְמִין דְּיִלְקוּן אֲבָהָן וְאָדָם קַדְמָאָה, וְאִלֵּין צַּדִּיקַיָּיא דְּבֵינַיְיהוּ, דְּלֵית אַפְרָשׁוּתָא בֵּין אִלֵּין צַּדִּיקַיָּא, לַאֲבָהָן וְאָדָם, דְּאִינּוּן נִשְׁמָתִין דִּלְהוֹן, וְדוֹחֲקָא וְצַּעֲרָא וִיגוֹנָא דִּלְהוֹן, מָטֵי לַאֲבָהָן וְאָדָם. כְּגַוְונָא דְּיַמָּא, אִלֵּין נַחֲלִין דְּנָפְקִין מִתַּמָּן, אִי חוֹזְרִין עֲכוּרִין וּמְלוּכְלָכִין לְיַמָּא, הָא יַמָּא נָטִיל מִן עָכִירוּ וְלִכְלוּכָא דִּלְהוֹן. וּבְחֵילָא דְּיַמָּא דְּאִיהִי תַּקִּיפָא, לָא סְבִילַת לִכְלוּכָא דִּלְהוֹן, וּזְרִיקַת לֵיהּ לְבַר, וְאִשְׁתְּאָרוּ נַחֲלִין צְּלִילִין וְדַכְיָין מֵהַהוּא לִכְלוּךְ.</p>\n<p>כְּגַוְונָא דְּאִימָא, דְּדָכִיאָת לִכְלוּכִין דִּבְנָהָא זְעִירִין, הָכִי אֲבָהָן מְדַכְּאִין חוֹבִין וְלִכְלוּכִין דִּבְנַיְיהוּ דְּיִשְׂרָאֵל, כַּד אִשְׁתְּכָחוּ בְּהוֹן צַּדִּיקַיָּיא בְּעוֹבָדֵיהוֹן, תַּקִּיפִין לְמִסְבַּל יִיסוּרִין עַל דָּרֵיהוֹן. בְּהַהוּא זִמְנָא לֵית אַפְרְשָׁא בְּהוֹן. אָתוּ כֻּלְּהוּ וּבָרִיכוּ לֵיהּ, וְאָמְרוּ לֵיהּ סִינַ\"י סִינַ\"י, דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ מַלִּיל בְּפוּמוֹי, מַאן יָכִיל לְקַיְּימָא קַמֵּיהּ בְּכֹלָּא. זַכָּאָה חוּלָקָנָא, דְּזָכֵינָא לְחַדְּשָׁא חִבּוּרָא קַדְמָאָה דָּא בָּךְ, לְאַנְהָרָא שְׁכִינְתָּא בְּגָלוּתָא.</p>"],[9520012523,"<p>אָמַר לוֹן, רַבָּנָן דְּכָל דָּרָא הֲוִיתוּ בִּזְמַנֵּיהוֹן, כָּל שֶׁכֵּן בּוּצִּינָא קַדִּישָׁא, דְּנָהִיר חָכְמָתֵיהּ בְּכָל דָּרִין דַּהֲווֹ אֲבַּתְרֵיהּ, אַל תִּתְּנוּ דֳּמִי לְּקוּדְשָׁא בְּרִיךְ הוּא בְּאוֹרַיְיתָא, עַד יֵעָרֶה עָלֵינוּ רוּחַ קֻדְשָׁא (לגבי שכינתיה) דְּהָא לָא אִית רְשׁוּ לְאִשְׁתַּמְּשָׁא בִּמְטַטְרוֹ\"ן שַׂר הַפָּנִים אֶלָּא לָךְ, דְּאַתְוָון דִּילֵיהּ רְמִיזִין בִּשְׁמָךְ.</p>\n<p>וּכְעַן צָּרִיךְ אַסְיָא, לְמִנְדַּע בְּכַמָּה דַּרְגִּין אִסְתָּלַּק דְּפִיקוּ דְּהַהוּא חוֹלֶה בְּגָלוּתָא דֶּאֱדוֹם, דְּאִתְּמַר עָלֵיהּ (שיר השירים ה׳:ח׳) שֶׁחוֹלַת אַהֲבָה אָנִי. דְּהָא כַּמָה אַסְיָין אִתְכְּנָשׁוּ עָלֵיהּ, לְמִנְדַּע קֵץ דְּמַרְעָא דִּילֵיהּ, בְּאִלֵּין דְּפִיקִין, וְלָא הֲוָה חַד מִנַּיְיהוּ דְּאִשְׁתְּמוֹדַע בְּהוֹן, דִּדְפִיקוּ דְּהַהוּא חוֹלֶה, לָא כָּל אַסְיָא בָּקִי לְאִשְׁתְּמוֹדַע בֵּיהּ, דְּאִית דְּפִיקִין דקשר\"ק קש\"ק קר\"ק, דְּאָמַר נָבִיא עָלַיְיהוּ (ישעיהו כ״ו:י״ז) כְּמוֹ הָרָה תַּקְרִיב לָלֶדֶת תָּחִיל תִּזְעַק בַּחֲבָלֶיהָ.</p>\n<p>וְכֻלְּהוּ עֶשֶׂר שׁוֹפָרוֹת, כְּלִילָן בִּתְלַת, דְּאִינּוּן סִימַן קש\"ר, דְּאִיהוּ תְּקִיעָה שְׁבָרִים תְּרוּעָה. וּתְקִיעָה אַחְזִי אֲרִיכוּ דְּגָלוּתָא, שְׁבָרִים קְרִיבוּ דְּגָלוּתָא. תְּרוּעָה בֵּיהּ יֵיתֵי פּוּרְקָנָא, דְּאַחְזֵי דּוֹחֲקָא בָּתַר דּוֹחֲקָא, וְלֵית רְוָוחָא בֵּין דָּא לְדָא, דְּוַדַּאי כֵּיוָן דִּשְׁאַר עַמִּין מְעַכְּבִין לוֹן לְיִשְׂרָאֵל בְּגָלוּתָא, דּוֹחֲקָא דִּלְהוֹן מְקָרֵב לוֹן פּוּרְקָנָא. אוּף הָכִי מְהִירוּ דִּדְפִיקוּ דָּא בָתֶר דָּא, בֵּיהּ נָפִיק נַפְשָׁא דְּבַּר נָשׁ, בָּתַר דְּלֵית רֶיוַח בֵּין דָּא לְדָא.</p>\n<p>קשר\"ק קש\"ק קר\"ק, אִיהוּ דְּשַׁוִּי קש\"ר, תְּקִיעָה שְׁבָרִים תְּרוּעָה. דְּאִתְעַבָּר בֵּיהּ שֶׁקֶר מִן עָלְמָא, <Nonei></i>דְּבֵיהּ אוֹמָאָה, (שמות י״ז:ט״ז) מִלְחָמָה לַיְיָ בַּעֲמָלֵק. יִתְּעַר בְּעָלְמָא. שִׁיר פָּשׁוּט, וְכָפוּל, וּמְשׁוּלָשׁ, וּמְרוּבָּע. דְּאִיהוּ סָלִיק אַתְוָון דִּילֵיהּ, י', י\"ה, יה\"ו, יהו\"ה, ע\"ב. בְּהַהוּא זִמְנָא, וּבְכֵן צַּדִּיקִים יִרְאוּ וְיִשְׂמָחוּ וִישָׁרִים יַעֲלוֹזוּ וַחֲסִידִים בְּרִנָּה יָגִילוּ. ו' תּוֹסֶפֶת, אֶלֶף שְׁתִיתָאָה. קוֹדֶם דִּילֵיהּ עָקֵ\"ב, חָרַב בֵּי מַקְדְּשָׁא, וּלְבָתַר דִּילֵיהּ, עַד תַּשְׁלוּם רָעָב, יִהְיֶה עֶרֶב. הֲדָא הוּא דִכְתִיב, (שמות ט״ז:ו׳) עֶרֶב וידַעְתֶּם כִּי יְיָ הוֹצִּיא אֶתְכֶם וְגוֹ'. (בראשית מ״ד:ל״ב) כִּי עַבְדֶּךָ עָרַב אֶת הַנַּעַר וְגוֹ'. (ע\"כ רעיא מהימנא)</p>\n<p>עַד דַּהֲווֹ יַתְבֵי, חָמוּ חַד טוּלָא דְּקַיְימָא עָלַיְיהוּ, אַזְלָא וְאַתְיָא, אַזְלָא וְאַתְיָא, בְּגוֹ בֵּיתָא. תַּוְוהוּ. אָמַר רִבִּי אַבָּא, יוֹסֵי בְּנִי, אֵימָא לָךְ מַה דְּהֲוָה לִי עִם בּוּצִינָא קַדִּישָׁא. יוֹמָא חַד הֲוִינָן אַזְלִינָן בְּבִקְעָתָא דְּאוֹנוֹ, וַהֲוִינָן לָעָאן בְּאוֹרַיְיתָא, כָּל הַהוּא <Nonei></i>יוֹמָא, וּמִגּוֹ תּוּקְפָּא דְּשִׁמְשָׁא אוֹתְבֵנָין גַּבֵּי חַד טִינָרָא, בְּגוֹ נוּקְבָּא חֲדָא.</p>\n<p>אֲמֵינָא לֵיהּ, מַאי הַאי, דִּבְכָל שַׁעֲתָא דְּחַיָּיבִין אַסְגִּיאוּ בְּעָלְמָא, וְדִינָא שַׁרְיָיא בְּעָלְמָא, זַכָּאִין דִּבְּהוֹן לָקָאן עָלַיְיהוּ. דְּהָכִי תָּנֵינָן, בְּחוֹבָא דְּדָרָא, קַדִּישַׁיָּיא וְצַדִּיקַיָּיא יִתָּפְסוּן. אֲמַאי, אִי בְּגִין דְּאִינּוּן דְּלָא מוֹכִיחִין לְעָלְמָא עַל עוֹבָדַיְיהוּ, כַּמָּה אִינּוּן דְּמוֹכִיחִין, וְלָא מְקַבְּלֵי מִנַּיְיהוּ, וְצַדִּיקַיָּיא אִתְכַּפְיָין קַמַּיְיהוּ. וְאִי בְּגִין דְּלָא הֲוִי מַאן דְּיָגִין עַל עָלְמָא, לָא יֵהוֹן מֵתִין, וְלָא יִתָּפְסוּן בְּחוֹבַיְיהוּ, דְּהָא חֶדְוָוה אִיהוּ לְצַדִּיקַיָּיא בְּאִבּוּדָא דִּלְהוֹן.</p>\n<p>אָמַר לֵיהּ, בְּחוֹבָה דְּדָרָא וַדַּאי מִתָּפְסִין צַדִּיקַיָּיא, וְהָא אוֹקִימְנָא הָנֵי מִילֵי. אֲבָל בְּשַׁעֲתָא דְּיִתָּפְסוּן צַדִּיקַיָּיא בְּמַרְעִין, אוֹ בְּמַכְתְּשִׁין, בְּגִין לְכַפְּרָא עַל עָלְמָא הֲוִי, כְּדֵין יִתְכַּפְּרוּן כָּל חוֹבֵי דָּרָא, מְנָלָן. מִכָּל שַׁיְיפֵי גּוּפָא, בְּשַׁעֲתָא דְּכָל שַׁיְיפִין בְּעָאקוּ, וּמְרָע סַגֵּי שַׁרְיָיא עָלַיְיהוּ, שַׁיְיפָא חֲדָא אִצְטְרִיךְ לְאַלְקָאָה, בְּגִין דְּיִתְסּוּן כֻּלְּהוּ, וּמַנוּ. דְּרוֹעָא. דְּרוֹעָא אַלְקֵי וְאַפִּיקוּ מִינֵּיהּ דָּמָא, כְּדֵין הָא אַסְוָותָא לְכָל שַׁיְיפֵי גּוּפָא.</p>\n<p>אוּף הָכִי בְּנֵי עָלְמָא אִינּוּן שַׁיְיפִין דָּא עִם דָּא. בְּשַׁעֲתָא דְּבָעֵי קוּדְשָׁא בְּרִיךְ הוּא לְמֵיהַב אַסְוָותָא לְעָלְמָא, אַלְקֵי לְחַד צַדִּיקָא בֵּינַיְיהוּ, בְּמַרְעִין וּבְמַכְתְּשִׁין, וּבְגִינֵיהּ יָהִיב אַסְוָותָא לְכֹלָּא. מְנָלָן. דִּכְתִּיב, (ישעיהו נ״ג:ה׳) וְהוּא מְחוֹלָל מִפְּשָׁעֵינוּ מְדוּכָּא מֵעֲוֹנוֹתֵינוּ וְגוֹ'. וּבַחֲבוּרָתוֹ נִרְפָּא לָנוּ. וּבַחֲבוּרָתוֹ, אֲקָזוּתָא דְּדָמָא, כְּמַאן דְּאָקִיז דְּרוֹעָא, וּבְהַהוּא חַבּוּרָא נִרְפָא לָנוּ, אַסְוָותָא הוּא לָנָא לְכָל שַׁיְיפִין דְּגוּפָא.</p>\n<p>וּלְעוֹלָם לָא אַלְקֵי צַדִּיקָא, אֶלָּא לְמֵיהַב אַסְוָותָא לְדָרָא, וּלְכַפְּרָא עָלַיְיהוּ. (ורזא דא צדיק ורע לו) דְּהָא נִיחָא לְסִטְרָא אַחֲרָא דְּדִינָא שַׁלְטָא (לשלטאה) עַל זַכָּאָה יַתִּיר מִכֹּלָּא, דְּלָא חָיִישׁ כְּדֵין לְכָל עָלְמָא, וְלָא אַשְׁגַּח בְּהוּ, מֵחֶדְוָה דְּשַׁלִּיט עָלֵיהּ. וְהַהוּא זַכָּאָה זָכֵי לְשׁוּלְטָנָא עִלָּאָה, בְּהַאי עָלְמָא, וּבְעָלְמָא דְּאָתֵי. צַדִּיק <Nonei></i>וְטוֹב לוֹ, דְּלָא חָיִישׁ קוּדְשָׁא בְּרִיךְ הוּא לְכַפְּרָא עַל עָלְמָא.</p>\n<p>אֲמֵינָא לֵיהּ, אִלּוּ לָא הֲווֹ בְּחַד זִמְנָא, יָאוּת. אֲבָל אִית צַדִּיק הָכָא, וְאִית צַדִּיק הָכָא, לְדָא אִית מַרְעִין וּמַכְתְּשִׁין, וּלְדָא אִית כָּל טִיבוּ דְּעָלְמָא. אָמַר לִי, בְּחַד מִנַּיְיהוּ אוֹ תְּרֵין סַגֵּי, דְּלָא בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְאַלְקָאָה כֹּלָּא, (ס\"א כל דמה) כְּמָה דְּלָא אִצְטְרִיךְ אֶלָּא דְּרוֹעָא חֲדָא, לְאַלְקָאָה וּלְאָקָזָאָה לְמֵיהַב אַסְוָותָא לְכָל שַׁיְיפִין. אוּף הָכָא, בְּחַד צַדִּיקָא סַגֵּי.</p>\n<p>וְאִי אִתְּקַף (ס\"א אתייקר) בֵּיהּ מְרָע, עַל כָּל שַׁיְיפִין, כְּדֵין אִצְטְרִיךְ תְּרֵין דְּרוֹעִין לְאָקָזָאָה. אוּף הָכִי, אִי אַסְגִּיאוּ חוֹבִין יַקִּירִין עַל עָלְמָא, כְּדֵין כָּל זַכָּאִין אַלְקוּן, לְמֵיהַב אַסְוָותָא עַל כָּל דָּרָא. אֲבָל בִּזְמַן דְּלָא אַסְגִּיאוּ כָּל כַּךְ, כְּדֵין חַד זַכָּאָה אַלְקֵי, וּשְׁאַר צַדִּיקַיָּא בִּשְׁלָם, דְּהָא לָא אִצְטְרִיךְ עָלְמָא דְּיִלְקוּן כֻּלְּהוּ. אִתְסִיאוּ עַמָּא. אִתְסִיאוּ צַדִּיקַיָּיא. וּלְזִמְנִין דְּכָל יוֹמֵיהוֹן קַיְימִין בְּמַרְעִין, לְאַגָּנָא עַל דָּרָא. מִיתוּ, הָא אַתְּסֵי כֹּלָּא, וְאִתְכְּפַּר. לְזִמְנִין דְּחוֹבִין אִינּוּן יַקִּירִין יַתִּיר.</p>"],[9520012524,"<p>קַמְנָא וְאָזַלְנָא. וְתּוּקְפָּא דְּשִׁמְשָׁא הֲוָה יַתִּיר, וְדָחִיק לָן בְּאוֹרְחָא. חֲמֵינָן אִילָנִין בְּמַדְבְּרָא, וּמַיִין תְּחוֹתַיְיהוּ. יָתִיבְנָא תְּחוֹת חַד טוּלָא דְּאִילָנָא דְּמַדְבְּרָא. שָׁאִילְנָא לֵיהּ, מַאי הַאי דְּכָל עַמִּין דְּעָלְמָא לָא עַבְדִּין נִעְנוּעָא, אֶלָּא יִשְׂרָאֵל בִּלְחוֹדַיְיהוּ, דְּכַד לָעָאן בְּאוֹרַיְיתָא, מִתְנַעְנְעָן הָכָא וְהָכָא, בְּלָא לִמּוּדָא דְּבַר נָשׁ בְּעָלְמָא, וְלָא יַכְלִין לְמֵיקָם בְּקִיּוּמַיְיהוּ.</p>\n<p>אָמַר לִי, אַדְכַּרְתָּן מִלְּתָא עִלָּאָה, וּבְנֵי עָלְמָא לָא יַדְעִין, וְלָא מַשְׁגִּיחִין. יָתִיב שַׁעֲתָא וּבָכָה, אָמַר, וַוי לִבְנֵי נָשָׁא דְּאַזְלִין כִּבְעִירֵי חַקְלָא, בְּלָא סוּכְלְתָנוּ. בְּמִלָּה דָּא בִּלְחוֹדוֹי אִשְׁתְּמוֹדְעָן נִשְּׁמָתְהוֹן קַדִּישִׁין דְּיִשְׂרָאֵל, בֵּין נִשְׁמָתְהוֹן דְּעַמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת. נִשְׁמָתְהוֹן דְּיִשְׂרָאֵל אִתְגְּזָרוּ, מִגּוֹ בּוּצִינָא קַדִּישָׁא דְּדָלִיק, דִּכְתִּיב, (משלי כ׳:כ״ז) נֵר יְיָ נִשְׁמַת אָדָם. וְהַאי נֵר בְּשַׁעֲתָא דְּאִתְאַחֲד (נ\"א דאתדליק) <Nonei></i>מִגּוֹ אוֹרַיְיתָא דִּלְעֵילָּא, לָא שָׁכִיךְ נְהוֹרָא עָלֵיהּ אֲפִילּוּ רִגְעָא. וְרָזָא דָּא, (תהילים פ״ג:ב׳) אֱלֹהִים אַל דֳּמִי לָךְ. כְּגַוְונָא דָּא כְּתִיב, (ישעיהו ס״ב:ו׳) הַמַּזְכִּירִים אֶת יְיָ אַל דֳּמִי לָכֶם, לָא שְׁכִיכוּ לְכוֹן. נְהוֹרָא דְּשַׁרְגָּא כֵּיוָן דְּאִתְאַחֲדָא גּוֹ פְּתִילָה, הַהוּא נְהוֹרָא לָא שָׁכִיךְ לְעָלְמִין, אֶלָּא מִתְנַעְנְעָא נְהוֹרָא לְכָאן וּלְכָּאן, וְלָא מִשְׁתְּכִיךְ לְעָלְמִין.</p>\n<p>כְּגַוְונָא דָּא, יִשְׂרָאֵל, דְּנִשְׁמָתַיְיהוּ מִגּוֹ הַהוּא נְהוֹרָא דְּשַׁרְגָּא, כֵּיוָן דְּאָמַר מִלָּה חֲדָא דְּאוֹרַיְיתָא, הָא נְהוֹרָא דָּלִיק, וְלָא יֵכְלוּן אִינּוּן לְאִשְׁתַּכְּכָא, וּמִתְנַעְנֵעָן לְכָאן וּלְכָּאן, וּלְכָל סִטְרִין. כִּנְהוֹרָא דְּשַׁרְגָּא, דְּהָא (משלי כ׳:כ״ז) נֵר יְיָ נִשְׁמַת אָדָם כְּתִיב.</p>\n<p>וּכְתִיב, (יחזקאל לד) אָדָם אַתֶּם, אַתֶּם קְרוּיִין אָדָם, וְלָא אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת. נִשְׁמָתִין דְּעַמִּין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת, מִדְעִיכוּ דְּקָשׁ, בְּלָא נְהוֹרָא דְּשָׁרֵי עָלַיְיהוּ. וְעַל דָּא מִשְׁתַּכְכִין, וְלָא מִתְנַעְנְעָן, דְּהָא לֵית לוֹן אוֹרַיְיתָא, וְלָא דַּלְקִין בָּהּ, וְלָאו נְהוֹרָא שַׁרְיָיא בְּהוֹן, אִינּוּן קַיְימִין כְּעֵצִים בְּגוֹ נוּרָא דְּדָלִיק, בְּלָא נְהוֹרָא דְּשַׁרְיָא עָלַיְיהוּ, וְעַל דָּא מִשְׁתַּכְכִין בְּלָא נְהוֹרָא כְּלָל. אָמַר רִבִּי יוֹסֵי, דָּא אִיהוּ בְּרִירוּ דְּמִלָּה, זַכָּאָה חוּלָקִי דְּזָכֵינָא לְהַאי, לְמִשְׁמַע דָּא.</p>"],[9520012525,"<p><Nonei></i>קוּם רִבִּי אַבָּא, לְחַדְּשָׁא מִילִין דְּאוֹרַיְיתָא, דְּאַמָרְת בְּחִבּוּרָא קַדְמָאָה. פָּתַח רִבִּי אַבָּא וְאָמַר, (ישעיהו מ״ב:י׳) שִׁירוּ לַיְיָ שִׁיר חָדָשׁ תְּהִלָּתוֹ מִקְצֵה הָאָרֶץ וְגוֹ'. כַּמָּה חֲבִיבִין יִשְׂרָאֵל קַמֵּי קוּדְשָׁא בְּרִיךְ הוּא, דְּחֶדְוָה דִּלְהוֹן וְתוּשְׁבַּחְתָּא דִּלְהוֹן, לָאו אִיהוּ אֶלָּא (ס\"א לשתפא לקודשא בריך הוא ושכינתיה בההוא דהכי וכו') בֵּיהּ. דְּהָכִי תָּנֵינָן, כָּל חֶדְוָה דְּיִשְׂרָאֵל דְּלָא מִשְׁתַּתְּפֵי בָּהּ לְּקוּדְשָׁא בְּרִיךְ הוּא (ושכינתיה), לָאו אִיהוּ חֶדְוָה. וְזַמִּין אִיהוּ סָמָאֵל וְכָל סִיַּיעְתָּא דִּילֵיהּ לְקַטְרְגָא לְהַהוּא חֶדְוָה, (ס\"א ואתחזר) וְאִשְׁתְּאָר בְּצַעֲרָא וּבִכְיָה, וְקוּדְשָׁא בְּרִיךְ הוּא לָא אִשְׁתְּתַּף בְּהַהוּא צַעֲרָא.</p>\n<p>אֲבָל מַאן דְּשָׁתִּיף קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּחֶדְוָה דִּילֵיהּ, אִם יֵיתֵי מְקַטְרְגָא לְקַטְרְגָא בְּהַהִיא חֶדְוָה. קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ מִשְׁתַּתֵּף בְּהַהוּא צַעֲרָא. מַה כְּתִיב בֵּיהּ (ישעיה סג) בְּכָל צָרָתָם לוֹ צָר. וּבְמָאי. בְּגִין (תהילים צ״א:ט״ו) דְּעִמּוֹ אָנֹכִי בְצָרָה.</p>\n<p>וּמְנָלָן, דְּאִית לוֹן לְיִשְׂרָאֵל לְשַׁתְּפָא לְּקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּחֶדְוָה דִּלְהוֹן. (בגין דלאו איהו חדוה, אלא בשותפות דיליה מאלין) דִּכְתִּיב, (שם קמט) יִשְׂמַח יִשְׂרָאֵל בְּעוֹשָׂיו. הַהוּא חֶדְוָה דְּיִשְׂרָאֵל לָאו אִיהוּ, אֶלָּא בְּעוֹשָׂיו. בְּעוֹשָׂיו, בְּעוֹשׂוֹ מִבָּעֵי לֵיהּ. אֶלָּא אִלֵּין קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ, וְאָבִיו וְאִמּוֹ, דְּאַף עַל גַּב דְּמִיתוּ, קוּדְשָׁא בְּרִיךְ הוּא אַעְקַר לוֹן מִגַּן עֵדֶן, וְאַיְיתֵי לוֹן עִמֵּיהּ לְהַהוּא חֶדְוָה, לְנַטְלָא חוּלָקָא דְּחֶדְוָה עִם קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ. כְּמָה דְאַתְּ אָמֵר (איוב מ׳:י״ט) הָעוֹשׂוֹ יַגֵּשׁ חַרְבּוֹ.</p>"],[9520012526,"<p>דָּבָר אַחֵר בְּעוֹשָׂיו, בְּגִין דְּבַּר נָשׁ אִתְעָבִיד בְּשׁוּתָּפוּת, גַּבְרָא וְאִתְּתָא, וְקוּדְשָׁא בְּרִיךְ הוּא. וְעַל רָזָא דָּא כְּתִיב, (בראשית א) נַעֲשֶׂה אָדָם, בְּשׁוּתָּפוּ. דְּתָנֵינָן, תְּלַת אוּמָנִין עָבֵד קוּדְשָׁא בְּרִיךְ הוּא, לְאַפָּקָא מִנְּהוֹן עָלְמָא, וְאִלֵּין אִינּוּן: שְׁמַיָּא, וְאַרְעָא, וּמַיָּיא. וְכָל חַד שִׁמֵּשׁ חַד יוֹמָא, וְאָהַדְרוּ כְּמִלְּקַדְּמִין.</p>\n<p>יוֹמָא קַדְמָאָה, אַפִּיק שְׁמַיָא אוּמָנוּתָא דִּילֵיהּ, דִּכְתִּיב (בראשית א׳:ג׳) וַיֹּאמֶר אֱלֹהִים יְהִי אוֹר וַיְהִי אוֹר. יוֹמָא תִּנְיָינָא, אַפִּיקוּ מַיָּא אוּמָנוּתָא לַעֲבִידְתָּא, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים יְהִי רָקִיעַ בְּתוֹךְ הַמָּיִם וְגוֹ'. אִסְתְּלָקוּ פַּלְגָּא מַיָּיא לְעֵילָּא, וּפַלְגָּא מַיָּיא לְתַתָּא אִשְׁתְּאָרוּ. וְאִלְמָלֵא כַּךְ דַּמְיָא אִתְפְּרָשׁוּ, עָלְמָא לָא הֲוָה קָאִים. יוֹמָא תְּלִיתָאָה, עֲבִידַת אַרְעָא וְאַפִּיקַת כְּמָה דְּאִתְפַּקְּדַת, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים תַּדְשֵׁא הָאָרֶץ דֶּשֶׁא עֵשֶׂב, וּכְתִיב וַתּוֹצֵא הָאָרֶץ דֶּשֶׁא וְגוֹ'.</p>\n<p>עַד הָכָא כָּל אוּמָנָא מֵאִלֵּין תְּלָתָא, אַפִּיק אוּמָנוּתָא דִּילֵיהּ, וְעַבְדוּ מַה דְּאִתְפְּקָדוּ. אִשְׁתָּאֲרוּ תְּלַת יוֹמִין אַחֲרָנִין. יוֹמָא ד', אִתְפְּקַד אוּמָנָא קַדְמָאָה לְמֶעְבַּד אוּמָנָא דִּילֵיהּ, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים יְהִי מְאֹרֹת וְגוֹ', וְהַיְינוּ שָׁמַיִם. בְּיוֹמָא חֲמִשָּׁאָה, אַפִּיקוּ מַיָּיא דְּאִיהוּ אוּמָנָא אָחֳרָא, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים יִשְׁרְצוּ הַמַּיִם וְגוֹ'. בְּיוֹמָא שְׁתִּיתָאָה, עַבְדַת אַרְעָא אוּמָנוּתָא דִּילָהּ, דִּכְתִּיב וַיֹּאמֶר אֱלֹהִים תּוֹצֵא הָאָרֶץ נֶפֶשׁ חַיָּה וְגוֹ'.</p>\n<p>כֵּיוָן דִּתְלַת אוּמָנִין אִלֵּין אַשְׁלִימוּ עוֹבָדַיְיהוּ. אָמַר לוֹן קוּדְשָׁא בְּרִיךְ הוּא, אוּמָנוּתָא חֲדָא אִית לִי לְמֶעְבַּד, וְאִיהוּ אָדָם. אִתְחַבָּרוּ כַּחֲדָא, וַאֲנָא עִמְּכוֹן, נַעֲשֶׂה אָדָם, גּוּפָא דִּלְכוֹן, וַאֲנָא אֱהֵא שׁוּתָּפוּ עִמְּכוֹן, וְנַעֲשֶׂה אָדָם. כְּמָה דִּבְקַדְמֵיתָא הֲוָה בְּשׁוּתָּפוּ, הָכִי נָמֵי לְבָתַר. אַבָּא, דְּבֵיהּ עָבִיד עֲבִידְתָּא דִּשְׁמַיָּא, וְעֲבִידְתָּא דְּמַיָיא. וְאִתְּתָא, דְּאִיהִי אוּמָנָא תְּלִיתָאָה, כְּגַוְונָא דְּאַרְעָא. וְקוּדְשָׁא בְּרִיךְ הוּא דְּאִשְׁתְּתַף בַּהֲדַיְיהוּ. וְעַל רָזָא דָּא כְּתִיב בְּעוֹשָׂיו.</p>\n<p>וְאַף עַל גַּב דְּאַבָּא וְאִמָּא אִתְפְּרָשׁוּ מֵהַאי עָלְמָא, חֶדְוָה בְּכָל שׁוּתָּפוּתָא הֲוִי. דְּתָנֵינָן, בְּשַׁעֲתָא דְּבַר נָשׁ <Nonei></i>שָׁתִּיף לְּקוּדְשָׁא בְּרִיךְ הוּא לְחֶדְוָוה דִּילֵיהּ, קוּדְשָׁא בְּרִיךְ הוּא אָתֵי לְגִנְתָּא דְּעֵדֶן, וְאַעְקַר מִתַּמָּן (ס\"א דאודע תמן) לַאֲבוּהִי וְאִמֵּיהּ, דְּאִינּוּן שׁוּתָּפִין בַּהֲדֵיהּ, וְאַיְיתֵי לוֹן עִמֵּיהּ לְהַהוּא חֶדְוָוה, וְכֻלְּהוּ זְמִינִין תַּמָּן, וּבְנֵי נָשָׁא לָא יַדְעִין. אֲבָל בְּעָקוּ דְּבַּר נָשׁ, קוּדְשָׁא בְּרִיךְ הוּא זַמִּין לְגַבֵּיהּ בִּלְחוֹדוֹי, וְלָא אוֹדַע לַאֲבוּהִי וּלְאִמֵּיהּ, הֲדָא הוּא דִכְתִיב, (תהילים י״ח:ז׳) בַּצַּר לִי אֶקְרָא יְיָ וְאֶל אֱלֹהַי אֲשַׁוִּעַ וְגוֹ'.</p>"],[9520012527,"<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר קוּדְשָׁא בְּרִיךְ הוּא, וּשְׁכִינְתִּי אֲנָא שׁוּתָּפוּתָא דְּנִשְׁמְתָא, וַאֲבוֹי וְאִמֵּיהּ שׁוּתָּפוּתָא דְּגוּפָא, דַּאֲבוֹי מַזְרִיעַ לוֹבֶן, דְּעַיְינִין, וּדְגַרְמִין, וְגִידִין, וּמוֹחָא. וְאִתְּתָא שְׁחוֹר דְּעַיְינִין, וְשַׂעֲרָא, וּבִשְׂרָא, וּמִשְׁכָא. וְאוֹף הָכִי שְׁמַיָיא וְאַרְעָא. וְכָל חַיָּילִין דִּלְהוֹן, אִשְׁתְּתָּפוּ בִּיצִּירָתֵיהּ. מַלְאָכִין, מִנְּהוֹן יֵצֶּר הַטוֹב וְיִצֶּר הָרָע לְמֶהֱוִי מְצּוּיָיר מִתַּרְוַויְיהוּ. שִׁמְשָׁא וְסִיהֲרָא, לְאַנְהָרָא לֵיהּ בִּימָמָא וְלֵילְיָא. חֵיוָן וּבְעִירָן וְעוֹפִין וְנוּנִין, לְאִתְפַּרְנְסָא מִנְּהוֹן. כָּל אִילָנִין וְזַרְעִין דְּאַרְעָא, לְאִתְפַּרְנְסָא מִנְּהוֹן.</p>\n<p>מַה עָבַד קוּדְשָׁא בְּרִיךְ הוּא, אַעְקַר לַאֲבוּי וּלְאִמֵּיהּ מִגִּנְתָּא דְּעֵדֶן, וְאַיְיתֵי לְהוּ עִמֵּיהּ, לְמֶהֱוִי <Nonei></i>עִמֵּיהּ בְּחֶדְוָה דִּבְנוֹי, וְלֵית חֶדְוָה כְּחֶדְוָה דְּפוּרְקָנָא, דִּכְתִּיב בָּהּ, (דברי הימים א ט״ז:ל״א) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ וַיּאמְרוּ בַגּוֹיִם יְיָ מָלָךְ. (דברי הימים א ט״ז:ל״ג) אָז יְרַנְּנוּ עֲצֵּי הַיָּעַר מִלִפְנֵי יְיָ כִּי בָא לִשְׁפּוֹט אֶת הָאָרֶץ. (ע\"כ רעיא מהימנא)</p>"],[9520012528,"<p>אַהְדָּר הַהוּא טוּלָא דְּמִלְקַדְּמִין, וְאַזְלָא גּוֹ בֵּיתָא, כְּמוֹ דִּיּוּקְנָא דְּבַּר נָשׁ. נָפַל עַל אַנְפּוֹי רִבִּי אַבָּא. אָמַר רִבִּי יוֹסֵי, אַדְכַּרְנָא דִּבְהַאי אַתְרָא חֲמֵינָא לֵיהּ לְרִבִּי פִּנְחָס בֶּן יָאִיר, יוֹמָא חַד הֲוָה קָאִים בְּהַאי דּוּכְתָּא, וַהֲוָה אָמַר הָכִי, (במדבר כ\"ב) פִּינְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן, בְּאָת י' זְעֵירָא.</p>\n<p>בְּגִין דִּתְרֵין אַלְפִין בֵּיתִין רְשִׁימִין, אַלְפָא בֵּיתָא דְּאַתְוָון רַבְרְבָן, וְאַלְפָא בֵּיתָא דְּאַתְוָון זְעִירָן. אַתְוָון רַבְרְבָן, אִינּוּן בְּעָלְמָא דְּאָתֵי. וְאַתְוָון זְעִירָן, אִינּוּן בְּעָלְמָא תַּתָּאָה. י' זְעֵירָא, בְּרִית קַיָּימָא קַדִּישָׁא. כֵּיוָן דְּקַנֵּי פִּנְחָס עַל בְּרִית דָּא, אִתּוֹסַף בֵּיהּ י' זְעֵירָא, רָזָא דִּבְרִית דָּא.</p>\n<p>בְּהַהוּא שַׁעֲתָא, אָמַר קוּדְשָׁא בְּרִיךְ הוּא, מָה אַעְבִּיד עִם מֹשֶׁה, בְּרִית דָּא מִמֹּשֶׁה הֲוִי, וְכַלָּה דִּילֵיהּ הֲוִי. גְּנַאי הוּא לְמֵיהַב לֵיהּ לְאַחֲרָא, בְּלָא דַּעְתָּא וּרְעוּתָא דְּמֹשֶׁה, לָאו יָאוּת הוּא. שָׁארֵי קוּדְשָׁא בְּרִיךְ הוּא וְאָמַר לְמֹשֶׁה, מֹשֶׁה, פִּנְחָס בֶּן אֶלְעָזָר בֶּן אַהֲרֹן הַכֹּהֵן. אָמַר לֵיהּ מֹשֶׁה, רִבּוֹנוֹ שֶׁל עוֹלָם מַהוּ. אָמַר לֵיהּ, אַנְתְּ הוּא דְּמַסְרַת נַפְשָׁךְ עַל יִשְׂרָאֵל דְּלָא יִשְׁתֵּצוּן מִן עָלְמָא בְּכַמָּה זִמְנִין, וְאִיהוּ הֵשִׁיב אֶת חֲמָתִי מֵעַל בְּנֵי יִשְׂרָאֵל וְגוֹ'. אָמַר מֹשֶׁה מַה אַתְּ בָּעֵי מִנִּי, הָא כֹּלָּא דִּידָךְ.</p>\n<p>אָמַר לֵיהּ, הָא כֹּלָּא דִּידָךְ הִיא, אֵימָא לֵיהּ דְּתִשְׁרֵי בְּגַוִיהּ. אָמַר מֹשֶׁה, הָא בְּלִבָּא שְׁלִים תְּהֵא לְגַבֵּיהּ. אָמַר לֵיהּ אֵימָא אַנְתְּ בְּפוּמָךְ, וְאָרִים קַלָךְ, דְּאַנְתְּ מָסַר לֵיהּ בִּרְעוּתָא, בְּלִבָּא שְׁלִים. הֲדָא הוּא דִכְתִיב, לָכֵן אֱמוֹר, אַתְּ אֵימָא בִּרְעוּתָא, הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם. מֹשֶׁה הֲוָה אָמַר הִנְנִי נוֹתֵן לוֹ וְגוֹ', דְּאִילּוּ קוּדְשָׁא בְּרִיךְ הוּא, הֲוָה לֵיהּ לְמֵימַר לָכֵן אֱמוֹר לוֹ הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, אֲבָל לָא כְּתִיב אֶלָּא לָכֵן אֱמוֹר. וְאִי תֵּימָא, דְּאִתְעַבְּרַת מִן מֹשֶׁה. לָא. אֶלָּא כְּבוּצִינָא דָּא דְּאַדְלִיקוּ מִינָהּ, דָּא יָהִיב וְאַהֲנֵי, וְדָא לָא אִתְגָּרַע מִנָּהּ.</p>\n<p>אָתָא הַהוּא טוּלָא, וְיָתִיב, וְנָשִׁיק לֵיהּ. שָׁמְעוּ חַד קָלָא דְּהֲוָה אָמַר, פְּנוּן אֲתָר, פְּנוּן אֲתָר לְרִבִּי פִּנְחָס בֶּן יָאִיר, דְּאִיהוּ גַּבַּיְיכוּ. דְּתָנֵינָן, דְּכָל אֲתָר דְּצַדִּיקָא אִתְחַדָּשׁ בֵּיהּ מִלֵּי דְּאוֹרַיְיתָא, כַּד אִיהוּ בְּהַהוּא עָלְמָא, פָּקִיד לְהַהוּא אֲתָר, וְאָתֵי לֵיהּ לְגַבֵּיהּ. וְכָּל שֶׁכֵּן כַּד שָׁרָאן בְּגַוִּויהּ צַדִּיקַיָּיא אָחֲרָנִין. לְחָדְתָּא בְּהַהוּא אֲתָר, דְּאַמְרִין מִלֵּי דְּאוֹרַיְיתָא. כְּגַוְונָא דָּא דְּהֲוָה אָתֵי רִבִּי פִּנְחָס בֶּן יָאִיר לְמִפְקַּד לְאַתְרֵיהּ, וְאַשְׁכַּח אִלֵּין צַדִּיקַיָּיא מְחַדְתִּין מִלִּין דְּאוֹרַיְיתָא, וְאִתְחַדָּשׁ כְּמִלְּקַדְּמִין, הַהוּא מִלָּה דְרִבִּי פִּנְחָס בֵּן יָאִיר קַמֵּיהּ.</p>\n<p>אָמַר רִבִּי אַבָּא, יָאוּת מִלָּה דְּרִבִּי פִּנְחָס בֶּן יָאִיר, דְּהָא לָא כְּתִיב לָכֵן הִנְנִי נוֹתֵן, אֶלָּא לָכֵן אֱמוֹר הִנְנִי נוֹתֵן לוֹ. וְכִי מִלָּה דָּא הֲוָה גְּנִיזָא מֵחַסִידָא דָּא תְּחוֹת יְדָךְ, וְלָא הֲוִית אָמַר. זַכָּאָה חוּלָקָנָא, דְּזָכֵינָא לְמֶהֱוִי בְּסִיַּעְתָּא דְּטוּלָא קַדִּישָׁא הָכָא.</p>"],[9520012529,"<p>אוּף הוּא פָּתַח וְאָמַר, מִשְּׁמֵיהּ דרִבִּי פִּנְחָס (קהלת ט׳:י׳) כֹּל אֲשֶׁר תִּמְצָא יָדְךָ לַעֲשׂוֹת בְּכֹחֲךָ עֲשֵׂה וְגוֹ', כַּמָה יָאוּת לֵיהּ לְבַּר נָשׁ בְּעוֹד דְּבוּצִינָא דָּלִיק וְשַׁרְיָא עַל רֵישֵׁיהּ, לְאִשְׁתַּדְּלָא וּלְמֶעְבַּד רְעוּתָא דְּמָארֵיהּ. בְּגִין דְּהַהוּא נְהוֹרָא דְּבוּצִינָא, אִיהִי כֹּ\"חַ דְּשַׁרְיָא עָלֵיהּ. וְעַל דָּא כְּתִיב, (במדבר י״ד:י״ז) יִגְדַּל נָא כֹּחַ יְיָ. כֹּחַ יְיָ, דָּא הוּא כֹּחַ, דְּשַׁרְיָא עַל רֵישֵׁיהוֹן דְּצַדִּיקַיָּיא, וְכֹל אִינּוּן דְּמִשְׁתַּדְּלִין בִּרְעוּתָא דְּמָארֵיהוֹן. וְעַל דָּא תָּנֵינָן, כָּל הָעוֹנֶה אָמֵן יְהֵא שְׁמֵיהּ רַבָּא מְבָרַךְ בְּכָל כֹּחוֹ. (דא איהו כחו)</p>\n<p>ודַּאי אִצְטְרִיךְ לְאִתְּעָרָא כָּל שַׁיְיפוֹי בְּחֵילָא תַּקִּיף בְּגִין דִּבְאִתְּעָרוּתָא תַּקִּיף דְּאִתָּקַף, אִתְּעַר הַהוּא כֹּחַ קַדִּישָׁא עִלָּאָה, וְאִסְתַּלָּק גּוֹ קוּדְשָׁא וְאִתְּבַּר חֵילָא וְתּוּקְפָּא דְּסִטְרָא אַחֲרָא. וְעַל דָּא <Nonei></i>בְּכֹחֲךָ, אִצְטְרִיךְ לְמֶעְבַּד רְעוּתָא דְּמָארָךְ.</p>\n<p>כִּי אֵין מַעֲשֵׂה וְחֶשְׁבּוֹן וְגוֹ', בְּגִין דִּבְהַהוּא כֹּחַ אִית מַעֲשֶׂה, אִשְׁתַּדְּלוּתָא לְאִשְׁתַּדְּלָא בְּהַאי עָלְמָא דְּאִקְרֵי מַעֲשֵׂה, עָלְמָא דְּעוֹבָדָא, לְמִשְׁלָם סוֹפָא דְּמַחֲשָׁבָה. וְחֶשְׁבּוֹן, דָּא הוּא עָלְמָא, דְּתַלְיָא בְּדִבּוּרָא, דְּהָא חֶשְׁבּוֹן בְּדִבּוּרָא תַּלְיָיא. וְעַל דָּא, כָּל גִּימַטְרִיּאוֹת, וּתְקוּפִין, וְעִבּוּרִין דְּעָלְמָא, בְּסִיהֲרָא הֲווֹ. וְדַעַת, דָּא אִיהוּ רָזָא דְּשִׁית סִטְרִין, דְּתַּלְיָין בְּמַחֲשָׁבָה, וְאִקְרוּן עָלְמָא דְּהַהוּא מַחֲשָׁבָה. וְחָכְמָה, דְּכֹלָּא תַּלְיָיא מִנֵּיהּ.</p>\n<p>וְכָל אִלֵּין כְּלִילָן בְּהַהוּא כֹּחַ, מַה דְּלָאו הָכִי בְּסִטְרָא דִּשְׁאוֹל, דַּרְגָּא דְּגֵיהִנָּם. דְּהָא כָּל בַּר נָשׁ דְּלָא אִשְׁתָּדַּל בְּהַאי כֹּ\"חַ, בְּהַאי עָלְמָא, לְאַעְלָאָה בֵּיהּ, בְּמַעֲשֶׂה וְחֶשְׁבּוֹן וָדַעַת וְחָכְמָה, סוֹפֵיהּ לְאַעְלָאָה בַּשְּׁאוֹל, דְּלֵית בֵּיהּ מַעֲשֵׂה וְחֶשְׁבּוֹן וְדַעַת וְחָכְמָה. דְּהָא סִטְרָא אָחֳרָא, אֹרַח שְׁאוֹל אִיהִי, דִּכְתִּיב, (משלי ז׳:כ״ז) דַּרְכֵי שְׁאוֹל בֵּיתָהּ. מַאן דְּאִתְרַפֵּי מֵהַאי כֹּ\"חַ קַדִּישָׁא, אַתְּקַף בֵּיהּ סִטְרָא אַחֲרָא, דִּשְׁאוֹל בֵּיתָהּ.</p>\n<p>אֲשֶׁר אַתָּה הוֹלֵךְ שָׁמָּה, וְכִי כָּל בְּנֵי עָלְמָא אָזְלֵי לִשְׁאוֹל. אִין. אֲבָל סַלְּקִין מִיַּד, דִּכְתִּיב, (שמואל א ב׳:ו׳) מוֹרִיד שְׁאוֹל וַיָּעַל. בַּר אִינּוּן חַיָּיבִין, דְּלָא הִרְהֵרוּ תְּשׁוּבָה לְעָלְמִין, דְּנַחְתִּין וְלָא סַלְּקִין. וַאֲפִילּוּ צַדִּיקִים גְּמוּרִים נַחְתִּין תַּמָּן. אֲמַאי נַחְתִּין. בְּגִין דְּנַטְלִין כַּמָה חַיָּיבִין מִתַּמָּן, וְסַלְּקִין לוֹן לְעֵילָּא. (ותמן עבדין לון להרהר בתשובה) וּמַאן אִינּוּן. אִינּוּן דְּהִרְהֵרוּ בִּתְשׁוּבָה בְּהַאי עָלְמָא, וְלָא יָכִילוּ, וְאִסְתְּלָּקוּ מִן עָלְמָא. וְצַדִּיקַיָּיא נַחְתִּין בְּגִינֵיהוֹן דְּחַיָּיבִין גּוֹ שְׁאוֹל, וְנַטְלִין לוֹן, וְסַלְּקִין לוֹן מִן תַּמָּן.</p>"],[9520012530,"<p>אָמַר רִבִּי יוֹסֵי, כְּתִיב (קהלת ז׳:כ״ז) אַחַת לְאַחַת לִמְצֹא חֶשְׁבּוֹן. חֶשְׁבּוֹן דְּגִימַטְרִייאוֹת דְּקַיְימָן בְּסִיהֲרָא, בְּאָן דַּרְגָּא דִּילָהּ אִינּוּן. לָא אָתִיב לֵיהּ. אָמַר, שְׁמַעְנָא, וְלָא אִדְכַּרְנָא מִלָּה. קָם הַהוּא טוּלָא, וּבָטַשׁ בְּעֵינוֹי דרִבִּי אַבָּא, נָפַל עַל אַנְפּוֹי מִגּוֹ דְּחִילוּ. עַד דְּהֲוָה נָפַל עַל אַנְפּוֹי, נָפַל קְרָא בְּפוּמֵיהּ, דִּכְתִּיב, (שיר השירים ז׳:ה׳) עֵינַיִךְ בְּרֵכוֹת בְּחֶשְׁבּוֹן עַל שַׁעַר בַּת רַבִּים. וְאִלֵּין עַיְינִין דִּילָהּ, פַּרְפְּרָאוֹת לְגוֹ חָכְמָה עִלָּאָה, דְּאִתְמַשְּׁכָא מִלְּעֵילָּא, וּמִגּוֹ חֶשְׁבּוֹן וּתְקוּפִין וְעִבּוּרִין אִתְמַלְּיָין, וְאִתְעָבִידוּ בְּרֵיכוֹת, דְּנַפְקוּ מִיָּמִין, לְכָל סִטְרִין, (נ\"א אינון עיינין) עַד דְּאִתְפָּקְדָן לְכָל חוּשְׁבָּן וְעִבּוּרִין דְּסִיהֲרָא בִּלְבַד (ס\"א דלבר), וְכֹכָבִין וּמַזָּלֵי לְמֶעְבַּד חֶשְׁבּוֹן, וְדָא אִיהוּ עַל שַׁעַר בַּת רַבִּים, דָּא אִיהִי סִיהֲרָא דִּלְבַר.</p>"],[9520012531,"<p>אָמַר רִבִּי אַבָּא לְרִבִּי יוֹסֵי, הַהוּא מַרְגְּלָא קַדִּישָׁא דְּהֲוָה תְּחוֹת יְדָךְ, מִגּוֹ סִיַּעְתָּא דַּחֲסִידָא קַדִּישָׁא דְּאִיהוּ גַּבָּן, כַּמָּה שַׁפִּיר אִיהוּ, וְאָהֲדַרְנָא בֵּיהּ. דְּהָא וַדַּאי לָא אִצְטְרִיךְ לְאַפָּקָא אִתְּתָא, לְמִשְׁרֵי בַּאֲתָר אַחֲרָא, עַד דְּבַעְלָהּ יַפְקֵד לָהּ וְיָהִיב לָהּ רְשׁוּ לְמֵהַךְ. וְאוֹדְעִין לְבַעְלָהּ בְּקַדְמִיתָא, וּמְפַיְיסִין לֵיהּ, דְּהוּא יַפְקֵד לָהּ, וְיָהִיב לָהּ רְשׁוּ לְמֵיהַךְ לְהַהוּא אֲתָר. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא פָּיִיס לְמֹשֶׁה, וְעַד דְּיָהַב לֵיהּ רְשׁוּ, וְאָמַר לֵיהּ אֵימָא אַנְתְּ, הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי שָׁלוֹם, לְמִשְׁרֵי בְּגַוִּויהּ, וְעַד דְּיָהַב לָהּ רְשׁוּ לְמֵהַךְ תַּמָּן, לָא אַזְלַת.</p>\n<p>מְנָלָן. מִצַּדִּיקוֹ שֶׁל עוֹלָם, דְּיָהִיב לָהּ רְשׁוּ, לְמִשְׁרֵי גּוֹ צַדִּיקֵי בְּהַאי עָלְמָא. וְיָתְבָא עִמְּהוֹן, כְּכַלָּה גּוֹ קִשּׁוּטָהָא. וְצַדִּיקָא דְּעָלְמָא חָמֵי, וְחַדֵּי בְּהַאי. אֲבָל בֵּין דְּרוֹעֵי דְּבַעְלָהּ שְׁכִיבַת, וְאִתְהַדְּרַת לְמֶהֱוִי בַּהֲדַיְיהוּ, וְתָבַת לְבַעְלָהּ. כְּמָה דְאַתְּ אָמֵר, (אסתר ב׳:י״ד) בָּעֶרֶב הִיא בָאָה וּבַבֹּקֶר הִיא שָׁבָה. בָּעֶרֶב הִיא בָאָה, לְגַבֵּי בַּעְלָהּ. וּבַבֹּקֶר הִיא שָׁבָה, לְגַבֵּי צַדִּיקַיָּיא דְּעָלְמָא. וְכֹלָּא בִּרְשׁוּתָא דְּבַעְלָהּ. (הדא הוא דכתיב, (תהילים ל״ז:כ״א) וצדיק חונן ונותן).</p>\n<p>וּמֹשֶׁה כַּךְ אָמַר, הִנְנִי נוֹתֵן לוֹ אֶת בְּרִיתִי, כְּמָה דְּצַדִּיק דִּלְעֵילָּא נוֹתֵן, אוּף אֲנָא הִנְנִי נוֹתֵן, מַתָּנָה לְמֶהֲדָר מַתָּנָה אִיהִי. וּבְגִין בְּרִית דָּא, רָוַוח כְּהוּנָה עִלָּאָה. וְאִי לָא תְּהֵא בַּהֲדֵיהּ, לָא אִתְקְשַׁר פִּנְחָס בְּדַרְגָּא דִּכְהוּנָה עִלָּאָה, דְּהָא בְּרִית דַּבְקָא אִיהוּ תָּדִיר בִּימִינָא עִלָּאָה. וִימִינָא עִלָּאָה דָּא, זַמִּין לְמִבְנֵי בֵּי מַקְדְּשָׁא, דְּאִיהוּ בְּרִית.</p>"],[9520012532,"<p>אָמַר רִבִּי אַבָּא, אִדְכַּרְנָא מִלָּה חֲדָא, דְּשָׁמַעְנָא מִבּוּצִינָא קַדִּישָׁא, דְּשָׁמַע מִשְּׁמֵיהּ דְּרִבִּי אֱלִיעֶזֶר. יוֹמָא חַד, אָתָא לְקַמֵּיהּ חַד חַכִּים גּוֹי, אָמַר לֵיהּ סָבָא סָבָא, תְּלַת בַּעְיָין <Nonei></i>בָּעֵינָא לְמִתְבַּע מִנָךְ. חַד, דְּאַתּוּן אַמְרִין דְּיִתְבְּנֵי לְכוּ בֵּי מַקְדְּשָׁא אָחֳרָא, וְהָא לָא הֲווֹ לְמִבְנֵי אֶלָּא תְּרֵי זִמְנִין, בַּיִת רִאשׁוֹן וּבַיִת שֵׁנִי, בַּיִת שְׁלִישִׁי (ובית רביעי) לָא תִּשְׁכַּח בְּאוֹרַיְיתָא, וְהָא מַה דְּהֲוָה לֵיהּ לְמִבְנֵי, כְּבַר אִתְבָּנוּן, וּלְעוֹלָם לֵית בֵּיהּ יַתִּיר, דְּהָא תְּרֵי בָּתֵּי יִשְׂרָאֵל קָרָא לוֹן קְרָא. וּכְתִיב, (חגי ב׳:ט׳) גָּדוֹל יִהְיֶה כְּבוֹד הַבַּיִת הַזֶּה הָאַחֲרוֹן מִן הָרִאשׁוֹן.</p>\n<p>וְתוּ, דְּאַתּוּן אַמְרִין, דְּאַתּוּן קְרֵבִין לְמַלְכָּא עִלָּאָה, יַתִּיר מִכָּל שְׁאַר עַמִּין, מַאן דְּמִתְקְרִיב לְמַלְכָּא, אִיהוּ חַדֵּי (יתיר) תָּדִיר, בְּלָא צַעֲרָא, בְּלָא דְּחִילוּ, וּבְלָא דְּחִיקוּ. וְהָא אַתּוּן בְּצַעֲרָא וּבְדֹחֲקָא וּבִיגוֹנָא תָּדִיר, יַתִּיר מִכָּל בְּנֵי עָלְמָא. וַאֲנָן לָא אִתְקְרִיב לָן צַעֲרָא וְדֹחֲקָא וִיגוֹנָא כְּלָל. אֲנָן קְרִיבִין לְמַלְכָּא עִלָּאָה, וְאַתּוּן רְחִיקִין מִנֵּיהּ, וְעַל דָּא אִית לְכוּ צַעֲרָא וְדֹחֲקָא אֶבְלָא וִיגוֹנָא, מַה דְּלָא אִית לָן.</p>\n<p>וְתוּ, דְּאַתּוּן לָא אָכְלֵי נְבֵלָה וּטְרֵפָה, בְּגִין דִּתְּהֱווֹן בְּרִיאִין, וְגוּפָא דִּלְכוֹן לִהֱוִי בִּבְרִיאוּתָא. אֲנָן אָכְלֵינָן כָּל מַה דְּבָעֵינָן, וַאֲנָן תַּקִּיפִין בְּחֵילָא בִּבְרִיאוּתָא, וְכָל שַׁיְיפוֹן דִּילָן בְּקִיּוּמַיְיהוּ. וְאַתּוּן דְּלָא אַכְלִין, חַלָּשִׁין כֻּלְכוּ בְּמַרְעִין בִּישִׁין, וּבִתְבִירוּ יַתִּיר מִכָּל שְׁאַר עַמִּין. עַמָּא דְּסָנֵי לְכוֹן אֱלָהֲכוֹן בְּכֹלָּא. סָבָא סָבָא, לָא תֵּימָא לִי מִדִּי, דְּלָא אַשְׁמְעִינָךְ, וְלָא אֲקַבֵּל מִנָךְ. זָקִיף עֵינוֹי רִבִּי אֱלִיעֶזֶר, וְאַשְׁגַּח בֵּיהּ, וְאִתְעָבִיד תִּלָּא דְּגַרְמֵי.</p>\n<p>כֵּיוָן דְּנָח רוּגְזֵיהּ, אַהְדָּר רֵישֵׁיהּ וּבָכָה, וְאָמַר, (תהילים ח׳:ב׳) יְיָ אֲדוֹנֵנוּ מָה אַדִּיר שִׁמְךָ בְּכָל הָאָרֶץ. כַּמָה תַּקִּיף חֵילָא דִּשְׁמָא קַדִּישָׁא, תַּקִּיפָא בְּכָל אַרְעָא, וְכַמָּה חֲבִיבִין מִלֵּי דְּאוֹרַיְיתָא, דְּלֵית לָךְ מִלָּה זְעֵירָא דְּלָא תִּשְׁכַּח לָהּ בְּאוֹרַיְיתָא, וְלֵית מִלָּה זְעֵירָא דְּאַתְיָא בְּאוֹרַיְיתָא, דְּלָא נַפְקַת מִפּוּמֵיהּ דְקוּדְשָׁא בְּרִיךְ הוּא. מִלִּין אִלֵּין דְּשָׁאַל הַהוּא רָשָׁע, אֲנָא שָׁאַלְנָא יוֹמָא חַד לְאֵלִיָּהוּ, וְאָמַר דְּהָא בִּמְתִיבְתָּא דִּרְקִיעָא, אִתְסְדָּרוּ קַמֵּיהּ דְקוּדְשָׁא בְּרִיךְ הוּא, וְהָכִי הוּא.</p>\n<p>דְּכַד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, בָּעָא קוּדְשָׁא בְּרִיךְ הוּא לְמֶעְבַּד לוֹן בְּאַרְעָא, כְּמַלְאָכִין קַדִּישִׁין לְעֵילָּא, וּבָעָא לְמִבְנֵי לוֹן בֵּיתָא קַדִּישָׁא, וּלְנַחְתָּא לֵיהּ מִגּוֹ שְׁמֵי רְקִיעִין, וּלְנַטְּעָא לוֹן לְיִשְׂרָאֵל, נְצִיבָא קַדִּישָׁא, כְּגַוְונָא דְּדִיּוּקְנָא דִּלְעֵילָּא. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:י״ז) תְּבִיאֵמוֹ וְתִטָּעֵמוֹ בְּהַר נַחֲלָתְךָ. בְּאָן אֲתָר בְּמָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ. בְּהַהוּא דְּפָעַלְתָּ אַנְתְּ יְיָ, וְלָא אַחֲרָא. מָכוֹן לְשִׁבְתְּךָ פָּעַלְתָּ יְיָ, דָּא בַּיִת רִאשׁוֹן. מִקְּדָּשׁ יְיָ כּוֹנְנוּ יָדֶיךָ, דָּא בַּיִת שֵׁנִי. וְתַרְוַויְיהוּ, אוּמָנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא אִינּוּן.</p>\n<p>וּמִדְּאַרְגִּיזוּ קַמֵּיהּ בְּמַדְבְּרָא, מִיתוּ, וְאַכְנָס לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִבְנַיְיהוּ בְּאַרְעָא. (אוליפו עובדיהון) וּבֵיתָא אִתְבְּנֵי עַל יְדָא דְּבַר נָשׁ, וּבְגִין כַּךְ לָא אִתְקְיָּים. וּשְׁלֹמֹה הֲוָה יָדַע, דִּבְגִין דְּהַאי עוֹבָדָא דְּבַר נָשׁ לָא יִתְקָיָּים, וְעַל דָּא אָמַר, (תהילים קכ״ז:א׳) אִם יְיָ לֹא יִבְנֶה בַיִת שָׁוְא עָמְלוּ בוֹנָיו בּוֹ, דְּהָא לֵית לֵיהּ בֵּיהּ קִיוּמָא. בְּיוֹמוֹי דְּעֶזְרָא, גָּרַם חֲטָּאָה, וְאִצְטָרְכוּן אִינּוּן לְמִבְנֵי, וְלָא הֲוָה בֵּיהּ קִיוּמָא. וְעַד כְּעַן, בִּנְיָינָא קַדְמָאָה דְקוּדְשָׁא בְּרִיךְ הוּא, לָא הֲוָה בְּעָלְמָא, וּלְזִמְנָא דְּאָתֵי כְּתִיב, (תהילים קמ״ז:ב׳) בּוֹנֵה יְרוּשָׁלַ ם יְיָ, אִיהוּ וְלָא אָחֳרָא. וּבִנְיָינָא דָּא אֲנָן מְחַכָּאן, וְלָא בִּנְיָינָא דְּבַר נָשׁ, דְּלֵית בֵּיהּ קִיּוּמָא כְּלַל.</p>\n<p>בַּיִת רִאשׁוֹן, וּבַיִת שֵׁנִי, יָחִית לוֹן קוּדְשָׁא בְּרִיךְ הוּא כַּחֲדָא מִלְּעֵילָּא. בַּיִת רִאשׁוֹן בְּאִתְכַּסְיָא, וּבַיִת שֵׁנִי בְּאִתְגַּלְיָא. הַהוּא בַּיִת לֶהֱוִי בְּאִתְגַּלְיָא, דְּאִתְקְרֵי בַּיִת שֵׁנִי, דְּיִתְחֲזֵי לְכָל עָלְמָא אוּמָנוּתָא דְקוּדְשָׁא בְּרִיךְ הוּא. חֶדְוָה שְׁלִים, וּרְעוּתָא דְּלִבָּא בְּכָל קִיּוּמָא.</p>\n<p>הַהוּא בַּיִת רִאשׁוֹן בְּאִתְכַּסְיָא, אִסְתְּלַּק לְעֵילָּא, עַל גַּבּוֹי דְּהַהוּא דְּאִתְגַּלְיָא. וְכָל עָלְמָא יֶחמוּן, עֲנָנֵי יְקָר דְּסָחֲרָן עַל גַּבֵּי דְּהַהוּא דְּאִתְגַּלְיָיא, וּבְגוֹ דְּאִינּוּן עֲנָנִין, הֲוִי בַּיִת רִאשׁוֹן, בְּעוֹבָדָא טְמִירָא, דְּסָלִיק עַד רוּם יְקַר שְׁמַיָּיא, וּבִנְיָינָא דָּא אֲנָן מְחַכָּאן.</p>\n<p>וְעַד כְּעַן, לָא הֲוָה בְּעָלְמָא, דְּאֲפִילּוּ קַרְתָּא דִּיְרוּשָׁלַם לָא לִיהֱוִי אוּמָנוּתָא דְּבַּר נָשׁ, דְּהָא כְּתִיב, (זכריה ב׳:ט׳) ואֲנִי אֶהְיֶה לָהּ נְאֻם יְיָ חוֹמַת אֵשׁ סָבִיב וְגוֹ'. אִי לְקַרְתָּא כְּתִיב הָכִי, כָּל שֶׁכֵּן בֵּיתָא, דְּאִיהוּ דִּיּוּרָא דִּילֵיהּ. וְעוֹבָדָא דָּא, הֲוִי אִתְחֲזֵי לְמֶהֱוִי בְּרֵישָׁא, כַּד נַפְקוּ יִשְׂרָאֵל מִמִּצְרַיִם, וְאִסְתְּלַּק עַד לְסוֹף יוֹמִין, בְּפוּרְקָנָא <Nonei></i>בַּתְרָאָה.</p>"],[9520012533,"<p>שְׁאֶלְתָּא אַחֲרָא, דְּודַּאי אֲנָן קְרֵבִין לְמַלְכָּא עִלָּאָה, יַתִּיר מִכָּל שְׁאַר עַמִּין. ודַּאי הָכִי הוּא, דְּיִשְׂרָאֵל עֲבַד לוֹן קוּדְשָׁא בְּרִיךְ הוּא לִבָּא דְּכָל עָלְמָא. וְהָכִי אִינּוּן יִשְׂרָאֵל בֵּין שְׁאַר עַמִּין, כְּלִבָּא בֵּין שַׁיְיפִין, כְּמָה דְּשַׁיְיפִין לָא יַכְלֵי לְמֵיקָם בְּעָלְמָא אֲפִילּוּ רִגְעָא חֲדָא בְּלָא לִבָּא, הָכִי עַמִּין כֻּלְּהוּ, לָא יַכְלִין לְמֵיקָם בְּעָלְמָא, בְּלָא יִשְׂרָאֵל. וְאוֹף הָכִי יְרוּשָׁלַם בְּגוֹ שְׁאַר אַרְעָאן, כְּלִבָּא בְּגוֹ שַׁיְיפִין. וְעַל דָּא אִיהִי בְּאֶמְצָעִיתָא דְּכוּלֵי עָלְמָא. כְּלִבָּא גּוֹ שַׁיְיפִין.</p>\n<p>וְיִשְׂרָאֵל מִתְנַהֲגָן גּוֹ שְׁאַר עַמִּין, כְּגַוְונָא דְּלִבָּא גּוֹ שַׁיְיפִין. לִבָּא אִיהִי רָכִיךְ וְחָלָשׁ, וְאִיהוּ קִיּוּמָא דְּכָל שַׁיְיפִין, לָא יָדַע מִצַּעֲרָא וְעָקָא וִיגוֹנָא כְּלָל אֶלָּא לִבָּא, דְּבֵיהּ קִיוּמָא, דְּבֵיהּ סוּכְלְתָנוּ, שְׁאַר שַׁיְיפִין לָא אִתְקְרִיב בְּהוּ כְּלָל, דְּהָא לֵית בְּהוּ קִיּוּמָא, וְלָא יַדְעִין מִדִי. כָּל שְׁאַר שַׁיְיפִין לָא קְרִיבִין לְמַלְכָּא, דְּאִיהוּ חָכְמְתָא וְסוּכְלְתָנוּ, דְּשַׁרְיָא בְּמוֹחָא, אֶלָּא לִבָּא. וּשְׁאַר שַׁיְיפִין, רְחִיקִין מִנֵּיהּ, וְלָא יַדְעִין מִנֵּיהּ כְּלָל. כַּךְ יִשְׂרָאֵל, לְמַלְכָּא קַדִּישָׁא קְרִיבִין, וּשְׁאַר עַמִּין רְחִיקִין מִנֵּיהּ.</p>"],[9520012534,"<p>שְׁאֶלְתָּא אַחֲרָא, דְּיִשְׂרָאֵל לָא אָכְלֵי נְבֵלוֹת וּטְרֵפוֹת, וְטִנּוּפָא וְלִכְלוּכָא דִּשְׁקָצִים וּרְמָשִׂים כִּשְׁאַר עַמִּין, הָכִי הוּא, דְּהָא לִבָּא דְּאִיהוּ רָכִיךְ וְחָלַשׁ, וּמַלְכָּא וְקִיּוּמָא דְּכָל שְׁאַר שַׁיְיפִין, לָא נָטִיל לִמְזוֹנֵיהּ, אֶלָּא בְּרִירוּ וְצָחוּתָא דְּכָל דָּמָא, וּמְזוֹנֵיהּ נָקִי וּבְרִירָא, וְאִיהוּ רָכִיךְ וְחָלִשׁ מִכֹּלָּא, וּשְׁאַר פְּסוֹלֶת אֲנָח לְכָל שַׁיְיפִין, וְכָל שְׁאַר שַׁיְיפִין לָא מַשְׁגִּחִין בְּהַאי, אֶלָּא כָּל פְּסוֹלֶת וּבִישׁ דְּכֹלָּא נַטְלִין, וְאִינּוּן בִּתְקִיפוּ כְּמָה דְּאִתְחֲזֵי לוֹן.</p>\n<p>וְעַל דָּא בְּכָל שְׁאַר שַׁיְיפִין אִית אֲבַעְבּוּעִין, שְׂאֵת אוֹ סַפַּחַת, סְגִירוּ דְּצָרַעַת. לְלִבָּא, לָאו מִכָּל הָנֵי כְּלוּם, אֶלָּא אִיהוּ נָקִי בְּרִירָא מִכֹּלָּא, לֵית בֵּיהּ מוּמָא כְּלָל. כַּךְ קוּדְשָׁא בְּרִיךְ הוּא נָטִיל לֵיהּ לְיִשְׂרָאֵל דְּאִיהוּ נָקִי וּבְרִירוּ דְּלֵית בֵּיהּ מוּמָא עַל דָּא כְּתִיב, (שיר השירים ד׳:ז׳) כֻּלָּךְ יָפָה רַעְיָתִי וּמוּם אֵין בָךְ. אָתָא רִבִּי יוֹסֵי, נָשִׁיק יְדוֹי, אָמַר, אִילּוּ לָא אֲתֵינָא לְעָלְמָא, אֶלָּא לְמִשְׁמַע דָּא, דַּיִּי.</p>"],[9520012535,"<p>(במדבר כ\"ב) וְשֵׁם אִישׁ יִשְׂרָאֵל הַמֻּכֶּה וְגוֹ'. אָמַר רִבִּי יִצְחָק, הַאי קְרָא הָכִי הֲוָה לֵיהּ לְמִכְתַּב, וְשֵׁם אִישׁ יִשְׂרָאֵל אֲשֶׁר הִכָּה פִּנְחָס, וְלֹא הַמֻּכֶּה אֲשֶׁר הֻכָּה, לָא נֶאֱמַר אֶלָּא בְּאֹרַח סָתִים.</p>\n<p>אֶלָּא הָכִי אָמַר רִבִּי אֶלְעָזָר (נ\"א (רצ\"ה ע\"ב) רבי שמעון), כֵּיוָן דְּסַלְקֵיהּ קוּדְשָׁא בְּרִיךְ הוּא לְפִנְחָס לְכַהֲנָא רַבָּא, לָא בָּעָא לְאַדְכְּרָא לֵיהּ לְפִנְחָס בְּקַטְלָנוּתָא דְּבַר נָשׁ. דְּהָא לָא אִתְחֲזֵי לְכַהֲנָא רַבָּא. עַד לָא סַלְקֵיהּ לְכַהֲנָא רַבָּא, אַדְכַּר לֵיהּ, וְאָמַר וַיַּרְא פִּנְחָס וַיִּקַּח רֹמַח וְגוֹ', וַיִּדְקוֹר אֶת שְׁנֵיהֶם וְגוֹ'. כֵּיוָן דְּסַלְקֵיהּ לְכַהֲנָא רַבָּא לָא אַדְכַּר שְׁמֵיהּ בְּקַטְלָנוּתָא, דְּלָא אִתְחֲזֵי לֵיהּ, וְחָס עָלֵיהּ יְקָרָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּכַהֲנָא רַבָּא לָא אִתְחֲזֵי לְאַדְכְּרָא בְּקַטְלָנוּתָא. וְשֵׁם הָאִשָּׁה הַמּוּכָּה, אוּף הָכִי.</p>"],[9520012536,"<p>רִבִּי שִׁמְעוֹן הֲוָה אָזִיל מִקַּפּוּטְקִיָּא לְלוּד, ורִבִּי יְהוּדָה אָזִיל עִמֵּיהּ, עַד דַּהֲווֹ אָזְלֵי פָּגַע בְּהוּ רִבִּי פִּנְחָס בֶּן יָאִיר, וּתְרֵין גּוּבְרִין טוֹעֲנִין אֲבַתְרֵיהּ. שָׁכִיךְ חֲמָרֵיהּ דְּרִבִּי פִּנְחָס. טָעִינוּ לֵיהּ, וְלָא אָזִיל. אָמַר רִבִּי פִּנְחָס, שְׁבִיקוּ לֵיהּ, דְּהָא רֵיחָא דְּאַנְפִּין חַדְתִּין קָא אָרַח, אוֹ נִסָּא אִתְעָבִיד לָן הַשְׁתָּא. עַד דְּאִינּוּן תַּמָּן, נָפַק רִבִּי שִׁמְעוֹן מִבָּתַר חַד טִנָרָא. נָטַל חֲמָרָא וְאָזִיל, אָמַר רִבִּי פִּנְחָס, וְלָא אֲמָרִית לְכוּ, דְּהָא רֵיחָא דְּאַנְפִּין חַדְתִּין קָא אָרַח.</p>\n<p>נָחַת וְגָפִיף לֵיהּ רִבִּי פִּנְחָס, וּבָכָה, אָמַר לֵיהּ, חֲמֵינָא בְּחֶלְמִי, דְּאַתְיָא שְׁכִינְתָּא לְגַבִּי, וְיָהָבַת לִי נְבִזְבְּזָן רַבְרְבָן, וְחַדִּינָא בָּהּ. הַשְׁתָּא כְּמָה דַּחֲמֵינָא. אָמַר רִבִּי שִׁמְעוֹן, מִקָּל פַּרְסֵי דַּחֲמָרָךְ, יְדַעְנָא דְּאַנְתְּ הוּא. הַשְׁתָּא חֶדְוָה שְׁלִים. אָמַר רִבִּי פִּנְחָס, נֵתִיב בְּדוּךְ חַד, דְּמִלֵּי דְּאוֹרַיְיתָא אִצְטְרִיךְ צָחוּתָא. אַשְׁכָּחוּ עֵינָא דְּמַיָיא, וְאִילָנָא, יָתְבוּ.</p>\n<p>אָמַר רִבִּי פִּנְחָס, מִסְתָּכַּל הֲוִינָא דְּהָא לִתְחִיַּית הַמֵּתִים, בְּאָרְחָא אָחֳרָא יַעְבִּיד לוֹן קוּדְשָׁא בְּרִיךְ הוּא, וּמַה דְּהֲוָה הַשְׁתָּא קַדְמָאָה, לִיהֱוִי כְּדֵין בַּתְרָאָה. מְנָלָן. מֵאִינּוּן עֲצָמוֹת, הַנְהוּ גַּרְמִין דְּאַחֲיָא לוֹן קוּדְשָׁא בְּרִיךְ הוּא עַל יְדֵי יְחֶזְקֵאל, דִּכְתִּיב, (יחזקאל ל״ז:ז׳) וַתִּקְרְבוּ עֲצָמוֹת עֶצֶם אֶל עַצְמוֹ בְּקַדְמִיתָא, וּלְבָתַר כְּתִיב <Nonei></i>וְרָאִיתִי וְהִנֵּה עֲלֵיהֶם גִּידִים וּבָשָׂר עָלָה וְגוֹ'. וַיִּקְרַם עֲלֵיהֶם עוֹר מִלְמָעְלָה וְרוּחַ אֵין בָּהֶם. דְּהָא מַה דְּאַפְשִׁיט בְּקַדְמִיתָא, לִיהֱוֵי בַּתְרָאָה. בְּקַדְמִיתָא (אפשיט מרוחא, ולבתר) עוֹר, וּלְבָתַר בָּשָׂר, בְּקַדְמִיתָא אַפְשִׁיט מֵרוּחָא, וּלְבָתַר עוֹר, וּלְבָתַר בָּשָׂר, וּלְבָתַר עֲצָמוֹת.</p>"],[9520012537,"<p>אָמַר רַבִּי שִׁמְעוֹן, בְּדָא אַקְשָׁן קַדְמָאֵי, אֲבָל גַּרְמִין אִלֵּין דְּאַחֲיָא קוּדְשָׁא בְּרִיךְ הוּא, נִסִּין וְאָתִין מְשַׁנְיָין, עֲבַד בְּהוּ קוּדְשָׁא בְּרִיךְ הוּא. תָּא חֲזֵי מַה כְּתִיב, (איוב י׳:ט׳) זְכָר נָא כִּי כַחוֹמֶר עֲשִׂיתָנִי וְאֶל עָפָר תְּשִׁיבֵנִי. מַה כְּתִיב בַּתְרֵיהּ, הֲלֹא כֶחָלָב תַּתִּיכֵנִי וְכַגְּבִינָה תַּקְפִּיאֵנִי, עוֹר וּבָשָׂר תַּלְבִּישֵׁנִי וּבַעֲצָמוֹת וְגִידִים תְּסוֹכְכֵנִי. זַמִּין קוּדְשָׁא בְּרִיךְ הוּא, לְבָתַר דְּיִתְבְּלֵי בַּר נָשׁ בְּעַפְרָא, וּמָטֵי זִמְנָא דִּתְחִיַית הַמֵּתִים, דְּהַהוּא גַּרְמָא דְּיִשְׁתְּאַר. לְמֶעְבַּד לֵיהּ כְּעִסָה דָּא, וְכַגְּבִינָה דְּחָלָב, וּנְבִיעַ כְּחָלָב, דְּהוּא נְבִיעוּ נָקִי מְצוּחְצַח בְּצָחוּתָא הַהוּא גַּרְמָא. כַּד יִתְעֲרָב הַהוּא גַּרְמָא וְיִתְמְחֵי כְּחָלָבָא, וּלְבָתַר יַקְפִּיא לֵיהּ, וְיִתְצַיֵּיר בְּצִייּוּרָא כַּגְּבִינָה בִּקְפִּיאוּתָא, וּלְבָתַר יִתְמְשַׁךְ עָלֵיהּ עוֹר וּבָשָׂר וַעֲצָמוֹת וְגִידִים.</p>\n<p>הֲדָא הוּא דִכְתִיב הֲלֹא כֶחָלָב תַּתִּיכֵנִי וְכַגְּבִינָה תַּקְפִּיאֵנִי. הִתַּכְתָּנִי לָא כְּתִיב, אֶלָּא תַּתִּיכֵנִי. הִקְפִּיתָנִי לָא כְּתִיב, אֶלָּא תַּקְפִּיאֵנִי. הִלְבַּשְׁתָּנִי לָא כְּתִיב, אֶלָּא תַּלְבִּישֵׁנִי. סוֹכַכְתָּנִי לָא כְּתִיב, אֶלָּא תְּסוֹכְכֵנִי. כֻּלְּהוּ לְבָתַר זִמְנָא מַשְׁמַע.</p>\n<p>וּלְבָתַר מַה כְּתִיב, חַיִים וָחֶסֶד עָשִׂיתָ עִמָּדִי, דָּא רוּחָא דְּחַיֵּי. (ס\"א ואי תימא) עָשִׂיתָ עִמָּדִי כְּתִיב, וְלָא כְּתִיב תַּעֲשֶׂה. אֶלָּא הָכִי אָמַר, חַיִים וָחֶסֶד עָשִׂיתָ עִמָּדִי. בְּהַהוּא עָלְמָא שָׁדִית בִּי רוּחָא דְּחַיִּים, אֲבָל וּפְקוּדָּתְךָ, דְּמַטְרוֹנִיתָא דְּמַלְכָּא, שָׁמְרָה רוּחִי, אִיהִי נַטְרַת לְרוּחִי, בְּהַהוּא עָלְמָא. מַאי וּפְקוּדָּתְךָ, דְּאַתְּ זַמִּין לְפַקְדָא לָהּ בְּקַדְמִיתָא.</p>\n<p>(שמרה רוחי) וְרָזָא דְּמִלָּה דָּא, כָּל נַפְשִׁין דְּצַדִיקַיָּיא, גְּנִיזִין וּטְמִירִין תְּחוֹת כֻּרְסְיָיא דְּמַלְכָּא, וְאִיהִי נַטְרָא לוֹן, לְאָתָבָא לוֹן לְדוּכְתַיְיהוּ, הֲדָא הוּא דִכְתִיב וּפְקוּדָּתְךָ שָׁמְרָה רוּחִי. מַאי וּפְקוּדָּתְךָ. כְּמָה דְאַתְּ אָמֵר, (תהילים ק״ט:ח׳) פְּקוּדָּתוֹ יִקַּח אַחֵר. פְּקוּדָּתְךָ, דָּא מַטְרוֹנִיתָא דְּמַלְכָּא, דְּכָל רוּחִין אִינּוּן פִּקְדוֹנִין בִּידָהָא, הֲדָא הוּא דִכְתִיב, (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי וְגוֹ', וְאִיהִי נַטְרָא לוֹן, בְּגִין דָּא שָׁמְרָה רוּחִי, וְאִיהִי נַטְרַת לָהּ.</p>\n<p>כְּגַוְונָא דָּא אָמַר דָּוִד, (תהילים פ״ו:ב׳) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. שָׁמְרָה: דָּא מַטְרוֹנִיתָא דְּמַלְכָּא. דְּאִיהִי נַטְרָא נַפְשִׁי, בְּגִין כִּי חָסִיד אֲנִי. וּבְכָל אֲתָר דִּכְתִיב סְתָם, דָּא מַטְרוֹנִיתָא. כְּמָה דְאַתְּ אָמֵר, (שמות כ״ד:ט״ז) וַיִּקְרָא אֶל מֹשֶׁה. (שמות ט״ו:כ״ו) וַיֹּאמֶר אִם שָׁמֹעַ תִּשְׁמַע בְּקוֹל יְיָ אֱלֹהֶיךָ.</p>\n<p>בָּכָה רִבִּי פִּנְחָס, וְאָמַר, וְלָאו אֲמָרִית לָךְ דִּשְׁכִינְתָּא יָהָבַת לִי נְבִזְבְּזָן וּמַתְנָן, זַכָּאָה חוּלָקִי דְּזָכֵינָא לְמֵחמֵי לָךְ, וְשָׁמַעְנָא דָּא. אָמַר לֵיהּ, בְּהַהוּא זִמְנָא, תִּינַח הַהוּא גַּרְמָא, שְׁאַר גַּרְמִין דְּיִשְׁתַּכְחוּן מַה יִתְעֲבִיד מִנְּהוֹן. אָמַר לֵיהּ, כֻּלְּהוּ יִתְכְּלִילוּ בְּהַהוּא נְבִיעוּ דְּהַאי גַּרְמָא, וְיִתְכְּלִילוּ בַּהֲדֵיהּ, וְיִתְעֲבִיד כֹּלָּא עִסָּה חֲדָא, וְתַּמָּן יִתְצַיֵּיר צִיּוּרָא, כְּמָה דְּאִתְּמַר. הֲדָא הוּא דִכְתִיב, (ישעיהו נ״ח:י״א) וְעַצְמוֹתֶיךָ יַחֲלִיץ. מַאי יַחֲלִיץ. כְּמָה דְאַתְּ אָמֵר (הושע ה׳:ו׳) חָלַץ מֵהֶם. כֻּלְּהוּ יִתְעַבְּרוּן מִקִּיוּמַיְיהוּ, וְיִתְכְּלִילוּ בְּהַאי גַּרְמָא, לְמֶהֱוִי עִסָּה חֲדָא. וּכְדֵין (ישעיהו נ״ח:י״א) וְהָיִיתָ כְּגַן רָוְה וּכְמוֹצָא מַיִם וְגוֹ'. (אמר רעיא מהימנא)</p>\n<p><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, וַוי לוֹן לִבְנֵי נָשָׁא, דְּאִינּוּן אֲטִימִין לִבָּא, סְתִימִין עַיְינִין, דְּלָא יַדְעִין דְּכַד אָתֵי לֵילְיָא, תַּרְעִין דְּגֵיהִנָּם אִתְפְתָּחוּ, דְּאִיהִי מָרָה. ועֲשָׁנִין דִּילָהּ דְּמִתְפַּשְּׁטִין, סַלְּקִין עַד מוֹחָא. וְכַמָּה חַיָּילִין דְּיֵצֶר הָרָע, מִתְפַּשְּׁטִין בְּכָל אֵבָרִין דְּגוּפָא. וְתַרְעִין דְגַּן עֵדֶן, דְּאִיהוּ עַיְינִין דְּלִבָּא, מִסְתַּתְמִין וְלָא מִתְפַּתְּחִין. דְּכָל נְהוֹרִין דְּעַיְינִין, מִלִּבָּא נָפְקִין.</p>"],[9520012538,"<p>וְתַרְעִין דְּלִבָּא, אִינּוּן עַיְינִין מִסְתַּתְמִין, בְּגִין דְּלָא מִסְתַּכְּלִין בְּאִלֵּין מַזִּיקִין, דְּאִינּוּן לִילִית. וְלָא שַׁלְטִין בִּנְהוֹרִין דְּלִבָּא, דְּאִינּוּן מַלְאָכִים דְּמִתְפַּשְּׁטִין בְּכָל אֵבָרִים, כְּעַנְפִין דְּאִילָנָא לְכָל סִטְרָא. בְּהַהוּא זִמְנָא אִינּוּן כֻּלְּהוּ נְהוֹרִין סְתִימִין בְּלִבָּא, וּמִתְכַּנְשִׁין לְגַבֵּיהּ, (ישעיה סא) כְּיוֹנִים אֶל אֲרֻבּוֹתֵיהֶם. כְּנֹחַ וְאִתְּתֵיהּ, וְכָל מִין וּמִין, דְּעָאלוּ עִמֵּיהּ בַּתֵּיבָה.</p>\n<p>וּמַזִּיקִין דְּמִתְגַּבְּרִין עַל כָּל אֵבָרִים דְּגוּפָא, כְּמֵי טוֹפָנָא דְּגָבְרוּ עָלֵיהּ ט\"ו אָמַה, בְּגִין דְּחָב בְּיָ\"הּ, וְאִסְתַּלָּק יָ\"הּ מִן גּוּפָא, וְאִשְׁתְּאַר אִלֵּם, בְּלָא רְאִיָה וּשְׁמִיעָה וְרֵיחָא וְדִבּוּר. וְרָזָא דְּמִלָּה, (תהילים ל״ט:ג׳) נֶאֱלַמְתִּי דּוּמִיָּה (החשיתי מטוב וכאבי נעכר), דּוּמִיָּ\"ה: דּוֹ\"ם יָ\"הּ. כְּהַהוּא זִמְנָא, חֲמֵשׁ עֶשְׂרֵה אַמָּה, גָּבְרוּ מַזִּיקִין עַל גּוּפָא. וְאִינּוּן כְּכִסְלָא לְעוּגְיָא.</p>\n<p><Nonei></i>וּכְגַוְונָא דְּנֹחַ, שָׁלַח אֶת הַיּוֹנָה בִּשְׁלִיחוּתֵיהּ. אוּף הָכִי שָׁלַח נִשְׁמְתָא בָּאָדָם. רוּחֵיהּ בִּשְׁלִיחוּתֵיהּ. וּבְגִין דָּא צָרִיךְ בַּר נָשׁ לְפַקְדָּא לָהּ בְּמַטְרוֹנִיתָא. הֲדָא הוּא דִכְתִיב (תהילים ל״א:ו׳) בְּיָדְךָ אַפְקִיד רוּחִי. וְאִם הִיא אֲסִירָא בְּחוֹבוֹי דְּגוּפָא, בִּידָא דְּחַיָּילִין דְּיֵצֶר הָרָע, מַה כְּתִיב, בְּיָדְךָ אַפְקִיד רוּחִי פָּדִיתָ אוֹתִי יְיָ אֵל אֱמֶת.</p>\n<p>וְעוֹד בְּזִמְנָא דְּאִיהִי חַיֶּיבֶת, מַה כְּתִיב בְּרוּחֵיהּ, (משלי י״א:כ״א) יָד לְיָד לֹא יִנָּקֶה רָע. דְּאָזִיל מִיָּד לְיָד, בְּמַשִׁרְיָין דְּיֵצֶר הָרָע, דְּשַׁרְיָין עָלֵיהּ בְּחוֹבִין דִּילֵיהּ, וְזַרְקִין לֵיהּ מֵאֲתָר לַאֲתָר. וְהַאי אִיהוּ דְּאַחְזֵי גַּרְמֵיהּ בִּמְדִינָה אַחֶרֶת, אוֹ בְּמַלְכוּ אַחֲרָא, וּלְזִמְנִין בָּאַשְׁפָּה, כְּפוּם חוֹבוֹי. וְאִי אִיהוּ זַכָּאָה, כָּל מַשִׁרְיָין דְּיֵצֶר טוֹב כֻּלְּהוּ, (יחזקאל א׳:ח׳) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת, לְקַבְּלָהּ רוּחֵיהּ, וְסַלְּקִין לֵיהּ לְעֵילָּא, לַאֲתָר דְּחֵיוָן דְּכֻרְסְיָיא, וְתַּמָּן חֲזֵי, כַּמָה חֶזְיוֹנוֹת, דִּמְיוֹנוֹת, וּמַרְאוֹת דִּנְבוּאָה. וּבְגִין דָּא אוֹקְמוּהָ רַבָּנָן, דְּחֲלוֹם אֶחָד מִשִּׁשִׁים בַּנְּבוּאָה. וְעוֹד (תהילים פ״ו:ב׳) שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי, אַף עַל גַּב דּאוּקְמוּהַ בַּגְּמָרָא וְלָא חָסִיד אֲנִי שֶׁכָּל מַלְכֵי מִזְרָח וּמַעֲרָב יְשֶׁנִים עַד ד' שָׁעוֹת וַאֲנִי (תהילים קי״ט:ס״ב) חֲצוֹת לַיְלָה אָקוּם לְהוֹדוֹת לָךְ. וְלֹא עוֹד אֶלָּא שֶׁכָּל מַלְכֵי מִזְרָח וּמַעֲרָב וכו' וַאֲנִי יָדַי מְלוּכְלָכוֹת בְּדָּם שַׁפִּיר וְשִׁלְיָא כְּדֵי לְטַהֵר אִשָּׁה לְבַעְלָהּ. מִיָד אִזְדָּמַן לֵיהּ צְפָרְדְּעַ וְאָמַר לֵיהּ לָמָּה אַתְּ מְשַׁבַּחַת גַרְמָךְ לְמֵימָר חֲצוֹת לַיְלָה אֲקוּם לְהוֹדוֹת לָּךְ וַאֲנָא כָּל לֵילְיָא לָא שָׁכִיבְנָא לְשַׁבְּחָא לֵיהּ וּלְנָגְנָא קַמֵּיהּ. אֲמָר דָּוִד וַוי לְמְמָנָא דְּהַהוּא צְפָרְדְּעַ דְלָא יָדַע מַאי דְּאֲנָא אֲמֵינָא דְלָא אֲמֵינָא כִּי חָסִיד אֲנִי.</p>\n<p>אֶלָּא בְּגִין דְּאוֹקְמוּהָ רַבָּנָן. וְלֹא עָם הָאָרֶץ חָסִיד. דְּאוֹרַיְיתָא אִתְיְהִיבַת מִימִינָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּאִיהוּ חֶסֶד. וּבְגִין דָּא, מַאן דְּאִתְעַסֵּק בְּאוֹרַיְיתָא, אִתְקְרֵי חָסִיד. בְּגִין דָּא, אֲמֵינָא לְּקוּדְשָׁא בְּרִיךְ הוּא, שָׁמְרָה נַפְשִׁי, וְלָא תִּדוּן לָהּ כְּעוֹבָדֵי אִלֵּין עַמֵּי הָאֲרָצוֹת, דְּאִתְּמַר בְּהוּ וְלֹא עַם הָאָרֶץ חָסִיד. וְאִי תֵּימָא, כַּמָּה עַמֵּי הָאֲרָצוֹת אִינּוּן דְּעָבְדוּ חֶסֶד. אֶלָּא הָכִי אוּקְמוּהָ, אֵי זֶהוּ חָסִיד, זֶה הַמִּתְחַסֵּד עִם קוֹנוֹ. כְּגוֹן דָּוִד דְּהֲוָה מְחַבֵּר. וּמַאי הֲוָה מְחַבֵּר, אוֹרַיְיתָא דִּלְעֵילָּא הֲוָה מְחַבֵּר עִם קוּדְשָׁא בְּרִיךְ הוּא. וּבְגִין דָּא, שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי.</p>"],[9520012539,"<p>וְכַד בַּר נָשׁ מִית, מַה כְּתִיב בָּהּ בְּהַאי נֶפֶשׁ (משלי ו׳:כ״ב) בְּהִתְהַלֶּכְךָ תַּנְחֶה אוֹתָךְ בְּשָׁכְבְּךָ תִּשְׁמוֹר עָלֶיךָ, וַהֲקִיצוֹתָ לִתְחִיַּית הַמֵּתִים, הִיא תְשִׂיחֶךָ. דָּא לִתְחִיַּית הַמֵּתִים שַׁפִּיר, דְּיוֹקִים לֵיהּ לְבַּר נָשׁ, אֲבָל לְאַגְרָא לְנִשְׁמְתָא בְּעָלְמָא דְּאָתֵי, מַאי הֲוִי.</p>\n<p>אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא מַלְבִּישׁ לָהּ כְּקַדְמֵיתָא בַּעֲנָנֵי כָּבוֹד. כְּקַדְמֵיתָא תֵּיעוּל בְּמַרְאָה, דְּאִיהוּ כְּגַוְונָא דְּגוּפָא, כָּלִיל בְּרמ\"ח אֵיבָרִים. אוּף הָכִי תֵּיעוּל בַּמַרְאָה, כָּלִיל בְּמָאתַיִם וְאַרְבָּעִים וּשְׁמֹנָה פִיקּוּדִין וּבְרמ\"ח. נְהִירִין דְּמִתְפָּרְשָׁן מֵהַהוּא מַרְאָה. דְּאִתְּמַר בֵּיהּ, (במדבר י״ב:ו׳) וַיֹּאמֶר אִם יִהְיֶה נְבִיאֲכֶם יְיָ בַּמַרְאָה אֵלָיו אֶתְודָּע. וּבִלְבוּשִׁין דַּעֲנָנֵי כָּבוֹד (בראשית ט׳:ט״ז) וּרְאִיתִיהָ לִזְכּוֹר בְּרִית עוֹלָם, דָּא אַסְפַּקְלַרְיָאָה הַמְּאִירָה. (במדבר י״ב:ו׳) בַּחֲלוֹם אֲדַבֵּר בּוֹ, דָּא אַסְפַּקְלַרְיָאָה דְּלָא נַהֲרָא. כָּלִיל מִשס\"ה נְהִירִין, כְּחֻשְׁבַּן יְשֵׁנָה. וְהַיְינוּ (שיר השירים ה׳:ב׳) אֲנִי יְשֵׁנָה. חַד בְּעָלְמָא דֵּין. וְחָד בְּעָלְמָא דְּאָתֵי. וְאִינּוּן בְּעוֹבְדֵי יְדוֹי דְקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וְרָזָא דִּלְהוֹן, (שמות ג׳:ט״ו) זֶה שְּׁמִי לְעוֹלָם. יָ\"הּ עִם שְׁמִי, שָׁלֹשׁ מֵאוֹת וַחֲמִשָּׁה וְשִׁשִׁים. ו\"ה עִם זִכְרִי, מָאתַּיִם וּשְׁמֹנָה וְאַרְבָּעִים. וְכָרוֹזִין נַחְתִין וְסַלְּקִין קַמֵּיהּ, הָבוּ יְקָר (ס\"א לדיוקנא) לִיקָרָא דְּמַלְכָּא.</p>\n<p>וְהַיְינוּ (בראשית א׳:כ״ז) וַיִּבְרָא אֱלֹהִים אֶת הָאָדָם בְּצַלְמוֹ בְּצֶלֶם אֱלֹהִים בָּרָא אוֹתוֹ. וְהוּא דְּעֲבַד לֵיהּ בִּתְרֵין דִּיוּקְנִין, בִּתְרֵין גַּנִּים (נ\"א פנים) דְּאִתְּמַר עָלַיְיהוּ (שיר השירים ה) הַיּוֹשֶׁבֶת בַּגַּנִּים אִיהוּ עִילַּת עַל כֹּלָּא דְּאִתְּמַר עָלָהּ (דברים ד׳:ט״ו) כִּי לֹא רְאִיתֶם כָּל תְּמוּנָה. וְעַל שְׁאַר דִּיוּקְנִין כְּתִיב, תְּמוּנַת כָּל וְגוֹ'. (במדבר י״ב:ח׳) וּתְמוּנַת יְיָ יַבִּיט. וְתרי\"ג מַלְאָכִין סַלְּקִין לָהּ לְנִשְׁמְתָא. בְּאִלֵּין דִּיוּקְנִין, כֻּלְּהוּ וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת, לְקַיֵּים קְרָא דִּכְתִּיב בְּהוֹן (שמות י״ט:ד׳) וָאֶשָּׂא אֶתְכֶם עַל כַּנְפֵי נְשָׁרִים וָאָבִיא אֶתְכֶם אֵלָי.</p>\n<p>כְּגַוְונָא דְּנַפְקוּ מִמִּצְרַיִם, וְאַזְלוּ בַּעֲנָנֵי כָּבוֹד, וּבְכָל הַהוּא יְקָר, כְּהַהוּא גַּוְונָא תְּהֵא מַפְקָנוּתָא דְּנִשְׁמְתָא, מִגוּפָא דְּטִפָּה סְרוּחָה, לְמֵיזָל לִתְרֵין גַּנִּים, דְּאִתְבְּרֵי שְׁמַיָא וְאַרְעָא דִּלְהוֹן בְּשֵׁם יְיָ. וּבְגִינֵיהּ אִתְּמַר, (תהילים צ״ו:י״א) יִשְׂמְחוּ הַשָּׁמַיִם וְתָגֵל הָאָרֶץ. בְּהַהוּא זִמְנָא יִתְקַיֵּים בְּבַּר נָשׁ (ישעיהו ל׳:כ׳) וְלֹא יִכָּנֵף עוֹד מוֹרֶיךָ לְגַבָּיךְ, (ישעיהו ו׳:ב׳) בִּשְׁתַּיִם יְכַסֶּה פָּנָיו, אֶלָּא וְהָיוּ עֵינֶיךָ רוֹאוֹת אֶת מוֹרֶיךָ. וּמִסִּטְרָא דְּאִלֵּין מַרְאוֹת, זָכָה מֹשֶׁה רַבֵּינוּ עָלָיו הֲשָׁלוֹם, רַבָּן שֶׁל נְבִיאִים וַחֲכָמִים. אָמַר בּוּצִינָא קַדִישָׁא, אַנְתְּ הוּא דְּזָכִית בְּחַיָיךְ, לְמָה דְּיִזְכּוּן צַדִיקַיָּא בָּתַר חַיֵּיהוֹן, זַכָּאָה חוּלָקָךְ.</p>"],[9520012540,"<p>דָּבָר אַחֵר שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי, אֲמַאי. כְּדֵי שֶׁאֶתְחָסֵּד עִם אֲנִ\"י. דְּאִתְּמַר בֵּיהּ אֲנִ\"י וָה\"וּ. וַוי לֵיהּ לְמַאן דְּאַפְרִישׁ <Nonei></i>אֲנִי מִן הוּא. דְּאִתְּמַר (תהילים ק׳:ג׳) הוּא עָשָׂנוּ וְלֹא אֲנַחְנוּ. דְּכֹלָּא חַד בְּלָא פִּרוּדָא. הֲדָא הוּא דִכְתִיב, (דברים ל״ב:ל״ט) רְאוּ עַתָּה כִּי אֲנִי אֲנִי הוּא אֲנִי אָמִית וַאֲחַיֶּה מָחַצְתִּי וַאֲנִי אֶרְפָּא וְאֵין מִיָּדִי מַצִּיל. אֲנִי יְדוָֹ\"ד, אֲנִי הוּא וְלֹא אַחֵר. וְדָא אֲנִי מִן אֲדֹנָ\"י. יְדוָֹד עַמּוּדָא דְּאֶמְצָעִיתָא.</p>\n<p>וּבְגִין דְּיְדוָֹ\"ד אִיהוּ לִימִינָא דְּאִיהִי חֶסֶד, אָמַר, שָׁמְרָה נַפְשִׁי דְּאֶתְחַסֵּד בָּךְ עִם אֲנִי, וְאִיהוּ אֲדֹנָ\"י לַגְּבוּרָה. וּבְתִפְאֶרֶת, אִתְחַבְּרָן תְּרֵין שְׁמָהָן יאהדונה\"י. וְרָזָא דְּמִלָּה בְּחֶסֶד וּבִגְבוּרָה, (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמָעְלָה וּבְתִפְאֶרֶת, דְּאִתְקְרֵי (שמות ט״ו:ג׳) יְדוָֹ\"ד אִישׁ מִלְחָמָה, מַה כְּתִיב (יחזקאל א׳:י״א) שְׁתַּיִם חוֹבְרוֹת אִישׁ, תַּרְתֵּין שְׁמָהָן מִתְחַבְּרָן בֵּיהּ כַּחֲדָא. וּשְׁתַּיִם מְכַסּוֹת אֶת גְּוִיּוֹתֵיהֶנָה. תִּפְאֶרֶת אִתְקְרֵי גּוּף, (דניאל י׳:ו׳) וּגְוִיָּתוֹ כַתַרְשִׁישׁ יאההויה\"ה.</p>"],[9520012541,"<p>(תהילים פ״ו:ב׳) הוֹשַׁע עַבְדְּךָ אַתָּה אֱלֹהַי שַׂמֵּחַ נֶפֶשׁ עַבְדֶּךָ תְּנָה עֻזְּךָ לְעַבְדֶּךָ. תְּלַת זִמְנִין אִתְעָבִיד דָּוִד עֶבֶד בִּתְהִלָּה דָּא, לָקֳבֵל ג' זִמְנִין, דְּאוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּבָעֵי בַּר נָשׁ לְמֶהֱוִי עַבְדָּא בִּצְלוֹתָא. בְּבִרְכָאן קַדְמָאִין, כְּעֶבֶד דִּמְסַדֵּר שְׁבָחוֹי קַמֵּי רַבֵּיהּ. בְּאֶמְצָעִיּוֹת, כְּעַבְדָּא דְּבָעֵי פְּרָס מֵרַבֵּיהּ. בַּאַחֲרוֹנוֹת, כְּעֶבֶד דְּמוֹדֶה קֳדָם רַבֵּיהּ, בַּפְּרַס דְּקַבִּיל מִינֵיהּ, וְאָזִיל לֵיהּ.</p>\n<p>וּתְלַת זִמְנִין דְּבָעֵי לְמֶעְבַּד עֶבֶד, מִסִּטְרָא דְּעֲבוֹדָה. דְּאוֹקְמוּהָ מָארֵי מַתְנִיתִין, דְּלֵית עֲבוֹדָה אֶלָּא תְּפִלָּה. וּתְלַת אֲבָהָן, אִתְקְרִיאוּ עֲבָדִים מִסִּטְרָהָא, עַל שֵׁם שְׁכִינְתָּא, דְּאִיהִי עֲבוֹדַת יְיָ. וְאוֹף הָכִי מֹשֶׁה עֶבֶד יְיָ. וּבְגִין דָּא, (ויקרא כה) כִּי לִי בְּנֵי יִשְׂרָאֵל עֲבָדִים. אֲבָל לְגַבֵּי אַחֲרָנִין, כָּל יִשְׂרָאֵל בְּנֵי מְלָכִים הֵם, מִסִּטְרָא דְּמַלְכוּת. וְאִיהִי אֲמַאי אִתְקְרִיאַת עֲבוֹדָה. כְּאוֹרַח דְּאִתְּתָא לְמִיפְלַח לְבַעְלָהּ, וְאוֹרַח בְּנִין, לְמִפְלַח לַאֲבוּהוֹן.</p>"],[9520012542,"<p>וְדָוִד, אִתְעָבִיד עָנִי, חָסִיד, וְעֶבֶד. הֲדָא הוּא דִכְתִיב, (תהילים פ״ו:א׳-ב׳) תְּפִלָּה לְדָוִד הַטֵּה אֲדֹנָי אָזְנְךָ עֲנֵנִי כִּי עָנִי וְאֶבְיוֹן אָנִי. שָׁמְרָה נַפְשִׁי כִּי חָסִיד אָנִי. הוֹשַׁע עַבְדְּךָ אַתָּה אֱלֹהַי הַבּוֹטֵחַ אֵלֶיךָ. אִתְעָבִיד עָנִי לְתַרְעָא דְּמַלְכָּא, דְּאִתְּמַר בָּהּ, (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח. אֲדֹנָ\"י הֵיכַ\"ל, אִתְעָבִיד עָנִי לְתַרְעָא דְּהֵיכָלָא דְּמַלְכָּא. וּמַה כְּתִיב. הַטֵּה אֲדֹנָי אָזְנְךָ עֲנֵנִי וְדָא שְׁכִינְתָּא תַּתָּאָה. דְּאִיהוּ אֹזֶן לְקַבְּלָא צְלוֹתִין וּלְמִשְׁמַע לוֹן. כְּדִכְתִיב, (תהילים כ״ב:כ״ה) כִּי לֹא בָזָה וְלֹא שִׁקַּץ עֱנוּת עָנִי וְלֹא הִסְתִּיר פָּנָיו מִמֶּנּוּ וּבְשַׁוְּעוֹ אֵלָיו שָׁמֵעַ.</p>\n<p>דְּאִיהוּ אִתְעָבִיד עָנִי וְדָל, מִסִּטְרָא דְּאָת ד' מִן אֶחָד, לְמִשְׁאַל מִן א\"ח, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָעִיתָא. לְקַיְּימָא בֵּיהּ, (תהילים קט״ז:ו׳) דַּלּוֹתִי וְלִי יְהוֹשִׁיעַ, דְּלָא יְמוּת מָשִׁיחַ בֶּן אֶפְרַיִם. וְשָׁאִיל מִנֵּיהּ בְּהַהוּא תַּרְעָא, בְּגִין יִשְׂרָאֵל הַעֲנִיִים, לְקַיֵּים בְּהוּ (שמואל ב כ״ב:כ״ח) וְאֶת עַם עָנִי תּוֹשִׁיעַ.</p>\n<p>וּלְבָתַר שָׁאִיל בְּגִין כַּהֲנַיָיא, דְּיַחֲזוֹר עֲבוֹדָה לִמְקוֹמָהּ, וְאִתְעָבִיד עֶבֶד. וּלְבָתַר דְּיָהִיב לוֹן אוֹרַיְיתָא מִסִּטְרָא דְּחֶסֶד, לְמֶעְבַּד גְּמוּל עִם דָּלֶי\"ת מִן אוֹרַיְיתָא, וּבְגִין דָּא אִתְעָבִיד חָסִיד. כַּךְ מָטָא לְג' סְפִירָאן עִלָּאִין, פָּתַח וְאָמַר (תהילים קל״א:א׳) יְיָ לֹא גָּבַהּ לִבִּי וְלֹא רָמוּ עֵינַי וְלֹא הִלַּכְתִּי בִּגְדוֹלוֹת וּבְנִפְלָאוֹת מִמֶּנִּי.</p>\n<p>שְׁלֹמֹה אָמַר, הָא בִּינָה אִיהִי דְּמֹשֶׁה, אֶשְׁאַל בְּחָכְמָה עִלָּאָה, דְּאִיהִי לְעֵיל מִדַּרְגֵּיהּ. מַה כְּתִיב, (קהלת ז׳:כ״ג) אָמַרְתִּי אֶחְכָּמָה וְהִיא רְחוֹקָה מִמֶּנִּי. וְהָא כְּתִיב (מלכים א ה׳:כ״ו) וַיְיָ נָתַן חָכְמָה לִשְׁלֹמֹה. חָכְמָה זְעֵירָא. וּבָעָא לְסַלְּקָא מִתַּתָּא לְעֵילָּא, דְּאִתְרְחִיקַת מִנֵּיהּ. בְּגִין דְּאֲפִילּוּ לַבִּינָה לֵית בַּר נָשׁ בְּעָלְמָא דְּיָכִיל לְסַלְּקָא, בַּר מִמֹּשֶׁה, כָּל שֶׁכֵּן לְעֵילָּא מִנֵּיהּ, דְּאִיהוּ חָכְמָה עִלָּאָה, מִסִּטְרָא דִּילָהּ חָכָם עָדִיף מִנָּבִיא. וְאַף עַל גַּב דְּאוּקְמוּהָ בְּאֹרַח דְּרָשָׁא, עַל פָּרָה אֲדוּמָה. שִׁבְעִים פָּנִים לַתּוֹרָה.</p>"],[9520012543,"<p>רִבִּי אֶלְעָזָר, קוּם לְחַדְּשָׁא מִלִּין קַמֵּי שְׁכִינְתָּא, דִּי תְּהֵא עֵזֶר לְאָבִיךָ, דִּשְׁמָא גָּרִים, עֵזֶר אֶל, אֵל מִימִינָא, עֵזֶר מִשְּׂמָאלָא. הֲדָא הוּא דִכְתִיב, (בראשית ב׳:י״ח) אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ. בְּמַאי. בְּזֶרַע שַׁפִּיר, דְּאִיהוּ הֶפֶךְ עֵזֶר. וְיֵקוּם רִבִּי יוֹסֵי עִמָּךְ, דְּאִיהוּ כֻּרְסְיָיא שְׁלֵימָתָא לְמָארֵיהּ, דְּהָכִי סָלִיק יוֹסֵי, לְחֶשְׁבּוֹן הַכִּסֵּ\"א, אֱלֹהִים בְּחוּשְׁבָּן.</p>\n<p>וְיֵקוּם עִמֵּיהּ רִבִּי יְהוּדָה, דְּבֵיהּ הוֹ\"ד, וּבֵיהּ יָ\"הּ, וּבֵיהּ יְדוָֹד ד', ד' חֵיוָן. (יחזקאל א׳:ח׳) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת, כֻּלְּהוּ, לְקַבְּלָא לֵיהּ. וּמִנֵּיהּ דָּוִד, דְּהוֹדָה לְּקוּדְשָׁא בְּרִיךְ הוּא, דַּרְגָּא בְּהוֹדָאוֹת דְּאִיהוּ מִצַּד הוֹד. וְיֵקוּם עִמֵּיהּ רִבִּי אֶלְעָאי, בְּגִימַטְרִיָא יַבֹּ\"ק, בָּקִי בְּהִלְכְתָא.</p>\n<p>וְיֵקוּם עִמֵּיהּ רִבִּי יוּדָאי, דְּחוּשְׁבָּנֵיהּ אֵ\"ל. כְּגוֹן מִיכָאֵל, מַלְאֲכִין רְשִׁימִין בְּאֵל. כְּגוֹן (בראשית ל״א:כ״ט) יֵשׁ לְאֵל יָדִי. וְרָזָא דְּאֵל, א' דְּמוּת אָדָם. ל' תְּלַת חֵיוָן, דְּאִינּוּן ד' אַנְפִין לְכָל חַד, דִּרְמִיזִין (ס\"א בה) בְּה' בְּחוּשְׁבָן ל' תְּלַת יוֹדִין, (נ\"א עולים ל'). וְאִינּוּן בְּרָאשֵׁי תְּלַת אַזְכָּרוֹת, דְּאִינּוּן יְיָ מֶלֶךְ, יְיָ מָלַךְ, יְיָ יִמְלוֹךְ לְעוֹלָם וָעֶד. וְיֵקוּם רִבִּי אַבָּא עִמְּהוֹן, דְּאִיהוּ חוּשְׁבָּנֵיהּ ד', ד' חֵיוָן.</p>\n<p><Nonei></i>רִבִּי שִׁמְעוֹן אִיהוּ כְּאִילָנָא, וְרִבִּי אֶלְעָזָר בְּרֵיהּ וְחַבְרוֹי, דְּאִינּוּן חֲמִשָּׁה דְּאַדְכַּרְנָא, כַּעֲנָפִין דְּאִילָנָא רַבְרְבִין דְּדַמְיָין לִדְרוֹעִין וְשׁוֹקִין.</p>"],[9520012544,"<p>קוּם רַבִּי שִׁמְעוֹן, וְיִתְחַדְּשׁוּן מִלִּין מִפּוּמָךְ, בְּהַאי קְרָא דְּמִלְּקַדְּמִין. לַמְנַצֵּחַ, תַּמָּן נֶצַח, נִגוּן צַח. וּבֵיהּ אִתְקְרֵי יְדוָֹד מָארֵי נָצְחָן קְרָבִין, לְגַבֵּי אוּמִין עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת דְּעָלְמָא, וְרַחֲמִין וְדִינָא לְיִשְׂרָאֵל. וְרָזָא דְּמִלָּה, (משלי י״א:י׳) וּבַאֲבוֹד רְשָׁעִים רִנָּה. מ\"ל, שִׁבְעִין שְׁמָהָן אִית לֵיהּ, וְעִם נֶצַח וְהוֹד, ע\"ב, כְּחוּשְׁבַּן חֶסֶ\"ד, וְרָזָא דְּמִלָּה, (תהילים ט״ז:י״א) נְעִימוֹת בִּימִינְךָ נֶצַח.</p>\n<p>הוֹד, בֵּיהּ (דברי הימים א ט״ז:ח׳) הוֹדוּ לַיְיָ. צַדִּיק, בֵּיהּ (תהילים ל״ג:ב׳) רַנְּנוּ צַדִּיקִים בַּיְדוָֹד. וּבֵיהּ (ירמיהו ל״א:ז׳) רָנּוּ לְיַעֲקֹב שִׂמְחָה. תִּפְאֶרֶת, בֵּיהּ הַלְלוּ אֵל. הַלְלוּיָהּ, הַלְלוּ יָהּ. דְּתַמָּן יְדוָֹ\"ד. בְּנִגוּן וּבְזֶמֶר, חֶסֶד וּגְבוּרָה. בְּשִׁיר וּבִבְרָכָה, חָכְמָה וּבִינָה. בְּאַשְׁרֵי, כֶּתֶר. בִּתְהִלָּה, מַלְכוּת.</p>\n<p>מִזְמוֹר, בֵּיהּ רָ\"ז, וּבֵיהּ מוּ\"ם. מִסִּטְרָא דְּזֶמֶר דְּאוֹרַיְיתָא וְזֶמֶר דִּצְלוֹתָא. זֶמֶר מִסִּטְרָא אַחֲרָא, אִיהִי מוּ\"ם זָ\"ר. זִמְרָא בְּבֵיתָא, חָרְבָּא בְּבֵיתָא. נִדָּה שִׁפְחָה בַּת עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת זוֹנָה. וְדָא אַתְוָון מִזְמוֹ\"ר. נִגּוּ\"ן, תַּמָּן גַּ\"ן. הָכִי שְׁפִּירוּ דְּנִגוּנָא, בֵּיהּ הַלֵּל. כְּגוֹן (שמות י״ב:מ״ב) לֵיל שִׁמּוּרִים הוּא לַיְיָ לְהוֹצִיאָם מֵאֶרֶץ מִצְרָיִם. אַשְׁרֵי דְּבֵיהּ שָׁרֵי עָלְמָא מְשַׁבְּחִין, (תהילים קמ״ד:ט״ו) אַשְׁרֵי הָעָם שֶׁכָּכָה לּוֹ. בִּבְרָכָה, (תהילים ל״ד:ב׳) אֲבָרְכָה אֶת ה' בְּכָל עֵת. בַּתְּהִלָּה, תָּמִיד תְּהִלָּתוֹ בְּפִי.</p>\n<p>(תהילים ס׳:א׳) עַל שׁוּשַׁן עֵדוּת, דָּא הוֹד. דְּאִיהוּ שׁוּשַׁן, סוּמָק שַׁלִּיט עַל חִוָּור, דְּנֶצַח שַׁלִּיט אִיהוּ חִוָּור עַל סוּמָק. מַאי עֵדוּת. דָּא צַדִּיק. אִיהוּ בְּרִית, דְּאִיהוּ אָחִיד לִשְׁמַיָּא וְאַרְעָא. הֲדָא הוּא דִכְתִיב, (דברים ד׳:כ״ו) הֲעִידוֹתִי בָכֶם הַיּוֹם אֶת הַשָּׁמַיִם וְאֶת הָאָרֶץ. מַאי מִכְתָּם. מָ\"ךְ תָּ\"ם מָךְ, אִיהוּ צַדִּיק. תָּם, עַמּוּדָא דְּאֶמְצָעִיתָא, דַּרְגָּא דְּיַעֲקֹב. אִישׁ תָּם. גּוּף וּבְרִית חַשְׁבֵינָן חַד. לְלַמֵּד, חֶסֶד וּגְבוּרָה, דְּמִתַּמָּן אוֹרַיְיתָא אִתְיְהִיבַת, לִלְמוֹד וּלְלַמֵּד.</p>\n<p>אָמַר לֵיהּ שַׁפִּיר קָאַמָרְת, אֲבָל (תהילים י״ב:א׳) לַמְנַצֵּחַ עַל הַשְּׁמִינִית, דְּלָא תָּזוּז נֶצַח מִן הוֹד, דְּאִיהִי סְפִירָה ח', אָמַר לַמְנַצֵּחַ עַל הַשְּׁמִינִית. אָמַר בּוּצִינָא קַדִּישָׁא, אִי הָכִי, בִּינָה דַּרְגָּא דִּילָךְ, וַאֲמַאי אוֹקְמוּהָ וְנִתָּן הַהוֹד לְמֹשֶׁה, שֶׁנֶּאֱמַר (במדבר כ״ז:כ׳) וְנָתַתָּה מֵהוֹדְךָ עָלָיו.</p>\n<p>אָמַר לֵיהּ, שַׁפִּיר קָא שָׁאַלְתָּ. ה' סַלְּקָא בְּאָת י', חֲמֵשׁ זִמְנִין עֶשֶׂר, לְחַמְשִׁין תַּרְעִין דְּבִינָה, וְאִתְפַּשְּׁטוּתָא דִּלְהוֹן מֵחֶסֶד עַד הוֹד, הֵן חֲמֵשׁ עַשְׂרָה בְּכָל סְפִירָה, אִינּוּן חַמְשִׁין. וּבְגִין דָּא, מִבִּינָה עַד הוֹד, כֹּלָּא אִתְפַּשְּׁטוּתָא חֲדָא. לְבָתַר אָתָא צַדִּיק, וְנָטִיל כָּל חַמְשִׁין תַּרְעִין בִּלְחוֹדוֹי, לְמֶהֱוִי שָׁקִיל לְכָל חֲמֵשׁ, וְאִתְקְרֵי כָּל, דְּנָטִיל כָּל חַמְשִׁין תַּרְעִין. וְאוֹף הָכִי כַּלָּה, נְטִּילַת לְהוּ כֻּלְּהוּ. אָמַר, כְּעַן וַדַּאי אִתְיָישָׁב מִלָּה עַל בּוּרְיֵיהּ.</p>\n<p>וְעוֹד לַמְנַצֵּחַ, תַּמָּן מ\"ל עִם נֶצַח. וְדָא מ\"ל מִן חַשְׁמַ\"ל. מִן ח\"ש, הוֹד וְנֶצַח, אִינּוּן לָקֳבֵיל תְּרֵין שִׂפְוָון. וּבְגִין דָּא אִתְקְרִיאוּ שִׂפְוָון, חֵיוָן אֶשָּׁא מְמַלְּלָא. וּבַחֲגִיגָה עַד הֵיכָן מַעֲשֵׂה מֶרְכָּבָה, וְאוֹקְמוּהָ מִן וָאֵרֶא עַד חַשְׁמַל. דְּמִסְטְרָא דִּגְבוּרָה אִתְקְרִיאוּ חֵיוָן אֶשָּׁא. וְנָהָר דְּנָפִיק מִזֵּיעָן דִּלְהוֹן, יְסוֹד. כֻּלְּהוּ תְּלַת אִינּוּן מֶרְכָּבָה לְתִפְאֶרֶת, אָדָם.</p>\n<p>מַעֲשֵׂה מֶרְכָּבָה, דָּא מַלְכוּת. וּבִתְלַת אִלֵּין, אִיהוּ חָכְמָה וּבִינָה וָדַעַת. וּבְגִין דָּא אוּקְמוּהָ מָארֵי מַתְנִיתִין, דְּאֵין דּוֹרְשִׁין בְּמַעֲשֶׂה מֶרְכָּבָה בְּיָחִיד, אֶלָּא אִם כֵּן הוּא חָכָם וּמֵבִין מִדַּעְתּוֹ.</p>"],[9520012545,"<p>וְאִית מֶרְכָּבָה לְתַתָּא מִזְּעֵיר אַנְפִּין, דְּאִיהוּ מְטַ\"טְרוֹן. אָדָם הַקָּטָן. דְּבַמֶּרְכָּבָה דִּילֵיהּ דְּאִיהוּ פַּרְדֵּס, רְדִיפֵי מַיָּא דְּאוֹרַיְיתָא, דְּנָפִיק מִגּוֹ פַּרְדֵּס דִּילֵיהּ, לִתְלַת מֵאַרְבַּע, דְּאִתְּמַר עָלַיְיהוּ, אַרְבָּעָה נִכְנְסוּ לַפַּרְדֵס. וְהָא אִתְּמַר.</p>\n<p>דְּאִיהוּ צִפָּרָא דְּחָזָא רַבָּה בַּר בַּר חַנָּה, לְכֵיף יַמָּא דְּאוֹרַיְיתָא, דְּיַמָּא מָטֵי עַד קוֹרְסוּלוֹי. וְרֵישֵׁיהּ מָטֵי עַד צֵית שְׁמַיָא, וְלָא אַכְשִׁילוּ תְּלַת בֵּיהּ, מִשּׁוּם דִּנְפִישֵׁי מַיָּא דִּילֵיהּ, אֶלָּא מִשּׁוּם דִּרְדִּיפֵי מַיָּא וְאוֹקְמוּהָ.</p>\n<p>אבג כָּלִיל לוֹן דְּסַלְּקִין לְשִׁית, לָקֳבֵל אַתְוָון מְטַטְרוֹ\"ן. רְבִיעָאָה ד', (מלכים א י״ט:י״ב) קוֹל דְּמָמָה דַקָּה, דְּתַמָּן אָתֵי מַלְכָּא. וְאִיהוּ אָדָם לָשֶׁבֶת עַל הַכִּסֵּא.</p>\n<p>אי\"י, מַיִם עֶלְיוֹנִים, וּמַיִם תַּחְתּוֹנִים. דְּלֵית בֵּינַיְיהוּ אֶלָּא כִּמְלֹא נִימָא, דְּאִיהוּ ו', נָטוּי בֵּינַיְיהוּ, בָּרָקִיעַ דְּאִיהוּ מַבְדִּיל בֵּין מַיִם לָמַיִם, דִּיְהֵא הַבְדָּלָה בֵּין נוּקְבָּא לִדְכוּרָא. בְּגִין דָּא (בראשית א׳:ו׳) וִיהִי מַבְדִּיל וְרָזָא דְּמִלָּה, יאהדונהי. מַיִם עֶלְיוֹנִים זְכָרִים י' עִלָּאָה, מַיִם תַּחְתּוֹנִים נְקֵבוֹת, י' תַּתָּאָה. שִׁית אַתְוָון בֵּינַיְיהוּ, כְּחוּשְׁבַּן ו', דָּא מְטַטְרוֹן, דְּאִיהוּ בֵּין א.</p>\n<p>וְעוֹד, יוֹד נְקוּדָה. ו' גַּלְגַּל. וְלֵית תְּנוּעָה בְּגַּלְגַּל בְּשִׁית סִטְרִין כְּחוּשְׁבַּן ו', אֶלָּא בְּהַהִיא נְקוּדָה. וְהַהוּא נְקוּדָה אִיהוּ יִחוּדָא דְּכֹלָּא, וְאַסְהִידַת עַל הַהוּא יָחִיד, דְּלֵית לֵיהּ שֵׁנִי, דְּאוֹקְמוּהָ עָלֵיהּ רַבָּנָן, שֶׁצָרִיךְ לְיַחֲדוֹ כְּדֵי שֶׁתַּמְלִיכֵהוּ עַל <Nonei></i>הַשָּׁמַיִם וְעַל הָאָרֶץ, וְעַל ד' רוּחוֹת עָלְמָא. ב', שָׁמַיִם וָאָרֶץ. ג', עַמּוּדָא סָבִיל לוֹן. ד', אַרְבַּע חֵיוָן. ה' כֻּרְסְיָיא. ו', שִׁית דַּרְגִּין לְכֻרְסְיָיא. וְעוֹד, א ב ג ד ה ו ז ח ט: אָדָם. י' יִיחוּד דִּילֵיהּ, מַלְכוּת, עֲשִׁירָאָה דְּאָדָם. תֵּשַׁע, אִיהוּ לָקֳבֵל תֵּשַׁע אַתְוָון. זַכָּאִין אִינּוּן יִשְׂרָאֵל, דְּיַדְעִין רָזָא דְּמָארֵיהוֹן.</p>"],[9520012546,"<p>דָּבָר אַחֵר, צַו אֶת בְּנֵי יִשְׂרָאֵל וְאָמַרְתָּ אֲלֵיהֶם אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי רֵיחַ נִיחוֹחִי. רִבִּי יְהוּדָה אָמַר, בְּקָרְבָּנָא אִית עָשָׁן, וְאִית רֵיחַ, וְאִית רֵיחַ נִיחֹחַ, עָשָׁן אִיהוּ מִסִּטְרָא דְּדִינָא, הֲדָא הוּא דִכְתִיב, (דברים כ״ט:י״ט) כִּי אָז יֶעְשַׁן אַף יְיָ. (תהילים י״ח:ט׳) עָלָה עָשָׁן בְּאַפּוֹ וְאֵשׁ מִפִּיו תֹּאכֵל. רֵיחַ נִיחֹחִי, רַחֲמֵי. (שיר השירים נ) וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים.</p>\n<p>אָמַר רַעְיָא מְהֵימָנָא, וְהָא תַּרְוַויְיהוּ עָשָׁן וְרֵיחַ, אִינּוּן בְּאַף, וּקְרָאִין סַהֲדִין. חַד, עָלָה עָשָׁן בְּאַפּוֹ. וְתִנְיָינָא, וְרֵיחַ אַפֵּךְ כַּתַּפּוּחִים. וַאֲמַאי אִתְקְרֵי חַד עָשָׁן דִּינָא וְתִנְיָינָא רַחֲמֵי. אֶלָּא, בְּחוֹטָמָא אִית תְּרֵין חַלּוֹנִין, וְאִתְּמַר בִּשְׂמָאלָא, עָלָה עָשָׁן בְּאַפּוֹ, מַאי עָלָה. אֶלָּא מִלִבָּא דְּאִיהוּ בִּשְׂמָאלָא, לָקֳבֵל גִבּוֹר. מִימִינָא נָחִית רוּחָא לְגַבֵּיהּ, לְקַרְרָא לֵיהּ, וּלְשַׁכְּכָא רוּגְזֵיהּ, מִסִּטְרָא דְּחֶסֶד, דְּתַמָּן מוֹחָא. חָכְמָה לִימִינָא, הָרוֹצֶה לְהַחְכִּים יַדְרִים. בִּינָה בְּלִבָּא, כְּלַפֵּי שְׂמָאלָא, הָרוֹצֶה לְהַעֲשִׁיר יַצְפִּין. וּבְגִין דָּא עָלָה עָשָׁן בְּאַפּוֹ, מִן בִּינָה לְגַבֵּי חָכְמָה, דְּאִיהִי לִימִינָא, וּמְקַבֵּל לֵיהּ בְּחֶדְוָה, בְּנִגּוּנָא דְּלֵיוָאֵי.</p>\n<p>וְהַאי עָשָׁן לָא סָלִיק, אֶלָּא עַל יְדֵי אֵשׁ, דְּאַדְלִיק בְּעֵצִים, דְּאִינּוּן אֵבָרִים מַלְיָין פִּקוּדִין, עֲצֵי עוֹלָה. מָארֵי תּוֹרָה, אוֹרַיְיתָא דְּאִיהִי אַדְלִיקָת בְּהוֹן, אֵשׁ בְּתּוּקְפָא דִּגְבוּרָה, וְעָלָה עָשָׁן בְּהוֹן. בַּבִּינָה עָשָׁן הַמַעֲרָכָה.</p>\n<p>וּמִדִּסְלִיקַת לְאַף, אִתְקְרֵי קְטֹרֶת, הֲדָא הוּא דִכְתִיב, (דברים ל״ג:י׳) יָשִׂימוּ קְטוֹרָה בְּאַפֶּךָ. וְלֵית דְּבָטִיל מוֹתָנָא בְּעָלְמָא, כַּקְּטֹרֶת, דְּאִיהוּ קִשּׁוּרָא דְּדִינָא בְּרַחֲמֵי, עִם רֵיחַ נִיחוֹחַ בְּאַף. תַּרְגּוּם דְּקֶשֶׁר קְטִירוּ. אָמַר רִבִּי יְהוּדָה, זַכָּאָה חוּלָקָנָא דְּרַוַוחְנָא מִלִּין סְתִימִין בְּאִתְגַּלְיָיא. עוֹד אָמַר בּוּצִינָא קַדִּישָׁא, דְּבָתַר דִּצְלוֹתָא אִיהִי כְּקָרְבְּנָא, מַאן דְּיֵימָּא פִּטּוּם הַקְּטֹרֶת, בָּתַר תְּהִלָּה לְדָוִד, בָּטִיל מוֹתָנָא מִבֵּיתָא.</p>"],[9520012547,"<p>אָמַר רַעְיָא מְהֵימָנָא, כְּעַן בָּעֵי לְמִנְדַּע, אֵיךְ אַתְקִינוּ צְלוֹתִין לָקֳבֵל קָרְבְּנִין. אֶלָּא תְּלַת צְלוֹתִין, לָקֳבֵל אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר, דָּא צְלוֹתָא דְּשַׁחְרִית, דְּאִתְּמַר בָּהּ, (בראשית י״ט:כ״ז) וַיַּשְׁכֵּם אַבְרָהָם בַבֹּקֶר אֶל הַמָּקוֹם אֲשֶׁר עָמַד שָׁם אֶת פְּנֵי יְיָ. וְאוֹקְמוּהָ רַבָּנָן, דְּלֵית עֲמִידָה אֶלָּא צְלוֹתָא. וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם, לְקַבֵּל צְלוֹתָא דְּמִנְחָה, דְּתַקִּין לָהּ יִצְחָק. הֲדָא הוּא דִכְתִיב, (בראשית כ״ד:ס״ג) וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עֶרֶב. וְלֵית שִׂיחָה, אֶלָּא צְלוֹתָא. צְלוֹתָא דְּעַרְבִית, לָקֳבֵל אֱמוּרִין וּפְדָרִין דְּמִתְאַכְּלִין כָּל הַלַּיְלָה. הֲדָא הוּא דִכְתִיב, (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ. וְלֵית פְּגִיעָה, אֶלָּא צְלוֹתָא.</p>\n<p>אַדְּהָכִי דַּאֲנָן בַּאֲתָר דָּא, אֲמַאי כְּתִיב וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשׁוֹתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, וְכִי לָא הֲווֹ לֵיהּ כָּרִים וּכְסָתוֹת לְמִשְׁכַּב. אֶלָּא הוֹאִיל וְאָתָא חָתָן לְגַבֵּי כַּלָּה, אַף עַל גַּב דְּלָא הֲוָה אָרְחוֹי לְמִשְׁכַּב אֶלָּא בְּכָּרִים וּכְסָתוֹת, וְאִיהִי יְהִיבַת לֵיהּ אֲבָנִים לְמִשְׁכַּב, יְקַבֵּל כֹּלָּא בִּרְעוּתָא דְּלִבָּא, וְהָא אִתְּמַר. וְאוֹף הָכִי אִתְּמַר בְּחִבּוּרָא קַדְמָאָה. מַהוּ דִּכְתִּיב, (בראשית ל״ב:ג׳) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם, אָמַר רַבִּי שִׁמְעוֹן תִּיב. וְאֵימָא קְרָא, (ע\"כ רעיא מהימנא) (ככתוב דף רכ\"ה ע\"ב אלא פגיעה בר\"מ שם)</p>\n<p>אָמַר רִבִּי פִּנְחָס, מִסְתָּכַּל הֲוִינָא, שְׁמִירָה בַּלֵּב אִיהוּ וַדַּאי, (דחמא בלב) (ס\"א ולב דוגמא דלב עילאה) וְעַל דָּא שָׁמוֹר בַּלֵּב, וְלָאו בַּאֲתָר אַחֲרָא. זְכִירָה בַּזָּכָר, בְּמוֹחָא, דְּרָכִיב וְשָׁלִיט עַל הַלֵּב. וְלֵית זְכִירָה אֶלָּא בְּמוֹחָא. וְעַל דָּא זָכוֹר לְזָכָר וְשָׁמוֹר לִנְקֵבָה. מוֹחָא דְּאִיהוּ דְּכוּרָא, רָכִיב וְשָׁלִיט עַל הַלֵּב. לֵב שַׁלִּיט וְרָכִיב עַל הַכָּבֵד. כָּבֵד סָמָאֵל וְנָחָשׁ דָּא בְּדָא, וְאִיהוּ חַד. (ס\"א ואינון דכר ונוקבא) <Nonei></i>יוֹתֶרֶת הַכָּבֵד וְכָבֵד. וְעַל דָּא בְּקוֹרְבָּנָא, יוֹתֶרֶת הַכָּבֵד, דָּא נָחָשׁ. כָּבֵד מֵיכְלָא דִּדְכוּרָא, רָזָא דְּסָמָאֵ\"ל.</p>\n<p>אָמַר רַבִּי שִׁמְעוֹן, וַדַּאי כַּךְ הוּא, וְיָאוּת הוּא. וּבְרִירָא דְּמִלָּה, וְרָזָא וְסִתְרִין דְּקָרְבָּן, הָכִי הוּא. כָּבֵד נָטִיל בְּקַדְמִיתָא, הוּא וְיוֹתֶרֶת דִּילֵיהּ, (ס\"א ולבתר יותרת דיליה) סָמָאֵל וּבַת זוּגוֹ. (ס\"א ולבתר כל וכו' דאינון חיילין) וְכָל אִינּוּן עַרְקִין דְּכַבְדָא. חַיָּילִין וּמַשִׁרְיָין דִּלְהוֹן. וּנְטִילוּ דִּלְהוֹן, דְּאַכְלִין חֲלָבִין שַׁמְנִינוֹ דְּקָרְבְּנָא. הֲדָא הוּא דִכְתִיב, (שמות כט) וְאֶת הַחֵלֶב אֲשֶׁר עֲלֵיהֶם. וּכְדֵין קָרִיב כֹּלָּא לְגַבֵּי לֵב.</p>\n<p>וְלֵב לָא נָטִיל מִכֹּלָּא. אֶלָּא וִדּוּי דְּאִתְעָבִיד בֵּיהּ, וְסָלִיק בְּהַהוּא תְּנָנָא וּצְלוֹתָא דְּאִתְעָבִיד עָלֵיהּ דְּקָרְבְּנָא. לֵב קָרִיב לְגַבֵּי מוֹחָא, רְעוּתָא דְּיִחוּדָא דְּכַהֲנָא בֵּיהּ, וְחֶדְוָותָא דְּלֵיוָאֵי. מוֹחָא דָּא, נְהוֹרָא דְּאַתְיָא מִמּוֹחָא עִלָּאָה. מוֹחָא קָרִיב לְגַבֵּיהּ טָמִיר מִכֹּלָּא, דְּלָא אִתְיְדַע כְּלַל. (ס\"א לגביה, מכלל דלא אתפרע כלל) וְכֹלָּא אִתְקְשַׁר דָּא בְּדָא. וּמוֹחָא קָרִיב נַחַת רוּחַ דְּכֹלָּא.</p>\n<p>עַרְקִין דְּכַבְדָא, אִלֵּין אִישִׁים, וְכָל אִינּוּן חַיָּילֵיהוֹן. כָּבֵד, כְּמָה דְּאִתְּמַר. יוֹתֶרֶת נְקֵבָה, נוּקְבָּא דִּילֵיהּ. אֲמַאי יוֹתֶרֶת. דְּלָא אִתְחַבְּרַת בִּדְכוּרָא אֶלָּא כַּד אַשְׁאָרַת לָהּ שַׁעֲתָא, לְבָתַר דְּעַבְדַּת נְאוּפָהָא, וְשַׁבְקָא לֵיהּ. תּוּ, יוֹתֶרֶת נְקֵבָה, דְּכַד בַּעְיָא לְאִתְחַבְּרָא בְּבַּר נָשׁ, אִתְעָבִידַת לְגַבֵּיהּ שִׁיּוּרִין, דְּלָא אִתְחֲשָּׁבַת כְּלַל. לְבָתַר אִיהִי אִתְקָרְבַת זְעֵיר זְעֵיר לְגַבֵּיהּ, עַד דְּאִתְעַבֵידָא לֵיהּ חִבּוּרָא חֲדָא. וּמֵאִלֵּין עַרְקִין דְּכַבְדָא, מִתְפַּשְּׁטָן אָחֳרָן זְעִירִין, לְכַמָּה זַיְינִין, וְכֹלָּא נַטְלִין אֵמוּרִין וּפְדָרִין. וְכֻלְּהוּ כְּלִילָן בַּכָּבֵד.</p>\n<p>לֵב דְּאִיהוּ עִקָּרָא בִּקְדוּשָּׁה, נָטִיל וּמַקְרִיב לְמוֹחָא כְּמָה דְּאִתְּמַר. לֵב שַׁרְיָא עַל תְּרֵין כּוּלְּיָין, וְאִינּוּן תְּרֵין כְּרוּבִין. יָהֲבִין עֵיטָא. וְאִינּוּן רְחִיקִין קְרִיבִין, יְמִינָא וּשְׂמָאלָא. וְכֻלְּהוּ נַטְלִין וְאָכְלִין כָּל חַד כַּדְּקָא יָאוּת, עַד דְּאִתְקְשַׁר כֹּלָּא כַּחֲדָא.</p>\n<p>(תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה, דָּא מִתְקָרִיב לַלֵב, רוּחַ נִשְׁבָּרָה, וִדּוּי וּצְלוֹתָא. דְּהָא וַדַּאי (קהלת י״ב:ז׳) וְהָרוּחַ תָּשׁוּב אֶל <Nonei></i>הָאֱלֹהִים אֲשֶׁר נְתָנָהּ. וְכָבֵד מַקְרִיב לֵיהּ לְגַבֵּיהּ לֵב, דְּאִיהוּ סַנֵּיגוֹרָא עָלֵיהּ, וְכֹלָּא קִשּׁוּרָא כַּחֲדָא בְּקוּרְבְּנָא.</p>\n<p>מִן כָּבֵד, נָפְקִין כָּל מַרְעִין, וְכָל מַכְתְּשִׁין, לְכָל שַׁיְיפֵי גּוּפָא, וּבֵיהּ שַׁרְיָין. לֵב, אִיהוּ זָכִיךְ מִכֹּלָּא. מִנֵּיהּ נָפְקִין כָּל טַב, וְכָל בְּרִיאוּתָא דְּשַׁיְיפִין כֻּלְּהוּ, וְכָל תּוּקְפָּא, וְכָל חֶדְוָה, וְכָל שְׁלִימוּ דְּאִצְטְרִיךְ לְכָל שַׁיְיפִין.</p>"],[9520012548,"<p><Nonei></i><Noneb>רעיא מהימנא</b> אָמַר רַעְיָא מְהֵימָנָא, לֵית קָרְבְּנִין, אֶלָּא לְרַחֲקָא סִטְרִין מִסְאֲבִין, וּלְקָרְבָא דַּרְגִּין קַדִּישִׁין. וְאִתְּמַר בְּחִבּוּרָא קַדְמָאָה, דִּלְהוֹן, (ערקין דכבדא, אלין אישים וכל אינון חיילין ואתמר) עַרְקִין דְּכַבְדָא אִית מִנְּהוֹן רַבְרְבִין, אִית מִנְּהוֹן רַבְרְבִין וּזְעִירִין, וּמִתְפַּשְׁטִין מִנְּהוֹן לְכַמָּה סִטְרִין. וְאִלֵּין נַטְלִין אֵבָרִין וְאֱמוּרִין וּפְדָרִין דְּמִתְאַכְּלִין כָּל הַלַּיְלָה, דְּהָא קָרְבָּן כֹּלָּא לַיְיָ.</p>\n<p>אָמַר בּוּצִּינָא קַדִּישָׁא, רַעְיָא מְהֵימָנָא, וַהֲלֹא אַמְרַת לְעֵיל דְּקָרְבְּנִין דְקוּדְשָׁא בְּרִיךְ הוּא לָאו אִינּוּן אֶלָּא לְקָרְבָא י' בְּה' ו' בְּה'. אֶלָּא, אַף עַל גַּב <Nonei></i>דְּכָל קָרְבָּנִין צְּרִיכִין לְקָרֵב קַמֵּיהּ, אִיהוּ פָּלִיג לְכָל מַשִּׁרְיָין, מַאֲכָלִין דְּקָרְבְּנִין, לְכָל חַד כַּדְקָא חֲזֵי לֵיהּ, לְשִׂכְלִיִּים, מְזוֹנֵי דְּאוֹרַיְיתָא, וּמִשְׁתְּיָיא דְּיִינָא וּמַיָּא דְּאוֹרַיְיתָא. לְטִבְעִיִּים, דְּאִינּוּן שֵׁדִים דְּאִינּוּן כִּבְנֵי אָדָם, יָהִיב לוֹן אִלֵּין מַאֲכָלִין טִבְעִיִּים, דְּנָחִית אֶשָּׁא דִּלְהוֹן, לְמֵיכַל לוֹן.</p>\n<p>כְּמָה דְּאוֹקְמוּהָ רַבָּנָן, אִי זָכוּ, הֲוָה נָחִית כְּמוֹ אַרְיֵה דְּאֶשָּׁא לְמֵיכַל קָרְבְּנִין. וְאִי לָא, הֲוָה נָחִית תַּמָּן כְּמִין כַּלְבָּא דְּאֶשָּׁא. וְאוֹף הָכִי כַּד מִית בַּר נָשׁ, אִי זָכֵי, נָחִית בִּדְמוּת אַרְיֵה, לְקַבְּלָא נַפְשֵׁיהּ. וְאִי לָאו בִּדְמוּת כֶּלֶב, דְּאָמַר דָּוִד עָלֵיהּ, (תהילים כ״ב:כ״א) הַצִּילָה מֵחֶרֶב נַפְשִׁי מִיַּד כֶּלֶב יְחִידָתִי.</p>\n<p>וּבְגִין לְשֵׁיזָבָא קוּדְשָׁא בְּרִיךְ הוּא גּוּפֵיהוֹן דְּיִשְׂרָאֵל מִנְּהוֹן וְנַפְשֵׁהוֹן. מָנֵי, לְקָרֵב קָרְבְּנִין דִּבְעִירָן וְגוּפָן בְּאַתְרַיְיהוּ, לְקַיֵּים (משלי כ״ה:כ״א) אִם רָעֵב שׂוֹנַאֲךָ הַאֲכִילֵהוּ לָחֶם וְאִם צָּמֵא הַשְׁקֵהוּ מָיִם. אֲבָל קוּדְשָׁא בְּרִיךְ הוּא, לָא נָטִיל אֶלָּא רְעוּתָא דְּלִבָּא, וּתְבִירוּ דִּילֵיהּ (דאיהו ישראל). הֲדָא הוּא דִכְתִיב, (תהילים נ״א:י״ט) זִבְחֵי אֱלֹהִים רוּחַ נִשְׁבָּרָה לֵב נִשְׁבָּר וְנִדְכֶּה אֱלֹהִים לֹא תִבְזֶה. כְּגַוְונָא דִּכְלֵי חֶרֶס, דְּאִתְּמַר בְּהוֹן נִשְׁבָּרוּ נִטְהָרוּ.</p>\n<p>כַּהֲנָא מוֹחָא. לֵוִי לִבָּא. גּוּפָא יִשְׂרָאֵל. וְאִתְּמַר בְּהוֹן, כֹּהֲנִים בַּעֲבוֹדָתָם, וּלְוִּיִם בְּדוּכָנָם, וְיִשְׂרָאֵל בְּמַעֲמָדָם. וְאִי כָּבֵד בָּעֵי לְקָרְבָא לְגַבֵּי דְּלִבָּא, חֶלְבֵּיהּ דְּאִינּוּן מִסְאֲבִין, אִיהוּ לָא נָטִיל. אֶלָּא שַׁמְנוּנוֹ דְּחֵלֶב טָהוֹר. כְּגַוְונָא דְּאִית בְּגוּפָא, חֵלֶב טָהוֹר וְחֵלֶב טָמֵא, דָּם צָּלִיל בְּלָא פְּסוֹלֶת, וְדָם עָכוּר בַּפְּסוֹלֶת. וְעַרְקִין דְּלִבָּא, חַיָּילִין קַדִּישִׁין. וְעַרְקִין דְּכָבֵד, חַיָּילִין מִסְאֲבִין. אוּף הָכִי אִינּוּן מַשִׁרְיָין דְּיֵצֶּר הָרָע, וּמַשִׁרְיָין דְּיִצֶּר הַטוֹב, אִלֵּין מְמָנָן עַל עַרְקִין דְּלִבָּא, וְאִלֵּין מְמָנָן עַל עַרְקִין דְּכַבְדָא. אוּף הָכִי תְּרֵי אוֹמֵי, יִשְׂרָאֵל, וְאוּמִין דְּעָלְמָא עוֹבְדֵי כּוֹכָבִים וּמַזָּלוֹת.</p>\n<p>אָמַר לֵיהּ רַעְיָא מְהֵימָנָא, שַׁפִּיר קָא אַמְרַת בְּכֹלָּא, אֲבָל אֲפִילּוּ יִשְׂרָאֵל לָאו כֻּלְּהוּ שָׁוִין, דְּאִית בְּהוֹן בְּנֵי מַלְכוּת, מִסִּטְרָא דְּמַלְכוּת קַדִּישָׁא, כְּלִילָא מֵעֶשֶׂר סְפִירָאן, וּמִכָּל הֲוָויָּין וְכִנּוּיִין. וְאִית מִנְּהוֹן עַבְדִּין, מִסִּטְרָא דְּעֶבֶד, דְּאִיהוּ (בראשית כ״ד:ב׳) עַבְדּוֹ זְקַן בֵּיתוֹ. וְאִית מִנְּהוֹן כִּבְעִירָן, וְאִתְּמַר בְּהוֹן, (יחזקאל ל״ד:ל״א) וְאַתֵּן צֹּאנִי צֹּאן מַרְעִיתִי אָדָם אַתֶּם. וְאִינּוּן דְּדַמְיָין לְעָנָא, קוּדְשָׁא בְּרִיךְ הוּא מָנֵי לְקָרְבָא בְּעִירָן בְּאַתְרַיְיהוּ, לְכַפְּרָא עָלַיְיהוּ. וְאִינּוּן דְּדַמְיָין לְמַלְאָכִין, קָרְבְּנִין דִּלְהוֹן אִינּוּן עוֹבָדִין טָבִין, דִּמְמָנָן עָלַיְיהוּ מַלְאָכִים, דִּמַקְרִיבִין לְּקוּדְשָׁא בְּרִיךְ הוּא בְּאַתְרַיְיהוּ.</p>\n<p>וְאִינּוּן דַּהֲווֹ בְּנִין <Nonei></i>לַיְדוָֹד, הֲדָא הוּא דִכְתִיב, (דברים י״ד:א׳) בָּנִים אַתֶּם לַיְיָ אֱלֹהֵיכֶם. בְּחוֹבִין דִּלְהוֹן מִתְפָּרְדֵי אַתְוָון, וְתִקּוּנָא (ס\"א דלהון הוא אורייתא), הוּא דְּלֶהֱוִי אוֹרַיְיתָא דְּאִיהוּ שֵׁם יְדוָֹד, לְקָרְבָא אַתְוָון, י' בְּה', ו' בְּה', בְּקָרְבְּנָא דִּלְהוֹן.</p>\n<p>הֲרֵי בְּכָל קָרְבְּנִין, בֵּין דִּבְעִירֵי, בֵּין דְּמַלְאָכִין דִּמְמָנָן עַל פִּקוּדִין, בֵּין בְּמַלְכוּתָא, בֵּין בִּשְׁמֵיהּ. כֹּלָּא צָּרִיךְ לְקָרְבָא לְקוּדְשָׁא בְּרִיךְ הוּא (דאורייתא דיליה) בְּאַתְוָון קַדִּישִׁין. וְאִיהוּ רָכִיב בְּאַרְבַּע חֵיוָן דְּמַלְאָכִים. וְאִיהוּ רָכִיב בְּאַרְבַּע יְסוֹדִין, דְּמִנְּהוֹן אִתְבְּרִיאוּ אַרְבַּע חֵיוָן טִבְעִיִּים. וְאִיהוּ הוּא דִּמְקָרֵב מַיָּא בְּאֶשָּׁא, וְרוּחָא בְּעַפְרָא. הֲדָא הוּא דִכְתִיב, (איוב כ״ה:ב׳) עוֹשֶׂה שָׁלוֹם בִּמְרוֹמָיו. וְאוֹף הָכִי הוּא מְקָרֵב מִיכָאֵל דְּאִיהוּ מַיִם שִׂכְלִיִּים, עִם גַּבְרִיאֵל. דְּהוּא אֵשׁ שִׂכְלִי. וְאִיהוּ מְקָרֵב אוּרִיאֵל, דְּאִיהוּ אַוִּיר. דְּהַיְינוּ רוּחַ שִׂכְלִי. עִם רְפָאֵל, דְּאִיהוּ אֵפֶר, דְּהַיְינוּ עָפָר שִׂכְלִית. דְּמִיָּד דְּאִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא מִבֵּינַיְיהוּ, לֵית בְּהוֹן חֵילָא.</p>\n<p>וְאִי תֵּימָא, הָא כְּתִיב בְּכָל קָרְבְּנִין לַיְדוָֹ\"ד, וְאֵיךְ אָמַרְנָא דְּאִית פִּרוּדָא בְּאַתְוָון. אֶלָּא הַאי אִתְּמַר, בְּדַרְגִּין דְּאִתְבְּרִיאוּ וְאִתְקְרִיאוּ בִּשְׁמֵיהּ. וְלָא דְּאִינּוּן אִיהוּ מַמָּשׁ. הֲדָא הוּא דִכְתִיב, (ישעיהו מ״ג:ז׳) כֹּל הַנִקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַּרְתִּיו אַף עֲשִׂיתִיו. דְּאִית אַתְוָון דַּיְדוָֹ\"ד בַּאֲצִּילוּת, דְּלֵית בְּהוֹן פִּרוּדָא וְהַפְסָקָה, דְּאִינּוּן כְּמַבּוּעִין לְגַבַּיְיהוּ, דְּאַשְׁקְיָּין לְאִילָנִין. וּבְגִין אִלֵּין דְּאִתְבְּרִיאוּ, אִדָמְיָין י' לְרֵישָׁא, ו' לְגוּפָא, ה' ה' לְעֶשֶׂר אֶצְּבְּעָן.</p>\n<p>אֲבָל עִלּוֹת הָעִלּוֹת עַל כֹּלָּא, דְּאִתְקְרֵי יְדוָֹ\"ד, אִתְּמַר בֵּיהּ, (ישעיהו מ׳:כ״ה) וְאֶל מִי תְּדַמְּיוּנִי וְאֶשְׁוְה יֹאמַר קָדוֹשׁ. (ישעיהו מ׳:י״ח) וְאֶל מִי תְּדַמְּיוּן אֵל וּמַה דְּמוּת תַּעַרְכוּ לוֹ. (מלאכי ג׳:ו׳) אֲנִי יְיָ לֹא שָׁנִיתִי. לָא מָטֵי בֵּיהּ חוֹבִין לְאַפְרְשָׁא אַתְווֹי, י' מֵה', ו' מֵה', דְּלֵית בֵּיהּ פִּרוּדָא. וְעָלֵיהּ אִתְּמַר, (תהילים ה׳:ה׳) לֹא יְגוּרְךָ רָע. אִיהוּ שַׁלִּיט עַל כֹּלָּא, וְלֵית מַאן דְּשָׁלִיט בֵּיהּ. אִיהוּ תָּפִיס בְּכֹלָּא, וְלֵית מַאן דְּתָפִיס בֵּיהּ. וְאִיהוּ לָא אִתְקְרֵי יְדוָֹ\"ד, וּבְכָל שְׁמָהָן, אֶלָּא בְּאִתְפַּשְּׁטוּת נְהוֹרֵיהּ עָלַיְיהוּ. וְכַד אִסְתְּלִיק מִנַּיְיהוּ, לֵית לֵיהּ מִגַּרְמֵיהּ שֵׁם כְּלָל מִנְּהוֹן. (קהלת ז׳:כ״ד) עָמוֹק עָמוֹק מִי יִמְצָּאֶנּוּ.</p>\n<p>לֵית נְהוֹרָא יָכִיל לְאִסְתַּכְּלָא בֵּיהּ, דְּלָא אִתְחַשְּׁכַת. אֲפִילּוּ כֶּתֶר עֶלְיוֹן, דְּאִיהוּ נְהוֹרֵיהּ תַּקִּיף עַל כָּל דַּרְגִּין, וְעַל כָּל חֵילֵי שְׁמַיָא, עִלָּאִין וְתַתָּאִין, אִתְּמַר עָלֵיהּ, (תהילים י״ח:י״ב) יָשֶׁת חֹשֶׁךְ סִתְרוֹ. וְעַל חָכְמָה וּבִינָה, (תהילים צ״ז:ב׳) עָנָן וַעֲרָפֶל סְבִיבָיו. כָּל שֶׁכֵּן שְׁאַר סְפִירָאן. כָּל שֶׁכֵּן חֵיוָן. כָּל שֶׁכֵּן יְסוֹדִין, דְּאִינּוּן מֵתִים. אִיהוּ סוֹבֵב עַל כָּל עָלְמִין, וְלֵית סוֹבֵב לוֹן לְכָל סִטְרָא, עֵילָּא וְתַתָּא, וּלְאַרְבַּע סִטְרִין, בַּר מִנֵיהּ. וְלֵית מַאן דְּנָפִיק מֵרְשׁוּתֵיהּ לְבַר. אִיהוּ מְמַלֵא כָּל עָלְמִין. וְלֵית (ס\"א אלהא וכו' לון בר מיניה) אוֹחֲרָא מְמַלֵא לוֹן.</p>\n<p>אִיהוּ מְחַיֶּה לוֹן וְלֵית עָלֵיהּ אֱלָהָא אַחֲרָא, לְמֵיהַב לֵיהּ חַיִּין. הֲדָא הוּא דִכְתִיב, (נחמיה ט׳:ו׳) וְאַתָּה מְחַיְּה אֶת כּוּלָם. וּבְגִינֵיהּ אָמֹר דָּנִיאֵל, (דניאל ד׳:ל״ב) וְכָל דְּאָרֵי אַרְעָא כְּלָּא חֲשִׁיבִין וּכְמִצְּבְּיֵיהּ עָבִיד בְּחֵיל שְׁמַיָא. אִיהוּ מְקַשֵּׁר וּמְיַחֵד זִינָא לְזִינֵיהּ, עֵילָּא וְתַתָּא. וְלֵית קוּרְבָא לְהוּ בְּד' יְסוֹדִין, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא כַּד אִיהוּ בֵּינַיְיהוּ.</p>\n<p>מִיַּד דְּחָבוּ, אִלֵּין דְּאִתְקְרִיאוּ בָּנִים אַתֶּם לַיְדוָֹד אֱלֹקֵיכֶם, אִסְתְּלַּק מִן אַתְוָון, אִשְׁתְּאָרוּ בְּפֵרוּדָא. וּמַאי תִּקּוּנֵיהּ, לְקָרְבָא אַתְוָון בְּקוּדְשָׁא בְּרִיךְ הוּא, י' בְּה', ו' בְּה'. אוּף הָכִי אִינּוּן עַבְדִּין דִּילֵיהּ, מִסִּטְרָא דְּחֵיוָן. בְּחוֹבִין דִּלְהוֹן גָּרְמוּ לֵיהּ, לְאִסְתַּלְּקָא מִנְּהוֹן. מַאי תָּקַנְתָּא דִּלְהוֹן. לְנַחְתָּא קוּדְשָׁא בְּרִיךְ הוּא עָלַיְיהוּ, לְקָרְבָא לוֹן. אוּף הָכִי אִינּוּן דַּהֲווֹ מֵאַרְבַּע יְסוֹדִין, דְּאִינּוּן עָאנָא דְקוּדְשָׁא בְּרִיךְ הוּא, דְּגַרְמוּ לְסַלְּקָא קוּדְשָׁא בְּרִיךְ הוּא מִינַּיְיהוּ. מַאי תַּקְנָה. לְקָרְבָא לוֹן לְּקוּדְשָׁא בְּרִיךְ הוּא.</p>\n<p>וּבְגִין דָּא בְּכֻלְּהוּ מָנֵי, קָרְבָּן לַיְדוָֹד, אֶת קָרְבָּנִי לַחְמִי לְאִשַּׁי. אוּף אֶת הַכֶּבֶשׂ אֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֶת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. וּכְתִיב (ולקחת) (ויקרא ה׳:ז׳) שְׁתֵּי תוֹרִים אוֹ שְׁנֵי בְנֵי יוֹנָה, כָּל זִינָא אָזִיל לְזִינֵיהּ. וְקוּדְשָׁא בְּרִיךְ הוּא מְקָרֵב כֹּלָּא בַּאֲתָר דָּא, אִיהוּ עִלַּת עַל כֹּלָּא, דְּלֵית אֱלָהָא בַּר מִנֵּיהּ. וְלֵית מַאן דְּיָכִיל לְקָרְבָא חֵילִין, בַּר מִנֵּיהּ.</p>\n<p>אֲבָל חֵילִין דְּאוּמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת, אִינּוּן מִסִּטְרָא דְּפֵרוּדָא. וַוי לְמַאן דְּגָרִים בְּחוֹבוֹי, לְאַעֲלָא אַתְוָון וְחֵיוָן וִיסוֹדִין. דְּמִיָּד אִסְתַּלָּק קוּדְשָׁא בְּרִיךְ הוּא מִיִשְׂרָאֵל. וְיִיעָלוּן אוּמִין עוֹבְדֵי עֲבוֹדַת כּוֹכָבִים וּמַזָּלוֹת בֵּינַיְיהוּ. לֵית לוֹן קְרִיבוּת בְּקוּדְשָׁא בְּרִיךְ הוּא, דְּלֵית קוֹרְבְּנִין בְּחוּצָּה לָאָרֶץ. וּבְגִין דָּא אוּקְמוּהָ רַבָּנָן, הַדָּר בְּחוּצָּה לָאָרֶץ דּוֹמֶה כְּמִי שֶׁאֵין לוֹ אֱלוֹהַּ. בְּהַהוּא זִמְנָא דְּאָמַר מִלִּין אִלֵּין, נַחְתּוּ כָּל אַתְוָון קַדִּישִׁין, וְחֵיוָן קַדִּישִׁין, וְד' יְסוֹדִין, לְגַבֵּיהּ, וּבָרִיכוּ לֵיהּ וְאָמְרוּ, עַל יְדָךְ רַעְיָא מְהֵימָנָא, נָחִית עֲלָן קוּדְשָׁא בְּרִיךְ הוּא, וּמִתְקָרְבִין זִינָא <Nonei></i>לְזִינֵיהּ, בְּרִיךְ אַנְתְּ לְּקוּדְשָׁא בְּרִיךְ הוּא, בְּאַרְבַּע יְסוֹדִין. כְּעַן אִתְבְּרִיר כֹּלָּא עַל בּוּרְיֵיהּ. (ע\"כ רעיא מהימנא) (ובחבורא קדמאה קיבה רל\"ד ע\"ב)</p>"],[9520012549,"<p>פָּתַח וְאָמַר, (תהלים לא) בְּטַח בַּיְיָ וַעֲשֵׂה טוֹב שְׁכָן אֶרֶץ וּרְעֵה אֱמוּנָה. בְּטַח בַּיְיָ, כַּדְּקָא יָאוּת. וַעֲשֵׂה טוֹב, תִּקּוּנָא דִּבְרִית קַדִּישָׁא. דִּתְּהֵא מְתַקֵּן לֵיהּ, וְנָטִיר לֵיהּ כַּדְּקָא יָאוּת. וְאִי תַּעֲבִיד דָּא, אַנְתְּ תְּהֵא הָכָא בְּאַרְעָא, וְיִתְּזָן מִנָךְ, וְיִתְפַּרְנֵס מִנָךְ, הַהִיא אֱמוּנָה דִּלְעֵילָּא.</p>\n<p>וְתוּ, (ס\"א מתקן ליה ונטיר ליה. שכן ארץ ארץ קדישא עילאה ארץ החיים דההיא ארץ תשרי בההוא טוב. ורעה אמונה ההיא אמונה דלעילא יתזן ויתפרנס מניה על ידך. ואי תעביד דא) תִּתְעַנַּג עַל יְיָ וְיִתֵּן לְךָ מִשְׁאֲלוֹת לִבֶּךָ. כָּל דָּא אִתְתְּקָנַת בְּתִקּוּנָא דִּבְרִית. כֵּיוָן דְּאִתַּקָנַת בְּרִית, אִתְּקַן כֹּלָּא. פִּנְחָס בְּגִין דְּקַנֵּי עַל בְּרִית דָּא, זָכָה לְכֹלָּא. וְלֹא עוֹד אֶלָּא דְּאָגִין עַל כָּל יִשְׂרָאֵל, וּבֵיהּ אִתְקַיָּים וְהִתְעַנַּג עַל יְיָ. דְּהָא סָלִיק וְאִתְקְשַׁר לְעֵילָּא, (ואנהיר) בְּאוֹר קַדְמָאָה דְּבָרָא קוּדְשָׁא בְּרִיךְ הוּא, וְגָנִיז לֵיהּ. בְּהַהוּא אוֹר דְּאִתְהֲנֵי אַבְרָהָם מִנֵּיהּ, וְאַהֲרֹן כַּהֲנָא אִתְקְשַׁר בֵּיהּ.</p>\n<p>לְבָתַר דְּאִסְתַּלָּק לְכַהֲנָא רַבָּא, לָא אַדְכַּר לֵיהּ קַטְלָנוּתָא דְּזִמְרִי, וְלָא יָאוּת בְּגִין דְּלָא יִתְאֲחָד כְּלַל בְּעַנְפּוֹי דְּסִטְרָא אַחֲרָא, וְלָא אִתְחֲזֵי לְאַדְכְּרָא עָלֵיהּ. דְּכָל מַאן דְּקָטִיל, עַנְפִין דְּסִטְרָא אָחֳרָא אִית בֵּיהּ. וּפִנְחָס הָא מִתְאֲחִיד בִּימִינָא, וְלֵית לֵיהּ חוּלָק בְּסִטְרָא אָחֳרָא כְּלָל, וְעַל דָּא לָא אַדְכַּר הָכָא. מַה דְּאִתְחֲזֵי שְׁבָחָא, אִיהוּ גְּנַאי לֵיהּ, וּנְחִיתוּ מִדַּרְגָּא עִלָּאָה דְּאִתְאֲחִיד בֵּיהּ. וְעַל דָּא כְּתִיב הַמּוּכֶּה אֲשֶׁר הוּכָּה סְתָם, וְשֵׁם הָאִשָׁה הַמּוּכָּה, וְלָא אַדְכַּר עַל יְדָא דְּמַאן.</p>\n<p>אָמַר רִבִּי פִּנְחָס, זַכָּאָה דָּרָא דְּשַׁמְעִין מִילָךְ בְּאוֹרַיְיתָא, וְזַכָּאָה חוּלָקִי דְּזָכֵינָא לְכַךְ. אָמַר רִבִּי שִׁמְעוֹן, זַכָּאָה דָּרָא, דְּאַנְתְּ וַחֲסִידוּתָךְ אִשְׁתְּכַח בְּגַוִּויהּ. עַד דַּהֲווֹ יַתְבִין וּמְפַיְיסִין דָּא לְדָא, אָתָא רִבִּי אֶלְעָזָר בְּרֵיהּ דְּרַבִּי שִׁמְעוֹן, וְאַשְׁכַּח לוֹן תַּמָּן. אָמַר רִבִּי פִּנְחָס, וַדַּאי דִּכְתִּיב, (בראשית ל״ב:ג׳) וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֶה אֱלֹהִים זֶה. אָמַר לֵיהּ רַבִּי שִׁמְעוֹן, אֶלְעָזָר בְּרִי, תִּיב בְּרִי, וְאֵימָא קְרָא. יָתִיב רִבִּי אֶלְעָזָר.</p>"],[9520012550,"<p>פָּתַח וְאָמַר, (בראשית ל״ב:ב׳) וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְעוּ בוֹ מַלְאֲכֵי אֱלֹהִים. מַאי וַיִּפְגְּעוּ בּוֹ. אֶלָּא אִית פְּגִיעָה לְטָב. וְאִית פְּגִיעָה לְבִישׁ. וְאִית פְּגִיעָה לִצְלוֹתָא. אֶלָּא בְּשַׁעֲתָא דְּהֲוָה אָזִיל לְחָרָן, מַה כְּתִיב. (בראשית כ״ח:י״א) וַיִּפְגַּע בַּמָּקוֹם, צְלוֹתָא דְּעַרְבִית הֲוָה דְּצַלֵּי בְּהַהוּא מָקוֹם. כְּמָה דְאַתְּ אָמֵר, (שמות ל״ג:כ״א) הִנֵּה מָקוֹם אִתִּי. וּצְלוֹתָא דְּעַרְבִית בְּהַהוּא אֲתָר אִתְחֲזֵי.</p>\n<p>תּוּ וַיִּפְגַּע בַּמָּקוֹם, מִלֵּי פִּיּוּסִין אִיהוּ. דְּאָתָא שִׁמְשָׁא קַדִּישָׁא לְגַבֵּי סִיהֲרָא, בַּעְלָהּ לְגַבֵּי אִתְּתָא. מִכָּאן דְּלָא יֵאוֹת לַבַּעַל לְמֵיתֵי לְגַבֵּי אִתְּתָא, אִי לָא הֲוִי בְּמִלֵּי פִּיּוּסִין לְפַיְּיסָא לָהּ. דִּכְתִּיב וַיִּפְגַּע בַּמָּקוֹם, וּלְבָתַר וַיָּלֶן שָׁם. כַּד הֲוָה אָתֵי יַעֲקֹב מֵחָרָן, מַה כְּתִיב, וַיִּפְגְּעוּ בוֹ, שַׁדְרַת הִיא לְפַיְּיסָא לֵיהּ, לְמֵיתֵי לְגַבָּהּ.</p>\n<p>וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם. מַאי כַּאֲשֶׁר רָאָם. אִלֵּין מַלְאָכִין דְּיוֹם, וּמַלְאָכִין דְּלַיְלָה הֲווֹ, וְאִתְכְּסִיאוּ מִנֵּיהּ, וּלְבָתַר אִתְגַּלְּיָין לֵיהּ. וְעַל דָּא כַּאֲשֶׁר רָאָם, כְּתִיב מַחֲנֶה אֱלֹהִים זֶה. מֵהָכָא דַּהֲווֹ אִלֵּין דִּימָמָא, וְאִלֵּין דְּלֵילְיָא. אִינּוּן דְּלֵילְיָא כְּתִיב בְּהוּ, <Nonei></i>מַחֲנֶה אֱלֹהִים, וְאִינּוּן דִּימָמָא, כְּתִיב בְּהוּ, זֶה. וְעַל דָּא וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. תְּרֵין מַשִׁרְיָין. וְהַשְּׁתָּא מַשִׁרְיָין קַדִּישִׁין חֲמֵינָא הָכָא. זַכָּאָה אָרְחִי דַּאֲתֵינָא הָכָא.</p>"],[9520012551,"<p><Nonei></i><Noneb>רעיא מהימנא</b> אֶלָּא פְּגִיעָה אִיהִי פִּיּוּסָא, דְּכַד יִיתֵי חָתָן לְגַבֵּי כַּלָּה, לֵית אֹרַח לְחָתָן לְיַיחֲדָא בְּכַלָּה, אֶלָּא בְּפִיּוּסָא. וּלְבָתַר יַעְבֵּד עִמָּהּ לִינָה. וְהַיְינוּ (ד\"א וילן שם) כִּי בָא הַשֶּׁמֶשׁ.</p>\n<p>אָמַר רַעְיָא מְהֵימָנָא, אִי הָכִי מַאי נִיהוּ כִּי בָא הַשֶּׁמֶשׁ דְּהָא אֹרַח דְּרָשָׁא אוּקְמוּהָ, לְשׁוֹן כְּבִיָּיה, וְהַיְינוּ כִּי בָא הַשֶּׁמֶשׁ. אֶלָּא מֵהָכָא אוֹלִיפְנָא, מַאן דִּמְיַיחֵד בְּאִתְּתֵיהּ, צָּרִיךְ בְּלֵילְיָא לְמִכְבֵּי שְׁרָגָא, וּבִימָמָא לָאו אֹרַח דְּרַבָּנָן לְשַׁמֵּשׁ מִטָתָן, אֶלָּא בַּלַּיְלָה, אֹרַח צִּנְעָא. וּבְגִין דָּא, מָתַי אִתְעָבִיד לִינָה. כִּי בָא הַשֶּׁמֶשׁ, דְּאִתְפְּנֵי שִׁמְשָׁא מֵעָלְמָא.</p>\n<p>וּבְגִין דָּא, אוּף הָכִי דְּצָּרִיךְ לְאִתְכַּסְּיָיא מִן שִׁמְשָׁא, וְהָכִי צָּרִיךְ לְאִתְכַּסְּיָיא מֵאִלֵּין מַלְאֲכִין, דְּאִינּוּן מִיִּצֶּר הַטוֹב מִימִינָא, בְּכַמָּה מַשִׁרְיָין. וּמִיִצֶּר הָרָע, דְּאָזִיל לִשְׂמָאלָא בְּכַמָּה מַשִׁרְיָין. וּבְגִין דָּא, בָּתַר דְּאָתָא צַּפְרָא, אָמַר כַּאֲשֶׁר רָאָם. וּמִסִּטְרָא דְּיַעֲקֹב דְּהֲוָה אִישׁ תָּם, לָא הֲוָה עִמֵּיהּ אֶלָּא חַיָּילִין דְּמַלְכָּא וּמַטְרוֹנִיתָא. וּבְגִין דָּא וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם. אִינּוּן מַלְאֲכִין דִּימָמָא כְּתִיב. כַּאֲשֶׁר רָאָם מַחֲנֶה אֱלֹהִים זֶה. וְכַד אָתוּ מַלְאָכִים דְּלֵילְיָא, דְּאִתְכְּנָשׁוּ בַּהֲדֵיהּ, לְנַטְרָא לֵיהּ אָמַר וַיִּקְרָא <Nonei></i>שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם.</p>\n<p>בְּגִין דִּצְּלוֹתָא אִיהִי כַּלָּה, הֲדָא הוּא דִכְתִיב, (שיר השירים ד׳:ח׳) אִתִּי מִלְּבָנוֹן כַּלָּה אִתִּי וְגוֹ'. אִתְקְרֵי הָכָא אִתִּי. וּבְאוֹרַיְיתָא דְּבִכְתָב אִתְּמַר עָלָהּ, (שמות ל״ג:כ״א) הִנֵּה מָקוֹם אִתִּי. וּבְגִין דְּאִיהִי אִתְקְרִיאַת מָקוֹם בְּעָלְמָא דֵּין, אִתְּמַר בָּהּ וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם.</p>\n<p>וּבְגִין דָּא אִיהִי אַמְרַת, (ירמיהו ט׳:א׳) מִי יִתְּנֵנִי בַמִּדְבָּר מְלוֹן אוֹרְחִים. דַּהֲוַת רְשׁוּ בִּפְנֵי עַצְּמָהּ, וְלָאו עִם אִינּוּן דְּקַבְעִין לָהּ חוֹבָה עִמְּהוֹן, בְּלָא חָתָן דִּילָהּ. וּבְכָל שַׁעֲתָא דְּבַּר נָשׁ מְצַּלֵּי, קוּדְשָׁא בְּרִיךְ הוּא אַקְדִּים וְנָטַר לֵיהּ. וְרָזָא דְּמִלָּה, (בראשית כ״ד:כ״א) וְהָאִישׁ מִשְׁתָּאֵה לָהּ. וְלֵית אִישׁ, אֶלָּא קוּדְשָׁא בְּרִיךְ הוּא. הֲדָא הוּא דִכְתִיב, (שמות ט״ו:ג׳) יְיָ אִישׁ מִלְחָמָה. (בראשית כ״ד:ט״ו) וַיְהִי הוּא טֶרֶם כִּלָה לְדַבֵּר וְהִנֵּה רִבְקָה יוֹצֵּאת, כְּגוֹן (זכריה ט׳:י״ד) וְיָצָּא כַּבָּרָק חִצּוֹ.</p>\n<p>וְאִי תֵּימְרוּן, דְּהָא אוּקְמוּהָ רַבָּנָן, לְעַשְׂרָה קַדְמָא שְׁכִינְתָּא וְאַתְיָא, לְאֶחָד עַד דְּיִתִיב. לְעַשְׂרָה דְּהִיא י' קַדְמָה ה'. לְאֶחָד דְּאִיהוּ ו', עַד דְּיָתִיב, לָא אַתְיָא לְגַבֵּיהּ ה' תִּנְיָינָא. וְרָזָא דְּמִלָּה, דְּבַאֲתָר דְּלֵית תַּמָּן יָ\"הּ, לָא אַתְיָא תַּמָּן ה'. וּמַאן דְּבָעֵי לְיַחֲדָא אַתְוָון, צָּרִיךְ בִּתְחִנָּה וּבְתַחֲנוּנֵי. וּבְגִין דָּא, (דברים ג׳:כ״ג) וָאֶתְחַנַּן אֶל יְיָ, בַּאֲדֹנָ\"י לִשְׁכִ ינְתָּא בְּתַחֲנוּנִים. וּלְּקוּדְשָׁא בְּרִיךְ הוּא בְּרַחֲמֵי, עַד הָכָא.</p>"],[9520012552,"<p>אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם. דְּאִיהוּ רָזָא דְּכַבְשֵׁי דְּרַחֲמָנָא, דְּאוֹקְמוּהָ עָלַיְיהוּ רַבָּנָן, גַּבֵּי כַּבְשֵׁי דְּרַחֲמָנָא לָמָּה לָךְ. אֶלָּא מִלִּין דִּיהוֹן תְּחוֹת כִּבְשׁוֹנֵי דְּעָלְמָא, יִהוֹן מְכוּסִין תְּחוֹת לְבוּשָׁךְ. מַה לְבוּשׁ אִיהוּ מְכַסֶּה עַל גּוּפָא, אוּף הָכִי צָּרִיךְ לְכַסָּאָה רָזִין דְּאוֹרַיְיתָא. כָּל שֶׁכֵּן רָזִין דְּקָרְבְּנִין, דְּאִינּוּן כְּגַוְונָא דִּקְרִיבוּ דְּאִתְּתָא לְגַבֵּי בַּעְלָהּ.</p>\n<p>וּמַה קְרִיבוּ דְּתַרְוַויְיהוּ צָּרִיךְ בְּאִתְכַּסְּיָא. אוּף הָכִי צָּרִיךְ קָרְבָּן לְכַסָּאָה לוֹן, מִבְּנֵי עַרְיָין רַשִׁיעַיָּיא חֲצּוּפִין, דְּלֵית לוֹן בֹּשֶׁת פָּנִים וְלָא עֲנָוָה. וְכַמָּה מִינֵי מַמְזְרִין אִינּוּן, בְּנֵי עֲרָיוֹת, בְּנֵי נִדָּה, דְּנָד ה' מִנָּהּ, וְאִשְׁתְּכַח בְּאַתְרָהּ. שִׁפְחָה בַּת אֵל נֵכָר זוֹנָה. וְהַאי אִיהוּ רָזָא, (משלי ל׳:כ״ב) תַּחַת שָׁלֹשׁ רָגְזָה אֶרֶץ וְגוֹ', תַּחַת עֶבֶד כִּי יִמְלוֹךְ וְנָבָל כִּי יִשְׂבַּע לָחֶם וְשִׁפְחָה כִּי תִּירַשׁ גְּבִירְתָּהּ. דְּנָד ה' מֵאַתְרָאָה, דְּאִיהִי מַטְרוֹנִיתָא, יֵצֶּר הַטוֹב. וְעָאלָא בְּאַתְרָהָא שִׁפְחָה יֵצֶּר הָרָע.</p>\n<p>וְרָזָא דְּמִלָּה, (ויקרא י״ד:ל״ה) כְּנֶגַע נִרְאָה לִי בַּבָּיִת, הַיְינוּ דָּם טָמֵא דְּנִדָּה. וּמַה הָתָם וְהִסְגִּירוֹ הַכֹּהֵן שִׁבְעַת יָמִים. אוּף הָכִי (ויקרא ט״ו:י״ט) שִׁבְעַת יָמִים תִּהְיֶה בְנִדָּתָהּ. (ולית מצורע וכו' עד לה' אלהיכם נדפס בפרשת צו דף ל\"ג ע\"ב) זַכָּאִין אִינּוּן אֵבָרִים דְּמִתְקַדְּשֵׁי בְּשָׁעַת תַּשְׁמִישׁ, דְּאִינּוּן עֲצֵּי <Nonei></i>הָעוֹלָה, דַּאֲחִידָן בְּהוֹן אֶשִּׁין קַדִּישִׁין, שֵׁם יְדוָֹד דְּאָחִיד בְּאֶשִׁין דִּלְהוֹן. וּבְגִין דָּא (ישעיהו כ״ד:ט״ו) בָּאוּרִים כַּבְּדוּ יְיָ עַל כֵּן כִּבְשֵׁי דְּרַחֲמָנָא, הַיְינוּ אֶת הַכֶּבֶשׂ הָאֶחָד תַּעֲשֶׂה בַבֹּקֶר וְאֵת הַכֶּבֶשׂ הַשֵּׁנִי תַּעֲשֶׂה בֵּין הָעַרְבָּיִם.</p>\n<p>שְׁלִימוּ דִּקְרָא, וַעֲשִׂירִית הָאֵיפָה סֹלֶת. זַכָּאָה אִיהוּ מַאן דְּאַנְגִּיד מִמוֹחֵיהּ, טִפָּה סֹלֶת נְקִיָּה בְּלָא פְּסוֹלֶת. וְאִיהִי רְמִיזָא בְּאָת י' מִן אֲדֹנָ\"י, כְּלִילָא בְּעֶשֶׂר סְפִירָאן. דְּאִיהִי בְּלוּלָה בְּשֶׁמֶן כָּתִית רְבִיעִית הַהִין. וְאִיהִי בְּלוּלָה, בַמִּקְרָא, בַּמִּשְׁנָה, בַּתַּלְמוּד, בְּקַבָּלָה. (כאן שייך מה שכתוב בדף רמ\"ד ע\"א אמר רעיא מהימנא ועשירית האיפה)</p>"],[9520012553,"<p>יְחֶזְקֵאל כַּד חָמָא שְׁכִינְתָּא מִגּוֹ קְלִיפִּין, חָזָא עִמָּהּ עֶשֶׂר סְפִירָאן. בְּלָא פִּרוּדָא כְּלַל. וְאִלֵּין אִינּוּן מוֹחָא, מִלְּגוֹ, כֻּלְּהוּ חָזָא לוֹן מִגּוֹ נְהַר כְּבָר דִּלְתַתָּא, אִיהִי (תהילים ס״ח:י״ח) רֶכֶב אֱלֹהִים רִבּוֹתַיִם, כָּל רִבּוֹא עֶשֶׂר אַלְפִין, רִבּוֹתַיִם כ' אֶלֶף, אַפִּיק תְּרֵי שֶׁאֵינָן, אִשְׁתָּאֲרוּ תִּמְנֵי סָר, בְּחוּשְׁבַּן ח\"י עָלְמִין. דְּכָלִיל עֶשֶׂר סְפִירָאן, דְּאִתְלָבַּשׁ בְּטֵ\"ט מִן מְטַטְרוֹן. טֵ\"ט מִן טֹטָפֹת, וְאִתְּמַר בֵּיהּ (דברים ו׳:ח׳) וְהָיוּ לְטֹטָפֹת בֵּין עֵינֶיךָ. מַאן עַיְינִין. אִלֵּין לְעֵילָּא, דְּאִתְּמַר בְּהוּ (יחזקאל א׳:א׳) נִפְתְּחוּ הַשָּׁמַיִם וָאֶרְאֶה מַרְאוֹת אֱלֹהִים. מַאן מַרְאוֹת. אִלֵּין אִינּוּן עֲשַׂרָה מַרְאוֹת דִּמְטַטְרוֹן, דְּחָזָא כִּשְׁרָגָא בְּגוֹ עֲשִׁישִׁיתָא. תְּשַׁע בְּאִתְגַלְיָיא, וְחַד סָתִים.</p>\n<p>מַרְאָה חֲדָא דְּאִיהוּ חֵזוּ קַדְמָאָה מֵאֵלּוּ עֲשַׂרָה, דָּא אִיהוּ דְּאִתְּמַר בֵּיהּ, (יחזקאל א׳:כ״ו) וּמִמַּעַל לָרָקִיעַ אֲשֶׁר עַל רֹאשָׁם כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. וְאַף עַל גַּב דְּאִתְפְּרַשׁ לְעֵילָּא, צָּרִיךְ לְחָדְתָּא עָלֵיהּ מִלִּין דְּחִדּוּשִׁין.</p>\n<p>אָמַר קוּדְשָׁא בְּרִיךְ הוּא, לְמַשִׁרְיָין דִּלְעֵילָּא, מַאן דִּמְצָּלֵי, בֵּין יְהֵא גִּבּוֹר, בֵּין יְהֵא חָכָם, בֵּין יְהֵא עָשִׁיר. בְּזַכְוָון גִּבּוֹר. חָכָם בַּתּוֹרָה. וְעָשִׁיר בַּמִּצְּוֹת. לָא יִיעוּל בְּהֵיכָלָא דָּא צְּלוֹתֵיהּ, עַד דְּתִחְזוּן בֵּיהּ סִימָנִין אִלֵּין, דְּיָהַב גַּרְמֵיהּ בֵּיהּ תִּקּוּנִין דִּילִי. וּבְגִין דָּא אוֹקְמוּהָ מָארֵי מַתְנִיתִין, אִם הָרַב דּוֹמֶה לְמַלְאַךְ יְיָ צְּבָאוֹת תּוֹרָה יְבַקְשׁוּ מִפִיהוּ. לְמַאן דִּיְהֵא רָשִׁים בְּאִלֵּין סִימָנִין בִּלְבוּשֵׁיהּ, תְּקַבְּלוּן צְּלוֹתֵיהּ. סִימָנָא חֲדָא דִּיְהֵא רָשִׁים בִּצְּלוֹתֵיהּ, בִּתְכֵלֶת, בְּכַנְפֵי מִצְּוָה צִּיצִּית. דְּאִיהוּ דָּמֵי לָרָקִיעַ, דְּאִיהוּ מְטַטְרוֹן. דִּיּוּקְנָא דִּילֵיהּ, תְּכֵלֶת שֶׁבַּצִּיצִּית.</p>\n<p>וּבְגִין דָּא, שִׁיעוּר הַצִּיצִּית אוֹקְמוּהָ רַבָּנָן, טַלִית שֶׁהַקָטָן מִתְכַּסָה בָּהּ רֹאשׁוֹ וְרוּבּוֹ. וְהַאי אִיהוּ דְּאִתְּמַר בֵּיהּ, (ישעיהו י״א:ו׳) וְנַעַר קָטֹן נוֹהֵג בָּם. וְהַאי אִיהוּ נוֹהֵג בְּד' חֵיוָן, דְּאִינּוּן ד', וְאִיהוּ כָּלִיל (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִסֵּא, דְּאִינּוּן ו'. וּבְגִין דְּאִיהוּ כָּלִיל עֶשֶׂר, מִתְלַבְּשִׁין בֵּיהּ עֶשֶׂר סְפִירָאן, י'. וּבֵיהּ הֲוָה אִתְחֲזִי קוּדְשָׁא בְּרִיךְ הוּא בִּשְׁכִינְתֵּיה, דְּאִיהִי כְּלִילָא מֵעֶשֶׂר סְפִירָאן, לִנְבִיאֵי. וּמִסִּטְרָא דִּשְׁכִינְתָּא דְּאִיהִי עֲשִׁירָאָה, תְּכֵלֶת שֶׁבַּצִּיצִּית, אִיהוּ תְּכֵלֶת דְּכָל גַּוְונִין.</p>\n<p>דְּאִיהִי תַּכְלִית דְּי' סְפִירָאן. וּבֵיהּ (שמות ל״ט:ל״ב) וַתֵּכֶל כָּל עֲבוֹדַת אֹהֶל מוֹעֵד. וְאִיהִי לָשׁוֹן כַּלָּה. הֲדָא הוּא דִכְתִיב, (במדבר ז׳:א׳) וַיְהִי בְּיוֹם כַּלֹּת מֹשֶׁה לְהָקִים אֶת הַמִּשְׁכָּן. וְאוֹקְמוּהָ רַבָּנָן, כַּלַּת כְּתִיב, וְאִיהוּ תְּכֵלֶת דִּשְׁרָגָא, דְּאָכִיל תְּרָבִין וְעִלָּוָון.</p>\n<p>וְעָלֵיהּ אָמַר יְחֶזְקֵאל (יחזקאל א׳:כ״ו) דְּמוּת כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. סְגוּלָה דְּהַאי אֶבֶן, מַאן דְּיָרִית לָהּ, לָא שַׁלְטָא נוּרָא דְּגֵיהִנָּם עָלֵיהּ. לֵית נוּרָא בְּעָלְמָא מְקַלְקֵל לָהּ, וְלָא כָּל מִינֵי מַתְּכוֹת. כָּל שֶׁכֵּן מַיָּא, דְּלָא מַזִּיקוּ לָהּ. מַאן דְּיָרִית לָהּ, אִתְקַיָּים בֵּיהּ (ישעיהו מ״ג:ב׳) כִּי תַעֲבוֹר בַּמַּיִם אִתְּךָ אָנִי וְגוֹ'. וְכָל עִלָּאִין וְתַתָּאִין דְּסִטְרָא אַחֲרָא דַּחֲלִין מִנֵּיהּ. תְּכֵלֶת דְּיַמָּא בְּגִינֵיהּ אִתְּמַר, כִּי תַעֲבוֹר בַּמַּיִם אִתְּךָ אָנִי. דְּבִסְגּוּלָה דָּא, (שמות ט״ו:א׳) סוּס וְרוֹכְבוֹ רָמָה בַיָּם, דָּא מְמָנָא דְּמִצְּרַיִם.</p>\n<p>מִגָּוְון דָּא, דַּחֲלִין עִלָּאִין וְתַתָּאִין. מַשִׁרְיָין דְּיַמָּא דַּחֲלִין מִנֵּיהּ. וּמַשִׁרְיָין דִּרְקִיעָא דְּאִיהוּ תְּכֵלֶת, מִנֵּיהּ דַּחֲלִין. מַשִׁרְיָין דִּתְכֵלֶת (ס\"א ומשריין דרקיעין ומשריין) דְּנוּרָא דְּגֵיהִנָּם דַּחֲלִין מִנֵּיהּ.</p>\n<p>וְהַאי תְּכֵלֶת <Nonei></i>אִיהוּ דִּין. דִּינָא אֲדֹנָ\"י. דִּינָא דְּמַלְכוּתָא דִּינָא וּתְרֵין גַּוְונִין רְשִׁימִין בְּטַלִית, חַד חִוָּור, וְחַד תְּכֵלֶת. וְעַל תְּרֵין גַּוְונִין אִלֵּין אִתְּמַר, (שמות כ״ד:י׳) וְתַחַת רַגְלָיו כְּמַעֲשֵׂה לִבְנַת הַסַּפִּיר. לִבְנַת, לוֹבֶן דְּסַפִּיר. דְּאִיהוּ כָּלִיל בִּתְרֵין גַּוְונִין, רַחֲמֵי וְדִינָא, חִוָּור וְאוּכָם. אוּכָמוּ דִּתְכֵלֶת. וְעַל תְּרֵין גַּוְונִין, רְמִיזוּ רַבָּנָן, מֵאֵימָתַי קוֹרִין אֶת שְׁמַע בְּשַׁחֲרִית, מִשֶּׁיַּכִּיר בֵּין תְּכֵלֶת לְלָבָן. לְמֶהֱוִי בְּרַתָּא דְּמַלְכָּא, קְרִיאַת שְׁמַע, יִחוּדָא דְקוּדְשָׁא בְּרִיךְ הוּא, כָּלִיל מִתְּרֵין גַּוְונִין אִלֵּין, דְּאִינּוּן יְדוָֹ\"ד אֲדֹנָ\"י, רַחֲמֵי וְדִינָא. כְּגַוְונָא דְקוּדְשָׁא בְּרִיךְ הוּא כָּלִיל ב' גַּוְונִין, יְהוָֹ\"ה אֲדֹנָ\"י לְמֶהֱוִי רַחֲמֵי וְדִינָא, כִּסֵּא דִּין וְכִסֵּא רַחֲמִים. (מטטרון)</p>\n<p>(יחזקאל א׳:כ״ו) כְּמַרְאֵה אֶבֶן סַפִּיר דְּמוּת כִּסֵּא. מַאי דְּמוּת כִּסֵּא. אֶלָּא לָקֳבֵל כֻּרְסְיָיא, דְּאִית לֵיהּ ע\"ב גְּשָׁרִים. דִּיְהֵא בַּר נָשׁ רָשִׁים בְּע\"ב קְשָׁרִים, וְחוּלְיָין דְּצִּיצִּית, לָקֳבֵל ע\"ב גְּשָׁרִים דְּכֻרְסְיָיא. דְּאִינּוּן ח\"י קְשָׁרִים, וְחוּלְיָין לְכָל סִטְרָא. דְּכֻרְסְיָיא דְּאִיהוּ ה', לְכָל סִטְרָא בְּד' חֵיוָן דְּכֻרְסְיָיא, דְּאִינּוּן ד'.</p>\n<p>וְשִׁית דַּרְגִּין דְּכֻרְסְיָיא, דְּאִינּוּן ו', וְדָא מְטַטְרוֹן, אִיהוּ כָּלִיל ד' חֵיוָון. הֲדָא הוּא דִכְתִיב, (ישעיהו י״א:ו׳) וְנַעַר קָטֹן נוֹהֵג בָּם. וְאִינּוּן מִיכָאֵל גַּבְרִיאֵל נוּרִיאֵל רְפָאֵל. מְטַטְרוֹן (מלכים א י׳:י״ט) שֵׁשׁ מַעֲלוֹת לַכִסֵּא, דְּסַלְּקִין שִׁית מְאָה, צִּיצִּית בִּתְרֵין יוֹדִי\"ן. וְאִי חָסֵר יוֹד, הָא חִירִק בְּאַתְרֵיהּ, הָכִי סַלְּקָא. בְּכָל סִטְרָא בְּד' כַּנְפֵי, צִּיצִּית וּתְלַת עֲשַׂר חֻלְיָין דְּצִּיצִּית, אִינּוּן תרי\"ג.</p>\n<p>וְעוֹד. שֵׁשׁ מַעֲלוֹת לַכִסֵּא, בְּרָזָא דָּא וָא\"ו, סָלִיק לְחֻשְׁבָּן י\"ג, דְּאִתְרְמִיז בִּתְלַת תֵּיבִין, וַיִּסַּע וַיָּבֹא וַיֵּט. דְּאִינּוּן וָהוּ אֲנִי וָהוּ. חָמֵשׁ קִשְׁרִין, ה' לְכָל סִטְרָא. א' טָלִית חַד לְכֻלְּהוּ. וּבְאָת ה' אִשְׁתְּלִים ח\"י. דְּאִינּוּן ט\"ט. לְמֶהֱוִי חַיָּה לְכָל סִטְרָא. כָּלִיל ד' חַיוֹת. וּלְכָל חַיָּה, אַרְבַּע אַנְפִּין, וְאַרְבַּע גַּדְפִּין, אִינּוּן ל\"ב אַנְפִּין וְגַדְפִּין. וְאִינּוּן תַּלְיָין מֵחַיָּה דְּאִיהוּ אָדָם.</p>\n<p>וְאִינּוּן ל\"ב, כְּחוּשְׁבַּן יוֹ\"ד הֵ\"א הֵ\"א. שְׁלִימוּ דִּלְהוֹן, וָא\"ו. תְּלֵיסַר חוּלְיָין בְּכָל ד' כַּנְפֵי, וְהַוָא\"ו מִתְיַיחֵד עִם כָּל אַרְבַּע חַיוֹת, וְאַשְׁלִים לְעֵילָּא, אַשְׁלִים לְתַתָּא. עַמּוּדָא דְּאֶמְצָּעִיתָא אִיהוּ מְטַטְרוֹן, לְאַשְׁלְמָא לְעֵילָּא, כְּגַוְונָא דְּתִפְאֶרֶת, שְׁמֵיהּ כְּשֵׁם רַבֵּיהּ. בְּצַּלְמוֹ כִּדְמוּתוֹ אִתְבְּרֵי. דְּאִיהוּ כָּלִיל כָּל דַּרְגִּין, מֵעֵילָּא לְתַתָּא, וּמִתַּתָּא לְעֵילָּא. וְאִיהוּ אָחִיד בְּאֶמְצָּעִיתָא. הֲדָא הוּא דִכְתִיב, (שמות כ״ו:כ״ח) וְהַבְּרִיחַ הַתִּיכוֹן בְּתוֹךְ הַקְּרָשִׁים מַבְרִיחַ מִן הַקָּצֶּה אֶל הַקָּצֶּה.</p>\n<p>וְאִיהוּ כָּלִיל ד' אַנְפִּין, וְאַרְבַּע גַּדְפִּין דְּכָל חַיָּה וְחַיָּה דִּלְעֵילָּא, דְּאִינּוּן, יְאֲדַדוֹנָהִי. אָז יָשִׁיר מֹשֶׁה. בְּכָל חַיָּה אַרְבַּע אַנְפִּין, וְאַרְבַּע גַּדְפִּין, כְּגַוְונָא דָּא. א\"ז בְּאַרְיֵה. א\"ז בְּשׁוֹר. א\"ז בַּנֶשֶׁר. א\"ז בָּאָדָם. דְּאִינּוּן ל\"ב אַנְפִּין וְגַדְפִּין, בְּחוּשְׁבַּן א\"ז ד' זִמְנִין.</p>\n<p>וְאִינּוּן ד' אַנְפִּין: יְדוָֹ\"ד. אַרְבַּע גַּדְפִּין: אֲדֹנָי. לָקֳבֵל ד' בִּגְדֵי זָהָב, וְאַרְבַּע בִּגְדֵי לָבָן, דְּלָבִישׁ כַּהֲנָא לְכַפְּרָא עַל יִשְׂרָאֵל. לָקֳבֵל, (תהילים נ״א:י״ז) אֲדֹנָי שְׂפָתַי תִּפְתָּח. וּצְּלוֹתָא. דִּתְפִלָּה יְדוָֹ\"ד, בַּחֲתִימָה ח\"י בִּרְכָאן דִּצְּלוֹתָא. וְתִמְנֵי סָרֵי זִמְנִין יְדוָֹ\"ד, אִית בְּהוֹן ע\"ב אַתְוָון, בְּחוּשְׁבַּן וַיְכֻלּוּ, דִּכְלִילָן בְּצַּדִּיק חַ\"י עָלְמִין.</p>\n<p>וּבְאַרְבַּע חִיוָן, יְדוָֹ\"ד אֲדֹנָי. תִּמְנֵי לְכָל סִטְרָא, אִינּוּן ל\"ב אַתְוָון, וי\"ג אַתְוָון, דְּאִשְׁתְּכָחוּ מִן וָה\"וּ אֲנִי וָה\"וּ, הָא תְּלַת עֲשַׂר, דִּכְלִילָן עֵילָּא וְתַתָּא. בְּהוֹן אִשְׁתְּלִים אָדָם, דְּאִיהוּ מ\"ה, עַמּוּדָא דְּאֶמְצָּעִיתָא.</p>"],[9520012554,"<p>לְעֵילָּא בְּאִילָנָא דְּחַיִּי, לֵית, קְלִיפִין. (אסתר ד׳:ב׳) כִּי אֵין לָבֹא אֶל שַׁעַר הַמֶּלֶךְ בִּלְבוּשׁ שָׂק. לְתַתָּא אִית קְלִיפִין בִּמְטַטְרוֹן, דְּאִיהוּ בְּדִיּוּקְנָא דְּעַמּוּדָא דְּאֶמְצָּעִיתָא. דִּבְזִמְנָא דְּקוּדְשָׁא בְּרִיךְ הוּא לְבַר מִמַלְכוּתֵיהּ, אִתְכַּסֵּי בְּגַדְפִּין וְאַנְפִּין דְּעֶבֶד דִּילֵיהּ, הֲדָא הוּא דִכְתִיב, (שמואל ב כ״ב:י״א) וַיִּרְכַּב עַל כְּרוּב וַיָּעֹף.</p>\n<p>וְאִינּוּן קְלִיפִּין דְּסָחֲרִין לְד' חֵיוָן דִּמְטַטְרוֹן, אִינּוּן: תֹּהוּ, (מלכים א י״ט:י״א) וְהִנֵּה רוּחַ גְּדוֹלָה וְחָזָק מְפָרֵק הָרִים וּמְשַׁבֵּר סְלָעִים לֹא בָרוּחַ יְיָ. בֹּה\"וּ, וְאַחַר הָרוּחַ רַעַשׁ לֹא בָרַעַשׁ יְיָ, הָא תְּרֵין קְלִיפִין, יָרוֹק וְחִוָּור, דִּקְלִיפִין דֶּאֱגוֹזָא, חַד תֹּהוּ, קַו יָרוֹק, תִּנְיָינָא בֹּהוּ, אֲבָנִין מְפוּלָּמִין, קְלִיפָא תַּקִּיפָא, כְּאַבְנָא מְפוּלָּמָא. לָקֳבֵל תְּרֵין קְלִיפִין אִלֵּין, מוֹץ וְתֶבֶן דְּחִטָה.</p>\n<p>קְלִיפָא תְּלִיתָאָה, דְּקִיקָא. לָקֳבֵל סוּבִּין דְּחִטָה, דְּהָכָא אִיהוּ מִתְדְּבַּק בָּחִטָה, וְלָא יָכִיל לְאִתְפָּרְשָׁא מִתַּמָּן, עַד דְּטָחֲנִין לֵיהּ בְּרֵיחַיָּיא, דְּאִינּוּן לָקֳבֵל טוֹחֲנוֹת דְּפוּמָא דְּבַּר נָשׁ, דְּצָּרִיךְ לְמִטְחַן בְּהוֹן מִלִּין דְּאוֹרַיְיתָא, עַד דִּיהוֹן כְּקֶמַח סֹלֶת נְקִיָּה, וּבְנָפָה דְּאִיהִי שָׂפָה, אִתְבְּרִיר פְּסוֹלֶת דְּאִיהִי סוּבִּין (דאורייתא) עַד דְּיִשְׁתְּכַח הֲלָכָה סֹלֶת נְקִיָּה. בְּהַהוּא זִמְנָא, נָטִיל לָהּ לִבָּא וּמוֹחָא, וְכָל אֵבָרִין דְּגוּפָא דְּאִתְפְּשַּׁט בְּהוֹן נִשְׁמְתָא, וְאִתְפַּרְנְּסַת בָּהּ נִשְׁמְתָא, כְּגַוְונָא דְּגוּפָא אִתְפַּרְנְּסַת בְּמִלִּין דְּעָלְמָא, (קהלת ז׳:י״ד) דְּזֶה לְעוּמַת זְה עָשָׂה אֱלֹהִים, נָהֲמָא דְּגוּפָא, וְנָהֲמָא דְּאוֹרַיְיתָא. הֲדָא הוּא דִּכְתִּיב, (משלי ט׳:ה׳) לְכוּ לַחֲמוּ בְּלַחְמִי.</p>\n<p>וְהַאי קְלִיפָא, אִיהוּ כִּקְלִיפָא דְּמִתְדַּבְּקָא בְּמוֹחָא דֶּאֱגוֹזָא, וּבְזִמְנָא דֶּאֱגוֹזָא אִיהִי רְכִיכָא, אִתְפְּרַשׁ הַהִיא קְלִיפָא מִמּוֹחָא דֶּאֱגוֹזָא, בְּלָא קוּשְׁיָא. וּבְזִמְנָא דֶּאֱגוֹזָא אִיהִי <Nonei></i>יְבֵשָׁה, קָשֶׁה לְבַּר נָשׁ לְאַעְבְּרָא לֵיהּ מִתַּמָּן, כִּי עֲדַיִין הַקּוּשְׁיָא בִּמְקוֹמָהּ עוֹמֶדֶת. וּבְגִין דָּא מָנֵי קוּדְשָׁא בְּרִיךְ הוּא לְבַּר נָשׁ, לְאָהַדְרָא בְּתִיּוּבְתָּא בְּבַחְרוּתֵיהּ, קוֹדֶם דְּיַזְקִין בֵּיהּ יֵצֶּר הָרָע. הֲדָא הוּא דִכְתִיב, (ויקרא י״ט:ל״ב) מִפְּנֵי שֵׂיבָה תָּקוּם, קוֹדֶם שֵׂיבָה דִּילָךְ. וְהַאי קְלִיפָּה אִיהִי אֵשׁ, וְאִתְּמַר בָּהּ וְאַחַר הָרַעַשׁ אֵשׁ לֹא בָּאֵשׁ יְיָ. רְבִיעָאָה, תְּהוֹם. חָלָל דֶּאֱגוֹזָא, בֵּיהּ קוֹל דְּמָמָה דַקָּה, תַּמָּן קָא אָתֵי מַלְכָּא, (יחזקאל א׳:ד׳) וּמִתּוֹכָהּ כְּעֵין הַחַשְׁמַל מִתּוֹךְ הָאֵשׁ.</p>\n<p>וְאִינּוּן קְלִיפִין, אִינּוּן רְשִׁימִין בְּד' אֵבָרִים דְּגוּפָא. בְּרֵיאָה, תַּמָּן לֵיחָא, דְּמִינָהּ אִשְׁתְּכָחוּ סִרְכוֹת דְּרֵיאָה, (משלי ה׳:ה׳-ו׳) רַגְלֶיהָ יוֹרְדוֹת מָוְת שְׁאוֹל צְּעָדֶיהָ יִתְמוֹכוּ. וְתַּמָּן רוּחַ חָזָק מְפָרֵק, דְּדָפִיק בְּכַנְפֵי רֵיאָה דְּבַּר נָשׁ, וְהַאי אִיהוּ רוּחָא דְּאַסְעִיר גּוּפֵיהּ דְּבַּר נָשׁ, מַה דְּכָפִף לֵיהּ אֵלִיָּהוּ תְּחוֹתוֹי, וְסָלִיק לְעֵילָּא בֵּיהּ. הֲדָא הוּא דִכְתִיב, (מלכים ב ב׳:י״א) וַיַּעַל אֵלִיָּהוּ בַּסֳּעָרָה הַשָּׁמַיְמָה. וְהַאי דָּפִיק עַל רֵיאָה, דְּשׁוֹתָה כָּל מַשְׁקִין. וּבְהוֹן, (בראשית א׳:ב׳) וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם, הַאי אִיהוּ קְלִיפָה לְרוּחָא דְּקוּדְשָׁא. לִשְׂמָאלָא, רוּחַ סְעָרָה, עָלַיְיהוּ אִתְּמַר, (קהלת י׳:ב׳) לֵב חָכָם לִימִינוֹ וְלֵב כְּסִיל לִשְׂמֹאלוֹ.</p>"],[9520012555,"<p>דָּוִד אַעְבָּר לֵיהּ מִלִּבּוֹי, וְקָטִיל לֵיהּ. הֲדָא הוּא דִכְתִיב, (תהילים ק״ט:כ״ב) וְלִבִּי חָלַל בְּקִרְבִּי וּבְגִין דָּא זָכָה, לִנְשָׁבָא רוּחַ צְּפוֹנִית, בְּכִנּוֹר דִּילֵיהּ. וְאִתְּמַר בֵּיהּ, (יחזקאל ל״ז:ט׳) כֹּה אָמַר יְיָ מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, וַהֲוָה מְנַגֵּן בֵּיהּ בַּכִּנּוֹר, בְּד' מִינֵי נִגּוּנִין, בְּשִׁיר פָּשׁוּט, דְּאִיהוּ י'. וּבְשִׁיר כָּפוּל, דְּאִיהוּ י\"ד. וּבְשִׁיר מְשׁוּלָּשׁ, דְּאִיהוּ יד\"ו. וּבְשִׁיר מְרוּבָּע, דְּאִיהוּ יְדוָֹ\"ד. הָא אִינּוּן עֶשֶׂר אַתְוָון. דְּעֲבַד דָּוִד לָקֳבְלַיְיהוּ, י' מִינֵי תִּלִים. וְסַלְּקִין לְע\"ב אַנְפִּין, כְּחוּשְׁבַּן י' אַתְוָון אִלֵּין.</p>\n<p>וּמָתַי סְלִיקוּ בְּע\"ב מִינֵי נִגּוּנָא. כַּד אִתְעֲבָר שׁוּלְטָנוּתָא דְּעָוֹן מַשְׁחִית אַף וְחֵימָה. דִּבְּהוֹן דָּפִיק רוּחַ סְעָרָה. בְּאַרְבַּע סִטְרִין, דְּסַלְּקִין לְּי' כִּתְרִין לְע\"ב אוּמִין, הֲדָא הוּא דִכְתִיב, (משלי י״א:י׳) וּבַאֲבוֹד רְשָׁעִים רִנָּה.</p>\n<p>דְּמִיכָאֵ\"ל גַּבְרִיאֵ\"ל נוּרִיאֵ\"ל רְפָאֵ\"ל, שַׁלְטִין עַל ד' סִטְרִין (ס\"א יסודין) טָבִין דְּבַּר נָשׁ, דְּאִינּוּן מַיָּא וְאֶשָּׁא וְרוּחָא וְעַפְרָא, וְכָל חַד אִית לֵיהּ ד' אַנְפִּין. עֲוֹן מַשְׁחִית אַף וְחֵימָה, תַּלְיָין (ס\"א שלטין) עַל מָרָה לְבָנָה, דְּרֵיאָה דְּעָבִיד סִרְכָא. וּבְמָרָה סוּמָקָא דְּכָבֵד, דְּאִתְאַדָּם בְּמַאֲדִים. וּבְמָרָה יְרוֹקָא דַּאֲחִידָא בְּכַבְדָא, דְּאִיהוּ חַרְבָּא דְּמַלְאָךְ הַמָּוְת, דְּאִתְּמַר בָּהּ (משלי ה׳:ד׳) וְאַחֲרִיתָהּ מָרָה כַלַּעֲנָה חַדָּה כְּחֶרֶב פִּיּוֹת. וּבְמָרָה שְׁחוֹרָה, לִילִית, שַׁבְּתַי, שׁוּלְטָנוּתָא בַּטְחוֹל, דְּאִיהוּ עֲצִּיבוּ, שְׁאוֹל תַּחְתִּית, עֲנִיּוּתָא וַחֲשׁוֹכָא בִּכְיָה וְהֶסְפְּדָא וְרַעֲבוֹן.</p>\n<p>מִיַּד דְּמִתְעָבְרִין אִלֵּין קְלִיפִין מִבַּר נָשׁ, שַׁלְטָא עָלֵיהּ אִילָנָא דְּחַיִּי, בְּע\"ב אַנְפִּין, דְּאִינּוּן י' יָ\"ד יְד\"וּ יְדוָֹ\"ד, דְּאִשְׁתְּכָחוּ עֲשַׂרָה תַּלְיָין מֵאַרְבַּע רוּחוֹת, דְּאִינּוּן יְדוָֹד, דְּאִתְּמַר בְּהוֹן, כֹּה אָמַר יְדוָֹד מֵאַרְבַּע רוּחוֹת בֹּאִי הָרוּחַ, דָּא הוּא רוּחוֹ דְּמָשִׁיחַ. דְּאִתְּמַר בֵּיהּ, (ישעיהו י״א:ב׳) וְנָחָה עָלָיו רוּחַ יְיָ, כַּד אִיהוּ מְנַשֵּׁב בְּאֹזֶן יְמִינָא דְּלִבָּא, דְּתַמָּן חָכְמָה מִסִּטְרָא דְּחֶסֶד, דְּבֵיהּ הָרוֹצֶּה לְהַחְכִּים יַדְרִים בְּחָכְמָה. וְחֶסֶ\"ד נָשַׁב בַּבִּינָה, דְּבַחָכְמָה י'. בַּבִּינָה ה'. בְּתִפְאֶרֶת ו'. בַּמַּלְכוּת ה'. יְדוָֹד דָּפִיק בְּכֻלְּהוּ אַרְבַּע. דְּסַלְּקִין לְעֶשֶׂר. ולע\"ב מַחֲשָׁבָה דְּלִבָּא.</p>\n<p>דָּא יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א, יְמִינָא אִיהוּ מַיִם. וְאִיהוּ יַד הַגְּדוֹלָה. מִשְּׂמָאלָא אֵשׁ. וְאִיהִי יַד הַחֲזָקָה. בְּעַמּוּדָא דְּאֶמְצָּעִיתָא, יָ\"ד רָמָה. דְּאִיהִי רוּחָא דְּקֻדְשָׁא. וְכֹלָּא בֶּן י\"ד.</p>\n<p>(יחזקאל א׳:י״ב) כִּי רוּחַ הַחַיָּה בָּאוֹפַנִּים אֶל אֲשֶׁר יִהְיְה שָׁמָּה הָרוּחַ לָלֶכֶת יֵלֵכוּ. בֵּיהּ מִתְנַהֲגִים מַיָּא וְאֶשָּׁא. דְּאָחִיד בְּתַרְוַיְיהוּ, וְדָפִיק בְּעַרְקִין דְּמוֹחָא, דְּאִיהוּ מַיִם. וּבְעַרְקִין דְּלִבָּא, דְּאִיהוּ אֵשׁ. וְרוּחַ בְּכַנְפֵי רֵיאָה.</p>\n<p>בְּכָל אֵבֶר וְאֵבֶר דְּגוּפָא, אִשְׁתְּכַח גַּלְגַּלֵּי יַמָּא דְּאוֹרַיְיתָא, וְגַלְגַּלֵּי רְקִיעָא, דְּאִינּוּן אֶשָּׁא. כֻּלְּהוּ סַלְּקִין וְנַחְתִּין בֵּיהּ. וְאִיהוּ אַתְרֵיהּ בֵּין רְקִיעָא וְיַמָּא, מָאנָא דִּילֵיהּ אַרְעָא, דְּאִיהִי שְׁכִינְתָּא.</p>\n<p>וּכְגַוְונָא דְּעוֹפִין, פְּתִיחוּ גַּדְפַיְיהוּ, לְקַבְּלָא רוּחָא לְפַרְחָא בֵּיהּ. הָכִי כָּל אֵבָרִים דְּגוּפָא, פְּתִיחָן בְּכַמָּה מְקוֹרִין, בְּכַמָּה פִּרְקִין, בְּכַמָּה עַרְקִין, בְּכַמָּה אִדָּרִין דְּלִבָּא, אִדָּרִין דְּמוֹחָא, לְקַבְּלָא לֵיהּ. דְּאִי לָאו דְּנָשִׁיב בְּבָתִּין דְּלִבָּא, הֲוָה נוּרָא דְּלִבָּא, אוֹקִיד כָּל גּוּפָא. וְכַמָּה סוּלָמִין, וְאִדָּרִין, דְּעַרְקִין דְּקָנֶה דְּלִבָּא, וְקָנֶה דְּרֵיאָה, כֻּלְּהוּ מִתַּתְקְּנִין לְגַבֵּיהּ.</p>"],[9520012556,"<p>כַּד סָלִיק דִּבּוּרָא, עַל כַּנְפֵי דְּרֵיאָה, אִתְעָבִיד קוֹל. בְּהַהוּא זִמְנָא (קהלת י׳:כ׳) כִּי עוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל. (תהילים כ״ט:ג׳) קוֹל יְיָ עַל הַמָּיִם. מִסִּטְרָא דְּמַיָּא, דְּאִיהוּ מוֹחָא, דְּתַמָּן סָלִיק בְּכַנְפֵי רֵיאָה. קוֹל יְיָ חוֹצֵּב לַהֲבוֹת אֵשׁ, מִסִּטְרָא דְּלִבָּא, כַּד נָפִיק מִפּוּמָא, אִתְקְרֵי דִּבּוּר.</p>\n<p>וְלָקֳבֵל תְּרֵין כַּנְפֵי רֵיאָה, דְּפַתְחִין גַּדְפִּין לְקַבְּלָא לֵיהּ, הֲדָא הוּא דִּכְתִּיב, (יחזקאל א׳:י״א) וּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת מִלְמָעְלָה. הָכִי שִׂפְוָון נַטְלִין לֵיהּ לְדִיבּוּר, וּפַרְחִין לֵיהּ לְעֵילָּא.</p>\n<p>וּכְגַוְונָא דְּאִינּוּן חֲמִשָׁה כַּנְפֵי (ס\"א ענפי) רֵיאָה, כֻּלְּהוּ פְּתִיחָן בְּלָא סִרְכָא, לְקַבְּלָא הַאי קוֹל, הָכִי נָמֵי צְּרִיכִין לְמֶהֱוִי חַמְשָׁא תִּקּוּנִין דְּפוּמָא, כֻּלְּהוּ פְּתִיחָן בְּלָא סִירְכָא, בְּחָמֵשׁ תִּקּוּנִין דְּאִינּוּן: <Nonei></i>אחהע בַּגָרוֹן. בומף בְּשִׂפְוָון. גיכק בַּחֵיךְ. דטלנתּ בְּלִישָׁנָא. זסשרץ בַּשִּׁינַיִם.</p>\n<p>וְדִבּוּר דִּיְהֵא בְּהוֹן, בְּלָא סִרְכָא וְעִכּוּבָא כְּלַל. הֲדָא הוּא דִכְתִיב, (בראשית כ״ד:ט״ו) וַיְהִי הוּא טֶרֶם כִּלָּה לְדַבֵּר וְהִנֵּה רִבְקָה יוֹצֵּאת. דָּא צְּלוֹתָא, דְּאִיהוּ דִּבּוּר. וּבְגִינֵיהּ אִתְּמַר, אִם שְׁגוּרָה תְּפִלָּתִי בְּפִי יוֹדֵעַ אֲנִי שֶׁמְקוּבָּל. וְאִי אִית סִרְכָא וְנָפְקָא בְּעִכּוּבָא, יוֹדֵעַ אֲנִי שֶׁמְטוּרָף. בְּגִין (ס\"א כגון) סִרְכָא בְּרֵיאָה דְּאִיהִי טְרֵפָה.</p>\n<p>וְקוֹל דָּא שְׁמַע יִשְׂרָאֵל, דְּבֵיהּ (יחזקאל א׳:כ״ד) וָאֶשְׁמַע אֶת קוֹל כַּנְפֵיהֶם. וְדָא יְדוָֹ\"ד דְּאִיהוּ קוֹל, כַּד נָפִיק לְקַבְּלָא שְׁכִינְתָּא בִּצְּלוֹתָא בַּחֲשָׁאי, דְּאִיהוּ דִּבּוּר, דְּבֵיהּ אֲדֹנָ\"י שְׂפָתַי תִּפְתָּח, כָּל אֵבָרִין פְּתִיחָן כֻּלְּהוּ גַּדְפַיְיהוּ, בְּרמ\"ח תֵּיבִין, דְּאִינּוּן בְּד' פָּרְשִׁיָין דִּקְרִיאַת שְׁמַע, דִּבְהוֹן נָחִית קָלָא.</p>\n<p>וְכַד נָחִית, כַּמָּה צִּפֳּרִין מְצַּפְצְּפִין לְגַבֵּיהּ, בְּכַמָּה מִינֵי נִגּוּן, כֻּלְּהוּ עַל אֵבָרִין דְּגוּפָא, דְּאִינּוּן עַנְפֵּי אִילָנָא. וּבְכָל גַּדְפִּין דְּכָל אֵבֶר, דְּתַמָּן דִּיּוּרָא דְּצִּפּוֹרָא, דְּאִיהִי אֲדֹנָ\"י, בְּכָל עַנְפָא וְעַנְפָא, אִשְׁתְּכַח פְּתִיחָא לְגַבֵּי דְּבַעְלָהּ. אֲדֹנָ\"י שְׂפָתַי תִּפְתָּח, אִיהוּ פִּתְחָא לְגַבֵּיהּ, בִּצְּלוֹתָא דַּעֲמִידָה. לֵית אֵבֶר מרמ\"ח אֵבָרִים דִּשְׁכִינְתָּא, דְּלָאו אִיהִי פְּתִיחָא לְקַבְּלָא לֵיהּ. וּבְגִין דָּא אִתְקְרִיאַת שִׂיחַת מַלְאֲכֵי הַשָּׁרֵת. אִיהוּ צִּפְצּוּף עוֹפוֹת, דְּאִינּוּן נִשְׁמָתִין דְּשַׁרְיָין בָּאֵבָרִים. אִיהִי שִׂיחַת דְּקָלִּים, דְּאִינּוּן עַנְפִין דְּאִילָנָא.</p>\n<p>וּבְהַהוּא זִמְנָא, דְּנָחִית יְדוָֹ\"ד לְגַבֵּי אֲדֹנָ\"י בְּכָל אֵבֶר, אִתְּמַר בְּהוּ, (יחזקאל א׳:כ״ד) בְּעָמְדָם תְּרַפֶּינָה כַּנְפֵיהֶם. וְהַאי רָזָא דְּחַשְׁמַל. חַיוֹת אֵשׁ, עִתִּים חָשׁוֹת, וְעִתִּים מְמַלְּלוֹת. וְאָמְרוּ מָארֵי מַתְנִיתִין, בְּמַתְנִיתָא תָּנָא, כְּשֶׁהַדִּבּוּר יוֹצֵּא מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא, חָשׁוֹת, וּכְשֶׁאֵין הַדִּבּוּר יוֹצֵּא מִפִּי הַקָּדוֹשׁ בָּרוּךְ הוּא, מְמַלְּלוֹת. בְּהַהוּא זִמְנָא דְּמִתְיַיחֲדִין קוֹל וְדִבּוּר כַּחֲדָא, דְּאִינּוּן יְאֲהדוָֹנָהי, חָשׁוֹת. אֲבָל בְּזִמְנָא דִּפְנֵיהֶם וְכַנְפֵיהֶם פְּרוּדוֹת, יְדוָֹ\"ד מִן אֲדֹנָ\"י בְּפֵרוּדָא, אִיהוּ אִשְׁתְּכַח בְּאַרְבַּע אַנְפֵּי חֵיוָן, כֻּלְּהוּ פְּתִיחָן, לָקֳבְלֵיהּ מְמַלְּלוֹת, לְמִשְׁאַל מְזוֹנָא, בְּגִין (דניאל ד) דְּמָזוֹן לְכֹלָּא בֵּיהּ. אֲדֹנָ\"י אִשְׁתְּכַח בְּכַנְפֵי הַחַיּוֹת, כֻּלְּהוּ פְּתִיחָן לְגַבֵּי חֵיוָן.</p>\n<p>שָׁאֲגִין בְּקוֹל דְּאִיהוּ יְדוָֹ\"ד, כֻּלְּהוּ בִּימִינָא. אוֹפַנִּים מְצַּפְצְּפָן בְּדִבּוּר, דְּאִיהוּ אֲדֹנָ\"י בִּשְׂמָאלָא. בִּשְׂרָפִים מִתְחַבְּרִים קוֹל וְדִבּוּר בְּאֶמְצָּעִיתָא. יְאֲהדוָֹנָהי. בְּהוֹן (בראשית א׳:כ׳) וְעוֹף יְעוֹפֵף. הֲדָא הוּא דִכְתִיב, (ישעיהו ו׳:ו׳) וַיָּעָף אֵלַי אֶחָד מִן הַשְּׂרָפִים. וְאִתְּמַר בְּהוֹן, (קהלת י׳:כ׳) וְעוֹף הַשָּׁמַיִם יוֹלִיךְ אֶת הַקּוֹל וּבַעַל כְּנָפַיִם יַגִּיד דָּבָר. וּשְׂרָפִים שֵׁשׁ כְּנָפַיִם לְאֶחָד. מִסִּטְרָא דְּאָת ו', דְּאִיהוּ עַמּוּדָא דְּאֶמְצָּעִיתָא, כָּלִיל יְמִינָא וּשְׂמָאלָא. וְאִיהוּ כָּלִיל שִׁית תֵּיבִין, (ישעיהו ו׳:ב׳) בִּשְׁתַּיִם יְכַסֶּה פָּנָיו וּבִשְׁתַּיִם יְכַסֶּה רַגְלָיו וּבִשְׁתַּיִם יְעוֹפֵף סִימָן.</p>\n<p>תִּקּוּנָא תִּנְיָינָא, (יחזקאל א׳:כ״ו) וְעַל דְּמוּת הַכִּסֵּא דְּמוּת כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. רְשִׁימוּ דְסֵפֶר תּוֹרָה, וְאִיהוּ (ישעיהו מ״ד:י״ג) כְּתִפְאֶרֶת אָדָם לָשֶׁבֶת בָּיִת.</p>"],[9520012557,"<p>וְאוֹקְמוּהָ רַבָּנָן, כָּל הַקּוֹרֵא קְרִיאַת שְׁמַע עַרְבִית וְשַׁחֲרִית, כְּאִילּוּ מְקַיֵּים (יהושע א׳:ח׳) וְהָגִיתָ בּוֹ יוֹמָם וָלַיְלָה. דְּטַלִּית לְבָנָה, אִיהוּ לִימִינָא מִסִּטְרָא דְּחֶסֶד. וְאִתְּמַר, אֵל מֶלֶךְ יוֹשֵׁב עַל כִּסֵּא רַחֲמִים וּמִתְנַהֵג בַּחֲסִידוּת. (ישעיהו ט״ז:ה׳) וְהוּכַן בַּחֶסֶד כִּסֵּא. חֶסֶד סָלִיק ע\"ב חוּלְיָין וְקִשְׁרִין דְּטַלִּית.</p>\n<p>וְאִית טַלִית מִסִּטְרָא דִּמְטַטְרוֹ\"ן, דְּאִיהוּ טֵ\"ט, כָּלִיל ח\"י, בֵּין קִשְׁרִין וְחוּלְיָין לְכָל סִטְרָא. ה' קִשְׁרִין לָקֳבֵל ה' חוֹמָשֵׁי תּוֹרָה. וּתְלֵיסָר חוּלְיָין, לָקֳבֵל תְּלֵיסַר מְכִילָן דְּרַחֲמֵי דְּאוֹרַיְיתָא. דְּאִתְּמַר בְּהוֹן, בי\"ג מִדּוֹת הַתּוֹרָה נִדְרֶשֶׁת.</p>\n<p>וּבְגִינָהּ אִתְּמַר, כְּמַרְאֵה אָדָם עָלָיו מִלְמָעְלָה. בְּדִיּוּקְנָא דְּתִפְאֶרֶת, דְּאִיהוּ תִפְאֶרֶת אָדָם עָלָיו מִלְמָעְלָה. וְאִתְקְרֵי בִּשְׁמֵיהּ, יוֹ\"ד הֵ\"א וָא\"ו הֵ\"א. (ישעיהו מ״ג:ז׳) כֹּל הַנִקְרָא בִשְׁמִי וְלִכְבוֹדִי בְּרָאתִיו יְצַּרְתִּיו אַף עֲשִׂיתִיו. וּלְעֵילָּא כְּמַרְאֵה אָדָם, דָּא שְׁכִינְתָּא, דְּאִיהִי כְּחֵיזוּ דְּעַמּוּדָא דְּאֶמְצָּעִיתָא, בְּד' אַנְפִּין, וּבְעֶשֶׂר סְפִירָאן, דְּאִינּוּן אָדָם. וְאַרְבַּע אַנְפִּין דְּאָדָם, אַרְבַּע אַתְוָון. וְאִינּוּן י\"ד אַתְוָון, וּבְהוֹן (הושע י״ב:י״א) וּבְיַד הַנְּבִיאִים אֲדַמֶּה.</p>\n<p>וְעוֹד אִתְקְרֵי חַ\"י, מִסִּטְרָא דְּצַּדִּיק, וּבֵיהּ קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ אִתְקְרֵי אָז אָדָם, דְּאִיהוּ עַמּוּדָא דְּאֶמְצָּעִיתָא, טַ\"ל, וּשְׁכִינְתֵּיהּ ה'. וּבְה' אִיהוּ אָדָם. בְּגִין דְּטַ\"ל הָכִי סָלִיק בְּחוּשְׁבַּן יוֹ\"ד הֵ\"א וָא\"ו. וְהַאי אִיהוּ מוֹרִיד הַטַ\"ל, לְגַבֵּי הֵ\"א. קֶשֶׁר דְּטַלִית, חַ\"י עָלְמִין, דְּקָשִׁיר קוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ בְּכָל סִטְרִין, בְּאַרְבַּע כַּנְפוֹת דְּטַלִית.</p>\n<p>תְּפִלִּין מִשְּׂמָאלָא, הֲדָא הוּא דִכְתִיב, (ישעיהו ס״ב:ח׳) נִשְׁבַּע יְיָ בִּימִינוֹ וּבִזְרוֹעַ עֻזּוֹ. בִּימִינוֹ, זוֹ תּוֹרָה. וּבִזְרוֹעַ עֻזּוֹ, אֵלּוּ תְּפִלִּין. יְהוָֹ\"ה בְּד' פָּרְשִׁיָין. אֲדֹנָ\"י הֵיכָלָא לְד' אַתְוָון, בְּד' בָּתֵּי דִּתְפִלִין. קֶשֶׁר שֶׁל תְּפִלִין דְּיַד, דָּא צַּדִּיק חַ\"י עָלְמִין, דְּאִיהוּ קִשּׁוּרָא דְּתַרְוַויְיהוּ. בִּזְרוֹעַ שְׂמָאלָא. קֶשֶׁר דְּרֵישָׁא, דָּא עַמּוּדָא דְּאֶמְצָּעִיתָא, דְּאָחִיד בֵּיהּ יְדוָֹ\"ד אֶהְיְ\"ה לְעֵילָּא, דְּאִינּוּן (כת\"ר) חָכְמָ\"ה וּבִינָ\"ה.</p>\n<p>קְרִיאַת שְׁמַע דְּאִיהוּ יִחוּדָא בְּאֶמְצָּעִיתָא, וְאִיהוּ אָחִיד בֵּין צִּיצִּית וּתְפִלִין, דְּכֻלְּהוּ פָּרְשִׁיָין דְּצִּיצִּית וּתְפִלִין, אִינּוּן כְּלִילָן בְּיִחוּדָא דִּקְרִיאַת שְׁמַע. וּמִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָּעִיתָא, דְּאִיהוּ טַלִית וּתְפִלִין, דְּאִתְּמַר בְּהוּ, (שמות י״ג:ט״ז) וְהָיָה לְאוֹת עַל יָדְכָה וּלְטוֹטָפוֹת בֵּין עֵינֶיךָ. (במדבר ט״ו:ל״ח) וְעָשׂוּ לָהֶם צִּיצִּית.</p>\n<p><Nonei></i>ש' שֶׁל תְּפִילִין, הֲלָכָה לְמֹשֶׁה מִסִּינַי. (דברים כ״ח:י׳) וְרָאוּ כָּל עַמֵּי הָאָרֶץ כִּי שֵׁם יְיָ נִקְרָא עָלֶיךָ וַיִּרְאוּ מִמְּךָּ. וְאוֹקְמוּהָ מַאי שֵׁם יְדוָֹ\"ד. אֵלּוּ תְּפִלִּין שֶׁבָּראֹשׁ. ש' שֶׁל תְּפִלִּין. תְּרֵין שִׁינִין שִׁית מְאָה. שִׁית דַּרְגִּין. וְשֶׁבַע עַנְפִין דִּתְרֵין שִׁינִין, הָא תְּלַת עֲשַׂר, וְכֹלָּא תרי\"ג. וְלֵית פִּקּוּדָא דְּלָאו אִיהִי שְׁקִילָא לְכָל אוֹרַיְיתָא.</p>\n<p>כְּגַוְונָא דָּא, כָּל מִצְּוָה אִיהִי יְהוָֹ\"ה. יָ\"הּ עִם שְׁמִ\"י שס\"ה. ו\"ה עִם זִכְרִי רמ\"ח. וּבְגִין דָּא כָּל מִצְּוָה אִיהִי שְׁקִילָא לְתרי\"ג. וְהָא אוּקְמוּהָ, שְׁמַע יִשְׂרָאֵל כָּלִיל תרי\"ג, מִסִּטְרָא דְּצִּיצִּית. וְתרי\"ג מִסִּטְרָא דִּתְפִלִּין אִיהוּ בְּכָל אֲתָר.</p>\n<p>וְהָיוּ לְטוֹטָפוֹת, טֹטָפֹת: טט, ח\"י עָלְמִין, צַּדִּיק, לְקָבְלֵיהּ מְטַטְרוֹן. פַּת, תִּפְאֶרֶת. מְטַטְרוֹן סוּס דְּתִפְאֶרֶת, דְּבֵיהּ כָּל סְפִירָאן מִתְלַבְּשִׁין. וְהָכִי אִיהוּ כְּגוּפָא לְנִשְׁמְתָא. וְכַד קוּדְשָׁא בְּרִיךְ הוּא אִסְתַּלָּק מִנֵּיהּ, אִשְׁתְּאַר אִלֵּם, לֵית לֵיהּ קוֹל וְלָא דִּבּוּר. אִשְׁתְּכַח, דְקוּדְשָׁא בְּרִיךְ הוּא וּשְׁכִינְתֵּיהּ אִיהוּ קוֹל וְדִבּוּר. דְּכָל מַלְאָךְ וּמַלְאָךְ. וּבְכָל קָלָא וְדִבּוּר דְּאוֹרַיְיתָא, וּבְכָל קָלָא דִּצְּלוֹתָא. וּבְכָל פִּקּוּדָא וּפִקּוּדָא. בְּכָל אֲתָר שׁוּלְטָנוּתֵיהּ בְּעִלָּאִין וְתַתָּאִין, אִיהוּ חַיִּים דְּכֹלָּא, אִיהוּ סָבִיל כֹּלָּא.</p>\n<p>וְלֵית אֲדֹנָי בְּלָא יְדוָֹד, כְּגַוְונָא דְּלֵית דִּבּוּר בְּלָא קוֹל. וְלֵית קוֹל בְּלָא דִּבּוּר. וְהַאי אִיהוּ קְשׁוֹט, בְּעָלְמָא דַּאֲצִּילוּת. אֲבָל בְּעָלְמָא דְּפֵרוּדָא, אִית קוֹל בְּלָא דִּבּוּר. קֶשֶׁר שֶׁל תְּפִלִּין שַׁדַּי, אָחִיד בֵּיהּ עֵילָּא וְתַתָּא. וְדָא צַּדִּיק חַי עָלְמִין, אָחִיד (ס\"א ביה) בֵּין קוֹל וְדִבּוּר.</p>\n<p>אַדְּהָכִי, הָא רַעְיָא מְהֵימָנָא אִזְדְּמַן לְגַבֵּי סָבָא, וְאָמַר סָבָא סָבָא, תְּפִלִּין וְצִּיצִּית וּפָרָשַׁת מְזוּזָה, אִינּוּן ג' פִּקּוּדִין, כְּלִילָן בְּקְרִיאַת שְׁמַע. וְקְרִיאַת שְׁמַע פִּקּוּדָא רְבִיעָאָה. וְצִּיצִּית אַדְכַּר ג' זִמְנִין. וּבַתְּפִלִּין אַדְכַּר בְּהוּ תְּרֵין זִמְנִין אוֹת. וּבַצִּיצִּית ז' שֶׁל תִּזְכְּרוּ דְּצָּרִיךְ לְהַתִּיז בָּהּ. וּבְמְּזוּזָה, שַׁדַּי מִלְבַר, יְדוָֹ\"ד מִלְּגוֹ.</p>\n<p>וּפָרְשִׁיָין סְתִימִין וּפְתִיחָן אֲמַאי. וְשִׁיעוּר אָרְכָּהּ דְּצִּיצִּית וְרוֹחְבָּהּ, דְּתָקִינוּ אֹרֶךְ כָּל הַצִּיצִּית תְּרֵין עֲשַׂר אֶצְּבְּעָן בְּגוּדָל. מִצְּוַת תְּכֵלֶת, שְׁלִישׁ גְּדִיל, וּשְׁנֵי שְׁלִישֵׁי עֲנָף. וּבֵין קֶשֶׁר לְקֶשֶׁר כִּמְלֹא גּוּדָל. וְכָל חוּלְיָא וְחוּלְיָא תִּהְיֶה מְשׁוּלֶשֶׁת. וְהָכִי תְּפִלִּין אֲמַאי בְּמוֹחָא. וְלָקֳבֵל לִבָּא. וְשִׁיעוּר רְצּוּעָתְהוֹן אֲמַאי אִינּוּן עַד לִבָּא לִשְׂמָאלָא. וְעַד טַבּוּרָא לִימִינָא. וּרְצּוּעָא דְּיַד עַד דְּיִכְרוֹךְ וִישַׁלֵּשׁ תְּלַת זִמְנִין בְּאֶצְּבַּע צְּרָדָא.</p>\n<p>אֶלָּא, וַדַּאי בֶּגֶד חָשׁוּב לָאו אִיהוּ, אֶלָּא שָׁלֹשׁ עַל שָׁלֹשׁ לְכָל סִטְרָא. אִינּוּן תְּרֵיסָר, לָקֳבֵל ד' בִּגְדֵי לָבָן, וְד' בִּגְדֵי זָהָב, וְד' בִּגְדֵי דְּכֹהֵן הֶדְיוֹט. וּמִסִּטְרָא דְּבִרְכַּת כֹּהֵן הֶדְיוֹט קָא רָמִיז, אַל תְּהִי בִּרְכַּת הֶדְיוֹט קַלָה בְּעֵינֶיךָ. שְׁלִישׁ גְּדִיל, וּשְׁנֵי שְׁלִישִׁי עֲנָף, דְּאִיהוּ תְּכֵלֶת.</p>\n<p>וְכָל חוּלְיָא מְשׁוּלֶשֶׁת, כָּל מְשׁוּלָשׁ מִסִּטְרָא דִּקְדוּשָּׁה. הֲדָא הוּא דִכְתִיב קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ. וְיִשְׂרָאֵל שְׁלִישִׁיָּה, בְּגִין (שמות יד) דִּוְשָׁלִישִׁים עַל כֻּלּוֹ. דְּצִּיצִּית מִסִּטְרָא דְּעַמּוּדָא דְּאֶמְצָּעִיתָא, דְּאִיהוּ תְּלִיתָאָה לַאֲבָהָן, וְכָל דָּבָר מְשׁוּלָשׁ, וה\"ו יל\"י, כָּל תֵּיבָה מְשׁוּלֶשֶׁת מִסִּטְרוֹי. חוּלְיָא כְּלִילָא מִתְּלַת כְּרִיכוֹת מְשֻׁלָּשִׁין, דָּא שְׁכִינְתָּא. קְדוּשָּׁה לְךָ יְשַׁלֵּשׁוּ. וְאִיהִי מְשׁוּלֶשֶׁת בְּעַמּוּדָא דְּאֶמְצָּעִיתָא, כָּלִיל תְּלַת עַנְפֵּי אֲבָהָן, דְּאִינּוּן ש' מִן שַׁבָּת, שְׁכִינְתָּא בַּת יְחִידָה. (ס\"א מליא מן) חֻלְיָא, תְּכֵלֶת שֶׁבַּצִּיצִּית.</p>\n<p>זַכָּאָה גּוּפָא, דְּהָכִי אִיהוּ רָשִׁים, בִּשְׁכִינְתָּא וְקוּדְשָׁא בְּרִיךְ הוּא, עַל כַּנְפֵי דְּמִצְּוָה. רָשִׁים בִּרְצּוּעָא דְּאִיהוּ תְּפִלָּה דְּיָד, בִּתְלַת כְּרִיכוֹת בְּאֶצְּבַּע צְּרָדָא. דְּאִיהִי כְּגַוְונָא דְּחוּלְיָא, כְּרִיכָא בִּתְלַת כְּרִיכוֹת בְּאֶצְּבְּעָא. רָשִׁים בְּקֶשֶׁר דִּתְפִלִּין, כָּלִיל בִּתְרֵין קִשְׁרִין, סַלְּקִין חַמִשָׁה עֲשַׂר מְשׁוּלָשִׁין, תְּרֵין בְּקִשְׁרָא חַד.</p>\n<p>שְׁלֹשָׁה עֲשַׂר חוּלְיָין, אִית בְּהוֹן תִּשְׁעָה וּשְׁלֹשִׁים כְּרִיכָן, כְּחוּשְׁבַּן טַ\"ל. וּשְׁלֹשָׁה עֲשַׂר חֻלְיָין, כְּחוּשְׁבַּן אֶחָד. סַלְּקִין בֵּ\"ן. וְהַאי אִיהוּ בֶּן יָ\"הּ. עַמּוּדָא דְּאֶמְצָּעִיתָא.</p>\n<p>כָּל קֶשֶׁר בְּדִיּוּקְנָא דְּכַף יְמִינָא, כָּל חוּלְיָא בְּדִיּוּקְנָא דְּאֶצְּבַּע, דְּאִית בֵּיהּ תְּלַת פִּרְקִין, לָקֳבֵל תְּלַת כְּרִיכוֹת. וְהָכִי בְּכָל אֶצְּבַּע תְּלַת פִּרְקִין, לְבַר מִגּוּדָל. דְּאִיהוּ שִׁיעוּר בֵּין קֶשֶׁר לְקֶשֶׁר דְּצִּיצִּית, כִּמְלֹא גּוּדָל. אִיהִי מִדָּה דְּחוֹטָמָא. וּמִדָּה דְּעַיִן יְמִינָא וּשְׂמָאלָא. וְאִיהוּ מִדָּה בֵּין עַיִן לְעַיִן. וּמִדָּה דְּאֹזְן יְמִינָא וּשְׂמָאלָא. וּמִדָּה דְּכָל שָׂפָה וְשָׂפָה. וּמִדָּה דְּלִישָׁנָא. (שמות כ״ו:ב׳) מִדָּה אַחַת לְכָל הַיְרִיעוֹת.</p>\n<p>אַמָּה שִׁיעוּר דְּגוּפָא, לְאַרְבַּע סִטְרִין וְעֵילָּא וְתַתָּא. דְּאִינּוּן שִׁית אַמּוֹת. וּבְכָל אַמָּה וְאַמָּה שְׁלֹשָׁה פִּרְקִין, ח\"י פִּרְקִין בְּשִׁית אַמִּין. וְאִינּוּן רָזָא דח\"י נִעְנוּעִין דְּלוּלָב. לְשִׁית סִטְרִין. תְּלַת נִעְנוּעִין לְכָל סִטְרָא. וְעָלַיְיהוּ אִתְּמַר, (שיר השירים ז׳:ח׳) זֹאת קוֹמָתֵךְ דָּמְתָה לְתָמָר. וְדָא שִׁיעוּר קוֹמָה, מִקְוֵה יִשְׂרָאֵל בִּשְׁכִינְתָּא, אִיהוּ ח\"י אַרְבַּע זִמְנִין, דְּאִינּוּן אַרְבַּע סַלְּקִין שִׁבְעִים וּשְׁנַיִם.</p>\n<p>וְרָזָא דְּחֵיוָן, קוֹמָה דִּלְהוֹן <Nonei></i>(יחזקאל א׳:י״ח) וְגַבֵּיהֶם וְגוֹבַהּ לָהֶם וְיִרְאָה לָהֶם וְגַבּוֹתָם וְגוֹ', וְגַבֵּיהֶם, אַרְבַּע חֵיוָן דְּמֶרְכַּבְתָּא תַּתָּאָה. וְגוֹבַהּ לָהֶם, ד' חֵיוָן דְּמֶרְכַּבְתָּא מְצִּיעָתָא. וְגַבּוֹתָם, אַרְבַּע חֵיוָן דְּמֶרְכַּבְתָּא תְּלִיתָאָה. וְכֻלְּהוּ י\"ב. וְאִינּוּן מְלֵאוֹת עֵינַיִם, כְּגַוְונָא דָּא סָבִיב לְאַרְבַּעְתָּן, יְדוָֹד יְדוָֹד יְדוָֹד.</p>"]]});
